# 對比度：掃這一頁上每一個「自己寫了文字」的元素，算它跟自己背景的比值。
# 剖析圖畫布（#prodDiagram / #prod3d）排除 —— 那塊在兩個主題下都是深底（既有決策）。
_B20_CONTRAST = """(minFsBody) => {
  // color-mix() 在 Chromium 算出來是 color(srgb 0.77 0.86 0.92)：那三個數是 0~1 不是 0~255。
  // 不正規化就會把淺底當成近黑，量出 1.19 這種**假的**低對比（2026-09-22 真的踩過一次）。
  const lum = (c) => { const isFn = /^color\(srgb/.test(c);
    let m = (c.match(/[\d.]+/g) || []).map(Number);
    if (isFn) m = m.map(v => v * 255);
    const f = (v) => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); };
    return .2126 * f(m[0] || 0) + .7152 * f(m[1] || 0) + .0722 * f(m[2] || 0); };
  const bgOf = (el) => { let e = el;
    while (e && e !== document.documentElement) {
      const s = getComputedStyle(e);
      if (s.backgroundImage && s.backgroundImage !== 'none') return null;   // 漸層量不出單一底色
      const c = s.backgroundColor;
      const m = (c.match(/[\d.]+/g) || []).map(Number);
      if (m.length >= 4 ? m[3] > 0.4 : m.length === 3) return c;
      e = e.parentElement;
    }
    return getComputedStyle(document.body).backgroundColor; };
  const out = {body: [], small: [], nBody: 0, nSmall: 0};
  // 只掃 main（這一頁的內容 ＋ 資料橫幅）。頂部列與側欄是全站共用的，
  // 它們的對比度歸「淺色主題」「明亮主題」那兩段管，混進來只會讓這一段對不相干的回歸變紅。
  const scope = document.querySelector('main') || document.body;
  for (const el of scope.querySelectorAll('*')) {
    if (!el.childNodes.length) continue;
    const txt = [...el.childNodes].filter(n => n.nodeType === 3).map(n => n.textContent.trim()).join('');
    if (!txt) continue;
    if (el.closest('#prodDiagram') || el.closest('#prod3d') || el.closest('#chainMap')) continue;
    const r = el.getBoundingClientRect();
    if (r.width < 6 || r.height < 6) continue;
    const st = getComputedStyle(el);
    if (st.visibility === 'hidden' || st.display === 'none' || +st.opacity < 0.25) continue;
    const bgc = bgOf(el); if (!bgc) continue;
    const a = lum(st.color), b = lum(bgc);
    const ratio = (Math.max(a, b) + .05) / (Math.min(a, b) + .05);
    const fs = parseFloat(st.fontSize) || 0;
    const rec = {cls: el.className.toString().slice(0, 38), txt: txt.slice(0, 20),
                 color: st.color, bg: bgc, ratio: +ratio.toFixed(2), fs: +fs.toFixed(1)};
    // 正文（>= minFsBody px）要 4.5:1；比它小的算次要文字／圖例，要 3:1
    if (fs >= minFsBody) { out.nBody++; if (ratio < 4.5) out.body.push(rec); }
    else { out.nSmall++; if (ratio < 3.0) out.small.push(rec); }
  }
  out.body.sort((x, y) => x.ratio - y.ratio); out.small.sort((x, y) => x.ratio - y.ratio);
  out.body = out.body.slice(0, 12); out.small = out.small.slice(0, 12);
  return out;
}"""


def _selected(args, name: str) -> bool:
    """這一段要不要跑。

    `--sections` 是**精準比對**（給平行模式的 worker 用，名稱逗號分隔）；
    `--only` 是**子字串比對**（給人用，好打）。
    兩者的差別很重要：`--only 資金流向` 會同時命中「資金流向」與「新-資金流向」，
    那對人是方便，對分工卻是災難 —— 同一段被兩個 worker 各跑一次，
    結果會重複計算。所以 worker 一律走 `--sections`。
    """
    if args.sections:
        return name in [x.strip() for x in args.sections.split(",")]
    if getattr(args, "module", "") or args.only:
        # --module 與 --only 可以一起給，取聯集
        return (bool(args.only) and _want(args.only, name)) \
            or (bool(getattr(args, "module", "")) and name in _module_sections(args.module))
    return True


def _buckets(names: list[str], n: int) -> list[list[str]]:
    """把段落分給 n 個 worker，讓每一份的預估耗時盡量接近。

    用最長優先（LPT）：把最重的先放進目前最輕的那一籃。
    段落之間的耗時差距很大（實測 11 秒到 200 秒都有），
    用平均分配的話最慢那一籃會拖垮整輪 —— 平行化的效果就沒了。
    """
    try:
        w = json.loads(TIMES_FILE.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001 —— 沒有紀錄就當每段一樣重
        w = {}
    order = sorted(names, key=lambda x: -float(w.get(x, 30)))
    out: list[list[str]] = [[] for _ in range(n)]
    load = [0.0] * n
    for nm in order:
        i = load.index(min(load))
        out[i].append(nm)
        load[i] += float(w.get(nm, 30))
    return [x for x in out if x]


def run_parallel(args) -> int:
    """把段落拆給幾個子行程同時跑，再把結果合起來。

    為什麼是「多行程」而不是「多執行緒」（2026-09-20）
    ------------------------------------------------
    Playwright 的同步 API **不能跨執行緒共用**，一個執行緒要有自己的
    `sync_playwright()`。與其在同一個行程裡繞開它，不如直接開子行程：
    每個 worker 跑的就是**今天已經驗證過的那條路徑**（單行程、依序跑它那幾段），
    只是段落少一點。風險最低，而驗收程式最怕的就是改出「假綠」。

    每個 worker 自己起一個 HTTP 伺服器，所以埠要分開（`TW_UITEST_PORT`）。
    """
    names = [n for n in SECTION_NAMES if _selected(args, n)]
    if not names:
        print("沒有符合的段落"); return 0
    n = max(1, min(args.workers, len(names)))
    parts = _buckets(names, n)
    print(f"平行驗收：{len(names)} 段拆成 {len(parts)} 份", flush=True)
    for i, part in enumerate(parts, 1):
        print(f"  #{i}（{len(part)} 段）：{'、'.join(part)}", flush=True)

    tmp = pathlib.Path(tempfile.mkdtemp(prefix="uitest-"))
    procs = []
    for i, part in enumerate(parts):
        out = tmp / f"w{i}.json"
        env = dict(os.environ, TW_UITEST_PORT=str(PORT + 1 + i))
        cmd = [sys.executable, str(pathlib.Path(__file__).resolve()),
               "--code", args.code, "--sections", ",".join(part), "--json", str(out)]
        procs.append((subprocess.Popen(cmd, env=env, stdout=subprocess.PIPE,
                                       stderr=subprocess.STDOUT, text=True), out, part))

    for pr, out, part in procs:
        tail = (pr.communicate()[0] or "")
        if pr.returncode not in (0, 1):
            fails.append(f"【worker {'、'.join(part)}】子行程異常結束（code {pr.returncode}）：{tail[-400:]}")

    merged_times: dict[str, float] = {}
    for _pr, out, part in procs:
        try:
            d = json.loads(out.read_text(encoding="utf-8"))
        except Exception as e:  # noqa: BLE001
            fails.append(f"【worker {'、'.join(part)}】沒有交回結果：{e}")
            continue
        fails.extend(d.get("fails") or [])
        for nt in (d.get("notes") or []):
            if nt not in notes:
                notes.append(nt)
        counts.update(d.get("counts") or {})
        merged_times.update(d.get("took") or {})
    shutil.rmtree(tmp, ignore_errors=True)

    # 依原本的順序印，這樣跟依序跑的輸出可以直接對照
    for nm in SECTION_NAMES:
        if nm in counts:
            print(f"  {nm}：{counts[nm]} 個問題（{merged_times.get(nm, 0):.0f}s）", flush=True)
    try:
        old = {}
        if TIMES_FILE.exists():
            old = json.loads(TIMES_FILE.read_text(encoding="utf-8"))
        old.update(merged_times)
        TIMES_FILE.write_text(json.dumps(old, ensure_ascii=False, indent=1), encoding="utf-8")
    except Exception:  # noqa: BLE001 —— 記不起來只是下次分得沒那麼平均，不該讓驗收失敗
        pass
    return 0



# ★ 2026-09-24 設計系統 v2 第 6 批（site/legal.js）：同意條款橫幅。
#   橫幅一旦啟用（site/legal_config.js 填完＋enabled:true），會固定在畫面最下方約 130～160px，
#   **擋住所有點畫面下緣的驗收步驟** —— 腳本沒改先上線，所有關卡會一起紅（docs/design_system_v2.md 4.1 最後一段）。
#   所以在這裡把 Playwright 的 Browser.new_page／new_context 包一層：每一個新開的頁面，
#   在頁面腳本執行前都先寫好 tw.consent（v:'*'＝這個瀏覽器不必再看橫幅）與 tw.tour。
#   · 只在「還沒有值」時才寫：有些段落會 localStorage.clear() 再重新整理，init script 會在下一次載入補回來。
#   · 包在類別上而不是某一個 page：驗收裡有幾十個地方各自 new_page，逐一加一定會漏。
#   · 「同意條款」那一段要刻意不寫，改用 Browser._tw_raw_new_context（原本那支）開乾淨的頁面。
# ===================================================================== 說明精簡（2026-09-24，visual-explainer）
# Andy 原話：「所有內容 已經有說明 就把表上補充文字拿掉，並且說明內容需要在簡短方便閱讀，
#            盡可能圖上只留功能按鍵及圖表 和簡短說明」。
# 這一段真的把全站（資金輪動卡與總覽小輪盤除外 —— 那兩張另一支 agent 在改）每一頁走一遍：
#   ① 每張卡片（或卡片裡標了 data-howsec 的區段）上，**不含「怎麼看 ?」展開內容**的說明文字 ≤ 40 字
#   ② 每一顆「怎麼看 ?」都**真的按下去**：盒子真的打開、內容非空、條列最多 5 條、每條 ≤ 30 字、
#      按鈕亮起來（aria-expanded=true；合併足跡輪盤那批後不再改字成「收起說明」）；再按一次真的收起來（不是只驗元素存在）
#   ③ 這一批新加的入口一顆都不准少（量不到就是被誰拿掉了）
# 量尺的定義寫在 COPY_MEASURE 的註解裡 —— 什麼算「說明文字」、什麼是「計算結果」（data-readout）不算。
COPY_MEASURE = r"""() => {
  const SKIP = '#flowRotCard, #ovRotCard';
  const UNIT = '.card, [data-howsec]';
  /* 說明文字＝副標（h3/h4/h5 裡的 small）、.sub、.note、.hint、.pnote、.kpinote、.hmhint、.skhelp、.muted、.themehint。
     不算：「怎麼看」盒子、側邊面板、表格、按鈕、圖表、燈號、數字格、環節詳情與清單、
           標了 data-readout 的「這一檔的計算結果」（停損目標、判讀、本益比與月份讀數）。
     一段字歸給離它最近的卡片或區段；字數＝去掉空白後的字元數。*/
  const EXPL = 'h3 > small, h4 > small, h5 > small, .sub, .note, .hint, .pnote, .kpinote, .hmhint, .skhelp, .muted, .themehint';
  const NOPE = '.howtxt, .hpanel, table, button, select, .chart, svg, .lights, .kvs, .sibs, .legend-ov, .segchips, #segBox, #chainList, .dgwrap, [data-readout], .rotfilter, .zbadge, .partcard, .chainmap, .tw, .cards, .facets, .kpi';
  const vis = (e) => { if (!e || !e.isConnected) return false; const r = e.getBoundingClientRect();
    if (r.width < 1 || r.height < 1) return false;
    const cs = getComputedStyle(e); return cs.visibility !== 'hidden' && cs.display !== 'none' && +cs.opacity > 0.05; };
  const len = (t) => (t || '').replace(/\s+/g, '').length;
  const units = [...document.querySelectorAll(UNIT)].filter(u => vis(u) && !u.closest(SKIP));
  const acc = new Map(units.map(u => [u, []]));
  document.querySelectorAll(EXPL).forEach(e => {
    if (!vis(e) || e.closest(NOPE) || e.closest(SKIP)) return;
    const u = e.closest(UNIT); if (!u || !acc.has(u)) return;
    const p = e.parentElement && e.parentElement.closest(EXPL);
    if (p && u.contains(p)) return;
    const n = len(e.innerText);
    if (n) acc.get(u).push({ n, t: e.innerText.replace(/\s+/g, ' ').trim().slice(0, 50) });
  });
  return units.map(u => {
    const h = u.querySelector('h3, h2, h4, h5');
    const title = h ? ((h.childNodes[0] && h.childNodes[0].textContent) || h.innerText || '').trim().slice(0, 20) : (u.id || '');
    const items = acc.get(u);
    const how = [...u.querySelectorAll('.howbtn[data-how]')].filter(b => vis(b) && b.closest(UNIT) === u).map(b => b.dataset.how);
    return { title, n: items.reduce((a, x) => a + x.n, 0), items, how };
  });
}"""

COPY_HOWBOX = r"""(k) => { const b = document.getElementById('how-' + k);
  const btn = document.querySelector('.howbtn[data-how="' + k + '"]');
  if (!b) return null;
  const lis = [...b.querySelectorAll('li')].map(li => li.innerText.replace(/\s+/g, ''));
  /* 2026-09-26：附註段＝條列下面那段小字（.howfine）。fine＝畫面上看得到、有字的 .howfine 個數；
     tail＝最後一條條列之後還看得到的字（innerText 不含 display:none，所以量的是「使用者真的看得到」的） */
  const all = b.innerText.replace(/\s+/g, ''), last = lis[lis.length - 1] || '';
  const fine = [...b.querySelectorAll('.howfine')].filter(e => e.getClientRects().length && e.textContent.trim()).length;
  return { open: !b.hidden && b.getBoundingClientRect().height > 10, len: all.length,
           n: lis.length, long: lis.filter(t => t.length > 30), label: btn ? btn.textContent : '',
           fine, tail: last ? all.slice(all.lastIndexOf(last) + last.length) : '' }; }"""


def how_fine(pg, key: str):
    """打開某顆「?」→ 回傳 {fine, tail, n, len}（fine＝看得到的附註段數、tail＝條列之後還看得到的字）→ 關回去。
    2026-09-26（Andy：「"?" 內說明欄下方的更詳細說明不需要附註」）：全站「?」只留標題＋條列，這支就是量那件事的。"""
    box = f"#how-{key}"
    if pg.evaluate(f"() => {{ const b = document.querySelector({box!r}); return !b || b.hidden; }}"):
        click(pg, f'.howbtn[data-how="{key}"]', 450)
    st = pg.evaluate(COPY_HOWBOX, key)
    if not pg.evaluate(f"() => {{ const b = document.querySelector({box!r}); return !b || b.hidden; }}"):
        if pg.evaluate("() => { const b = document.getElementById('howBack'); return !!b && !b.hidden; }"):
            pg.keyboard.press("Escape"); pg.wait_for_timeout(250)
        else:
            click(pg, f'.howbtn[data-how="{key}"]', 300)
    return st


OVR_WHEEL = r"""() => { const e = document.getElementById('rotClockMini'); const c = e && echarts.getInstanceByDom(e); if (!c) return null;
  const pol = c.getModel().getComponent('polar'); const cs = pol && pol.coordinateSystem;
  const ext = cs ? cs.getRadiusAxis().getExtent() : [0, 0];
  return { R: Math.abs(ext[1] - ext[0]), W: e.clientWidth, H: e.clientHeight,
           wrapW: (document.getElementById('rotClockMiniWrap') || e).clientWidth }; }"""


DD_CONTRAST = r"""(sel) => {
  const P = (c) => { let m = String(c).match(/rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?/);
    if (m) return [+m[1], +m[2], +m[3], m[4] == null ? 1 : +m[4]];
    m = String(c).match(/color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)(?: \/ ([\d.]+))?/);
    if (m) return [m[1] * 255, m[2] * 255, m[3] * 255, m[4] == null ? 1 : +m[4]];
    return [0, 0, 0, 0]; };
  const bgOf = (el) => { const st = []; for (let e = el; e; e = e.parentElement) st.push(P(getComputedStyle(e).backgroundColor));
    let c = [255, 255, 255]; for (let i = st.length - 1; i >= 0; i--) { const [r, g, b, a] = st[i]; c = [r * a + c[0] * (1 - a), g * a + c[1] * (1 - a), b * a + c[2] * (1 - a)]; } return c; };
  const L = (c) => { const f = (v) => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); }; return .2126 * f(c[0]) + .7152 * f(c[1]) + .0722 * f(c[2]); };
  return [...document.querySelectorAll(sel)].map(o => { const bg = bgOf(o), fg = P(getComputedStyle(o).color);
    const a = L(bg), b = L(fg.slice(0, 3)); return { t: o.textContent.trim().slice(0, 12), r: +((Math.max(a, b) + .05) / (Math.min(a, b) + .05)).toFixed(2), on: o.classList.contains('on') }; }); }"""


# ★ 2026-09-26 Andy：「昨日資金去向這邊 UI 也需要重新設定，但功能照舊」→ 桌機改用 flowtopo.js 的緊湊版 layout:'mini'
#   （和資金流向頁「經典光纖」第二版同一支引擎、同一套視覺）。手機（視窗 ≤ 820）維持 ECharts 樹。
#   以下三支是這張卡在各段共用的量測：探針、把某個節點捲到視窗中間拿螢幕座標、以及整套「新版長相＋功能照舊」的斷言。
OVFX = """() => { const el = document.getElementById('ovFlow');
  return el && window.FlowTopo && window.FlowTopo.has(el) ? window.FlowTopo.probe(el) : null; }"""


def _ovfx_node(pg, key):
    pg.eval_on_selector("#ovFlow", "el => el.scrollIntoView({block:'center', behavior:'instant'})")
    pg.wait_for_timeout(500)
    t = pg.evaluate(OVFX)
    n = [x for x in (t or {}).get("nodes", []) if x["key"] == key]
    return n[0] if n else None


def _ovfx_checks(pg, tag, dark=True):
    """總覽「昨日資金去向」新版：長相照經典光纖第二版、功能照舊。每一條讀探針或真的用滑鼠操作。"""
    pg.eval_on_selector("#ovFlow", "el => el.scrollIntoView({block:'center', behavior:'instant'})")
    t = wait_until(pg, """() => { const el = document.getElementById('ovFlow');
        const t = el && window.FlowTopo && window.FlowTopo.has(el) ? window.FlowTopo.probe(el) : null;
        return t && !t.pending && t.W > 0 ? t : null; }""", 6000)
    if not ok(f"{tag} 昨日資金去向改用光纖緊湊版（flowtopo layout:'mini'，不是 ECharts 樹）",
              bool(t) and t["layout"] == "mini" and not pg.evaluate(
                  "() => !!(window.echarts && echarts.getInstanceByDom(document.getElementById('ovFlow')))"), t and t.get("layout")):
        return
    L = [[n for n in t["nodes"] if n["lv"] == k] for k in range(4)]
    ok(f"{tag} 三層：加權指數 1、產業鏈 ≥ 3、族群 ≥ 10，沒有代表股欄（功能照舊：只到族群層）",
       len(L[0]) == 1 and len(L[1]) >= 3 and len(L[2]) >= 10 and not L[3], [len(x) for x in L])
    ok(f"{tag} 根節點名稱「加權指數」、看得見（圓點 ＋ 標籤）",
       L[0][0]["name"] == "加權指數" and L[0][0]["r"] > 0 and "加權指數" in L[0][0]["text"], L[0][0])
    n_g = len(L[2])
    ok(f"{tag} 高度沒有比改前高：畫布高＝改前公式 max(300, 族群數 × 22 ＋ 46)、沒有上方說明列",
       t["H"] == max(300, n_g * 22 + 46) and t["total"] == t["H"], {"H": t["H"], "total": t["total"], "族群": n_g})
    # 視覺：精緻圓點、不要直條
    ok(f"{tag} 節點全部是圓點（改前產業鏈是直條 roundRect 4×高）、半徑 4.5～7.5",
       all(n["shape"] == "circle" and n["hh"] == 0 and 4.5 <= n["r"] <= 7.5 for n in L[0] + L[1] + L[2]),
       [(n["name"], n["shape"], n["r"]) for n in L[0] + L[1] + L[2] if not (n["shape"] == "circle" and 4.5 <= n["r"] <= 7.5)][:4])
    # 視覺：CP 0.45 對稱貝茲、細亮光芯＋淡外暈（和經典光纖第二版同一組數字）
    lk = [x for x in t["links"] if not x["dead"]]
    bad_cp = [x["key"] for x in lk if not (abs(x["cp"][2] - (x["cp"][0] + (x["cp"][6] - x["cp"][0]) * 0.45)) < 0.05
                                           and abs(x["cp"][4] - (x["cp"][6] - (x["cp"][6] - x["cp"][0]) * 0.45)) < 0.05
                                           and abs(x["cp"][3] - x["cp"][1]) < 0.05 and abs(x["cp"][5] - x["cp"][7]) < 0.05)]
    ok(f"{tag} 連線是 CP 0.45 對稱的水平切線貝茲（改前 ECharts curveness .5）", bool(lk) and not bad_cp, bad_cp[:3])
    ok(f"{tag} 細亮光芯 1.1px／alpha .65、淡外暈 ≤ .09（和經典光纖第二版同一組）",
       all(x["inW"] == 1.1 and x["inA"] == 0.65 and 0 < x["outA"] <= 0.0901 for x in lk),
       [(x["key"], x["inW"], x["inA"], x["outA"]) for x in lk][:2])
    # 視覺：產業鏈飽和色（同一組）；族群跟著它的鏈；不用紅綠
    dot = {n["key"]: n["dot"] for n in t["nodes"]}
    ok(f"{tag} 族群圓點＝所屬產業鏈的色（顏色講「哪條鏈」）、鏈與鏈不同色",
       all(n["dot"] == dot.get(n["parent"]) for n in L[2]) and len({n["dot"] for n in L[1]}) >= min(3, len(L[1])),
       [(n["name"], n["dot"]) for n in L[1]])
    want = {"semiconductor": "#22d3ee", "ai_server": "#c084fc"} if dark else {"semiconductor": "#0891b2", "ai_server": "#9333ea"}
    got = {n["key"][2:]: n["dot"] for n in L[1]}
    ok(f"{tag} 產業鏈色和資金流向頁經典光纖第二版同一組（半導體／AI 伺服器）",
       all(got.get(k) == v for k, v in want.items() if k in got) and any(k in got for k in want), got)
    rise, fall = pg.evaluate("() => { const s = getComputedStyle(document.documentElement);"
                             " return [s.getPropertyValue('--rise').trim(), s.getPropertyValue('--fall').trim()]; }")
    ok(f"{tag} 節點不染紅綠（紅綠只給漲跌字）", rise not in dot.values() and fall not in dot.values())
    # 標籤：17px 膠囊、名稱＋佔比、不硬加漲跌、不被切、不重疊
    labs = [n for n in L[1] + L[2]]
    ok(f"{tag} 產業鏈與族群的標籤是高 17px 的膠囊、寫著「名稱 佔比%」",
       all(n["lab"]["badge"] and n["lab"]["h"] == 17 and re.search(r"\d+\.\d%$", n["text"]) for n in labs),
       [(n["text"], n["lab"]) for n in labs if not (n["lab"]["badge"] and n["lab"]["h"] == 17)][:3])
    ok(f"{tag} 這張卡沒有漲跌，就不硬加（沒有 ▲▼）", all(n["chg"] is None for n in t["nodes"]),
       [n["text"] for n in t["nodes"] if n["chg"]][:3])
    out = [n["name"] for n in t["nodes"] if n["lab"] and (n["lab"]["x"] < 0 or n["lab"]["x"] + n["lab"]["w"] > t["W"] + 0.5
                                                          or n["lab"]["y"] < 0 or n["lab"]["y"] + n["lab"]["h"] > t["H"] + 0.5)]
    ok(f"{tag} 標籤全部在畫布內（沒有被切，寬 {t['W']}px）", not out, out[:4])
    ok(f"{tag} 標籤兩兩不重疊", _topo_overlap(t) == 0, _topo_overlap(t))
    # 寬度 ≥ 290（側欄打開的 1440 是 294、收起來約 454、單欄 450～650）名稱一個都不截；
    # 更窄（1280＋側欄＝241px，兩邊都放不下）才准截名稱，而且 % 一定完整、全名在提示框
    tr_ = [n["text"] for n in t["nodes"] if "…" in n["text"]]
    if t["W"] >= 290:
        ok(f"{tag} 寬 {t['W']}px：沒有任何名稱被截（…）", not tr_, tr_[:4])
    else:
        notes.append(f"{tag} 寬 {t['W']}px（1280＋側欄）截了 {len(tr_)} 個名稱：{tr_[:6]}")
    ok(f"{tag} 就算截名稱，每個膠囊仍以「數字%」結尾", all(re.search(r"\d%$", n["text"]) for n in t["nodes"] if n["lv"] > 0),
       [n["text"] for n in t["nodes"] if n["lv"] > 0 and not re.search(r"\d%$", n["text"])][:3])
    root_n = [n for n in t["nodes"] if n["lv"] == 0][0]
    near = [n["name"] for n in t["nodes"] if n["lv"] == 1 and n["lab"]["x"] < root_n["x"] + root_n["r"] + 1
            and n["lab"]["y"] < root_n["y"] + root_n["r"] and root_n["y"] - root_n["r"] < n["lab"]["y"] + n["lab"]["h"]]
    ok(f"{tag} 產業鏈膠囊沒有蓋住根節點的圓點", not near, near)
    ok(f"{tag} 畫布字 ≥ 12px、發光 ≤ 6px", (t["minFont"] or 0) >= 12 and t["maxBlur"] <= 6, [t["minFont"], t["maxBlur"]])
    # 特效：粒子（小預算）、碰撞光環／細漣漪
    t1 = wait_until(pg, """() => { const el = document.getElementById('ovFlow'); const t = window.FlowTopo.probe(el);
        return t && t.running && t.hits > 0 && t.nodes.some(n => n.hf > 0) ? t : null; }""", 6000)
    if ok(f"{tag} 白核心粒子在跑、粒子到站會激發節點（hitFlash）", bool(t1), (pg.evaluate(OVFX) or {}).get("hits")):
        ok(f"{tag} 粒子數在小預算內（總覽首屏；≤ 160 顆）", 0 < t1["particles"] <= 160, t1["particles"])
        ok(f"{tag} 漣漪 ≤ 60 圈", t1["ripples"] <= 60 and t1["rpPeak"] <= 60, {k: t1[k] for k in ("ripples", "rpPeak")})
    # 功能照舊：滑過出提示（精簡後的內容）、點族群不跳頁
    g0 = sorted(L[2], key=lambda n: -(n["value"] or 0))[0]
    nd = _ovfx_node(pg, g0["key"])
    if ok(f"{tag} 找得到一顆族群節點來操作", bool(nd), g0["key"]):
        pg.mouse.move(nd["cx"] - 40, nd["cy"] - 30); pg.wait_for_timeout(150)
        pg.mouse.move(nd["cx"], nd["cy"]); pg.wait_for_timeout(500)
        tt = pg.evaluate("() => { const t = document.querySelector('#ovFlow .fttip.on'); return t ? t.innerText : ''; }")
        if ok(f"{tag} 滑到族群節點出現提示框（成交值／佔上一層／佔全場）",
              "成交值" in tt and "佔上一層" in tt and "佔全場" in tt, tt):
            ok(f"{tag} 提示框沒有 09-25 拿掉的那兩行（1/n 拆分、點一下進族群頁）",
               "1/n" not in tt and "盤後結算" not in tt and "進族群頁" not in tt, tt)
        ok(f"{tag} 滑過族群：路徑以外壓暗", (pg.evaluate(OVFX) or {}).get("hover") == g0["key"])
        h0 = pg.evaluate("() => location.hash")
        pg.mouse.click(nd["cx"], nd["cy"]); pg.wait_for_timeout(900)
        ok(f"{tag} 點族群節點不跳頁（09-25 切斷超連結；改前是 ECharts 節點）", pg.evaluate("() => location.hash") == h0 and h0 in ("", "#overview"),
           pg.evaluate("() => location.hash"))
        pg.mouse.move(5, 5); pg.wait_for_timeout(200)
    rt = _ovfx_node(pg, "root")
    if rt:
        pg.mouse.move(rt["cx"], rt["cy"]); pg.wait_for_timeout(450)
        tt = pg.evaluate("() => { const t = document.querySelector('#ovFlow .fttip.on'); return t ? t.innerText : ''; }")
        ok(f"{tag} 滑到「加權指數」出現合計成交值", "加權指數" in tt and "成交值" in tt, tt)
        pg.mouse.move(5, 5); pg.wait_for_timeout(200)
    # 動態開關（畫布左下角那顆，跟資金流向頁同一個設定）
    if ok(f"{tag} 動態開關在畫布左上角（左上角一直是空的；左下角在窄排法會壓到最後一條鏈的膠囊）", pg.evaluate("""() => { const b = document.querySelector('#ovFlow .ftstage #ovFlowMotionBtn.ftcorner');
            if (!b) return false; const r = b.getBoundingClientRect(), s = b.parentNode.getBoundingClientRect();
            return r.left - s.left < 20 && r.top - s.top < 20; }""")):
        bb = pg.evaluate("""() => { const b = document.getElementById('ovFlowMotionBtn'), s = b.parentNode.getBoundingClientRect(), r = b.getBoundingClientRect();
            return { x: r.left - s.left, y: r.top - s.top, w: r.width, h: r.height }; }""")
        hitb = [n["name"] for n in t["nodes"] if n["lab"] and n["lab"]["x"] < bb["x"] + bb["w"] and bb["x"] < n["lab"]["x"] + n["lab"]["w"]
                and n["lab"]["y"] < bb["y"] + bb["h"] and bb["y"] < n["lab"]["y"] + n["lab"]["h"]]
        ok(f"{tag} 動態開關沒有壓到任何標籤", not hitb, {"鈕": bb, "壓到": hitb})
        pg.eval_on_selector("#ovFlowMotionBtn", "b => b.click()"); pg.wait_for_timeout(600)
        tm = pg.evaluate(OVFX)
        ok(f"{tag} 按「動態」：動畫停、設定寫進 localStorage、沒有漣漪與激發",
           not tm["running"] and not tm["motion"] and tm["ripples"] == 0 and all(n["hf"] == 0 for n in tm["nodes"])
           and pg.evaluate("() => localStorage.getItem('tw.flowtopo.motion')") == "0", {k: tm[k] for k in ("running", "ripples")})
        ha = canvas_hash(pg, "#ovFlow"); pg.wait_for_timeout(800)
        ok(f"{tag} 動態關掉之後畫面完全靜止", ha == canvas_hash(pg, "#ovFlow"))
        pg.eval_on_selector("#ovFlowMotionBtn", "b => b.click()")
        ok(f"{tag} 再按一次：動畫又跑起來", bool(wait_until(pg, "() => { const t = window.FlowTopo.probe(document.getElementById('ovFlow')); return t && t.running ? 1 : 0; }", 5000)))
    # 捲出畫面停動畫
    pg.evaluate("() => window.scrollTo({top: document.documentElement.scrollHeight, behavior: 'instant'})")
    if pg.evaluate("() => document.querySelector('#ovFlow .ftstage').getBoundingClientRect().bottom < 0"):
        ok(f"{tag} 捲出畫面：動畫停掉", bool(wait_until(pg, "() => { const t = window.FlowTopo.probe(document.getElementById('ovFlow')); return t && !t.running ? 1 : 0; }", 4000)))
    pg.evaluate("() => window.scrollTo({top: 0, behavior: 'instant'})"); pg.wait_for_timeout(300)


def t_ov_right(pg, base):
    """總覽右欄（2026-09-25）：足跡輪盤放大、族群面板收小；昨日資金去向「?」、族群不跳頁、提示框精簡、起點「加權指數」。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2800)
    scroll_to(pg, "rotClockMini"); pg.wait_for_timeout(600)
    wh = pg.evaluate(OVR_WHEEL)
    # 改前：盤半徑 ＝ 0.66 × min(寬,高)/2（1440 實測約 97px，約佔卡寬 58%）。改後：離容器邊 18px。
    if ok("[總覽右欄] 讀得到足跡輪盤的半徑", bool(wh) and wh["R"] > 0, wh):
        ok("[總覽右欄] ★ 輪盤直徑填滿卡寬（直徑 ≥ 容器寬的 80%）", 2 * wh["R"] >= 0.8 * wh["W"], wh)
        ok("[總覽右欄] 輪盤離容器邊還留一點距離（直徑 ≤ 寬 − 20px）", 2 * wh["R"] <= wh["W"] - 20, wh)
        ok("[總覽右欄] 輪盤直徑比改前 0.66 倍的公式大", wh["R"] > 0.66 * min(wh["W"], wh["H"]) / 2 + 10, wh)
    # 點族群點 → 面板打開，而且高度緊湊、個股是一行多檔的小標籤
    rp = pg.evaluate("""() => { const e = document.getElementById('rotClockMini'), c = echarts.getInstanceByDom(e); if (!c) return null;
        const o = c.getOption(); const si = o.series.findIndex(s => s.type === 'scatter' && (s.data || []).some(d => d && d.row && d.row.gid));
        if (si < 0) return null; const d = o.series[si].data.find(d => d && d.row && d.row.gid);
        const p = c.convertToPixel({seriesIndex: si}, d.value); const r = e.getBoundingClientRect();
        return {x: r.left + p[0], y: r.top + p[1], gid: d.row.gid}; }""")
    if ok("[總覽右欄] 算得出輪盤上一顆族群點", bool(rp), rp):
        pg.mouse.click(rp["x"], rp["y"]); pg.wait_for_timeout(900)
        pn = pg.evaluate("""() => { const b = document.getElementById('ovRotPanel'); if (!b || b.hidden) return null;
            const as = [...b.querySelectorAll('.ms a')]; const tops = new Set(as.slice(0, 6).map(a => Math.round(a.getBoundingClientRect().top)));
            const fs = as.length ? parseFloat(getComputedStyle(as[0]).fontSize) : 0;
            const min = Math.min(...[...b.querySelectorAll('*')].filter(x => x.getClientRects().length && x.textContent.trim()).map(x => parseFloat(getComputedStyle(x).fontSize)));
            return { h: Math.round(b.getBoundingClientRect().height), n: as.length, rows6: tops.size, fs, min }; }""")
        # 改前：每檔一格 168px 寬的卡片、面板高約 280px（.ms 上限 232）。改後：上限約 88px 的小標籤。
        if ok("[總覽右欄] 點族群點 → 面板原地打開", bool(pn) and pn["n"] >= 1, pn):
            ok("[總覽右欄] ★ 面板高度大幅縮小（≤ 150px）", pn["h"] <= 150, pn)
            ok("[總覽右欄] ★ 個股改成一行多檔（前 6 檔排不到 6 行）", pn["n"] < 2 or pn["rows6"] < min(6, pn["n"]), pn)
            ok("[總覽右欄] 面板字收小但不小於 11px", pn["fs"] <= 12.5 and pn["min"] >= 11, pn)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(300)
    # 熱門題材下拉（2026-09-25 Andy：「展開後清單項目是白底、字看不到」）：
    # 改前選項吃瀏覽器預設白底按鈕（.ddlist 包住，舊選擇器 .ddpanel>.ddopt 沒套到）→ 改後跟「產業鏈：全部 ▾」同一套深色清單
    for th in ("dark", "light"):
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        pg.eval_on_selector("#ovThemeCard", "el => el.scrollIntoView({block:'start', behavior:'instant'})"); pg.wait_for_timeout(400)
        click(pg, "#ovThemeDD .ddbtn", 400)
        rows = pg.evaluate(DD_CONTRAST, "#ovThemeDD .ddpanel:not([hidden]) .ddopt")
        if ok(f"[總覽右欄][{th}] 題材下拉打得開、列得出選項", len(rows) >= 2, len(rows)):
            bad = [r for r in rows if r["r"] < 4.5]
            ok(f"[總覽右欄][{th}] ★ 題材下拉每一列文字對比 ≥ 4.5（不再是白底白字）", not bad, bad[:4] or rows[:2])
            ok(f"[總覽右欄][{th}] 選中那一列有高亮（.on）", sum(1 for r in rows if r["on"]) == 1, [r for r in rows if r["on"]])
            pg.keyboard.press("Escape"); pg.wait_for_timeout(250)
        # 2026-09-26：資金熱力圖的產業鏈下拉是同一支 ddSingle，深淺主題一樣要看得到字
        pg.eval_on_selector("#ovHeatCard", "el => el.scrollIntoView({block:'start', behavior:'instant'})"); pg.wait_for_timeout(400)
        click(pg, "#heatDD .ddbtn", 400)
        rows = pg.evaluate(DD_CONTRAST, "#heatDD .ddpanel:not([hidden]) .ddopt")
        if ok(f"[總覽右欄][{th}] 產業鏈下拉打得開、列得出選項", len(rows) >= 3, len(rows)):
            bad = [r for r in rows if r["r"] < 4.5]
            ok(f"[總覽右欄][{th}] ★ 產業鏈下拉每一列文字對比 ≥ 4.5", not bad, bad[:4] or rows[:2])
            pg.keyboard.press("Escape"); pg.wait_for_timeout(250)
            ok(f"[總覽右欄][{th}] 產業鏈下拉按 Esc 收起來", pg.evaluate("() => document.querySelector('#heatDD .ddpanel').hidden"))
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    # 昨日資金去向：「?」開關
    pg.evaluate("() => window.scrollTo(0, 0)")
    click(pg, '#ovFlowHead .howbtn.pop[data-how="ovflow"]', 450)
    hp = pg.evaluate("""() => { const p = document.getElementById('howPop'), b = document.getElementById('how-ovflow');
        return { open: !!p && !p.hidden && !!b && p.contains(b), txt: b ? b.innerText : '', ttl: p ? p.querySelector('.hp-h').textContent : '' }; }""")
    ok("[總覽右欄] ★「昨日資金去向」的「?」點得開、標題對", hp["open"] and "昨日資金去向" in hp["ttl"], hp["ttl"])
    # 改前：驗口徑（1/n 拆分、盤後結算）搬進「?」的附註段 → 改後：Andy 2026-09-26「"?" 內說明欄下方的更詳細說明不需要附註」，
    #   附註段整段拿掉，只驗條列裡仍講清楚起點是「加權指數」、而且沒有附註段。
    ok("[總覽右欄] 「?」只剩條列、起點講明是加權指數、沒有附註段", "加權指數" in hp["txt"] and "1/n" not in hp["txt"], hp["txt"][-160:])
    pg.mouse.click(6, 300); pg.wait_for_timeout(350)
    ok("[總覽右欄] 點背景就關", pg.evaluate("() => document.getElementById('how-ovflow').hidden && document.getElementById('howBack').hidden"))
    click(pg, '#ovFlowHead .howbtn.pop[data-how="ovflow"]', 450)
    pg.keyboard.press("Escape"); pg.wait_for_timeout(300)
    ok("[總覽右欄] 按 Esc 也關", pg.evaluate("() => document.getElementById('how-ovflow').hidden"))
    # ★ 2026-09-26 改前→改後：起點節點、滑過提示、點族群不跳頁 —— 改前讀 ECharts 的 series／getItemGraphicEl，
    #   改後這張在桌機是 flowtopo 緊湊光纖版，改讀畫布探針＋真的用滑鼠滑過／點（_ovfx_checks，深淺主題各一輪）。
    for th in ("dark", "light"):
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); localStorage.removeItem('tw.flowtopo.motion'); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        _ovfx_checks(pg, f"[總覽右欄][{th}][1440]", dark=(th == "dark"))
    # 其他寬度：側欄打開（預設）時 1440＝294px、1280＝241px；側欄收起 1440≈454px；1024 單欄 ≈ 574px
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); } catch (e) {} }")
    # ⚠ tw.side 量完要還原成原本的值（驗收框架預設把側欄收起＝'0'；拿掉這個 key 會讓後面的段落在側欄打開的窄版面下跑、整批假紅）
    side0 = pg.evaluate("() => { try { return localStorage.getItem('tw.side'); } catch (e) { return null; } }")
    for w, side in ((1280, None), (1024, None), (1440, "0")):
        pg.evaluate("(s) => { try { if (s == null) localStorage.removeItem('tw.side'); else localStorage.setItem('tw.side', s); } catch (e) {} }", side)
        pg.set_viewport_size({"width": w, "height": 1000}); pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        _ovfx_checks(pg, f"[總覽右欄][{w}{'・側欄收起' if side == '0' else ''}]")
    pg.evaluate("(s) => { try { if (s == null) localStorage.removeItem('tw.side'); else localStorage.setItem('tw.side', s); } catch (e) {} }", side0)
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1200)
    # 減少動態：只畫靜態
    ctx = pg.context.browser.new_context(viewport={"width": 1440, "height": 1000}, reduced_motion="reduce")
    p2 = ctx.new_page()
    p2.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    p2.goto(f"{base}#overview", wait_until="networkidle"); p2.wait_for_timeout(2400)
    p2.eval_on_selector("#ovFlow", "el => el.scrollIntoView({block:'center', behavior:'instant'})"); p2.wait_for_timeout(900)
    tr = p2.evaluate(OVFX)
    ok("[總覽右欄][減少動態] 昨日資金去向照樣畫得出來、動畫不跑、動態鈕停用、沒有漣漪",
       bool(tr) and tr["reduce"] and not tr["running"] and tr["ripples"] == 0 and p2.evaluate(
           "() => document.querySelector('#ovFlowMotionBtn').disabled"), tr and {k: tr[k] for k in ("reduce", "running")})
    ctx.close()


def t_copy_trim(pg, base, code):
    """說明精簡：卡片上的說明 ≤40 字、每顆「怎麼看 ?」點得開且條列短。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    routes = [("overview", None), ("market", None), ("flow", None), ("heatmap", None), ("heatmap/theme/cowos", None),
              ("industry", None), ("industry/semiconductor/overview", None), ("industry/semiconductor", None),
              ("industry/ai_server", None), ("season", None)] + \
             [(f"stock/{code}", t) for t in ("overview", "profit", "basics", "news")]
    seen_how = set()
    for route, tab in routes:
        pg.goto(f"{base}#{route}", wait_until="networkidle"); pg.wait_for_timeout(2400)
        if tab:
            click(pg, f'#stockTabs button[data-t="{tab}"]', 1300)
        where = route + (f"／{tab}" if tab else "")
        for u in pg.evaluate(COPY_MEASURE):
            ok(f"[說明精簡] {where}「{u['title']}」卡片上的說明 ≤ 40 字（不含怎麼看）", u["n"] <= 40,
               f"{u['n']} 字：" + "｜".join(f"{x['n']} {x['t']}" for x in u["items"]))
            for k in u["how"]:
                if k in ("rot", "rotm"):
                    continue                     # 資金輪動卡／總覽小輪盤是另一支 agent 的範圍
                pg.evaluate("() => window.scrollTo(0, 0)")
                was_open = pg.evaluate(f"() => {{ const b = document.getElementById('how-{k}'); return !!b && !b.hidden; }}")
                if was_open:                     # 保險：前一段留下的開著狀態先收起來
                    click(pg, f'.howbtn[data-how="{k}"]', 300)
                click(pg, f'.howbtn[data-how="{k}"]', 450)
                st = pg.evaluate(COPY_HOWBOX, k)
                seen_how.add(k)
                ok(f"[說明精簡] {where}「怎麼看：{k}」按下去真的展開、內容非空", bool(st) and st["open"] and st["len"] > 20, st)
                ok(f"[說明精簡] {where}「怎麼看：{k}」條列 1～5 條", bool(st) and 1 <= st["n"] <= 5, st and st["n"])
                ok(f"[說明精簡] {where}「怎麼看：{k}」每條 ≤ 30 字", bool(st) and not st["long"], st and st["long"])
                # ★ 2026-09-26（Andy：「"?" 內說明欄下方的更詳細說明不需要附註」）：
                #   改前：條列下方還有一段 .howfine 小字口徑 → 改後：只留標題＋條列，條列之後一個字都看不到
                ok(f"[說明精簡] ★ {where}「怎麼看：{k}」沒有附註段（條列之後沒有字）",
                   bool(st) and st["fine"] == 0 and not st["tail"], st and [st["fine"], st["tail"][:60]])
                # ★ 合併（2026-09-24）：Andy「不需要"收起"選項，點擊背景即可消除」—— 按鈕不改字，改成亮起來
                ok(f"[說明精簡] {where}「怎麼看：{k}」按鈕亮起來（aria-expanded），字不變成「收起」",
                   pg.evaluate(f"() => {{ const b = document.querySelector('.howbtn[data-how=\"{k}\"]'); return !!b && b.getAttribute('aria-expanded') === 'true'; }}")
                   and "收起" not in ((st or {}).get("label") or ""), st and st["label"])
                # ★ 2026-09-24 總覽改版：總覽的「?」（.howbtn.pop）是跳出式說明，背後墊一層背景 ——
                #   改前「再按一次那顆鈕」→ 改後「點背景」（Andy：「點了跳出說明（點背景關閉）」）；按鈕被背景蓋住是刻意的。
                if pg.evaluate(f"() => !!document.querySelector('.howbtn.pop[data-how=\"{k}\"]')"):
                    pg.mouse.click(6, 300); pg.wait_for_timeout(300)
                else:
                    click(pg, f'.howbtn[data-how="{k}"]', 300)
                closed = pg.evaluate(f"() => document.getElementById('how-{k}').hidden")
                ok(f"[說明精簡] {where}「怎麼看：{k}」再按一次（跳出式：點背景）真的收起來", closed is True)
    # 這一批新加（或改寫）的入口，一顆都不准少
    # 2026-09-24：總覽的「今日候選」表拿掉 → 拿掉 cand；新增總覽的 themeov（熱門題材熱力圖）與 m3（大盤三張圖）
    want = {"heat", "breadth", "trust", "themeov", "m3", "mkt", "sankey", "inst", "conc", "indheat", "theme", "themedg",
            "gp", "nb", "dg", "rel", "season", "kline", "mtf", "pe", "ms"}
    ok("[說明精簡] 全站「怎麼看 ?」入口一顆都沒少", want <= seen_how, sorted(want - seen_how))
    # 搬家不是刪除：幾段搬進盒子的關鍵句，打開盒子之後真的讀得到
    pg.goto(f"{base}#season", wait_until="networkidle"); pg.wait_for_timeout(2400)
    # ★ 2026-09-26（Andy：「"?" 內說明欄下方的更詳細說明不需要附註」）：
    #   改前：驗口徑小字（生存者偏差／不拆分／Yahoo 來源）搬進「?」沒有消失
    #   改後：「?」只留條列 —— 條列的讀法還在、附註段真的不見；週期統計的基準改掛在副標的滑鼠提示
    txt = how_text(pg, "season")
    ok("[說明精簡] 週期統計「?」只剩條列（沒有「生存者偏差」那段附註）", "生存者偏差" not in txt and "紅＝強" in txt, txt[-120:])
    ok("[說明精簡] 週期統計的基準改掛在副標的滑鼠提示（不在「?」裡、也不佔版面）",
       "基準" in pg.evaluate("() => (document.getElementById('seasonRange') || {}).title || ''"))
    pg.goto(f"{base}#heatmap", wait_until="networkidle"); pg.wait_for_timeout(2400)
    txt = how_text(pg, "theme")
    ok("[說明精簡] 題材熱力「?」只剩條列（讀法「熱度」還在、「不拆分」那段附註不見）",
       "不拆分" not in txt and "熱度" in txt, txt[-120:])
    pg.goto(f"{base}#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(2600)
    txt = how_text(pg, "kline")
    ok("[說明精簡] K 線「?」只剩條列（滾輪、分隔線還在；Yahoo 來源那段附註不見）",
       "滾輪" in txt and "分隔線" in txt and "Yahoo" not in txt, txt[:120])


# ===================================================================== 收尾 0925（claude/wrapup-1）
# Andy 規則（2026-09-25）：「所有說明都拿掉，改成 ? 點擊後可觀看說明，文字只需要留名稱；
#   卡片下方『其他題材』『族群』這類欄位都拿掉」—— 總覽已做，這一批補熱力圖頁、市場明細、週期統計、個股頁。
# 每一段都真的按：按「?」→ 跳出說明（內容非空）→ 點背景關 → 再按 → Esc 關；不是只驗元素存在。
POP_STATE = r"""() => { const p = document.getElementById('howPop'), bk = document.getElementById('howBack');
  return { open: !!p && !p.hidden, back: !!bk && !bk.hidden, len: p ? p.innerText.replace(/\s+/g, '').length : 0,
           title: p ? ((p.querySelector('.hp-h') || {}).innerText || '') : '' }; }"""
# 這一頁（#v-xxx）上還看得見的「舊式」說明：不是「?」的怎麼看鈕、標題裡不是讀數的副標、卡片下方連結列
LEFTOVER = r"""(root) => { const v = document.querySelector(root); if (!v) return null;
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && getComputedStyle(e).visibility !== 'hidden'; };
  const q = (s) => [...v.querySelectorAll(s)].filter(vis);
  return { oldHow: q('.howbtn:not(.pop)').map(b => b.dataset.how + '：' + b.textContent.trim()),
           pops: q('.howbtn.pop').map(b => b.dataset.how),
           popTxt: q('.howbtn.pop').filter(b => b.textContent.trim() !== '?').map(b => b.dataset.how),
           subs: q('h3 > small:not([data-readout]):not([data-warn]):not([id]), h4 > small:not([data-readout]):not([data-warn]):not([id])')
             .filter(e => !e.closest('[data-readout]')).map(e => e.innerText.trim().slice(0, 30)),
           linkrow: q('.linkrow').map(e => e.innerText.trim().slice(0, 30)) }; }"""


def _pop_cycle(pg, where, key):
    """按一顆「?」：跳出 → 點背景關 → 再按 → Esc 關。回傳第一次打開時的狀態。"""
    sel = f'.howbtn.pop[data-how="{key}"]'
    pg.eval_on_selector(sel, "b => b.scrollIntoView({block:'center', behavior:'instant'})"); pg.wait_for_timeout(200)
    click(pg, sel, 400)
    st = pg.evaluate(POP_STATE)
    ok(f"[說明改問號] {where}「?」（{key}）按下去跳出說明、內容非空", st["open"] and st["back"] and st["len"] > 20, st)
    ok(f"[說明改問號] {where}「?」（{key}）說明框有標題", len(st["title"].strip()) >= 1, st["title"])
    pg.mouse.click(6, 300); pg.wait_for_timeout(300)
    st2 = pg.evaluate(POP_STATE)
    ok(f"[說明改問號] {where}「?」（{key}）點背景就關", not st2["open"] and not st2["back"], st2)
    ok(f"[說明改問號] {where}「?」（{key}）關了之後說明盒搬回卡片原位（#how-{key} 不在浮層裡）",
       pg.evaluate(f"() => {{ const b = document.getElementById('how-{key}'); return !!b && !b.closest('#howPop') && b.hidden; }}"))
    click(pg, sel, 350)
    pg.keyboard.press("Escape"); pg.wait_for_timeout(250)
    ok(f"[說明改問號] {where}「?」（{key}）按 Esc 也會關", not pg.evaluate(POP_STATE)["open"])
    return st


def t_wrap_popq(pg, base, code):
    """說明改問號：熱力圖頁、市場明細、週期統計、個股頁。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pages = [("heatmap", "#v-heatmap", None), ("heatmap/theme/cowos", "#v-heatmap", None),
             ("market/updown", "#v-market", None), ("market/ma", "#v-market", None), ("market/cand", "#v-market", None),
             ("season", "#v-season", None)] + \
            [(f"stock/{code}", "#v-industry", t) for t in ("overview", "revenue", "profit", "dividend", "chips", "basics", "news")]
    seen = set()
    for route, root, tab in pages:
        pg.goto(f"{base}#{route}", wait_until="networkidle"); pg.wait_for_timeout(2300)
        if tab:
            click(pg, f'#stockTabs button[data-t="{tab}"]', 1200)
        where = route + (f"／{tab}" if tab else "")
        lf = pg.evaluate(LEFTOVER, root)
        ok(f"[說明改問號] {where}：沒有舊式「怎麼看 ?」鈕", lf is not None and not lf["oldHow"], lf and lf["oldHow"])
        ok(f"[說明改問號] {where}：「?」鈕上只有一個問號", lf is not None and not lf["popTxt"], lf and lf["popTxt"])
        ok(f"[說明改問號] {where}：卡片標題不再有說明副標（只留名稱與資料讀數）", lf is not None and not lf["subs"], lf and lf["subs"])
        ok(f"[說明改問號] {where}：卡片下方沒有「其他題材／族群」連結列", lf is not None and not lf["linkrow"], lf and lf["linkrow"])
        for k in (lf or {}).get("pops", []):
            if k in seen and not tab:
                continue
            seen.add(k)
            _pop_cycle(pg, where, k)
    # ★ 2026-09-26 改前：清單含 skchain（個股頁「產業鏈位置」卡的「?」）→ 改後：那張卡整張拿掉（Andy），「?」跟著走
    want = {"indheat", "theme", "themedg", "mkt", "season", "kline", "mtf", "skchip", "skrev", "skrevy",
            "pe", "skeps", "skpeq", "skdiv", "skfill", "ms", "skmops", "sknews"}
    ok("[說明改問號] 這一批的「?」一顆都沒少", want <= seen, sorted(want - seen))
    # 市場明細：卡片上那行「總覽上方那幾個數字…」拿掉；盤後的定義句不再印、即時的警示句另外由 D4 段驗
    pg.goto(f"{base}#market/updown", wait_until="networkidle"); pg.wait_for_timeout(1800)
    ok("[說明改問號] 市場明細上方那行說明拿掉了", count(pg, "#mktNote") == 0)
    ok("[說明改問號] 盤後的漲停頁不再印「漲幅 ≥ 9.5%」那句（定義在「?」裡）",
       "9.5" not in text(pg, "#mktInner .kpinote") if count(pg, "#mktInner .kpinote") else True, text(pg, "#mktInner"))
    # ★ 2026-09-26 改前：驗「漲停＝漲幅 ≥ 9.5%」在「?」的附註裡 → 改後：「?」沒有附註段（Andy：「不需要附註」）
    _mf = how_fine(pg, "mkt")
    ok("[說明改問號] ★ 市場明細「?」只剩標題＋條列（沒有附註段）", bool(_mf) and _mf["n"] >= 1 and _mf["fine"] == 0 and not _mf["tail"], _mf)
    # 週期統計：卡片上的「基準：…」拿掉、搬進「?」
    pg.goto(f"{base}#season", wait_until="networkidle"); pg.wait_for_timeout(2200)
    ok("[說明改問號] 週期統計卡片上不再有「基準：…」", "基準" not in text(pg, "#seasonNote"), text(pg, "#seasonNote"))
    # ★ 2026-09-26 改前：基準在「?」的附註裡 → 改後：「?」不放附註，基準改掛在副標 #seasonRange 的滑鼠提示
    ok("[說明改問號] 週期統計的基準在副標的滑鼠提示（不在「?」裡）",
       "基準" in pg.evaluate("() => (document.getElementById('seasonRange') || {}).title || ''")
       and "基準" not in how_text(pg, "season"))
    # 題材剖析圖：「?」開著時點背景只關說明，剖析圖不能跟著被收掉（dismissable 要放過 #howBack）
    pg.goto(f"{base}#heatmap/theme/cowos", wait_until="networkidle"); pg.wait_for_timeout(2200)
    if ok("[說明改問號] 題材剖析圖打開了", count(pg, "#themeDiagram svg") > 0):
        pg.eval_on_selector('.howbtn.pop[data-how="themedg"]', "b => b.scrollIntoView({block:'center', behavior:'instant'})")
        click(pg, '.howbtn.pop[data-how="themedg"]', 400)
        pg.mouse.click(6, 300); pg.wait_for_timeout(500)
        ok("★ [說明改問號] 點背景關說明之後，題材剖析圖還在（沒有被當成點外面收掉）",
           count(pg, "#themeDiagram svg") > 0 and pg.evaluate("location.hash") == "#heatmap/theme/cowos", pg.evaluate("location.hash"))
        click(pg, '.howbtn.pop[data-how="themedg"]', 400)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(400)
        ok("★ [說明改問號] 按 Esc 關說明之後，題材剖析圖還在", count(pg, "#themeDiagram svg") > 0
           and not pg.evaluate(POP_STATE)["open"], pg.evaluate("location.hash"))
        # 換題材的路：點正上方題材熱力圖的另一塊，網址真的換、剖析圖換成那一個
        pg.evaluate("document.getElementById('themeMap').scrollIntoView({block:'center'})"); pg.wait_for_timeout(600)
        tiles = [v for v in (pg.evaluate(HM_LEAF_XY, {"id": "themeMap"}) or []) if v["key"] != "cowos"]
        tiles = [v for v in tiles if pg.evaluate("(k) => !!(window.ThemeDiagrams || {})[k]", v["key"])]
        if ok("[說明改問號] 題材熱力圖上有別的有剖析圖的方塊可點", bool(tiles)):
            h0 = pg.evaluate("location.hash")
            pg.mouse.click(tiles[0]["cx"], tiles[0]["cy"]); pg.wait_for_timeout(1500)
            changed("★ [說明改問號] 點題材熱力圖的別塊＝換題材（「其他題材」那排拿掉後的換法）", h0, pg.evaluate("location.hash"))


def t_flow_popq(pg, base, code):
    """資金流向頁說明改問號（claude/flow-howpop，2026-09-25）：四張卡（資金輪動、資金去向、族群×法人、集中度）
    的「怎麼看 ?」→ 標題旁「?」；副標、篩選列提示句、拓撲版圖例句搬進「?」。只驗桌機 1440（手機不在這批範圍）。
    每一顆都真的按：跳出 → 點背景關 → 再按 → Esc 關（_pop_cycle）；搬走的句子打開「?」讀得到（搬家不是刪除）。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(3000)
    lf = pg.evaluate(LEFTOVER, "#v-flow")
    ok("[資金流向問號] 沒有舊式「怎麼看 ?」鈕", lf is not None and not lf["oldHow"], lf and lf["oldHow"])
    ok("[資金流向問號] 「?」鈕上只有一個問號", lf is not None and not lf["popTxt"], lf and lf["popTxt"])
    ok("[資金流向問號] 卡片標題不再有說明副標（「錢往哪跑…」「族群在強弱循環…」拿掉）",
       lf is not None and not lf["subs"] and "錢往哪跑" not in text(pg, "#flowRotCard h3")
       and "強弱循環" not in text(pg, "#flowRotCard h4"), lf and lf["subs"])
    pops = (lf or {}).get("pops", [])
    ok("[資金流向問號] 四張卡各有一顆「?」、而且就在卡片標題裡", sorted(pops) == ["conc", "inst", "rot", "sankey"]
       and pg.evaluate("""() => ['flowRotCard:rot', 'flowSankeyCard:sankey', 'flowInstCard:inst', 'flowConcCard:conc'].every(x => {
            const [c, k] = x.split(':'); const b = document.querySelector(`#${c} .howbtn.pop[data-how="${k}"]`);
            return !!b && !!b.closest('h3'); })"""), pops)
    # 資料讀數留著：排行的日期區間、法人的區間、集中度的讀數、資金去向的日期與分母
    ok("[資金流向問號] 排行的日期區間讀數還在（M/D ～ M/D）", bool(re.search(r"\d+/\d+\s*～\s*\d+/\d+", text(pg, "#rankSub"))), text(pg, "#rankSub"))
    ok("[資金流向問號] 資金去向的讀數還在（% 佔上一層）", "佔上一層" in text(pg, "#sankeySub"), text(pg, "#sankeySub"))
    ok("[資金流向問號] 族群×法人的區間讀數還在", "日" in text(pg, "#instSub") and "～" in text(pg, "#instSub"), text(pg, "#instSub"))
    cs = text(pg, "#concState")
    ok("[資金流向問號] 集中度讀數縮成一行（≤ 26 字、沒有「冷門股／主流容易休息」解讀句）",
       0 < len(cs) <= 26 and "冷門股" not in cs and "休息" not in cs, cs)
    # 篩選列的操作說明句與拓撲版圖例句不再印在卡片上
    ok("[資金流向問號] 篩選列不再印「先挑產業鏈，再挑一個族群…」", "先挑產業鏈" not in text(pg, "#v-flow"), text(pg, "#flowSankeyCard")[:120])
    ok("[資金流向問號] 資金去向圖上方不再印「粒子＝資金流動…」圖例句", "粒子＝資金流動" not in text(pg, "#flowSankeyCard"))
    for k in ("rot", "sankey", "inst", "conc"):
        st = _pop_cycle(pg, "flow", k)
        ttl = {"rot": "資金輪動", "sankey": "資金去向", "inst": "族群 × 法人", "conc": "資金集中度"}[k]
        ok(f"[資金流向問號] 「?」（{k}）說明框標題是卡片名「{ttl}」", st["title"].strip() == ttl, st["title"])
    # 點背景關的時候，底下的輪盤／排行／桑基狀態不能被當成「點外面」收掉：先開成分股面板，再開關「?」
    ok("[資金流向問號] 關掉「?」之後頁面還在 #flow、沒有殘留背景", pg.evaluate("location.hash") == "#flow"
       and not pg.evaluate(POP_STATE)["back"])
    # 搬家不是刪除
    # ★ 2026-09-26（Andy：「"?" 內說明欄下方的更詳細說明不需要附註」）：
    #   改前：驗篩選說明／粒子圖例／「休息」那句附註搬進「?」→ 改後：三顆「?」都只剩標題＋條列
    for _k in ("sankey", "inst", "conc"):
        _f = how_fine(pg, _k)
        ok(f"[資金流向問號] ★「?」（{_k}）只剩標題＋條列、沒有附註段", bool(_f) and _f["n"] >= 1 and _f["fine"] == 0 and not _f["tail"], _f)
    ok("[資金流向問號] 集中度的讀法（冷門股）還在條列裡", "冷門股" in how_text(pg, "conc"))
    ok("[資金流向問號] 集中度讀數的解讀句滑上去看得到（title）", len(pg.evaluate("() => document.getElementById('concState').title || ''")) > 4)
    # 選了族群時，篩選列只留狀態讀數「只看「X」」（不寫圖只剩一支會被讀成資料壞掉）
    pg.evaluate("() => document.getElementById('flowSankeyCard').scrollIntoView({block:'start', behavior:'instant'})"); pg.wait_for_timeout(300)
    if count(pg, '#flowSankeyCard .rotdd[data-dd="group"] .ddbtn'):
        click(pg, '#flowSankeyCard .rotdd[data-dd="group"] .ddbtn', 400)
        opt = pg.evaluate("""() => { const b = document.querySelector('#flowSankeyCard .rotdd[data-dd="group"] .ddopt .nm[data-g]'); return b ? b.textContent.trim() : ''; }""")
        if ok("[資金流向問號] 族群下拉有選項可選", bool(opt), opt):
            click(pg, '#flowSankeyCard .rotdd[data-dd="group"] .ddopt .nm[data-g]', 900)
            t = text(pg, "#flowSankeyCard .ddrow")
            ok("[資金流向問號] 選了族群：篩選列寫「只看「X」」、不再附長句", f"只看「{opt}」" in t and "回到整張圖" not in t, t[-80:])
            pg.keyboard.press("Escape"); pg.wait_for_timeout(600)


def t_stock_0926(pg, base, code):
    """個股 K 線四件（Andy 2026-09-26）的真人操作驗收：
      ① 「將所有指標納入在 Setting，並且以下拉清單形式呈現」—— 打開下拉 → 關 KD → KD 副圖真的消失 →
         展開 MACD 改參數 → 圖真的變 → 重新整理後記住
      ② 「四週期成交量呢？」—— 四張小圖都有量副圖（約 20% 高）、關成交量四張一起消失、滑過看板寫量
      ③ 「將這兩個指標拿掉」（SMC 區間、BOS/CHoCH）—— 清單、主圖、小圖都沒有
      ④ 「幫我將縮放放到圖上位置」—— 重設縮放在主圖右下角、四週期每張小圖各一顆，按了真的回原位
    每一條都驗「畫面真的因此變了」（副圖數、canvas 指紋、圖例文字、localStorage），不是驗元素存在。"""
    DBG = "() => window.Industry._dbg()"
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#overview", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.removeItem('tw.kcfg'); } catch (e) {} }")   # 從預設開始，才知道「改了」是誰改的
    pg.goto(f"{base}#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(2600)
    if not ok("[0926] 個股頁 K 線畫得出來（前提）", count(pg, "#lwc canvas") > 0):
        return

    # ---------------------------------------------------------------- ① 指標下拉
    btn0 = text(pg, "#indBtn")
    ok("[0926-①] 工具列只剩一顆「指標 ▾」，寫著已開幾個", "指標" in btn0 and "已開" in btn0, btn0)
    ok("[0926-①] 那一整排指標晶片與「⚙ 設定」都拿掉了", count(pg, "#indChips") == 0 and count(pg, "#cfgBtn") == 0)
    click(pg, "#indBtn", 500)
    ok("[0926-①] 點「指標 ▾」→ 清單真的打開", pg.evaluate(IND_POP_OPEN))
    ok("[0926-①] 按鈕標成展開（aria-expanded）", pg.get_attribute("#indBtn", "aria-expanded") == "true")
    rows = pg.evaluate("() => [...document.querySelectorAll('#cfgPop .indrow')].map(r => r.dataset.k)")
    ok("[0926-①] 最上面一列是「整體」（線寬／K 棒寬度）", bool(rows) and rows[0] == "base", rows)
    ok("[0926-③] 清單裡沒有 SMC 區間、BOS/CHoCH", "smc" not in rows and "marks" not in rows, rows)
    # 關 KD → KD 副圖真的消失
    p0 = pg.evaluate(DBG)["paneH"] or {}
    h0 = canvas_hash(pg, "#lwc")
    ok("[0926-①] KD 預設是開的、而且有自己的副圖（前提）", ind_on(pg, "kd") is True and "kd" in p0, p0)
    ind_toggle(pg, "kd", 900)
    p1 = pg.evaluate(DBG)["paneH"] or {}
    ok("[0926-①] 在清單裡把 KD 關掉 → 勾選框真的取消", ind_on(pg, "kd") is False)
    ok("★ [0926-①] 關 KD → KD 副圖真的消失（副圖少一格）", "kd" not in p1 and len(p1) == len(p0) - 1, f"{p0} → {p1}")
    changed("[0926-①] 關 KD 之後 K 線圖真的重畫", h0, canvas_hash(pg, "#lwc"))
    ok("[0926-①] 按鈕上的「已開 N」跟著少一個", text(pg, "#indBtn") != btn0, f"{btn0} → {text(pg, '#indBtn')}")
    ok("[0926-①] 清單還開著（在裡面點不會把自己關掉）", pg.evaluate(IND_POP_OPEN))
    # 展開 MACD 改參數 → 圖真的變
    ok("[0926-①] MACD 那一列按 ▸ → 就地展開", ind_expand(pg, "macd"))
    ok("[0926-①] 展開後有快線／慢線／訊號三格參數＋顏色線寬透明度",
       count(pg, '#cfgPop .indrow[data-k="macd"] .prow input[data-p]') == 3
       and count(pg, '#cfgPop .indrow[data-k="macd"] .strow input[type=color]') == 2)
    h1 = canvas_hash(pg, "#lwc")
    inp = pg.query_selector('#cfgPop .indrow[data-k="macd"] input[data-p=f]')
    inp.fill("8"); inp.press("Enter"); pg.wait_for_timeout(900)
    lab = pg.evaluate("() => (document.getElementById('lwc') || {}).innerText || ''").replace(" ", "")
    changed("★ [0926-①] 改 MACD 快線 12→8，K 線圖真的重畫", h1, canvas_hash(pg, "#lwc"))
    ok("★ [0926-①] MACD 副圖標題真的變成 MACD(8,26,9)", "MACD(8,26,9)" in lab, lab[-160:])
    ok("[0926-①] 清單那一列的參數摘要跟著變 8,26,9", "8,26,9" in text(pg, '#cfgPop .indrow[data-k="macd"] .isum'),
       text(pg, '#cfgPop .indrow[data-k="macd"] .isum'))
    # 亂填超出範圍的數字 → 退回原值、不把指標弄壞
    inp = pg.query_selector('#cfgPop .indrow[data-k="macd"] input[data-p=s]')
    inp.fill("0"); inp.press("Enter"); pg.wait_for_timeout(500)
    ok("[0926-①] 慢線填 0（範圍外）→ 退回原本的 26、圖例不變", inp.input_value() == "26"
       and "MACD(8,26,9)" in pg.evaluate("() => (document.getElementById('lwc') || {}).innerText || ''").replace(" ", ""), inp.input_value())
    # 關著的指標也能先調參數，打開時沿用（KD 關著 → 調 5 → 打開就是 5,3,3）
    ind_expand(pg, "kd")
    kin = pg.query_selector('#cfgPop .indrow[data-k="kd"] input[data-p=n]')
    kin.fill("5"); kin.press("Enter"); pg.wait_for_timeout(500)
    ok("[0926-①] KD 關著時改參數不會自己打開", ind_on(pg, "kd") is False)
    ind_toggle(pg, "kd", 900)
    lab2 = pg.evaluate("() => (document.getElementById('lwc') || {}).innerText || ''").replace(" ", "")
    ok("[0926-①] 再打開 KD → 沿用剛剛調的 KD(5,3,3)（關著調的參數沒被丟掉）", "KD(5,3,3)" in lab2, lab2[-160:])
    ind_toggle(pg, "kd", 900)     # 再關掉，下面驗「重新整理後記住」
    # 點外面就關、Esc 也關
    pg.click("#pxNow"); pg.wait_for_timeout(450)     # 點頁面上一塊不是連結的地方（股價數字）＝點外面
    ok("[0926-①] 點清單外面 → 清單收起來", not pg.evaluate(IND_POP_OPEN))
    ok("[0926-①] 收起來後按鈕標成收合", pg.get_attribute("#indBtn", "aria-expanded") == "false")
    click(pg, "#indBtn", 450); pg.keyboard.press("Escape"); pg.wait_for_timeout(400)
    ok("[0926-①] 按 Esc 也會關", not pg.evaluate(IND_POP_OPEN))
    # 重新整理後記住（等圖真的畫好、副圖標題出來才讀，不然讀到的是「還沒畫」的空白 —— 那不是「記住了」）
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1200)
    wait_until(pg, "() => /MACD\\(/.test((document.querySelector('#lwc .pane-labels') || {}).innerText || '')", 8000)
    p2 = pg.evaluate(DBG)["paneH"] or {}
    ok("[0926-①] 重新整理後副圖都畫出來了（前提）", len(p2) >= 3, p2)
    lab3 = pg.evaluate("() => (document.getElementById('lwc') || {}).innerText || ''").replace(" ", "")
    ok("★ [0926-①] 重新整理後 KD 還是關的（沒有 KD 副圖）", "kd" not in p2, p2)
    ok("★ [0926-①] 重新整理後 MACD 還是 (8,26,9)", "MACD(8,26,9)" in lab3, lab3[-160:])
    ok("[0926-①] 重新整理後清單裡 KD 沒勾、MACD 摘要是 8,26,9",
       ind_on(pg, "kd") is False and "8,26,9" in text(pg, '#cfgPop .indrow[data-k="macd"] .isum'))
    ind_close(pg)
    # 主圖上沒有 SMC 區塊與 BOS／CHoCH（舊 localStorage 帶著 smc:true 也一樣）
    pg.evaluate("() => { const c = JSON.parse(localStorage.getItem('tw.kcfg') || '{}'); c.smc = true; c.marks = true;"
                " c.zone = { fill: 40 }; localStorage.setItem('tw.kcfg', JSON.stringify(c)); }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    wait_until(pg, "() => !!document.getElementById('fitBtn') && !!document.querySelector('#lwc canvas')", 6000)
    d = pg.evaluate(DBG)
    ok("★ [0926-③] 舊存檔寫著 smc／marks:true，主圖照樣沒有 SMC 區塊、區間標籤、BOS／CHoCH／掃蕩標記",
       not d.get("zoneCount") and not (d.get("zoneLabels") or []) and not (d.get("markers") or []),
       {k: d.get(k) for k in ("zoneCount",)} | {"標籤": len(d.get("zoneLabels") or []), "標記": len(d.get("markers") or [])})

    # ---------------------------------------------------------------- ④ 重設縮放搬進圖裡
    fg = pg.evaluate("""() => { const b = document.getElementById('fitBtn'), l = document.getElementById('lwc');
        if (!b || !l) return null; const r = b.getBoundingClientRect(), lr = l.getBoundingClientRect();
        const kc = window.KChart.last; const mh = kc.chart.panes()[0].getHeight(), pw = kc.chart.priceScale('right').width();
        return { inChart: l.contains(b), tools: !!document.querySelector('#skTools #fitBtn'), right: lr.right - r.right,
                 bottom: r.bottom - lr.top, mh, pw, op: +getComputedStyle(b).opacity, title: b.title }; }""")
    ok("★ [0926-④] 重設縮放鈕在 K 線圖裡、工具列上那顆拿掉了", bool(fg) and fg["inChart"] and not fg["tools"], fg)
    if fg:
        ok("★ [0926-④] 它在主圖右下角：價格軸左邊、成交量副圖上方", fg["pw"] <= fg["right"] <= fg["pw"] + 20
           and fg["mh"] - 16 <= fg["bottom"] <= fg["mh"], fg)
        ok("[0926-④] 平常是半透明（不搶 K 棒的眼）、有滑鼠提示", fg["op"] < 0.8 and "縮放" in fg["title"], fg)
        pg.hover("#fitBtn"); pg.wait_for_timeout(300)
        ok("[0926-④] 滑過變亮", pg.evaluate("() => +getComputedStyle(document.getElementById('fitBtn')).opacity") > 0.9)
    r = pg.evaluate("() => { const b = document.getElementById('lwc').getBoundingClientRect(); return {x:b.x,y:b.y,w:b.width,h:b.height}; }")
    vb0 = pg.evaluate(DBG)["visibleBars"]
    pg.mouse.move(r["x"] + r["w"] * 0.5, r["y"] + r["h"] * 0.3)
    pg.mouse.wheel(0, -600); pg.wait_for_timeout(500)
    vb1 = pg.evaluate(DBG)["visibleBars"]
    click(pg, "#fitBtn", 800)
    vb2 = pg.evaluate(DBG)["visibleBars"]
    changed("[0926-④] 滾輪縮放之後畫面裡的根數真的變了（前提）", vb0, vb1)
    changed("★ [0926-④] 按圖上右下角的重設鈕 → 畫面裡的根數真的回來", vb1, vb2)
    ok("[0926-④] 按重設鈕不會在圖上多畫一筆線", pg.evaluate(DBG)["shapes"] in (0, -1), pg.evaluate(DBG)["shapes"])
    # 拖副圖分隔線之後，重設鈕跟著主圖的新高度走（不會停在舊位置蓋到成交量）
    mh0 = pg.evaluate("() => window.KChart.last.chart.panes()[0].getHeight()")
    sep_y = r["y"] + mh0 + 1
    pg.mouse.move(r["x"] + r["w"] * 0.4, sep_y); pg.mouse.down()
    pg.mouse.move(r["x"] + r["w"] * 0.4, sep_y - 80, steps=6); pg.mouse.up(); pg.wait_for_timeout(500)
    fg2 = pg.evaluate("""() => { const b = document.getElementById('fitBtn'), l = document.getElementById('lwc');
        const r = b.getBoundingClientRect(), lr = l.getBoundingClientRect();
        return { bottom: r.bottom - lr.top, mh: window.KChart.last.chart.panes()[0].getHeight() }; }""")
    if abs(fg2["mh"] - mh0) > 20:
        ok("[0926-④] 拖副圖分隔線後，重設鈕跟著貼到新的主圖右下角", fg2["mh"] - 16 <= fg2["bottom"] <= fg2["mh"], {"原主圖高": mh0, **fg2})
    click(pg, "#fitBtn", 600)

    # ---------------------------------------------------------------- ② 四週期成交量
    click(pg, "#mtfBtn", 2400)
    mini = pg.evaluate(DBG).get("mini") or []
    drawn = [m for m in mini if m["bars"] >= 2]
    ok("[0926-②] 四週期同看排出四格、至少兩格有 K 棒（前提）", count(pg, ".mtf-cell") == 4 and len(drawn) >= 2, mini)
    ok("★ [0926-②] 每一張有 K 棒的小圖都有成交量副圖", bool(drawn) and all(m["vol"] for m in drawn), mini)
    ok("★ [0926-②] 量副圖約佔圖高 18～22%", bool(drawn) and all(0.16 <= m["volShare"] <= 0.24 for m in drawn),
       [m["volShare"] for m in drawn])
    ok("★ [0926-③] 四張小圖都沒有 SMC 區塊、BOS／CHoCH 標記", all(m["zones"] == 0 and m["markers"] == 0 for m in mini), mini)
    ok("[0926-②] 小圖的量軸單位是「張」", "張" in pg.evaluate("() => document.getElementById('mtfGrid').innerText") or
       pg.evaluate("""() => [...document.querySelectorAll('#mtfGrid canvas')].length > 0"""))
    ok("[0926-④] 四週期每張小圖右下角各有一顆重設鈕", count(pg, "#mtfGrid .mtf-cell .kfit") == len(drawn),
       count(pg, "#mtfGrid .mtf-cell .kfit"))
    # 滑過 → 看板寫量
    cv = pg.evaluate("() => { const b = document.getElementById('mini-0').getBoundingClientRect(); return {x:b.x,y:b.y,w:b.width,h:b.height}; }")
    pg.mouse.move(cv["x"] + cv["w"] * 0.55, cv["y"] + cv["h"] * 0.45); pg.wait_for_timeout(400)
    t1 = text(pg, "#mtip-0")
    ok("★ [0926-②] 滑過小圖 → 游標看板出現、寫著那一根的量（張）", "量" in t1 and "張" in t1
       and pg.evaluate("() => !document.getElementById('mtip-0').hidden"), t1)
    pg.mouse.move(cv["x"] + cv["w"] * 0.25, cv["y"] + cv["h"] * 0.45); pg.wait_for_timeout(400)
    changed("[0926-②] 換一根 K 棒，看板裡的時間／量跟著換", t1, text(pg, "#mtip-0"))
    # 小圖的重設鈕：先滾輪縮放那一張，再按它的重設鈕
    hm0 = canvas_hash(pg, "#mini-0")
    pg.mouse.wheel(0, -500); pg.wait_for_timeout(400)
    hm1 = canvas_hash(pg, "#mini-0")
    click(pg, "#mini-0 .kfit", 600)
    changed("[0926-④] 小圖滾輪縮放真的變了（前提）", hm0, hm1)
    changed("★ [0926-④] 按小圖右下角的重設鈕 → 那一張真的回到預設取景", hm1, canvas_hash(pg, "#mini-0"))
    pg.mouse.move(5, 5)
    # 在四週期模式從下拉把「成交量」關掉 → 四張一起消失；再打開 → 四張都回來
    ok("[0926-②] 四週期模式下，下拉裡 KD 那幾列標著「四週期不畫」",
       ind_open(pg) and "四週期不畫" in text(pg, '#cfgPop .indrow[data-k="kd"]'))
    hg0 = canvas_hash(pg, "#mtfGrid")
    ind_toggle(pg, "vol", 900)
    m_off = pg.evaluate(DBG).get("mini") or []
    ok("★ [0926-②] 關「成交量」→ 四張小圖的量副圖一起消失", all(not m["vol"] for m in m_off), m_off)
    changed("[0926-②] 關成交量之後小圖真的重畫", hg0, canvas_hash(pg, "#mtfGrid"))
    ind_toggle(pg, "vol", 900)
    m_on = pg.evaluate(DBG).get("mini") or []
    ok("[0926-②] 再打開 → 四張都回來", all(m["vol"] for m in m_on if m["bars"] >= 2), m_on)
    ind_close(pg)
    # 回單一週期
    click(pg, "#mtfBtn", 1600)
    ok("[0926] 切回單一週期，K 線圖回得來", count(pg, "#lwc canvas") > 0)

    # 1 小時／4 小時：4 小時一根的量＝四根 1 小時量的總和（合成時量一起加總）。
    # 本機 payload 常是 SKIP_INTRADAY 建的、沒有 60 分 K，所以這裡**自己餵一份** 1 小時 K 進去（量刻意每根不同），
    # 再真的用下拉把兩格換成 1 小時／4 小時 —— 不然這條在本機永遠被跳過，等於沒驗。
    def feed60(route):
        resp = route.fetch(); j = resp.json()
        bars, k = [], 0
        for dd in range(1, 21):
            for hh in (9, 10, 11, 12, 13):
                k += 1; px = 100 + k * 0.5
                bars.append([f"2026-08-{dd:02d}T{hh:02d}:00:00+08:00", px, px + 1, px - 1, px + 0.3, 1000 * (k * 7 % 23 + 1)])
        j.setdefault("intraday", {})["60m"] = bars
        route.fulfill(response=resp, body=json.dumps(j, ensure_ascii=False), headers={**resp.headers, "content-type": "application/json; charset=utf-8"})
    pg.route(f"**/data/stock/{code}.json*", feed60)
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1500)
    click(pg, "#mtfBtn", 2000)
    pg.select_option("#mtfGrid select.mtfsel >> nth=0", "60m"); pg.wait_for_timeout(1200)
    pg.select_option("#mtfGrid select.mtfsel >> nth=1", "240m"); pg.wait_for_timeout(1200)
    mm = pg.evaluate(DBG).get("mini") or []
    h1 = next((m for m in mm if m["tf"] == "60m"), None)
    h4 = next((m for m in mm if m["tf"] == "240m"), None)
    if ok("[0926-②] 用下拉換成 1 小時／4 小時，兩格都畫得出來（前提）", bool(h1 and h4 and h1["bars"] >= 8 and h4["bars"] >= 2),
          [(m["tf"], m["bars"]) for m in mm]):
        ok("★ [0926-②] 1 小時與 4 小時兩格都有量副圖", h1["vol"] and h4["vol"], [h1, h4])
        ok("★ [0926-②] 4 小時第一根的量＝前四根 1 小時量的總和", h4["v4"][0] == sum(h1["v4"][:4]) and h4["v4"][0] > 0,
           {"1H 前四根": h1["v4"], "4H 第一根": h4["v4"][0]})
    pg.unroute(f"**/data/stock/{code}.json*")
    click(pg, "#mtfBtn", 1400)
    pg.evaluate("() => { try { const c = JSON.parse(localStorage.getItem('tw.kcfg') || '{}'); delete c.mtfTfs; localStorage.setItem('tw.kcfg', JSON.stringify(c)); } catch (e) {} }")

    # ---------------------------------------------------------------- 窄畫面：800／390
    for vw in (800, 390):
        pg.set_viewport_size({"width": vw, "height": 900})
        pg.goto(f"{base}#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(2400)
        click(pg, "#indBtn", 500)
        for k in ("base", "ma", "macd"):
            ind_expand(pg, k)
        geo = pg.evaluate("""() => { const p = document.getElementById('cfgPop'), r = p.getBoundingClientRect();
            return { l: r.left, r: r.right, t: r.top, b: r.bottom, vw: innerWidth, vh: innerHeight,
                     sh: p.scrollHeight, ch: p.clientHeight, oy: getComputedStyle(p).overflowY,
                     hs: document.documentElement.scrollWidth > innerWidth + 1 }; }""")
        ok(f"[0926-{vw}px] 指標清單整塊在螢幕裡（左右上下都不超出）",
           geo["l"] >= 0 and geo["r"] <= geo["vw"] + 1 and geo["t"] >= 0 and geo["b"] <= geo["vh"] + 1, geo)
        ok(f"[0926-{vw}px] 展開三列之後清單比畫面長 → 清單自己可以捲", geo["sh"] <= geo["ch"] + 1 or geo["oy"] in ("auto", "scroll"), geo)
        ok(f"[0926-{vw}px] 沒有橫向捲軸", not geo["hs"], geo)
        small = pg.evaluate("""() => [...document.querySelectorAll('#cfgPop *')].filter(e => e.childNodes.length && [...e.childNodes].some(n => n.nodeType === 3 && n.textContent.trim())
            && e.getClientRects().length).map(e => ({ t: e.textContent.trim().slice(0, 10), f: parseFloat(getComputedStyle(e).fontSize) })).filter(x => x.f < 11)""")
        ok(f"[0926-{vw}px] 清單裡沒有小於 11px 的字", not small, small[:4])
        # 捲到最下面點得到「本益比河流」那一列的開關
        on0 = ind_on(pg, "peRiver")
        ind_toggle(pg, "peRiver", 700)
        changed(f"[0926-{vw}px] 捲到清單最下面點「本益比河流」→ 真的切換", on0, ind_on(pg, "peRiver"))
        ind_toggle(pg, "peRiver", 500)
        ind_close(pg)
        fgn = pg.evaluate("""() => { const b = document.getElementById('fitBtn'), l = document.getElementById('lwc');
            if (!b || !l) return null; const r = b.getBoundingClientRect(), lr = l.getBoundingClientRect();
            return { in: r.left >= lr.left && r.right <= lr.right && r.top >= lr.top && r.bottom <= lr.bottom, w: r.width }; }""")
        ok(f"[0926-{vw}px] 重設縮放鈕在圖裡面、沒被切掉", bool(fgn) and fgn["in"] and fgn["w"] >= 20, fgn)
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.evaluate("() => { try { localStorage.removeItem('tw.kcfg'); } catch (e) {} }")


def t_wrap_adj(pg, base, code):
    """還原小標：K 線右上角「還原」、滑過說明（還原價 vs 原始價、最近一次事件）。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    c6 = "6669"
    pg.goto(f"{base}#stock/{c6}", wait_until="networkidle"); pg.wait_for_timeout(2600)
    pa = pg.evaluate(f"() => fetch('data/stock/{c6}.json').then(r => r.json()).then(d => d.price_adjust).catch(() => null)")
    if not ok("[還原小標] 6669 的資料有 price_adjust.daily_adjusted", bool(pa) and pa.get("daily_adjusted"), pa and list(pa)):
        return
    t = pg.evaluate("""() => { const e = document.getElementById('adjTag'), w = document.getElementById('chartWrap'); if (!e || !w) return null;
        const r = e.getBoundingClientRect(), R = w.getBoundingClientRect(), tip = e.querySelector('.adjtip');
        return { txt: e.firstChild.textContent.trim(), right: Math.round(R.right - r.right), top: Math.round(r.top - R.top),
                 fs: parseFloat(getComputedStyle(e).fontSize), tipShown: getComputedStyle(tip).display !== 'none' }; }""")
    ok("[還原小標] K 線圖角落有「還原」小標", bool(t) and t["txt"] == "還原", t)
    ok("[還原小標] 小標在圖的右上角（離右緣 ≤ 120px、離上緣 ≤ 20px）、字 ≥ 11px",
       bool(t) and 0 <= t["right"] <= 120 and 0 <= t["top"] <= 20 and t["fs"] >= 11, t)
    ok("[還原小標] 沒滑過時說明是收起來的", bool(t) and not t["tipShown"], t)
    pg.hover("#adjTag"); pg.wait_for_timeout(300)
    tip = pg.evaluate("""() => { const tip = document.querySelector('#adjTag .adjtip'); const r = tip.getBoundingClientRect();
        return { shown: getComputedStyle(tip).display !== 'none', txt: tip.innerText, l: r.left, rr: r.right, w: innerWidth }; }""")
    ok("★ [還原小標] 滑過：說明真的出現", tip["shown"], tip)
    ok("[還原小標] 說明寫清楚「K 線與均線用除權息還原價；報價與漲跌是原始價」",
       "還原價" in tip["txt"] and "原始價" in tip["txt"], tip["txt"][:80])
    ev = [e for e in pa.get("events") or [] if e and e[0]]
    if ev:
        last = ev[-1]
        ok(f"[還原小標] 列出最近一次還原事件的日期（{last[0]}）", last[0] in tip["txt"], tip["txt"])
        if float(last[2] or 0) > 0:
            ok("[還原小標] 最近一次是除權：寫出配股比例（1:1.98）", "配股比例 1:" in tip["txt"] and "1.98" in tip["txt"], tip["txt"])
    ok("[還原小標] 說明框不出畫面", tip["l"] >= 0 and tip["rr"] <= tip["w"], tip)
    pg.mouse.move(5, 500); pg.wait_for_timeout(250)
    ok("[還原小標] 滑開就收起", not pg.evaluate("() => getComputedStyle(document.querySelector('#adjTag .adjtip')).display !== 'none'"))
    # 鍵盤也叫得出來（tabindex＋:focus）
    pg.focus("#adjTag"); pg.wait_for_timeout(200)
    ok("[還原小標] 鍵盤 focus 也看得到說明", pg.evaluate("() => getComputedStyle(document.querySelector('#adjTag .adjtip')).display !== 'none'"))
    pg.evaluate("() => document.activeElement && document.activeElement.blur()")
    # 淺色主題看得見（字色對底色有差）
    pg.evaluate("() => { document.documentElement.dataset.theme = 'light'; }"); pg.wait_for_timeout(300)
    cc = pg.evaluate("""() => { const e = document.getElementById('adjTag'); const cs = getComputedStyle(e);
        return { c: cs.color, bg: cs.backgroundColor }; }""")
    ok("[還原小標] 淺色主題下字色與底色不同（看得見）", cc["c"] != cc["bg"], cc)
    pg.evaluate("() => { delete document.documentElement.dataset.theme; }")


def t_wrap_season_tip(pg, base, code):
    """週期統計「本月最強」提示框：多寫中位數與勝率；排序不變。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#season", wait_until="networkidle"); pg.wait_for_timeout(2400)
    # 熱力圖：滑到第一列本月那一格，提示框多一列「報酬中位數」
    cell = pg.evaluate("""() => { const el = document.getElementById('seasonHeat'); const c = echarts.getInstanceByDom(el); if (!c) return null;
        const d = c.getOption().series[0].data; const m = (new Date()).getMonth();
        const x = d.find(q => q.value[1] === 0 && q.value[0] === m) || d[0];
        const p = c.convertToPixel({ seriesIndex: 0 }, [x.value[0], x.value[1]]); const r = el.getBoundingClientRect();
        return { x: r.left + p[0], y: r.top + p[1], med: x.c && x.c.median_return }; }""")
    order0 = pg.evaluate("() => echarts.getInstanceByDom(document.getElementById('seasonHeat')).getOption().yAxis[0].data.slice(0, 5)")
    if ok("[週期統計提示框] 熱力圖有格子可滑", bool(cell), cell):
        pg.mouse.move(cell["x"], cell["y"]); pg.wait_for_timeout(500)
        tt = pg.evaluate("() => document.getElementById('seasonHeat').innerText")
        ok("★ [週期統計提示框] 熱力圖提示框有「報酬中位數」", "報酬中位數" in tt, tt[:160])
        ok("[週期統計提示框] 熱力圖提示框仍有「勝率」", "勝率" in tt, tt[:160])
    # 曲線圖（預設「本月最強 5」）：每條線後面接「中位 … ・ 超額勝率 …」
    click(pg, '#seasonView button[data-v="line"]', 1400)
    pt = pg.evaluate("""() => { const el = document.getElementById('seasonLine'); const c = echarts.getInstanceByDom(el); if (!c) return null;
        const m = (new Date()).getMonth(); const o = c.getOption();
        const s = o.series.find((q, i) => i > 0 && (o.legend[0].selected || {})[q.name] !== false && q.data[m] != null); if (!s) return null;
        const p = c.convertToPixel({ xAxisIndex: 0, yAxisIndex: 0 }, [m, s.data[m]]); const r = el.getBoundingClientRect();
        return { x: r.left + p[0], y: r.top + p[1] }; }""")
    if ok("[週期統計提示框] 曲線圖有線可滑", bool(pt), pt):
        pg.mouse.move(pt["x"], pt["y"]); pg.wait_for_timeout(500)
        tt = pg.evaluate("() => document.getElementById('seasonLine').innerText")
        ok("★ [週期統計提示框] 曲線圖提示框每條線寫出「中位」", "中位" in tt, tt[:200])
        ok("★ [週期統計提示框] 看超額報酬時寫「超額勝率」", "超額勝率" in tt, tt[:200])
        click(pg, '#seasonMetric button[data-v="avg_return"]', 1300)
        pg.mouse.move(5, 500); pg.wait_for_timeout(200)
        pt2 = pg.evaluate("""() => { const el = document.getElementById('seasonLine'); const c = echarts.getInstanceByDom(el);
            const m = (new Date()).getMonth(); const o = c.getOption();
            const s = o.series.find((q, i) => i > 0 && (o.legend[0].selected || {})[q.name] !== false && q.data[m] != null); if (!s) return null;
            const p = c.convertToPixel({ xAxisIndex: 0, yAxisIndex: 0 }, [m, s.data[m]]); const r = el.getBoundingClientRect();
            return { x: r.left + p[0], y: r.top + p[1] }; }""")
        if pt2:
            pg.mouse.move(pt2["x"], pt2["y"]); pg.wait_for_timeout(500)
            tt2 = pg.evaluate("() => document.getElementById('seasonLine').innerText")
            ok("[週期統計提示框] 切到絕對報酬：寫「勝率」（上漲年數比例）", "勝率" in tt2 and "中位" in tt2, tt2[:200])
        click(pg, '#seasonMetric button[data-v="avg_excess"]', 1000)
    click(pg, '#seasonView button[data-v="heat"]', 1200)
    order1 = pg.evaluate("() => echarts.getInstanceByDom(document.getElementById('seasonHeat')).getOption().yAxis[0].data.slice(0, 5)")
    ok("[週期統計提示框] 排序沒有被改（前 5 列跟原本一樣）", order0 == order1, [order0, order1])
    # R4：800 寬選「全部」，框的高度要完整落在頂列與底部分頁列之間（框底不被分頁列蓋住）
    pg.set_viewport_size({"width": 800, "height": 900})
    pg.goto(f"{base}#season", wait_until="networkidle"); pg.wait_for_timeout(2200)
    click(pg, '#seasonRows button[data-v="all"]', 1200)
    bx = pg.evaluate("""() => { const b = document.getElementById('seasonHeatBox'); const t = document.querySelector('.tabs');
        const tr = t ? t.getBoundingClientRect() : { top: innerHeight, height: 0 };
        return { h: b.getBoundingClientRect().height, sh: b.scrollHeight, vh: innerHeight, tabsTop: Math.round(tr.top), tabsH: Math.round(tr.height) }; }""")
    ok("★ [R4 收尾] 800 寬「全部」：週期統計框的高度 ≤ 視窗扣掉頂列與底部分頁列（捲到框底看得到最後一列）",
       bx["sh"] > bx["h"] and bx["h"] <= bx["vh"] - 58 - bx["tabsH"] + 2, bx)
    pg.evaluate("() => { const b = document.getElementById('seasonHeatBox'); b.scrollIntoView({ block: 'start', behavior: 'instant' }); window.scrollBy({ top: -70, behavior: 'instant' }); b.scrollTop = b.scrollHeight; }")
    pg.wait_for_timeout(300)
    vis = pg.evaluate("""() => { const b = document.getElementById('seasonHeatBox').getBoundingClientRect(); const t = document.querySelector('.tabs').getBoundingClientRect();
        return { boxBottom: Math.round(b.bottom), tabsTop: Math.round(t.top) }; }""")
    ok("[R4 收尾] 800 寬：框捲到最底、把框捲到頂列下方時，框底在底部分頁列之上", vis["boxBottom"] <= vis["tabsTop"] + 1, vis)
    click(pg, '#seasonRows button[data-v="20"]', 800)
    pg.set_viewport_size({"width": 1440, "height": 1000})


def t_wrap_r4_label(pg, base, code):
    """R4 收尾：產業熱力中型方塊（高 ≥ 44、寬夠放數值）要寫數值，不再只寫名字。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#heatmap", wait_until="networkidle"); pg.wait_for_timeout(2600)
    r = pg.evaluate("""() => { const el = document.getElementById('indTree'); const c = el && echarts.getInstanceByDom(el); if (!c) return null;
        const cv = document.createElement('canvas').getContext('2d'); cv.font = '700 12px Noto Sans TC, JetBrains Mono, sans-serif';
        const bad = [], two = []; c.getModel().getSeriesByIndex(0).getData().tree.root.eachNode(n => {
          if (n.children && n.children.length) return; const o = n.getModel().option || {}; const m = (el._hmLab || {})[o.gid]; if (!m) return;
          const val = window.App.fmt.pct(o.chg); const vw = cv.measureText(val).width;
          if (m.h >= 44 && m.w >= 48 && vw + 16 <= m.w && m.mode === 1) bad.push({ n: n.name, w: m.w, h: m.h, t: m.text });
          if (m.mode === 2 && m.text.split('\\n')[0].endsWith('…')) two.push(m.text.replace('\\n', ' / ')); });
        return { bad, two }; }""")
    ok("★ [R4 收尾] 高度夠、數值放得下的中型方塊，一律寫出漲跌（不再只寫名稱）", r is not None and not r["bad"], r and r["bad"][:5])
    notes.append(f"R4 中型方塊改成「截短名稱＋數值」的有：{(r or {}).get('two', [])[:8]}")


def _dd_state(pg, cid):
    """某一排兩層下拉（filterDropdown）＋它那張圖的現況。長條圖回 y 軸名稱；桑基回 None（只看下拉）。"""
    return pg.evaluate("""(cid) => { const r = document.querySelector('.ddrow[data-for="' + cid + '"]'); if (!r) return null;
        const el = document.getElementById(cid); const c = el && echarts.getInstanceByDom(el); const o = c && c.getOption();
        const bars = o && (o.series || []).filter(s => s.type === 'bar');
        const dim = bars && bars[0] ? (bars[0].data || []).filter(d => d.itemStyle && d.itemStyle.opacity != null && d.itemStyle.opacity < 0.5).length : null;
        return { chain: r.querySelector('[data-dd=chain] .ddbtn b').textContent.trim(),
                 grp: r.querySelector('[data-dd=group] .ddbtn b').textContent.trim(),
                 cur: (r.querySelector('[data-dd=chain] .ddopt.on') || {dataset: {}}).dataset.c,
                 note: [...r.querySelectorAll(':scope > span.muted')].map(x => x.textContent).join('|'),
                 clear: !!r.querySelector('.dd-clear'),
                 chains: [...r.querySelectorAll('[data-dd=chain] .ddopt[data-c]')].map(b => ({ c: b.dataset.c, t: b.textContent.trim(),
                           n: +((b.querySelector('em') || {}).textContent || 0) })),
                 groups: [...r.querySelectorAll('[data-dd=group] button[data-g]')].map(b => b.dataset.g).filter(Boolean),
                 gnames: [...r.querySelectorAll('[data-dd=group] button[data-g]')].map(b => b.textContent.trim()),
                 names: o && o.yAxis && o.yAxis[0] && o.yAxis[0].data ? o.yAxis[0].data.slice() : null,
                 sub: cid === 'instGroups' ? (document.getElementById('instSub') || {}).textContent : null,
                 dim }; }""", cid)


def _dd_chain(pg, cid, c, wait=900):
    """用真的滑鼠：打開第一層 → 點某條鏈。"""
    row = f'.ddrow[data-for="{cid}"]'
    if pg.evaluate(f"() => document.querySelector('{row} [data-dd=chain] .ddpanel').hidden"):
        pg.click(f'{row} [data-dd=chain] .ddbtn'); pg.wait_for_timeout(200)
    pg.click(f'{row} [data-dd=chain] .ddopt[data-c="{c}"]'); pg.wait_for_timeout(wait)


def _dd_group(pg, cid, g, wait=900):
    """用真的滑鼠：第二層沒開就先打開 → 點某個族群（g＝'' 是「全部族群（不篩選）」）。"""
    row = f'.ddrow[data-for="{cid}"]'
    if pg.evaluate(f"() => document.querySelector('{row} [data-dd=group] .ddpanel').hidden"):
        pg.click(f'{row} [data-dd=group] .ddbtn'); pg.wait_for_timeout(200)
    pg.click(f'{row} [data-dd=group] [data-g="{g}"]'); pg.wait_for_timeout(wait)


def t_inst_filter(pg, base):
    """2026-09-26（Andy）族群 × 法人：① ETF 拿掉 ② 「先點一個族群後，再點其他族群／其他產業鏈無法切換」。

    根因（寫在 site/app.js 的 ddSelSeen 上面）：filterDropdown() 每次重建都把第一層跳回「選取所屬的鏈」，
    使用者自己換鏈也會重建 → 又被跳回去。資金去向（桑基）共用同一支，所以這段連它一起做 A→B；
    資金輪動那排是另一支（wireRotFilter，複選），也做一次 A→B 確認沒有同樣的問題。
    每一步都驗「畫面真的變了」（長條名單、副標、按鈕字、壓暗數），不是驗元素存在。
    """
    pg.set_viewport_size({"width": 1440, "height": 1000})
    reset_rot(pg, base, 2600)
    CID = "instGroups"
    IDD = f'.ddrow[data-for="{CID}"]'
    pg.evaluate("() => { const e = document.getElementById('flowInstCard'); e && e.scrollIntoView({block:'center', behavior:'instant'}); }")
    if not ok("[族群法人篩選] 族群×法人那排兩層下拉畫得出來",
              wait_until(pg, f"() => document.querySelectorAll('{IDD} .rotdd[data-dd=group] [data-g]').length > 1", 10000)):
        return
    s0 = _dd_state(pg, CID)

    # ---------------------------------------------------------------- ① ETF 不在這張卡任何地方
    ok("★ [ETF] 長條（y 軸）沒有 ETF", not any("ETF" in n for n in s0["names"]), s0["names"])
    ok("★ [ETF] 第二層族群清單（全部）沒有 ETF", not any("ETF" in g.upper() for g in s0["groups"])
       and not any("ETF" in n for n in s0["gnames"]), [g for g in s0["groups"] if "ETF" in g.upper()])
    ok("[ETF] 長條上沒有「≫」折斷記號、也沒有折斷系列（ETF 不在之後刻度交給 ECharts）",
       not any("≫" in n for n in s0["names"]) and pg.evaluate(f"""() => {{ const c = echarts.getInstanceByDom(document.getElementById('{CID}'));
           return c.getOption().series.every(s => s.type === 'bar') && c.getOption().xAxis[0].max == null; }}"""), s0["names"])
    tot = [x for x in s0["chains"] if x["c"] == ""]
    n_all = int("".join(ch for ch in (tot[0]["t"] if tot else "") if ch.isdigit()) or 0)
    per = sum(x["n"] for x in s0["chains"] if x["c"])
    ok("★ [ETF] 「全部（N 個族群）」的 N ＝ 第二層列出的族群數（不含 ETF）", n_all == len(s0["groups"]) and n_all > 0,
       {"全部": n_all, "第二層": len(s0["groups"])})
    ok("[ETF] 各產業鏈的族群數加起來 ＝ 全部（沒有查不到鏈的族群被漏掉）", per == n_all, {"各鏈合計": per, "全部": n_all})
    ind = [x for x in s0["chains"] if x["c"] == "industry"]
    if ind:
        _dd_chain(pg, CID, "industry")
        si = _dd_state(pg, CID)
        ok("★ [ETF] 「其他產業別」底下沒有 ETF，而且數字跟第二層對得上",
           not any("ETF" in g.upper() for g in si["groups"]) and len(si["groups"]) == ind[0]["n"],
           {"數字": ind[0]["n"], "第二層": si["groups"][:40]})
        click(pg, f"{IDD} .dd-clear", 900)
    else:
        notes.append("族群法人篩選：這份資料的產業鏈下拉沒有「其他產業別」（ETF 拿掉後那條鏈剩 0 個族群，已經自動從下拉消失）")

    # ---------------------------------------------------------------- ② 選鏈 A → 選鏈 B 真的切
    big = [x["c"] for x in sorted(s0["chains"], key=lambda x: -x["n"]) if x["c"] and x["n"] >= 2]
    if not ok("[族群法人篩選] 至少有兩條鏈各有 ≥2 個族群（才驗得了 A→B、X→Y）", len(big) >= 2, s0["chains"]):
        return
    A, B = big[0], big[1]
    _dd_chain(pg, CID, A)
    sa = _dd_state(pg, CID)
    ok("[A] 選鏈 A：第一層按鈕寫 A、第二層只列 A 的族群", sa["cur"] == A and len(sa["groups"]) < len(s0["groups"]), [sa["chain"], len(sa["groups"])])
    changed("★ [A] 選鏈 A：長條真的換成 A 的族群（y 軸名單變了）", s0["names"], sa["names"])
    changed("[A] 選鏈 A：副標跟著寫出鏈名", s0["sub"], sa["sub"])
    ok("[A] 選完鏈，第二層自動打開（兩層連動）", not pg.evaluate(f"() => document.querySelector('{IDD} [data-dd=group] .ddpanel').hidden"))
    _dd_chain(pg, CID, B)
    sb = _dd_state(pg, CID)
    ok("★ [A→B] 沒選族群時換鏈 B：第一層真的變 B", sb["cur"] == B, [sa["chain"], sb["chain"]])
    changed("★ [A→B] 長條換成 B 的族群", sa["names"], sb["names"])
    changed("[A→B] 副標換成 B", sa["sub"], sb["sub"])

    # ---------------------------------------------------------------- ③ Andy 的重現路徑：先選一個族群，再換別的鏈
    _dd_chain(pg, CID, A)
    X, Y = sa["groups"][0], sa["groups"][1]
    _dd_group(pg, CID, X)
    sx = _dd_state(pg, CID)
    ok("[X] 選族群 X：按鈕寫 X、旁邊寫「只亮」、其餘長條壓暗", X and sx["cur"] == A and "只亮" in sx["note"] and (sx["dim"] or 0) >= 1, sx)
    _dd_chain(pg, CID, B)
    sxb = _dd_state(pg, CID)
    ok("★★ [Andy 回報的 bug] 選了族群之後再點別的產業鏈 B → 第一層真的換成 B（修之前會被跳回 A）",
       sxb["cur"] == B, {"之前": sx["chain"], "之後": sxb["chain"]})
    changed("★★ [Andy 回報的 bug] 換到 B 之後長條真的換了", sx["names"], sxb["names"])
    ok("[X→B] 選取（屬於 A 的 X）被清掉：沒有「只亮」、沒有長條被壓暗，按鈕寫「未篩選」",
       "只亮" not in sxb["note"] and not sxb["dim"] and "未篩選" in sxb["grp"], sxb)
    ok("[X→B] 第二層列的是 B 的族群，可以直接挑", set(sxb["groups"]) == set(sb["groups"]), [len(sxb["groups"]), len(sb["groups"])])

    # ---------------------------------------------------------------- ④ X → 同鏈 Y → 別鏈 Z
    _dd_chain(pg, CID, A)
    _dd_group(pg, CID, X)
    d_x = _dd_state(pg, CID)
    _dd_group(pg, CID, Y)
    d_y = _dd_state(pg, CID)
    ok("★ [X→Y] 同鏈換族群：按鈕從 X 換成 Y", d_y["grp"] != d_x["grp"] and d_y["cur"] == A, [d_x["grp"], d_y["grp"]])
    lit = lambda cid: pg.evaluate(f"""() => {{ const c = echarts.getInstanceByDom(document.getElementById('{cid}'));
        const s = c.getOption().series[0]; return (s.data || []).map(d => d.gid + ':' + (d.itemStyle && d.itemStyle.opacity < 0.5 ? 0 : 1)); }}""")
    ly = lit(CID)
    ok("[X→Y] 亮的那一條真的是 Y（其餘壓暗）", [x for x in ly if x.endswith(":1")] == [f"{Y}:1"], ly)
    # 別鏈 Z：回到「全部」→ 在全部清單裡挑一個 B 鏈的族群，第一層要自動跟到 B
    Z = sb["groups"][0]
    _dd_chain(pg, CID, "")
    s_all = _dd_state(pg, CID)
    ok("[→全部] 選了族群時換回「全部」也換得過去（修之前一樣會被跳回原鏈）", s_all["cur"] == "", s_all["chain"])
    _dd_group(pg, CID, Z)
    d_z = _dd_state(pg, CID)
    ok("★ [Y→Z] 在全部清單挑別鏈的族群 Z：第一層自動跟到 Z 那條鏈、只亮 Z", d_z["cur"] == B and "只亮" in d_z["note"], d_z)
    lz = lit(CID)
    ok("[Y→Z] 亮的那一條真的是 Z", [x for x in lz if x.endswith(":1")] == [f"{Z}:1"], lz)
    # 清除 → 回到全部
    click(pg, f"{IDD} .dd-clear", 1000)
    d_c = _dd_state(pg, CID)
    ok("★ [清除] 回到全部：第一層「全部」、沒有「清除」鈕、沒有壓暗、長條名單和一開始一樣",
       d_c["cur"] == "" and not d_c["clear"] and not d_c["dim"] and d_c["names"] == s0["names"] and d_c["sub"] == s0["sub"],
       {"cur": d_c["cur"], "clear": d_c["clear"], "dim": d_c["dim"], "sub": [s0["sub"], d_c["sub"]]})

    # ---------------------------------------------------------------- ⑤ 資金去向（共用 filterDropdown）：A → 選族群 → B
    SK = "sankey"
    pg.evaluate("() => { const e = document.getElementById('flowSankeyCard') || document.getElementById('sankey'); e && e.scrollIntoView({block:'center', behavior:'instant'}); }")
    if ok("[資金去向] 那排兩層下拉畫得出來",
          wait_until(pg, "() => document.querySelectorAll('.ddrow[data-for=sankey] .rotdd[data-dd=group] [data-g]').length > 1", 8000)):
        k0 = _dd_state(pg, SK)
        kb = [x["c"] for x in sorted(k0["chains"], key=lambda x: -x["n"]) if x["c"]]
        if ok("[資金去向] 至少兩條鏈", len(kb) >= 2, k0["chains"]):
            _dd_chain(pg, SK, kb[0])
            ka = _dd_state(pg, SK)
            _dd_group(pg, SK, ka["groups"][0], 1500)
            kx = _dd_state(pg, SK)
            ok("[資金去向] 選了族群：摘要寫出它", "只看" in kx["note"], kx["note"])
            _dd_chain(pg, SK, kb[1], 1500)
            kbb = _dd_state(pg, SK)
            ok("★★ [資金去向] 選了族群之後換別的鏈 → 第一層真的換過去（共用同一支，修之前一樣會跳回去）",
               kbb["cur"] == kb[1], {"之前": kx["chain"], "之後": kbb["chain"]})
            ok("[資金去向] 換鏈後選取清掉、第二層換成新鏈的族群", "只看" not in kbb["note"] and kbb["groups"] != ka["groups"], kbb)
            click(pg, '.ddrow[data-for="sankey"] .dd-clear', 1200)
            ok("[資金去向] 清除回到全部", _dd_state(pg, SK)["cur"] == "")

    # ---------------------------------------------------------------- ⑥ 資金輪動那排（另一支 wireRotFilter，複選）：A → 勾族群 → B
    pg.evaluate("() => { const e = document.getElementById('flowRotCard'); e && e.scrollIntoView({block:'center', behavior:'instant'}); }")
    RR = ROT_DD
    rch = pg.evaluate(f"""() => [...document.querySelectorAll('{RR} .rotdd[data-dd=chain] .ddopt[data-c]')]
        .map(b => ({{ c: b.dataset.c, n: +((b.querySelector('em') || {{}}).textContent || 0) }})).filter(x => x.c && x.n >= 1)""") or []
    if ok("[資金輪動] 第一層至少兩條鏈", len(rch) >= 2, rch):
        def rot_chain(c):
            if pg.evaluate(f"() => document.querySelector('{RR} .rotdd[data-dd=chain] .ddpanel').hidden"):
                pg.click(f'{RR} .rotdd[data-dd=chain] .ddbtn'); pg.wait_for_timeout(200)
            pg.click(f'{RR} .rotdd[data-dd=chain] .ddopt[data-c="{c}"]'); pg.wait_for_timeout(1000)
        RS = f"""() => ({{ chain: (document.querySelector('{RR} .rotdd[data-dd=chain] .ddopt.on') || {{dataset:{{}}}}).dataset.c,
            btn: document.querySelector('{RR} .rotdd[data-dd=group] .ddbtn b').textContent,
            gs: [...document.querySelectorAll('{RR} .rotdd[data-dd=group] input[data-g]')].map(i => i.dataset.g) }})"""
        rot_chain(rch[0]["c"])
        r1 = pg.evaluate(RS)
        pg.click(f'{RR} .rotdd[data-dd=group] input[data-g="{r1["gs"][0]}"]'); pg.wait_for_timeout(1000)
        r2 = pg.evaluate(RS)
        ok("[資金輪動] 勾了一個族群：摘要寫「已選 1 個」", "已選 1" in r2["btn"], r2["btn"])
        rot_chain(rch[1]["c"])
        r3 = pg.evaluate(RS)
        ok("★ [資金輪動] 勾了族群之後換別的鏈 → 第一層真的換過去、第二層換成新鏈的族群",
           r3["chain"] == rch[1]["c"] and r3["gs"] != r1["gs"], {"之前": r2, "之後": r3})
        click(pg, f"{RR} .rot-clear", 1000)
        ok("[資金輪動] 清除回到全部", pg.evaluate(RS)["chain"] == "")

    # ---------------------------------------------------------------- ⑥b 總覽的單層下拉（ddSingle：資金熱力圖產業鏈、熱門題材）A → B
    # 這兩顆不是 filterDropdown（沒有「選取 → 鏈跟過去」那一步，所以沒有同一個根因），但一樣是「先選一個再換另一個」，
    # Andy 要求共用類似元件的卡也做一次 A→B：真的點 A、再點 B，驗按鈕字與圖真的換過去。
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    for ddid, key, chart_id in (("heatDD", "c", "heat"), ("ovThemeDD", "t", None)):
        pg.evaluate(f"() => {{ const e = document.getElementById('{ddid}'); e && e.scrollIntoView({{block:'center', behavior:'instant'}}); }}")
        pg.wait_for_timeout(400)
        opts = pg.evaluate(f"() => [...document.querySelectorAll('#{ddid} .ddopt')].map(o => o.dataset.{key}).filter(Boolean)") or []
        if not ok(f"[{ddid}] 單層下拉至少兩個選項（才驗得了 A→B）", len(opts) >= 2, opts):
            continue
        SIG = (f"""() => {{ const b = document.querySelector('#{ddid} .ddbtn b'); const el = {f"document.getElementById('{chart_id}')" if chart_id else 'null'};
            const c = el && echarts.getInstanceByDom(el); const d = c ? c.getOption().series[0].data : null;
            return {{ btn: b ? b.textContent : null, data: d ? d.map(x => x.gid || x.name).join('|').slice(0, 400) : null }}; }}""")
        got = []
        for v in opts[:2]:
            pg.click(f"#{ddid} .ddbtn"); pg.wait_for_timeout(250)
            pg.click(f'#{ddid} .ddopt[data-{key}="{v}"]'); pg.wait_for_timeout(1000)
            got.append(pg.evaluate(SIG))
        ok(f"★ [{ddid}] 選 A 再選 B：按鈕字真的從 A 換成 B", got[0]["btn"] != got[1]["btn"], got)
        if chart_id:
            changed(f"[{ddid}] 選 A 再選 B：圖上的方塊真的換了", got[0]["data"], got[1]["data"])
        pg.click(f"#{ddid} .ddbtn"); pg.wait_for_timeout(250)
        pg.click(f"#{ddid} .ddopt:first-child"); pg.wait_for_timeout(800)
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(2600)

    # ---------------------------------------------------------------- ⑦ 手機 390：換鏈之後不長出橫向捲軸
    pg.set_viewport_size({"width": 390, "height": 900})
    pg.wait_for_timeout(1200)
    pg.evaluate("() => { const e = document.getElementById('flowInstCard'); e && e.scrollIntoView({block:'center', behavior:'instant'}); }")
    pg.wait_for_timeout(600)
    # 手機版的族群×法人是另一套（`.m3keep[data-k=inst]` 的外資／投信／自營切換清單），桌機那排下拉在 390 是藏起來的 ——
    # 藏起來就不驗（驗的會是一個使用者碰不到的東西），改記一筆；看得到才真的點
    vis = pg.evaluate(f"() => {{ const b = document.querySelector('{IDD} [data-dd=chain] .ddbtn'); return !!(b && b.offsetParent && b.getBoundingClientRect().width > 0); }}")
    if not vis:
        notes.append("族群法人篩選：390 寬時族群×法人的兩層下拉不在畫面上（手機版是另一套清單），手機那步只驗了沒有橫向捲軸")
        ok("[390] 手機寬沒有橫向捲軸", pg.evaluate("() => document.documentElement.scrollWidth <= innerWidth"))
        # 手機版那一份（同一張卡）也不列 ETF：四格（外資／投信／自營／合計）逐格真的點過去，每一格都量
        if wait_until(pg, "() => document.querySelectorAll('#flowInstCard .minst li').length > 0", 6000):
            seen = {}
            for k in ("foreign", "trust", "dealer", "total"):
                pg.evaluate(f"() => {{ const b = document.querySelector('#mInstSw button[data-k=\"{k}\"]'); b && b.click(); }}"); pg.wait_for_timeout(300)
                seen[k] = pg.evaluate("() => [...document.querySelectorAll('#flowInstCard .minst li .n')].map(x => x.textContent)")
            ok("★ [ETF] 手機版族群×法人四格都沒有 ETF", all(v and not any("ETF" in n for n in v) for v in seen.values()),
               {k: [n for n in v if "ETF" in n] for k, v in seen.items()})
        else:
            notes.append("族群法人篩選：390 寬時手機版族群×法人清單沒畫出來，ETF 那條沒驗到")
    else:
        _dd_chain(pg, CID, B)
        m = pg.evaluate(f"""() => {{ const r = document.querySelector('{IDD}').getBoundingClientRect();
            const p = document.querySelector('{IDD} [data-dd=group] .ddpanel'); const pr = p && !p.hidden ? p.getBoundingClientRect() : null;
            return {{ sw: document.documentElement.scrollWidth, w: innerWidth, row: [Math.round(r.left), Math.round(r.right)],
                     pan: pr ? [Math.round(pr.left), Math.round(pr.right)] : null, cur: (document.querySelector('{IDD} [data-dd=chain] .ddopt.on') || {{dataset:{{}}}}).dataset.c }}; }}""")
        ok("[390] 手機上換鏈一樣換得過去", m["cur"] == B, m)
        ok("[390] 換鏈後沒有橫向捲軸、下拉面板沒跑出畫面", m["sw"] <= m["w"] and (not m["pan"] or (m["pan"][0] >= 0 and m["pan"][1] <= m["w"])), m)
        click(pg, f"{IDD} .dd-clear", 800)
    pg.set_viewport_size({"width": 1440, "height": 1000})


def t_wrap_r2(pg, base, code):
    """R2 收尾：放大輪盤的象限徽章與即時鈕、族群×法人 ETF 折斷刻度、集中度側欄 N 一致、x 軸有年份、800 寬拉Bar 夠長。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(2800)
    # #35 放大視窗
    # ★ 2026-09-26 改前→改後（Andy：「放大功能取消」）：資金流向頁足跡輪盤的「⤢ 放大」（#rotZoomBtn）連同它開的放大視窗拿掉。
    #   改前：放大視窗要有四個象限徽章與「即時」鈕（R2 #35）。改後：沒有放大視窗，#35 不再適用 → 驗入口與即時鈕都不在；
