def t_switch_v2(pg, base):
    """圖8 交換器板卡（v2，半層疊）：共用驗收 ＋ 規格書 switch_board.md §3／§4／§6 的硬規則，全部從畫面量。"""
    ROUTE = "industry/ai_server/dg/switch_wireless"
    FEAT = "交換器板卡"
    s0 = _v2_common(pg, base, ROUTE, FEAT, 600, ("sw_cage", "sw_fan"), (3, 3))
    if not s0:
        return
    url = f"{base}#{ROUTE}"
    _seg_rows_distinct(pg, base, FEAT, ("optical", "thermal", "connector"))
    _v2_land(pg, url, "dark", 1440, "0")
    s = pg.evaluate(_V2)
    for kw in ("示意圖，非實物比例", "埠側進風", "16 個籠架", "台股沒有直接對應", "資料中心交換器", "一個都不寫"):
        ok(f"[{FEAT}] ★「{kw}」真的印在畫面上", kw in s["all"], "")
    _v2_open_all(pg)
    st = pg.evaluate("""() => {
      const svg = document.querySelector('#prodDiagram svg');
      const bb = (n) => { const r = n.getBBox(); return {x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), y1: +(r.y + r.height).toFixed(1), x1: +(r.x + r.width).toFixed(1)}; };
      const g = (part) => svg.querySelector('[data-part="' + part + '"]');
      // §3-A 疊構節律（章節 ②）：由上到下的層別序列
      const rows = []; svg.querySelectorAll('[data-part^="sw_ly_"] rect.part').forEach(r => rows.push({k: r.closest('[data-part]').dataset.part.slice(6), y: +r.getAttribute('y')}));
      rows.sort((a, b) => a.y - b.y); const seq = rows.map(r => r.k);
      // 「上一層／下一層」講的是**銅層**（core／pp／⋮ 是介電，不算層）
      const cuSeq = seq.filter(k => ['out', 'gnd', 'sig', 'pwr'].indexOf(k) >= 0);
      const sigOK = cuSeq.every((k, i) => k !== 'sig' || (cuSeq[i - 1] === 'gnd' && cuSeq[i + 1] === 'gnd'));
      const sym = seq.join() === seq.slice().reverse().join();
      const outer = seq.filter(k => k !== 'sm')[0];
      // §3-B 走線：每一條 .dp 從 ASIC（畫面上方）走到前面板（畫面下方），近的埠繞得多（總長接近）
      const panel = bb(g('sw_cage')), asic = bb(g('sw_asic'));
      const dps = [...svg.querySelectorAll('path.dp')].map(p => { const d = p.getAttribute('d'); const pts = d.replace(/^M/, '').split(' L').map(s => s.split(',').map(Number));
        return {n: pts.length, len: +p.getTotalLength().toFixed(1), y0: pts[0][1], y1: pts[pts.length - 1][1], x1: pts[pts.length - 1][0]}; });
      const cageXs = [...svg.querySelectorAll('[data-part="sw_cage"] rect.cage')].map(bb).map(r => r.x + r.w / 2);
      const dpOK = dps.every(t => t.y0 < t.y1 && t.y1 <= panel.y1 && t.y1 >= panel.y - 20 && t.y0 <= asic.y1 + 4);
      const lens = dps.map(t => t.len); const ratio = Math.max(...lens) / Math.min(...lens);
      const flys = svg.querySelectorAll('[data-part="sw_fly"] path.fly').length;
      // 走飛越纜線的那兩個籠架（最左邊兩個）板子上沒有走線
      const leftTwo = cageXs.slice().sort((a, b) => a - b).slice(0, 2);
      const noDup = !dps.some(t => leftTwo.some(cx => Math.abs(t.x1 - cx) < 8));
      const beams = [...svg.querySelectorAll('.fxbeam')].map(b => ({rev: b.classList.contains('rev'), c: (b.getAttribute('style') || '')}));
      // §3-C 供電：VRM 緊貼 ASIC、供電線比訊號線粗
      const vrm = bb(g('sw_vrm'));
      const gap = Math.max(0, asic.x - vrm.x1);
      const pw = svg.querySelector('path.pw'), dp = svg.querySelector('path.dp');
      const pwW = pw ? parseFloat(getComputedStyle(pw).strokeWidth) : 0, dpW = dp ? parseFloat(getComputedStyle(dp).strokeWidth) : 0;
      // §3-D 氣流：風扇在後（畫面上方，比前面板高）、鰭片沿前後方向拉長（每一片的深度 > 厚度）
      const fan = bb(g('sw_fan'));
      const fins = [...svg.querySelectorAll('[data-part="sw_hs"] path.fin')].map(bb), fine = [...svg.querySelectorAll('[data-part="sw_hs"] rect.fine')].map(bb);
      const finOK = fins.length >= 8 && fins.every(f => f.w >= 10) && fine.every(f => f.w <= 4);
      const cages = [...svg.querySelectorAll('[data-part="sw_cage"] rect.cage')].map(bb);
      const cageSame = cages.length === 16 && new Set(cages.map(c => c.w + 'x' + c.h)).size === 1;
      const spins = svg.querySelectorAll('[data-part="sw_fan"] .spin').length;
      // 背鑽特寫：下半段孔徑較大
      const bdr = [...svg.querySelectorAll('[data-part="sw_backdrill"] rect')].map(bb).filter(r => r.w === 24 || r.w === 16);
      const wide = bdr.filter(r => r.w === 24), narrow = bdr.filter(r => r.w === 16);
      const bdOK = wide.length >= 1 && narrow.length >= 2 && wide[0].y > Math.min(...narrow.map(r => r.y));
      // 流程列順序
      const steps = [...svg.querySelectorAll('.step')].map(g => g.textContent.replace(/\s+/g, ''));
      const asicSeg = !!g('sw_asic').closest('[data-seg]') || g('sw_asic').hasAttribute('data-seg');
      const texts = [...svg.querySelectorAll('text')].map(n => n.textContent).join('。') + [...document.querySelectorAll('#prodDiagram .dgc')].map(c => c.innerText).join('。') + ((document.querySelector('#prodDiagram .dghead') || {}).innerText || '');
      return {seq: seq.join(','), sigOK, sym, outer, nDp: dps.length, dpOK, ratio: +ratio.toFixed(2), folds: dps.map(t => t.n), flys, noDup, beams, gap, pwW, dpW,
        fanAbove: fan.y1 <= panel.y, finOK, nFins: fins.length, cageSame, nCage: cages.length, spins, bdOK, steps, asicSeg, texts};
    }""")
    ok(f"[{FEAT}] §3-A：每一層高速訊號層的正上方與正下方都是接地層（{st['seq'][:60]}…）", st["sigOK"] and "sig" in st["seq"], st["seq"])
    ok(f"[{FEAT}] §3-A：疊構上下鏡像對稱", st["sym"], st["seq"])
    ok(f"[{FEAT}] §3-A：外層是線路層不是接地層", st["outer"] == "out", st["outer"])
    ok(f"[{FEAT}] §3-B：6 條差動對每一條都從 ASIC 走到前面板的籠架（沒有籠架直連籠架）", st["nDp"] == 6 and st["dpOK"], {"n": st["nDp"], "ok": st["dpOK"]})
    ok(f"[{FEAT}] §3-B：等長 —— 近的埠繞路、遠的直走（最長／最短 ≤ 1.35，折數 {st['folds']}）", st["ratio"] <= 1.35 and max(st["folds"]) > min(st["folds"]), st["ratio"])
    ok(f"[{FEAT}] §3-B：飛越纜線兩條，走纜線的那兩個埠板子上沒有再畫走線", st["flys"] == 2 and st["noDup"], {"flys": st["flys"], "noDup": st["noDup"]})
    ok(f"[{FEAT}] §3-B：訊號雙向 —— 電訊號光束一條進（正向）一條出（反向），光纖光束也是", sum(1 for b in st["beams"] if b["rev"]) == 2 and sum(1 for b in st["beams"] if not b["rev"]) == 2, st["beams"])
    ok(f"[{FEAT}] §3-C：VRM 緊貼 ASIC（間距 {st['gap']}px ≤ 24）、供電線（{st['pwW']}）比差動對（{st['dpW']}）粗", st["gap"] <= 24 and st["pwW"] > st["dpW"], "")
    ok(f"[{FEAT}] §3-D：風扇在後方（畫面上比前面板高）、看得到扇葉（{st['spins']} 組）", st["fanAbove"] and st["spins"] == 3, "")
    ok(f"[{FEAT}] §3-D：散熱片鰭片 ≥ 8 片、每一片沿前後方向拉長（深度 ≥ 10、厚度 ≤ 4）", st["finOK"], st["nFins"])
    ok(f"[{FEAT}] §4：前面板 16 個同規格籠架", st["cageSame"], st["nCage"])
    ok(f"[{FEAT}] §4：背鑽特寫「上半段有銅、下半段孔徑較大且沒有銅」", st["bdOK"], "")
    joined = "".join(st["steps"])
    idx = [joined.find(k) for k in ("CCL", "多層板", "光模組", "連接", "整機")]
    ok(f"[{FEAT}] §3-E：價值鏈五格由左到右 CCL → 多層板 → 光模組 → 連接 → 整機", min(idx) >= 0 and idx == sorted(idx), st["steps"])
    ok(f"[{FEAT}] ★ §6-D：交換器 ASIC 沒有掛任何 data-seg", not st["asicSeg"], "")
    bad = [ln for ln in st["texts"].split("。") if re.search(r"\d\s*%|\d\s*W\b|\d\s*mm", ln)]
    ok(f"[{FEAT}] ★ §6-C：整張圖沒有市占百分比、瓦數、板厚 mm", not bad, bad[:3])
    for kw in ("20 dB 以上", "個位數 dB", "不挑一個當定論", "40 層以上"):
        ok(f"[{FEAT}] 「{kw}」在章節裡", kw in st["texts"], "")
    # ---- 誰做的：ASIC 明說外商、籠架列光通訊廠、飛越纜線列連接器廠
    _v2_land(pg, url, "dark", 1440, "0")
    _v2_click_part(pg, "sw_asic"); c1 = pg.evaluate(_V2)["card"]
    ok(f"[{FEAT}] ★ 點 ASIC → 小卡明說外商供應、台股沒有直接對應，而且不列任何公司", bool(c1) and "外商" in c1["none"] and not c1["codes"], c1 and (c1["none"][:50], c1["codes"]))
    _v2_click_part(pg, "sw_cage"); c2 = pg.evaluate(_V2)["card"]
    ok(f"[{FEAT}] 點籠架 → 小卡列光通訊那一格（4979 華星光在裡面）", bool(c2) and "4979" in c2["codes"], c2 and c2["codes"])
    _v2_click_part(pg, "sw_fly"); c3 = pg.evaluate(_V2)["card"]
    ok(f"[{FEAT}] 點飛越纜線 → 小卡列連接器廠 3665，不是光通訊廠", bool(c3) and "3665" in c3["codes"] and "4979" not in c3["codes"], c3 and c3["codes"])
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.evaluate("() => { try { localStorage.removeItem('tw.dg3d.pal'); localStorage.setItem('tw.theme', 'dark'); localStorage.removeItem('tw.side'); } catch (e) {} }")


DG3D_DE_MIN = 25.0

# 七類模組各挑一個**代表零件**（機櫃場景裡都有）。挑的原則：
# 那個零件「體積最大的那顆 mesh」就是這一類的材質本體 —— mats() 的 now 量的就是它。
#   ag_rack  機架（銀灰金屬橫樑；側板是玻璃但體積小）
#   ag_pcb   主機板（墨綠板材）
#   ag_gpu   運算模組（深藍載板）
#   ag_uqd   快接頭（暖銅本體）
#   ag_cdu   液冷立柱（青綠半透明外殼；掛在它身上的水路不算，見 three3d.js 的 mats()）
#   ag_fan   風扇（藍灰外框）
#   ag_psu   電源櫃（暖橘機殼）
DG3D_MODULES = {
    "機架": "ag_rack", "PCB": "ag_pcb", "晶片": "ag_gpu", "銅件": "ag_uqd",
    "液冷": "ag_cdu", "風扇框": "ag_fan", "電源": "ag_psu",
}

# 三個場景的效能上限（三角形／draw call）。L3_ROUTES 已經有一份，這裡只是把 draw call 也寫成表，
# 讓「改前／改後」的對照表有一個固定的欄位。
DG3D_PERF = {"ai_server": (40000, 680), "semiconductor": (40000, 240), "mlcc": (6000, 120)}


def _lab(rgb):
    """sRGB(0~255) → CIE L*a*b*（D65）。只給 _de76 用。"""
    def inv(c):
        c = c / 255.0
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = (inv(x) for x in rgb)
    x = (0.4124 * r + 0.3576 * g + 0.1805 * b) / 0.95047
    y = (0.2126 * r + 0.7152 * g + 0.0722 * b)
    z = (0.0193 * r + 0.1192 * g + 0.9505 * b) / 1.08883

    def f(t):
        return t ** (1.0 / 3.0) if t > 0.008856 else 7.787 * t + 16.0 / 116.0
    fx, fy, fz = f(x), f(y), f(z)
    return (116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz))


def _de76(a, b):
    """兩個 #rrggbb 的 CIE76 色差。算不出來回 -1（讓驗收看得出是「量不到」不是「很接近」）。"""
    ra, rb = _hex2rgb(a), _hex2rgb(b)
    if not ra or not rb:
        return -1.0
    la, lb = _lab(ra), _lab(rb)
    return round(sum((p - q) ** 2 for p, q in zip(la, lb)) ** 0.5, 1)


# 關／開文字標籤的開關（驗收第 1 條「關掉標籤還認得出七類」要真的關掉，而且要關得回來）
_DG3D_NOLBL_ON = """() => { let st = document.getElementById('dg3dNoLbl');
  if (!st) { st = document.createElement('style'); st.id = 'dg3dNoLbl'; document.head.appendChild(st); }
  st.textContent = '.lbl3d,.lead3d{display:none!important}'; }"""
_DG3D_NOLBL_OFF = """() => { const st = document.getElementById('dg3dNoLbl'); if (st) st.textContent = ''; }"""

DG3D_AUDIT = """() => { const v = window.Rack3D.current;
  const a = v.audit ? v.audit() : null, st = v.stats();
  const host = document.getElementById('prodDiagram'), h3 = document.getElementById('prod3d');
  const hr = h3 ? h3.getBoundingClientRect() : null;
  const cardsOut = hr ? [...h3.querySelectorAll('.lbl3d')].filter(c => !c.classList.contains('hid'))
      .filter(c => { const b = c.getBoundingClientRect();
        return b.width > 1 && (b.left < hr.left - 1 || b.right > hr.right + 1); }).map(c => c.dataset.dgno) : [];
  /* ★ 量「誰會捲」要量對東西：3D 開著的時候 #prodDiagram 是 hidden（scrollWidth 一律 0），
     量它等於沒量。真正會捲的是 3D 畫布本身（#prod3d）與它的外層（#dgBody），
     而且要順便確認 #prodDiagram 的 overflow-x **沒有**被 native 那條規則設成 auto。*/
  const body = document.getElementById('dgBody') || (h3 ? h3.parentElement : null);
  const br = body ? body.getBoundingClientRect() : null;
  return { audit: a, mats: v.mats(), calls: st.drawCalls, tris: st.triangles,
    scrollW: h3 ? h3.scrollWidth : 0, clientW: h3 ? h3.clientWidth : 0,
    bodyScrollW: body ? body.scrollWidth : 0, bodyClientW: body ? body.clientWidth : 0,
    /* ★ 量的是 **inline** 的 overflow-x（applyDgNative 寫的那一個），不是 computed ——
       窄畫面的 `.dgwrap{overflow-x:auto}` 是 CSS 媒體查詢給 **2D** 的規則，
       而 3D 開著時 #prodDiagram 本來就是 hidden，那條規則碰不到 3D。*/
    dgInlineOx: host ? host.style.overflowX : '',
    dgHidden: host ? !!host.hidden : null,
    sticksOut: !!(br && hr && (hr.right > br.right + 1 || hr.left < br.left - 1)),
    pageW: document.documentElement.scrollWidth, pageC: document.documentElement.clientWidth,
    cardsOut: cardsOut, hostW: h3 ? Math.round(hr.width) : 0 }; }"""


def t_dg3d_pbr(pg, base):
    """DECISIONS #244：環境貼圖、真陰影、收透明、七類模組配色、效能、3D 不橫向捲動。

    這一段驗的全部是「畫面真的因此改變」：
      ① 關掉 .lbl3d 之後，七類模組的代表色兩兩 ΔE76 ≥ 25（關掉標籤仍然認得出來）
      ② scene.environment 不是 null、而且至少一顆零件 metalness ≥ .8（證明上限真的解除了）
      ③ renderer.shadowMap.enabled、castShadow 的 mesh 數落在 [5, 60]
      ④ 「沒有選取」的靜止狀態下，半透明 mesh ≤ 25%
      ⑤ 三角形／draw call 在上限內
      ⑥ 四個寬度下 #prodDiagram 不橫向捲動、卡片完整落在 #prod3d 內
    """
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(base, wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d.pal', 'tech'); localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
    if not pg.evaluate("() => !!window.Rack3D"):
        notes.append("這個環境載不到 Rack3D（WebGL？），3D PBR 整段跳過")
        return

    for nice, (route, cmax, tmax) in L3_ROUTES.items():
        if not _l1_open(pg, base, route):
            notes.append(f"{nice}：3D 掛不起來（WebGL？），這一張跳過")
            continue
        for pal in ("tech", "read"):
            pg.evaluate("(x) => window.Rack3D.current.setPal(x)", pal)
            pg.wait_for_timeout(500)
            lab = "科技" if pal == "tech" else "閱讀"
            # ---- 先點背景把選取清掉：透明比例要量的是「靜止狀態」，
            #      不是「選了一個環節、其餘淡到 0.12」那個狀態（那是高亮，不是設計）
            bg = pg.evaluate(_L1_BG)
            if bg:
                pg.mouse.click(bg["x"], bg["y"])
                pg.wait_for_timeout(500)
            z = pg.evaluate(DG3D_AUDIT)
            a = z["audit"]
            if not ok(f"[{nice}／{lab}] audit() 量得到（env／陰影／透明比例）", bool(a), a):
                continue

            # ---------------- ② 環境貼圖：金屬才會是金屬
            ok(f"[{nice}／{lab}] ★ scene.environment 真的掛上了環境貼圖（沒有它 PBR 金屬只會變暗灰）",
               a["env"] is True, a)
            ok(f"[{nice}／{lab}] envMapIntensity 是模式自己的值（--dg-env），不是寫死的 1",
               a["envIntensity"] > 0, a["envIntensity"])
            ok(f"[{nice}／{lab}] ★ metalness 的上限真的解除了：至少一顆零件 ≥ .8（現在 {a['maxMetal']}）",
               a["maxMetal"] >= 0.8, a["maxMetal"])

            # ---------------- ③ 真陰影
            ok(f"[{nice}／{lab}] ★ renderer.shadowMap 真的開著（不是只有底下那片 sprite）",
               a["shadowMap"] is True, a)
            ok(f"[{nice}／{lab}] castShadow 的 mesh 數在 [5, 60]（太多＝效能會爆，太少＝等於沒做）：{a['castShadow']}",
               5 <= a["castShadow"] <= 60, a["castShadow"])
            ok(f"[{nice}／{lab}] 有接收陰影的面（不然影子沒地方落）：{a['receiveShadow']}",
               a["receiveShadow"] >= 3, a["receiveShadow"])

            # ---------------- ④ 收透明
            # ★ 量的是 **designRatio**（baseOp：沒有選取時該有的不透明度），不是當下的 opacity。
            #   高亮會把「沒被選到的環節」壓到 0.12（#238），而多環節場景一進來就有選取 ——
            #   量 opacity 會得到 68.5% 的假數字，那是**高亮狀態**不是設計（2026-09-22 實際踩到）。
            ratio = a.get("designRatio", a["transRatio"])
            ok(f"[{nice}／{lab}] ★ 設計上半透明的 mesh 佔比 ≤ 25%"
               f"（{a.get('designTrans')}/{a.get('designTotal')} ＝ {ratio:.1%}；"
               f"當下含高亮淡出的是 {a['transparent']}/{a['meshTotal']}）",
               ratio <= 0.25, a)

            # ---------------- ⑤ 效能
            tm, cm = DG3D_PERF.get(nice, (tmax, cmax))
            ok(f"[{nice}／{lab}] 三角形 ≤ {tm}（{z['tris']}）", 0 < z["tris"] <= tm, z["tris"])
            ok(f"[{nice}／{lab}] draw call ≤ {cm}（{z['calls']}）", 0 < z["calls"] <= cm, z["calls"])

            # ---------------- ① 七類模組：關掉標籤還認得出來（只有機櫃場景七類齊全）
            if nice == "ai_server":
                # 用一個具名的 <style> 當開關：關完要能「真的把那條規則拿掉」——
                # 再補一條 display:revert!important 會連卡片原本的 display 一起改掉（版面跟著變）
                pg.evaluate(_DG3D_NOLBL_ON)
                pg.wait_for_timeout(350)
                gone = pg.evaluate("""() => [...document.querySelectorAll('.lbl3d')]
                    .filter(c => c.getBoundingClientRect().width > 1).length""")
                ok(f"[{nice}／{lab}] 標籤真的關掉了（畫面上一張卡片都看不到）", gone == 0, gone)
                m2 = {m["part"]: m["now"] for m in pg.evaluate(DG3D_AUDIT)["mats"]}
                cols = {}
                miss = []
                for cls, part in DG3D_MODULES.items():
                    c = m2.get(part)
                    if c:
                        cols[cls] = c
                    else:
                        miss.append((cls, part))
                if ok(f"[{nice}／{lab}] 七類模組的代表零件都在場景裡", not miss, miss):
                    ks = list(cols)
                    pairs = [(_de76(cols[ks[i]], cols[ks[j]]), ks[i], ks[j])
                             for i in range(len(ks)) for j in range(i + 1, len(ks))]
                    pairs.sort()
                    same = [(x, y) for d, x, y in pairs if d <= 0.5]
                    ok(f"[{nice}／{lab}] ★ 沒有任何兩類模組是同一個顏色", not same, same[:3])
                    worst = pairs[0] if pairs else (0, "", "")
                    ok(f"[{nice}／{lab}] ★ 關掉標籤：七類模組兩兩色差 ΔE76 ≥ {DG3D_DE_MIN}"
                       f"（最接近的是 {worst[1]}／{worst[2]} ΔE={worst[0]}）",
                       bool(pairs) and worst[0] >= DG3D_DE_MIN,
                       {"色": cols, "最接近的三組": pairs[:3]})
                # 把標籤放回去（下一輪還要量卡片有沒有出框）：清掉那條規則，不是再蓋一條
                pg.evaluate(_DG3D_NOLBL_OFF)
                pg.wait_for_timeout(300)

    # ---------------- ⑥ 四個寬度：不橫向捲動、卡片完整在容器內
    for nice, (route, _c, _t) in L3_ROUTES.items():
        for w in (1440, 1100, 800, 390):
            pg.set_viewport_size({"width": w, "height": 1000})
            if not _l1_open(pg, base, route):
                notes.append(f"[{w}px] {nice} 3D 掛不起來，版面那一條跳過")
                continue
            pg.wait_for_timeout(900)
            z = pg.evaluate(DG3D_AUDIT)
            ok(f"[{nice} {w}px] ★ 3D 畫布本身不橫向捲動：scrollWidth {z['scrollW']} ≤ clientWidth {z['clientW']}",
               z["scrollW"] <= z["clientW"] + 1, z)
            ok(f"[{nice} {w}px] ★ 3D 區塊的外層不橫向捲動（卡片不會被捲到畫面外）"
               f"：{z['bodyScrollW']} ≤ {z['bodyClientW']}",
               z["bodyScrollW"] <= z["bodyClientW"] + 1, z)
            ok(f"[{nice} {w}px] ★ 3D 開著時 applyDgNative 沒有把「原尺寸左右滑」套到 3D 上"
               f"（inline overflow-x = {z['dgInlineOx']!r}）",
               z["dgInlineOx"] != "auto", z)
            ok(f"[{nice} {w}px] 3D 開著時 2D 外框是收起來的（所以它的捲動規則碰不到 3D）",
               z["dgHidden"] is True, z["dgHidden"])
            ok(f"[{nice} {w}px] 3D 畫布沒有凸出它的容器", not z["sticksOut"], z)
            ok(f"[{nice} {w}px] ★ 每一張卡片都完整落在 3D 容器內（不會被切一半）",
               not z["cardsOut"], z["cardsOut"][:5])
            ok(f"[{nice} {w}px] 3D 畫布真的吃到欄寬（不是縮成一小塊）：{z['hostW']}px",
               z["hostW"] >= min(300, w - 90), z["hostW"])
    pg.set_viewport_size({"width": 1500, "height": 1000})
    # ★ #246：按工具列的鈕之前先把游標移出 3D，再等展開補間停下來。
    #   理由不是「讓測試好過」，是**真人本來就做不到「游標停在畫布上同時去按工具列」**——
    #   工具列在 #prod3d 外面，手移過去的那一刻圖就收攏了。
    #   測試把游標留在畫布裡按鈕，等於要求瀏覽器一邊用 3fps（容器是軟體渲染）畫爆炸補間、
    #   一邊在 6 秒內回應 Playwright 的可點擊性輪詢 —— 實測就是這樣紅的，而且紅在收尾。
    pg.mouse.move(4, 4)
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        _dg3d_settle(pg, 0, 3000)
        click(pg, "#dg3d", 900)
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dganim', '1'); localStorage.setItem('tw.dg3d.pal', 'tech'); } catch (e) {} }")


# ================================================================ #246：3D 預設收攏、游標移過去才爆開
# Andy 2026-09-23：「所有 3D 圖都需要預設是收攏的，游標移動過去才會自動分開，變成爆炸圖」。
# 這一段驗的全部是「畫面真的因此改變」——量的是**零件離原位跑了多遠**（exMove，世界座標、
# 跟相機無關），不是只看 explode 這個變數。變數改了不等於零件動了。
DG3D_EXP_IN_MS = 820          # 展開補間的長度（site/three3d.js 的 EXP_IN）
DG3D_EXP_OUT_MS = 500         # 收回補間的長度（site/three3d.js 的 EXP_OUT）

# 「這一格 3D 容器的裡面一點／外面一點」。移出去要走**垂直**方向（同一個 x、y 拉到畫面最上緣）：
# 往左移在窄畫面會還踩在容器裡，那樣 pointerleave 根本不會來，測出來就是假紅。
_DG3D_PTS = """() => { const h = document.getElementById('prod3d'); if (!h) return null;
  const r = h.getBoundingClientRect();
  if (r.width < 40 || r.height < 40 || r.top > innerHeight - 40) return null;
  const cx = Math.round(r.left + r.width / 2);
  const cy = Math.round(Math.max(r.top + 12, Math.min(r.bottom - 12, r.top + r.height / 2)));
  if (cy < 2 || cy > innerHeight - 2 || r.top < 30) return null;   // 容器要離畫面上緣夠遠，才有地方「移出去」
  return { inX: cx, inY: cy, outX: cx, outY: 4 }; }"""

# 目前的展開狀態。explode() 不像 stats() 要遍歷整個場景，取樣可以每一幀跑
_DG3D_EXP = """() => { const v = window.Rack3D.current; const st = v.stats();
  return { t: +v.explode().toFixed(3), target: st.explodeTarget, move: st.exMove,
           from: st.expFrom, hover: st.canHover, running: st.exploding }; }"""

# rAF 取樣器：把每一幀的 explode 記下來，用它看「進 → 出 → 進」的軌跡真的有上去、下來、再上去
_DG3D_REC_ON = """() => { window.__expRec = []; window.__expRecOff = false;
  const v = window.Rack3D.current;
  const f = () => { if (window.__expRecOff) return;
    window.__expRec.push(+v.explode().toFixed(4)); requestAnimationFrame(f); };
  requestAnimationFrame(f); }"""
_DG3D_REC_OFF = """() => { window.__expRecOff = true; return window.__expRec || []; }"""

# 掃一個「射線真的打得到零件」的畫布座標（_L1_BG 的反面）。
# 不用 screen(seg)：那是引線的錨點（零件上緣再往上），小畫布上常常落在空白處。
_DG3D_PART_PT = """() => {
  const v = window.Rack3D && window.Rack3D.current; if (!v || !v.hitAt) return null;
  const cv = document.querySelector('#prod3d canvas'); if (!cv) return null;
  const r = cv.getBoundingClientRect();
  for (let fy = 0.1; fy < 0.92; fy += 0.04) {
    for (let fx = 0.1; fx < 0.92; fx += 0.04) {
      const x = Math.round(r.left + r.width * fx), y = Math.round(r.top + r.height * fy);
      if (y < 4 || y > window.innerHeight - 4) continue;
      if (document.elementFromPoint(x, y) !== cv) continue;   // 壓著文字框就不算
      const hitp = v.hitAt(x, y);
      if (hitp) return { x: x, y: y, part: hitp };
    }
  }
  return null;
}"""


def _dg3d_wait_t(pg, lo, hi, ms=4000):
    """等到 explode 落進 [lo, hi]（或逾時）。**不要用固定的 wait 賭幀率**——
    這個容器只有 3~8 fps，同一句 `wait_for_timeout(300)` 有時走到 0.005、有時走到 0.9。"""
    t0 = time.time()
    while (time.time() - t0) * 1000 < ms:
        v = pg.evaluate("() => window.Rack3D.current.explode()")
        if lo <= v <= hi:
            return v
        pg.wait_for_timeout(40)
    return pg.evaluate("() => window.Rack3D.current.explode()")


def _dg3d_toolbar_click(pg, sel, wait=900):
    """按 3D 工具列的鈕（#dg3d／#dgReset／#dgAnim…）之前，先把游標移出 #prod3d 再等它靜下來。
    （#dgPal 已於 2026-09-23 C1 整顆移除，配色改跟著全站主題走。）

    ★ #246 之後這件事變成必要：游標停在畫布上時圖是展開的、而且補間期間每一幀都要重畫，
      容器又是 swiftshader 軟體渲染（3~8 fps）—— Playwright 的可點擊性輪詢就被主執行緒餓死，
      6 秒點不到，紅在收尾而且會連鎖（3D 沒關掉 → 後面驗 2D 的段落看到圖被藏起來，整段紅）。
      而**真人根本做不到「游標停在畫布上同時按工具列」**：工具列在 #prod3d 外面，
      手移過去的那一刻圖就收攏了。所以這不是放寬，是把測試改成真人做得到的順序。
    """
    pg.mouse.move(4, 4)
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        _dg3d_settle(pg, 0, 3000)
    click(pg, sel, wait)


def _dg3d_settle(pg, want, ms=6000):
    """等到爆炸展開**真的停下來**在 want（補間跑完、expAnim 清掉）。

    ★ 為什麼不能用固定的 `wait_for_timeout(900)`：捲動會讓容器在游標底下移動，
      Chromium 會因此補送 pointerenter／pointerleave（游標沒動、元素動了）——
      那一發會在我們把游標移開之後才進來，於是「等 900ms」量到的是
      **一段還沒跑完的收回補間**（實測 t=0、exMove=0.001、exploding=True）。
      要驗的是「沒有游標在上面時的靜止狀態」，所以等的條件是「停下來了」，不是「過了幾毫秒」。
    """
    t0 = time.time()
    while (time.time() - t0) * 1000 < ms:
        v, run = pg.evaluate("() => { const x = window.Rack3D.current; return [x.explode(), x.stats().exploding]; }")
        if abs(v - want) < 1e-6 and not run:
            return True
        pg.wait_for_timeout(50)
    return False


def _dg3d_open_mobile(pg, base, route):
    """行動版（390px）開 3D。`dgOpen = innerWidth >= 640`，所以手機進來剖析圖是**收合**的，
    收合時 industry.js 刻意不掛 3D（`wireDg(!dgOpen)`），#dg3d 那顆鈕也還是 hidden ——
    所以要先真的按一下「展開剖析圖 ▾」，鈕才會出現。這就是手機使用者真正的操作順序。"""
    pg.goto(f"{base}#{route}", wait_until="networkidle")
    # ★ 一定要 reload：goto 到**同一個 hash** 是 same-document navigation、不會重畫，
    #   第二次呼叫這支（驗「下次進來照上一次的狀態」）會拿到上一輪還活著的那個 view，
    #   localStorage 存的展開狀態根本沒被讀過 —— 那是假紅（跟 t_clickbg 踩到的是同一件事）。
    pg.reload(wait_until="networkidle")
    pg.wait_for_timeout(2600)
    if pg.evaluate("() => { const b = document.getElementById('dg3d'); return !!b && b.hidden; }"):
        fold = pg.query_selector("#dgFold")
        if fold:
            fold.click()
            pg.wait_for_timeout(2600)
    if not pg.evaluate("() => { const b = document.getElementById('dg3d'); return !!b && !b.hidden; }"):
        return False
    if not pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        b = pg.query_selector("#dg3d")
        if b:
            b.click()
            pg.wait_for_timeout(4000)
    return pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)")


def t_dg3d_hover(pg, base):
    """#246：進場收攏、游標移進才爆開、移開收回；動畫關＝一幀到位；沒有 hover 的裝置改成點背景切換。"""
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(base, wait_until="networkidle")
    pg.evaluate("""() => { try { localStorage.setItem('tw.dg3d.pal', 'tech');
        localStorage.setItem('tw.dganim', '1'); localStorage.removeItem('tw.dg3d.exp'); } catch (e) {} }""")
    if not pg.evaluate("() => !!window.Rack3D"):
        notes.append("這個環境載不到 Rack3D（WebGL？），#246 收攏／展開整段跳過")
        return

    for nice, (route, _c, _t) in L3_ROUTES.items():
        if not _l1_open(pg, base, route):
            notes.append(f"{nice}：3D 掛不起來（WebGL？），#246 這一張跳過")
            continue
        scroll_to(pg, "prod3d")
        pts = pg.evaluate(_DG3D_PTS)
        if not ok(f"[{nice}] 3D 容器在畫面裡、而且上方有地方可以把游標移出去", bool(pts), pts):
            continue
        # 先把游標移到容器外，確定沒有殘留的 hover（上一張圖可能停在畫布上），
        # 然後**等到真的停下來**再量（捲動補送的 pointerenter/leave 會晚一拍到，見 _dg3d_settle）
        pg.mouse.move(pts["outX"], pts["outY"])
        settled = _dg3d_settle(pg, 0)
        ok(f"[{nice}] 游標不在圖上時，展開狀態會**停下來**（補間跑完、不是一直在動）", settled)

        # ---------------- ① 進場＝完全收攏，而且零件真的是合攏的
        a = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] ★ 進場就是收攏：explode = 0、目標也是 0（不是一進來就自己爆開）",
           a["t"] == 0 and a["target"] == 0, a)
        ok(f"[{nice}] ★ 零件**真的**回在原位：離原位最遠的那一顆只跑了 {a['move']}（世界座標，跟相機無關）",
           a["move"] == 0, a)
        ok(f"[{nice}] 這個環境量得到「有游標」（桌機瀏覽器），所以 hover 那條路才適用", a["hover"] is True, a)

        # ---------------- ② 游標移進去 → 平滑爆開（先確認它是「補間」不是「瞬跳」）
        pg.mouse.move(pts["inX"], pts["inY"])
        pg.wait_for_timeout(70)
        mid = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] ★ 游標一進來就**開始補間**而不是瞬間爆開（70ms 時 t = {mid['t']}，補間中 = {mid['running']})",
           0 <= mid["t"] < 0.8 and mid["target"] == 1, mid)
        pg.wait_for_timeout(DG3D_EXP_IN_MS + 260)
        b = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] ★ 游標移進 3D 容器 → {DG3D_EXP_IN_MS}ms 後真的爆開到底（t = {b['t']}）",
           b["t"] >= 0.99 and b["target"] == 1 and not b["running"], b)
        ok(f"[{nice}] ★ 零件**真的**分開了：離原位最遠的那一顆跑了 {b['move']}（收攏時是 {a['move']}）",
           b["move"] >= 2 and b["move"] > a["move"] + 1, {"收攏": a["move"], "展開": b["move"]})

        # ---------------- ③ 游標移開 → 平滑收回
        pg.mouse.move(pts["outX"], pts["outY"])
        pg.wait_for_timeout(70)
        mid2 = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] 游標一離開就開始往回收，不是瞬間合攏（70ms 時 t = {mid2['t']}）",
           mid2["t"] > 0.2 and mid2["target"] == 0, mid2)
        pg.wait_for_timeout(DG3D_EXP_OUT_MS + 500)
        c = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] ★ 游標移開 → {DG3D_EXP_OUT_MS}ms 後真的收回原位（t = {c['t']}、離原位 {c['move']}）",
           c["t"] <= 0.01 and c["move"] <= 0.15 and c["target"] == 0, c)

        # ---------------- ④ 快速進 → 出 → 進：從目前的 t 接著補，不准跳回 0 或 1 重來
        #   ★ 量的是 expFrom（這一段補間「從哪個 t 開始」），**不是 rAF 取樣的 Δt**。
        #     這個容器是 swiftshader 軟體渲染、只有 3~8 fps：一個**正常**的補間單幀就會前進 0.7，
        #     跟「真的跳回去」分不出來；而且「hover 進去等 300ms」常常只走到 0.005，
        #     拿它當「一半」是賭幀率（第一版就是這樣紅的）。
        #     所以先用 explode(0.45) 把零件**停在半路**（這是狀態，不是事件），
        #     再用**真的滑鼠移動**觸發方向改變 —— 接手點就必須正好是 0.45。
        for seed, go_in, why in ((0.45, False, "展開到一半就把游標移開 → 往回收"),
                                 (0.40, True, "收到一半又把游標移回來 → 往外爆")):
            pg.mouse.move(pts["outX"] if go_in else pts["inX"], pts["outY"] if go_in else pts["inY"])
            pg.wait_for_timeout(120)
            pg.evaluate("(x) => window.Rack3D.current.explode(x)", seed)
            pg.mouse.move(pts["inX"] if go_in else pts["outX"], pts["inY"] if go_in else pts["outY"])
            f = pg.evaluate(_DG3D_EXP)
            ok(f"[{nice}] ★ {why}：補間從**目前的 t**（{f['from']}）接手，不是從 {1 - int(go_in)} 重來",
               f["from"] is not None and abs(f["from"] - seed) <= 0.02
               and f["target"] == (1 if go_in else 0), {"seed": seed, **f})
        # 回到收攏的起點，再跑一次真的「快速進 → 出 → 進」，看軌跡真的轉過向
        pg.mouse.move(pts["outX"], pts["outY"])
        pg.wait_for_timeout(DG3D_EXP_OUT_MS + 700)
        pg.evaluate(_DG3D_REC_ON)
        pg.mouse.move(pts["inX"], pts["inY"])
        _dg3d_wait_t(pg, 0.30, 1.0)               # 等到真的爆開一段（不賭幀率）
        pg.mouse.move(pts["outX"], pts["outY"])
        _dg3d_wait_t(pg, 0.0, 0.20)               # 等到真的收回一段
        pg.mouse.move(pts["inX"], pts["inY"])
        # 尾巴用「等到真的到底」而不是固定秒數：3~8 fps 的機器最後一幀可能落在 0.988，
        # 那不是壞了，是還沒畫到下一幀（這裡量的是「轉過向」，不是「幾毫秒到底」）
        _dg3d_wait_t(pg, 0.999, 1.0, 4000)
        pg.wait_for_timeout(200)
        rec = pg.evaluate(_DG3D_REC_OFF)
        ok(f"[{nice}] 快速進出的過程真的被畫出來了（rAF 取到 {len(rec)} 幀、{len(set(rec))} 個不同的值）",
           len(rec) >= 6 and len(set(rec)) >= 4, rec[:12])
        ok(f"[{nice}] 整段軌跡都落在 0～1 之間（沒有出現超界或 NaN）",
           bool(rec) and all(isinstance(x, (int, float)) and -0.001 <= x <= 1.001 for x in rec), rec[:12])
        # 「轉過向」＝某一點之後的最低值比那一點低 0.08 以上；最後一定要回到 1
        drop = max((x - min(rec[i:]) for i, x in enumerate(rec)), default=0)
        ok(f"[{nice}] ★ 軌跡真的轉過向（中途往回收了 {drop:.2f}）、最後停在 {rec[-1] if rec else None}",
           bool(rec) and drop >= 0.08 and rec[-1] >= 0.99, {"回收幅度": round(drop, 3), "尾": rec[-3:], "取樣": len(rec)})

        # ---------------- ⑤ 動畫：關 → 不補間，一幀到位（狀態本身仍然切得動）
        pg.mouse.move(pts["outX"], pts["outY"])
        _dg3d_settle(pg, 0)
        if pg.evaluate("() => window.Rack3D.current.isAnim()"):
            pg.eval_on_selector("#dgAnim", "b => b.click()")
            pg.wait_for_timeout(400)
        ok(f"[{nice}] 「動畫：關」真的關掉了（後面兩條的前提）",
           pg.evaluate("() => !window.Rack3D.current.isAnim()"))
        d0 = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] 「動畫：關」時游標在外面 → 還是收攏的（關動畫不等於替使用者決定要攤開）",
           d0["t"] == 0 and d0["move"] == 0, d0)
        pg.mouse.move(pts["inX"], pts["inY"])
        pg.wait_for_timeout(60)
        d1 = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] ★ 「動畫：關」時游標移進來 → **一幀內**就到 1（不補間）、零件真的分開（{d1['move']}）",
           d1["t"] == 1 and not d1["running"] and d1["move"] >= 2, d1)
        pg.mouse.move(pts["outX"], pts["outY"])
        pg.wait_for_timeout(60)
        d2 = pg.evaluate(_DG3D_EXP)
        ok(f"[{nice}] ★ 「動畫：關」時游標移開 → **一幀內**回到 0、零件真的回原位",
           d2["t"] == 0 and not d2["running"] and d2["move"] == 0, d2)
        pg.eval_on_selector("#dgAnim", "b => b.click()")     # 開回來，還原給下一張
        pg.wait_for_timeout(300)

    # ---------------- ⑥ 沒有 hover 的裝置：點背景切換、而且記得住
    #   用一個真的 is_mobile 的分頁（(hover: none)），不是把旗標改掉騙自己。
    #   ⚠ 先把**桌機這一頁的 3D 收掉**再開手機分頁。兩個分頁在 Playwright 裡都算「看得見」，
    #     所以桌機那個場景會一直用 30fps 畫下去，跟手機分頁的場景搶同一顆 CPU
    #     （容器是 swiftshader 軟體渲染）—— 實測結果是收尾那一下 `#dg3d` 6 秒點不下去，
    #     報出來長得跟「功能壞了」一模一樣。真實世界不會這樣（一次只有一個分頁在前景）。
    pg.mouse.move(4, 4)
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        _dg3d_settle(pg, 0, 3000)
        click(pg, "#dg3d", 1200)
    mob = None
    try:
        mob = pg.context.browser.new_page(viewport={"width": 390, "height": 844},
                                          device_scale_factor=2, is_mobile=True, has_touch=True)
        mob.on("pageerror", lambda e: fails.append(f"[無 hover 裝置] pageerror: {e}"))
        mob.goto(base, wait_until="networkidle")
        mob.evaluate("""() => { try { localStorage.setItem('tw.dg3d', '1');
            localStorage.setItem('tw.dg3d.pal', 'tech'); localStorage.setItem('tw.dganim', '1');
            localStorage.removeItem('tw.dg3d.exp'); } catch (e) {} }""")
        hv = mob.evaluate("() => matchMedia('(hover: none)').matches")
        if not ok("[無 hover 裝置] 這個分頁真的是 (hover: none)（手機／平板）", hv is True, hv):
            raise RuntimeError("拿不到無 hover 的環境")
        if not _dg3d_open_mobile(mob, base, L3_ROUTES["ai_server"][0]):
            notes.append("[無 hover 裝置] 3D 掛不起來，⑥ 跳過")
        else:
            # ★ 手機不能用 scroll_to(mob, "prod3d")：窄畫面時卡片全部搬到畫布底下，
            #   #prod3d 整格高達 ~2000px，把「整格」捲到畫面中央會讓**畫布本身跑到視窗上方外面**
            #   （實測 canvas.top = -574），_L1_BG 掃到的每一點都在視窗外 → 找不到背景。
            #   要捲的是畫布，不是整格。
            mob.evaluate("() => { const c = document.querySelector('#prod3d canvas');"
                         " if (c) c.scrollIntoView({ block: 'center' }); }")
            mob.wait_for_timeout(700)
            e0 = mob.evaluate(_DG3D_EXP)
            ok("[無 hover 裝置] 進場一樣是收攏的，而且它知道自己沒有游標",
               e0["t"] == 0 and e0["hover"] is False, e0)
            bg = mob.evaluate(_L1_BG)
            if ok("[無 hover 裝置] 畫布上找得到一塊真的背景可以點", bool(bg), bg):
                mob.mouse.click(bg["x"], bg["y"])
                mob.wait_for_timeout(DG3D_EXP_IN_MS + 400)
                e1 = mob.evaluate(_DG3D_EXP)
                ok("[無 hover 裝置] ★ 點一下背景 → 真的展開（零件離原位 "
                   f"{e1['move']}，收攏時是 {e0['move']}）",
                   e1["t"] >= 0.99 and e1["move"] > e0["move"] + 1, {"前": e0, "後": e1})
                ok("[無 hover 裝置] 展開的選擇寫進 localStorage（tw.dg3d.exp）",
                   mob.evaluate("() => { try { return localStorage.getItem('tw.dg3d.exp'); } catch (e) { return null; } }") == "1")
                bg2 = mob.evaluate(_L1_BG)
                if ok("[無 hover 裝置] 展開之後仍然找得到背景可以再點一次", bool(bg2), bg2):
                    mob.mouse.click(bg2["x"], bg2["y"])
                    mob.wait_for_timeout(DG3D_EXP_OUT_MS + 500)
                    e2 = mob.evaluate(_DG3D_EXP)
                    ok("[無 hover 裝置] ★ 再點一下背景 → 真的收回去（不是只會展開）",
                       e2["t"] <= 0.01 and e2["move"] <= 0.15, e2)
                # 點零件仍然是選零件，不會被「點背景切換」吃掉
                # ★ 用 hitAt 掃一個**射線真的打得到零件**的座標，不要用 screen(seg)：
                #   screen() 回的是引線錨點（零件上緣再往上），在手機的小畫布上常常落在空白處 ——
                #   那樣點下去就變成「點背景」，這一條會紅在錯的地方。
                pt = mob.evaluate(_DG3D_PART_PT)
                if pt:
                    before = mob.evaluate(_DG3D_EXP)
                    mob.mouse.click(pt["x"], pt["y"])
                    mob.wait_for_timeout(700)
                    after = mob.evaluate(_DG3D_EXP)
                    selp = mob.evaluate("() => { const e = document.querySelector('.lbl3d.sel-part'); return e ? e.dataset.dgpart : null; }")
                    ok("[無 hover 裝置] ★ 點**零件**只選零件、不會順手把展開狀態切掉（兩件事不打架）",
                       selp is not None and after["target"] == before["target"],
                       {"選到": selp, "前": before["target"], "後": after["target"]})
                # 記憶：重新載入一次，展開狀態要照上一次
                mob.evaluate("() => { try { localStorage.setItem('tw.dg3d.exp', '1'); } catch (e) {} }")
                if _dg3d_open_mobile(mob, base, L3_ROUTES["ai_server"][0]):
                    mob.wait_for_timeout(500)
                    e3 = mob.evaluate(_DG3D_EXP)
                    ok("[無 hover 裝置] ★ 下次進來照上一次的狀態（存了「展開」→ 進場就是展開的）",
                       e3["t"] == 1 and e3["move"] >= 2, e3)
    except Exception as e:                       # noqa: BLE001 —— 拿不到無 hover 環境就記一筆，不要讓整段掛掉
        notes.append(f"[無 hover 裝置] 這一節跑不完：{e}")
    finally:
        if mob:
            try:
                mob.close()
            except Exception:                    # noqa: BLE001
                pass

    # 收尾：偏好還原（3D 在開手機分頁之前就已經收掉了，見上面那段註解）
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.mouse.move(4, 4)
    pg.wait_for_timeout(600)          # 手機分頁剛關掉，讓 GPU 行程喘一口氣再繼續
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        click(pg, "#dg3d", 900)
    pg.evaluate("""() => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dganim', '1');
        localStorage.setItem('tw.dg3d.pal', 'tech'); localStorage.removeItem('tw.dg3d.exp'); } catch (e) {} }""")
"""★ 批次24（2026-09-23）：半導體鏈四張剖析圖補上 3D 立體。

Andy 2026-09-23：「確保這邊都有 3D 圖」。晶圓代工／矽晶圓／HBM／第三代半導體
四張原本 `scene: null`，現在各自有自己的場景（site/three3d.js 的 SCENES 檔尾四筆）。

這一段驗的全部是「畫面真的因此改變」，不是「元素存在」：
  ① 四張都真的掛得起來，而且零件數等於場景宣告的那個數（少一個就是有 kind 叫不到、退回方塊）
  ② 材質底色不是環節色（#238 那一刀；這四張刻意只有一個主色）
  ③ 換模式 → 材質色的指紋、畫布底、卡片底色真的變；閱讀模式零件完全不自體發光
  ④ 用滑鼠真的點一顆零件 → 只有那一顆被標成主角；真的點背景 → 全部歸零
  ⑤ 收攏（explode 0）與展開（explode 1）零件的世界座標真的不同 ——
     另一支 agent 正在把預設改成「收攏、游標移過去才爆開」，兩種狀態都要成立
  ⑥ 卡片：編號圓點、中英雙語、字級 ≥ 12px、台股晶片或明寫「台股無直接對應」（不准留白）
  ⑦ 效能上下限；⑧ 800px 窄畫面不橫向捲動、卡片不出框
"""
B24_ROUTES = {
    # 名稱: (路由, draw call 上限, 三角形上限, 三角形下限, 場景宣告的零件數)
    #   上限＝量出來的數字留約一倍餘裕；下限是「不准退回一堆方塊」的地板。
    #   第三代半導體那張的地板刻意低（量出來 424）：它畫的是**一疊薄層的半剖**，
    #   一層就是一塊板 —— 那張圖的資訊量在「層的順序與厚薄關係」，不在多邊形數。
    "晶圓代工":     ("industry/semiconductor/dg/foundry", 95, 6000, 1200, 7),
    "矽晶圓":       ("industry/semiconductor/dg/silicon_wafer", 60, 9000, 2000, 9),
    "HBM":          ("industry/semiconductor/dg/hbm", 120, 36000, 14000, 8),
    "第三代半導體": ("industry/semiconductor/dg/wide_bandgap", 70, 4000, 300, 13),
}

_B24_CARDS = """() => { const host = document.getElementById('prod3d');
  const cards = [...host.querySelectorAll('.lbl3d')];
  let minFs = 1e9;
  cards.forEach(c => c.querySelectorAll('b,i,em,.chip3d,s,small').forEach(t => {
    if (!t.textContent.trim()) return;
    const r = t.getBoundingClientRect(); if (r.width < .5) return;
    minFs = Math.min(minFs, parseFloat(getComputedStyle(t).fontSize)); }));
  return { n: cards.length,
    no: cards.filter(c => { const e = c.querySelector('em.no3d'); return e && e.textContent.trim(); }).length,
    en: cards.filter(c => { const e = c.querySelector('b small.en'); return e && e.textContent.trim(); }).length,
    // 每張卡片底下要嘛列得出台股、要嘛明寫「台股無直接對應」—— 留白是不准的
    told: cards.filter(c => { const u = c.querySelector('u.chips3d'); if (!u) return false;
      return u.querySelector('a.chip3d') || /台股無直接對應/.test(u.textContent); }).length,
    minFs: minFs === 1e9 ? null : minFs,
    noPart: cards.filter(c => !c.dataset.dgpart).map(c => c.dataset.dgno) }; }"""

# 批次24 新增的零件字彙（site/three3d.js 的 mkBuilders 檔尾那一段）。
# 少掛一個的後果不是「畫得醜一點」，是**那個 kind 安靜退回方塊**、而且沒有人會發現。
B24_KINDS = ["fetp", "fetf", "nsheet", "gaagate", "wafer", "wstack",
             "czshell", "crucible", "susceptor", "melt", "ingot", "seedrod", "heater",
             "hbmcore", "hbmbase", "tsvcol", "ubumprows",
             "wbglay", "wbgbody", "wbggate", "wbgtop", "wbgpgan", "wbgelec"]

# 收攏／展開要量的是「零件在畫面上真的動了」，不是 explode 這個變數本身
# （只看自己寫的變數就是 DECISIONS #199 那一類的錯）。
# 引線端點 .ld-dot 的 cx／cy 就是每個零件投影到畫面上的位置 —— 它動了，零件就是真的動了。
_B24_SCREEN = """() => { const out = {};
  document.querySelectorAll('#prod3d .lead3d .ld-dot').forEach((d, i) => {
    out[String(i)] = [parseFloat(d.getAttribute('cx') || '0'), parseFloat(d.getAttribute('cy') || '0')]; });
  return out; }"""


def t_b24_semi3d(pg, base):
    """批次24：半導體鏈四張的 3D（真的開、真的點、真的切模式、真的收攏展開）。"""
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(base, wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d.pal', 'tech');"
                " localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
    if not pg.evaluate("() => !!window.Rack3D"):
        notes.append("這個環境載不到 Rack3D（WebGL？），批次24-半導體鏈3D 整段跳過")
        return
    have = pg.evaluate("() => window.Rack3D.kinds()")
    if not have:
        notes.append("Rack3D.kinds() 回空（WebGL 不支援），批次24-半導體鏈3D 整段跳過")
        return
    missing = [k for k in B24_KINDS if k not in have]
    ok("批次24 新增的 kind 全部掛進分派表了（叫不到就會安靜退回方塊）", not missing, missing)
    probes = pg.evaluate("""async (ks) => { const out = [];
        for (const k of ks) out.push(await window.Rack3D.probe(k)); return out; }""", B24_KINDS)
    bad = [p for p in probes if not p or p.get("error")]
    ok("批次24 每一個新 kind 都建得起來（沒有一個丟例外）", not bad, bad[:3])
    # ⚠ 判準是「三角形數」不是「mesh 數」：這一批有好幾個 kind 刻意**只有一顆 mesh** ——
    #   坩堝是一圈車出來的（LatheGeometry）、TSV 是 InstancedMesh、電極是 merge 過的，
    #   那正是效能要的樣子。一顆方塊是 12 個三角形，門檻放在它的兩倍。
    # ⚠ 三個「層」類的 kind（半導體疊層、閘極堆疊、p-GaN）**本來就是一塊板** ——
    #   對它們要求「比方塊細」是拿錯尺量：一層的資訊量在厚薄與順序，不在多邊形。
    #   它們改驗「本體之外還有第二顆 mesh」（剖面／氧化層），那才是它們該有的東西。
    layers = {"wbglay", "wbggate", "wbgpgan"}
    flat = [p for p in probes if p and not p.get("error")
            and p["kind"] not in layers and p["tris"] <= 24]
    ok("批次24 每一個新 kind 都不只是一顆方塊（方塊＝12 個三角形，門檻放在兩倍）",
       not flat, [(p["kind"], p["meshes"], p["tris"]) for p in flat])
    thin = [p for p in probes if p and not p.get("error")
            and p["kind"] in layers and p["meshes"] < 2]
    ok("批次24 的「層」類 kind 除了本體還畫得出剖面／氧化層（不是一塊光板子）",
       not thin, [(p["kind"], p["meshes"]) for p in thin])
    # 陣列類（晶圓疊、TSV、微凸塊、加熱器立柱、奈米片、鰭）一律要收成 InstancedMesh，
    # 不然光是加熱器的 16 根立柱就是 16 個 draw call。
    # ⚠ `wafer` 不在這張表上：它的晶粒陣列要 `dies` 這個參數才畫得出來，
    #   而 probe() 只餵 box —— 拿 probe 驗它等於驗一片沒有晶粒的空晶圓。
    #   它的晶粒陣列由下面「晶圓代工那張的 draw call ≤ 95」守住（90 顆晶粒沒收成 instance 就會爆掉）。
    arr = {"wstack", "tsvcol", "ubumprows", "heater", "nsheet", "fetf"}
    noinst = [p["kind"] for p in probes if p and not p.get("error")
              and p["kind"] in arr and p["instanced"] < 1]
    ok("批次24 陣列類零件真的收成 InstancedMesh（一次 draw call）", not noinst, noinst)

    for nice, (route, cmax, tmax, tmin, nparts) in B24_ROUTES.items():
        if not _l1_open(pg, base, route):
            fails.append(f"[{nice}] 3D 掛不起來 —— 這張圖的 `scene:` 沒接上，或 WebGL 壞了")
            continue
        pg.evaluate("() => window.Rack3D.current.setPal('tech')")
        pg.wait_for_timeout(300)
        st = pg.evaluate("() => window.Rack3D.current.stats()")

        # ---------------- ① 真的畫出東西，而且零件一個都沒漏
        ok(f"[{nice}] 3D 真的畫出東西（draw call 與三角形都 > 0）",
           st["drawCalls"] > 0 and st["triangles"] > 0, st)
        ok(f"[{nice}] 零件數＝場景宣告的 {nparts} 個（少一個就是有 kind 叫不到）",
           st["parts"] == nparts, st["parts"])

        # ---------------- ⑦ 效能上下限
        ok(f"[{nice}] draw call 在上限內（{st['drawCalls']} ≤ {cmax}）", st["drawCalls"] <= cmax, st["drawCalls"])
        ok(f"[{nice}] 三角形在上限內（{st['triangles']} ≤ {tmax}）", st["triangles"] <= tmax, st["triangles"])
        ok(f"[{nice}] 三角形沒有退回「一堆方塊」（下限 {tmin}）", st["triangles"] >= tmin, st["triangles"])

        # ---------------- ② 材質底色 ≠ 環節色
        a = pg.evaluate(_L3_PROBE)
        near = [(m["part"], m["base"], m["segHex"], _dist(m["base"], m["segHex"])) for m in a["mats"]
                if _dist(m["base"], m["segHex"]) < 20]
        ok(f"[{nice}] ★ 沒有任何一個零件的材質底色是環節色（#238 那一刀）", not near, near[:4])
        ok(f"[{nice}] 還沒點任何零件時，沒有一顆被拉向環節色",
           not any(m["tinted"] for m in a["mats"]),
           [m["part"] for m in a["mats"] if m["tinted"]][:4])

        # ---------------- ③ 兩種模式：切了畫面真的變
        pg.evaluate("() => window.Rack3D.current.setPal('read')")
        pg.wait_for_timeout(500)
        r = pg.evaluate(_L3_PROBE)
        _mv = _pal_moved(a, r)
        ok(f"[{nice}] 切到「閱讀」→ **每一個零件**現在畫出來的顏色都真的換了"
           f"（{len(_mv)}/{len(a['mats'])}；colorSig {a['colorSig']} → {r['colorSig']} 只是參考值）",
           len(_mv) == len(a["mats"]) and len(a["mats"]) > 0,
           {"沒換色的零件": [m["part"] for m in a["mats"] if m["part"] not in {x[0] for x in _mv}][:6]})
        ok(f"[{nice}] 切到「閱讀」→ 畫布底真的變了",
           r["pal"] == "read" and r["bg"] != a["bg"], f"{a['bg'][:50]} → {r['bg'][:50]}")
        ok(f"[{nice}] 切到「閱讀」→ 卡片底色與字色真的變了",
           r["cardBg"] != a["cardBg"] and r["ink"] != a["ink"],
           {"科技": (a["cardBg"], a["ink"]), "閱讀": (r["cardBg"], r["ink"])})
        ok(f"[{nice}] 「閱讀」模式零件完全不自體發光（淺底上發光會刺眼）", r["idleEm"] == 0, r["idleEm"])
        pg.evaluate("() => window.Rack3D.current.setPal('tech')")
        pg.wait_for_timeout(300)

        # ---------------- ⑥ 卡片：編號圓點、中英雙語、字級、台股不留白
        c = pg.evaluate(_B24_CARDS)
        ok(f"[{nice}] 每張卡片都有編號圓點", c["no"] == c["n"] and c["n"] > 0, f"{c['no']}/{c['n']}")
        ok(f"[{nice}] 每張卡片都有英文副標（中英雙語，v3 §4）", c["en"] == c["n"], f"{c['en']}/{c['n']}")
        ok(f"[{nice}] 每張卡片的零件身分（data-dgpart）都在，2D 才點得到同一個零件",
           not c["noPart"], c["noPart"])
        ok(f"[{nice}] 每張卡片底下要嘛列得出台股、要嘛明寫「台股無直接對應」（不准留白）",
           c["told"] == c["n"], f"{c['told']}/{c['n']}")
        ok(f"[{nice}] 卡片上最小的字 ≥ 12px", c["minFs"] is not None and c["minFs"] >= 11.9, c["minFs"])

        # ---------------- ⑤ 收攏／展開兩種狀態都成立
        #   另一支 agent 正在把預設改成「收攏、游標移過去才爆開」，所以兩邊都要驗得到。
        #   ⚠ 一定要先把畫布捲進畫面：三、四張圖的畫布很高，離開視窗時
        #     IntersectionObserver 會把 rAF 停掉（那是刻意的省電機制），
        #     引線端點就不會重算 —— 量到的會是「一個都沒動」的假紅。
        scroll_to(pg, "prod3d")
        pg.wait_for_timeout(500)
        # ⚠ 等 1200ms 不是隨便抓的：容器裡是軟體渲染，這幾張的 rAF 大約 3 fps
        #   （DECISIONS #244 七量過），一幀就要 330ms。等 300ms 有可能**一幀都還沒畫**，
        #   兩次取樣就會拿到同一批舊座標 —— 那是假紅，不是零件沒動（矽晶圓那張實際踩到）。
        pg.evaluate("() => window.Rack3D.current.explode(0)")
        pg.wait_for_timeout(1200)
        p0 = pg.evaluate(_B24_SCREEN)
        pg.evaluate("() => window.Rack3D.current.explode(1)")
        pg.wait_for_timeout(1200)
        p1 = pg.evaluate(_B24_SCREEN)
        moved = sum(1 for k in p0 if k in p1 and (abs(p0[k][0] - p1[k][0]) > 2 or abs(p0[k][1] - p1[k][1]) > 2))
        ok(f"[{nice}] ★ 收攏 → 展開時零件真的在畫面上移動了（{moved}/{len(p0)} 個零件）",
           moved >= max(2, len(p0) // 2), {"收攏": dict(list(p0.items())[:3]), "展開": dict(list(p1.items())[:3])})
        # 「每個零件都要給 ex」量的是場景宣告本身：有些零件的位移在這個視角下投影出來不到 2px，
        # 拿畫面位移當唯一證據會變成「看不到就當沒給」—— 那是量錯了東西。
        noex = pg.evaluate("""(id) => { const s = window.Rack3D.SCENES[id];
            return s.parts.filter(p => !p.ex || (!p.ex[0] && !p.ex[1] && !p.ex[2])).map(p => p.part); }""",
                           route.rsplit("/", 1)[-1])
        ok(f"[{nice}] 每個零件都給了爆炸位移 ex（收攏看得出成品、展開看得出層次）", not noex, noex)

        # ---------------- ④ 真的用滑鼠點一顆零件 → 只有那一顆；點背景 → 全部歸零
        anim_txt = text(pg, "#dgAnim")
        if "開" in anim_txt:                       # 先把動畫關掉，座標才不會在點下去之前飄走
            pg.eval_on_selector("#dgAnim", "b => b.click()")
            pg.wait_for_timeout(900)
        pg.evaluate("() => window.Rack3D.current.explode(1)")
        pg.wait_for_timeout(300)
        scroll_to(pg, "prod3d")
        seg = pg.evaluate("""() => { const v = window.Rack3D.current;
            const cv = document.querySelector('#prod3d canvas'); if (!cv) return null;
            const r = cv.getBoundingClientRect();
            return v.segs().find(s => { const p = v.screen(s);
              return p && p.x > r.left + 8 && p.x < r.right - 8
                       && p.y > Math.max(r.top, 0) + 8 && p.y < Math.min(r.bottom, innerHeight) - 8; }); }""")
        pt = pg.evaluate("(s) => s ? window.Rack3D.current.screen(s) : null", seg)
        sig0 = pg.evaluate("() => window.Rack3D.current.stats().matSig")
        # ★ 基準是「點零件之前長什麼樣」，不是 0。族群層級的網址（/dg/<族群>）本來就會
        #   把那個族群的環節點亮 —— 在那種頁面上「點背景＝全部歸零」從一開始就是錯的期待
        #   （t_dg3d_parts 2026-09-22 已經踩過同一個坑）。
        h0 = pg.evaluate(_L1_HI)
        if not pt:
            fails.append(f"[{nice}] 在畫布上找不到任何點得到的零件座標，「點零件」這一條驗不了")
        else:
            pg.mouse.click(pt["x"], pt["y"])
            pg.wait_for_timeout(900)
            h1 = pg.evaluate(_L1_HI)
            sig1 = pg.evaluate("() => window.Rack3D.current.stats().matSig")
            ok(f"[{nice}] 真的用滑鼠點一顆零件 → 只有那一顆被標成主角",
               h1["selPart"] == 1, {"點之後": h1, "座標": pt})
            ok(f"[{nice}] 點完之後材質狀態的指紋也變了（不是只有 class 換）",
               sig0 != sig1, f"{sig0} -> {sig1}")
            bg = pg.evaluate(_L1_BG)
            if not bg:
                fails.append(f"[{nice}] 在畫布上找不到「打不到零件」的空白點，「點背景」驗不了")
            else:
                pg.mouse.click(bg["x"], bg["y"])
                pg.wait_for_timeout(700)
                h2 = pg.evaluate(_L1_HI)
                back = pg.evaluate("() => !document.getElementById('prod3d').classList.contains('haspart')")
                ok(f"[{nice}] 真的點背景 → 零件的選取真的清掉、回到點之前的樣子"
                   f"（主角 {h1['selPart']} → {h2['selPart']}、dim {h1['dim']} → {h2['dim']}）",
                   h2["selPart"] == 0 and h2["dim"] == h0["dim"] and h2["sel"] == h0["sel"] and back,
                   {"點零件之前": h0, "點零件之後": h1, "點背景之後": h2, "座標": bg})

    # ---------------- ⑧ 800px 窄畫面：不橫向捲動、卡片不出框
    #   （AGENTS：開發過程就要驗窄畫面，不要只在 1440 看 —— DECISIONS #171 就是這樣漏掉的）
    for nice, (route, _c, _t, _tm, _n) in B24_ROUTES.items():
        pg.set_viewport_size({"width": 800, "height": 1000})
        if not _l1_open(pg, base, route):
            notes.append(f"[800px] {nice} 3D 掛不起來，窄畫面那一條跳過")
            continue
        pg.wait_for_timeout(900)
        z = pg.evaluate(DG3D_AUDIT)
        ok(f"[{nice} 800px] 3D 畫布本身不橫向捲動（{z['scrollW']} ≤ {z['clientW']}）",
           z["scrollW"] <= z["clientW"] + 1, z)
        ok(f"[{nice} 800px] 每一張卡片都完整落在 3D 容器內（不會被切一半）",
           not z["cardsOut"], z["cardsOut"][:5])
        ok(f"[{nice} 800px] 3D 畫布真的吃到欄寬（不是縮成一小塊）：{z['hostW']}px",
           z["hostW"] >= min(300, 800 - 90), z["hostW"])

    pg.set_viewport_size({"width": 1500, "height": 1000})
    # 收尾：把 3D 關回平面圖、偏好恢復預設（跟「3D零件字彙」那一段同一條規矩）
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        click(pg, "#dg3d", 900)
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0');"
                " localStorage.setItem('tw.dganim', '1');"
                " localStorage.setItem('tw.dg3d.pal', 'tech'); } catch (e) {} }")


"""批次27：AI 伺服器鏈六張補上 3D（IC 載板／PCB 硬板／電源／液冷／氣冷／網通）。

★ 這一段一律 `--workers 1`（跟批次24 同一個理由）：多工時 CPU 被吃滿，
  工具列的「3D 立體」鈕六秒都點不到，整批會變成假紅。

驗的跟批次24 完全一樣的八件事（寫法直接照抄 `t_b24_semi3d`，連踩過的坑都照抄）：
  ① 3D 真的掛得起來、零件數＝場景宣告的數字
  ② 材質底色不是環節色（DECISIONS #238 那一刀）
  ③ 切「科技／閱讀」→ 材質指紋、畫布底、卡片底色、字色四樣都真的變
  ④ 用滑鼠真的點一顆零件 → 只有那一顆被標成主角；真的點背景 → 回到點之前的樣子
  ⑤ 收攏（explode 0）與展開（explode 1）零件在畫面上真的移動了
  ⑥ 卡片：編號圓點、中英雙語、字級 ≥ 12px、台股晶片或明寫「台股無直接對應」（不准留白）
  ⑦ 效能上下限；⑧ 800px 窄畫面不橫向捲動、卡片不出框
另外多驗一條批次24 沒有的：**`codes: []` 的零件真的顯示「台股無直接對應」** ——
這一批新增了「明說沒有對應」這個寫法（DECISIONS #250），沒有斷言的話它安靜退回去
列該環節的台股，就會變成「散熱廠在做那顆晶片」這種錯誤宣稱。
"""
B27_ROUTES = {
    # 名稱: (路由, draw call 上限, 三角形上限, 三角形下限, 場景宣告的零件數)
    #   上限＝量出來的數字留約一倍餘裕；下限是「不准退回一堆方塊」的地板。
    #   ⚠ 下限各自訂，不是一個全站的數字：載板與硬板畫的是**一疊薄層的半剖**，
    #     一層就是一塊板，資訊量在「層的順序與厚薄關係」，不在多邊形數（#247 §三 同一條）。
    "IC載板":     ("industry/ai_server/dg/ic_substrate", 80, 18000, 3000, 11),
    "PCB硬板":    ("industry/ai_server/dg/pcb_rigid", 50, 11000, 1800, 13),
    "電源PSU3D":  ("industry/ai_server/dg/server_psu", 150, 12000, 2000, 10),
    "液冷":       ("industry/ai_server/dg/liquid_cooling", 130, 12000, 2000, 13),
    "氣冷":       ("industry/ai_server/dg/air_cooling", 120, 14000, 2200, 12),
    "網通板卡":   ("industry/ai_server/dg/switch_wireless", 210, 30000, 6000, 13),
}

# 批次27 新增的零件字彙（site/three3d.js 的 mkBuilders 檔尾那一段）。
# 少掛一個的後果不是「畫得醜一點」，是**那個 kind 安靜退回方塊**、而且沒有人會發現。
B27_KINDS = ["abfcore", "abfbu", "abftrace", "abfvia", "abfsr", "abfpad", "abfbga",
             "pcblay", "pcbtrc", "pcbmask", "pcbenig", "pcbvia",
             "pshelf", "pshell", "pboard", "pcardedge", "pbusbar", "pvrm", "pbbu", "pscap",
             "timlay", "ihslid", "cplate", "cpfin", "cpport", "lcmani", "lcphe",
             "fframe", "frotor", "fhub", "fmotor", "fbear", "fwire", "fwall", "fshroud",
             "swboard", "swasic", "swcage", "swmod", "swgold", "swcpo"]

# 陣列類：這幾個 kind 一定要收成 InstancedMesh，不然光是籠架 24 格就是 24 個 draw call。
B27_ARRAY_KINDS = {"abfvia", "abfpad", "abfbga", "abftrace", "pcbtrc", "pcbvia",
                   "cpfin", "pvrm", "pbbu", "pscap", "fwall", "swcage"}

# `codes: []` ＝ 明說「台股無直接對應」。少了斷言，它退回去列該環節的台股就會變成錯誤宣稱。
B27_NO_TW = {
    "industry/ai_server/dg/ic_substrate": ["abf_die_ghost"],
    "industry/ai_server/dg/server_psu": ["psu_die"],
    "industry/ai_server/dg/liquid_cooling": ["die"],
    "industry/ai_server/dg/switch_wireless": ["sw_cpu"],
}


def t_b27_aiserver3d(pg, base):
    """批次27：AI 伺服器鏈六張的 3D（真的開、真的點、真的切模式、真的收攏展開）。"""
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(base, wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d.pal', 'tech');"
                " localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
    if not pg.evaluate("() => !!window.Rack3D"):
        notes.append("這個環境載不到 Rack3D（WebGL？），批次27-AI伺服器鏈3D 整段跳過")
        return
    have = pg.evaluate("() => window.Rack3D.kinds()")
    if not have:
        notes.append("Rack3D.kinds() 回空（WebGL 不支援），批次27-AI伺服器鏈3D 整段跳過")
        return
    missing = [k for k in B27_KINDS if k not in have]
    ok("批次27 新增的 kind 全部掛進分派表了（叫不到就會安靜退回方塊）", not missing, missing)
    probes = pg.evaluate("""async (ks) => { const out = [];
        for (const k of ks) out.push(await window.Rack3D.probe(k)); return out; }""", B27_KINDS)
    bad = [p for p in probes if not p or p.get("error")]
    ok("批次27 每一個新 kind 都建得起來（沒有一個丟例外）", not bad, bad[:3])
    # ⚠ 判準是「三角形數」不是「mesh 數」（#247 §五-1 踩過）：這一批也有好幾個 kind
    #   刻意**只有一兩顆 mesh** —— 一整疊層 merge 成一個、整片孔收成 InstancedMesh，
    #   那正是效能要的樣子。一顆方塊是 12 個三角形，門檻放在它的兩倍。
    flat = [p for p in probes if p and not p.get("error") and p["tris"] <= 24]
    ok("批次27 每一個新 kind 都不只是一顆方塊（方塊＝12 個三角形，門檻放在兩倍）",
       not flat, [(p["kind"], p["meshes"], p["tris"]) for p in flat])
    noinst = [p["kind"] for p in probes if p and not p.get("error")
              and p["kind"] in B27_ARRAY_KINDS and p["instanced"] < 1]
    ok("批次27 陣列類零件真的收成 InstancedMesh（一次 draw call）", not noinst, noinst)

    for nice, (route, cmax, tmax, tmin, nparts) in B27_ROUTES.items():
        if not _l1_open(pg, base, route):
            fails.append(f"[{nice}] 3D 掛不起來 —— 這張圖的 `scene:` 沒接上，或 WebGL 壞了")
            continue
        pg.evaluate("() => window.Rack3D.current.setPal('tech')")
        pg.wait_for_timeout(300)
        st = pg.evaluate("() => window.Rack3D.current.stats()")

        # ---------------- ① 真的畫出東西，而且零件一個都沒漏
        ok(f"[{nice}] 3D 真的畫出東西（draw call 與三角形都 > 0）",
           st["drawCalls"] > 0 and st["triangles"] > 0, st)
        ok(f"[{nice}] 零件數＝場景宣告的 {nparts} 個（少一個就是有 kind 叫不到）",
           st["parts"] == nparts, st["parts"])

        # ---------------- ⑦ 效能上下限
        ok(f"[{nice}] draw call 在上限內（{st['drawCalls']} ≤ {cmax}）", st["drawCalls"] <= cmax, st["drawCalls"])
        ok(f"[{nice}] 三角形在上限內（{st['triangles']} ≤ {tmax}）", st["triangles"] <= tmax, st["triangles"])
        ok(f"[{nice}] 三角形沒有退回「一堆方塊」（下限 {tmin}）", st["triangles"] >= tmin, st["triangles"])

        # ---------------- ② 材質底色 ≠ 環節色
        a = pg.evaluate(_L3_PROBE)
        near = [(m["part"], m["base"], m["segHex"], _dist(m["base"], m["segHex"])) for m in a["mats"]
                if _dist(m["base"], m["segHex"]) < 20]
        ok(f"[{nice}] ★ 沒有任何一個零件的材質底色是環節色（#238 那一刀）", not near, near[:4])
        ok(f"[{nice}] 還沒點任何零件時，沒有一顆被拉向環節色",
           not any(m["tinted"] for m in a["mats"]),
           [m["part"] for m in a["mats"] if m["tinted"]][:4])

        # ---------------- ③ 兩種模式：切了畫面真的變
        pg.evaluate("() => window.Rack3D.current.setPal('read')")
        pg.wait_for_timeout(500)
        r = pg.evaluate(_L3_PROBE)
        _mv = _pal_moved(a, r)
        ok(f"[{nice}] 切到「閱讀」→ **每一個零件**現在畫出來的顏色都真的換了"
           f"（{len(_mv)}/{len(a['mats'])}；colorSig {a['colorSig']} → {r['colorSig']} 只是參考值）",
           len(_mv) == len(a["mats"]) and len(a["mats"]) > 0,
           {"沒換色的零件": [m["part"] for m in a["mats"] if m["part"] not in {x[0] for x in _mv}][:6]})
        ok(f"[{nice}] 切到「閱讀」→ 畫布底真的變了",
           r["pal"] == "read" and r["bg"] != a["bg"], f"{a['bg'][:50]} → {r['bg'][:50]}")
        ok(f"[{nice}] 切到「閱讀」→ 卡片底色與字色真的變了",
           r["cardBg"] != a["cardBg"] and r["ink"] != a["ink"],
           {"科技": (a["cardBg"], a["ink"]), "閱讀": (r["cardBg"], r["ink"])})
        ok(f"[{nice}] 「閱讀」模式零件完全不自體發光（淺底上發光會刺眼）", r["idleEm"] == 0, r["idleEm"])
        pg.evaluate("() => window.Rack3D.current.setPal('tech')")
        pg.wait_for_timeout(300)

        # ---------------- ⑥ 卡片：編號圓點、中英雙語、字級、台股不留白
        c = pg.evaluate(_B24_CARDS)
        ok(f"[{nice}] 每張卡片都有編號圓點", c["no"] == c["n"] and c["n"] > 0, f"{c['no']}/{c['n']}")
        ok(f"[{nice}] 每張卡片都有英文副標（中英雙語，v3 §4）", c["en"] == c["n"], f"{c['en']}/{c['n']}")
        ok(f"[{nice}] 每張卡片的零件身分（data-dgpart）都在，2D 才點得到同一個零件",
           not c["noPart"], c["noPart"])
        ok(f"[{nice}] 每張卡片底下要嘛列得出台股、要嘛明寫「台股無直接對應」（不准留白）",
           c["told"] == c["n"], f"{c['told']}/{c['n']}")
        ok(f"[{nice}] 卡片上最小的字 ≥ 12px", c["minFs"] is not None and c["minFs"] >= 11.9, c["minFs"])
        # ★ 批次27 多的這一條：`codes: []` 的零件**一定要**顯示「台股無直接對應」。
        #   它要是安靜退回去列該環節的台股，畫面上就會變成
        #   「散熱廠在做那顆晶片」「電源廠在做那顆 GPU」這種錯誤宣稱 —— 那比沒有圖還糟。
        for part in B27_NO_TW.get(route, []):
            said = pg.evaluate("""(pt) => { const c = document.querySelector(`#prod3d .lbl3d[data-dgpart="${pt}"]`);
                if (!c) return null; const u = c.querySelector('u.chips3d');
                return { none: !!u && /台股無直接對應/.test(u.textContent), chips: u ? u.querySelectorAll('a.chip3d').length : -1 }; }""", part)
            ok(f"[{nice}] `{part}` 明寫「台股無直接對應」，沒有退回去列該環節的台股",
               bool(said) and said["none"] and said["chips"] == 0, said)

        # ---------------- ⑤ 收攏／展開兩種狀態都成立
        #   ⚠ 先捲進畫面再量，而且等 1200ms —— 兩個都是 #247 §五-3 記過的坑：
        #     離開視窗時 IntersectionObserver 會把 rAF 停掉；容器裡是軟體渲染，
        #     一幀就要三百多毫秒，等 300ms 會拿到同一批舊座標（假紅）。
        scroll_to(pg, "prod3d")
        pg.wait_for_timeout(500)
        pg.evaluate("() => window.Rack3D.current.explode(0)")
        pg.wait_for_timeout(1200)
        p0 = pg.evaluate(_B24_SCREEN)
        pg.evaluate("() => window.Rack3D.current.explode(1)")
        pg.wait_for_timeout(1200)
        p1 = pg.evaluate(_B24_SCREEN)
        moved = sum(1 for k in p0 if k in p1 and (abs(p0[k][0] - p1[k][0]) > 2 or abs(p0[k][1] - p1[k][1]) > 2))
        ok(f"[{nice}] ★ 收攏 → 展開時零件真的在畫面上移動了（{moved}/{len(p0)} 個零件）",
           moved >= max(2, len(p0) // 2), {"收攏": dict(list(p0.items())[:3]), "展開": dict(list(p1.items())[:3])})
        # 「每個零件都要給 ex」量的是場景宣告本身：有些零件的位移在這個視角下投影出來不到 2px，
        # 拿畫面位移當唯一證據會變成「看不到就當沒給」—— 那是量錯了東西。
        noex = pg.evaluate("""(id) => { const s = window.Rack3D.SCENES[id];
            return s.parts.filter(p => !p.ex || (!p.ex[0] && !p.ex[1] && !p.ex[2])).map(p => p.part); }""",
                           route.rsplit("/", 1)[-1])
        ok(f"[{nice}] 每個零件都給了爆炸位移 ex（收攏看得出成品、展開看得出層次）", not noex, noex)

        # ---------------- ④ 真的用滑鼠點一顆零件 → 只有那一顆；點背景 → 回到點之前
        anim_txt = text(pg, "#dgAnim")
        if "開" in anim_txt:                       # 先把動畫關掉，座標才不會在點下去之前飄走
            pg.eval_on_selector("#dgAnim", "b => b.click()")
            pg.wait_for_timeout(900)
        pg.evaluate("() => window.Rack3D.current.explode(1)")
        pg.wait_for_timeout(300)
        scroll_to(pg, "prod3d")
        seg = pg.evaluate("""() => { const v = window.Rack3D.current;
            const cv = document.querySelector('#prod3d canvas'); if (!cv) return null;
            const r = cv.getBoundingClientRect();
            return v.segs().find(s => { const p = v.screen(s);
              return p && p.x > r.left + 8 && p.x < r.right - 8
                       && p.y > Math.max(r.top, 0) + 8 && p.y < Math.min(r.bottom, innerHeight) - 8; }); }""")
        pt = pg.evaluate("(s) => s ? window.Rack3D.current.screen(s) : null", seg)
        sig0 = pg.evaluate("() => window.Rack3D.current.stats().matSig")
        # ★ 基準是「點零件之前長什麼樣」，不是 0（#247 §五-2）：`/dg/<族群>` 本來就會
        #   把那個族群的環節點亮，在那種頁面上「點背景＝全部歸零」從一開始就是錯的期待。
        h0 = pg.evaluate(_L1_HI)
        if not pt:
            fails.append(f"[{nice}] 在畫布上找不到任何點得到的零件座標，「點零件」這一條驗不了")
        else:
            pg.mouse.click(pt["x"], pt["y"])
            pg.wait_for_timeout(900)
            h1 = pg.evaluate(_L1_HI)
            sig1 = pg.evaluate("() => window.Rack3D.current.stats().matSig")
            ok(f"[{nice}] 真的用滑鼠點一顆零件 → 只有那一顆被標成主角",
               h1["selPart"] == 1, {"點之後": h1, "座標": pt})
            ok(f"[{nice}] 點完之後材質狀態的指紋也變了（不是只有 class 換）",
               sig0 != sig1, f"{sig0} -> {sig1}")
            bg = pg.evaluate(_L1_BG)
            if not bg:
                fails.append(f"[{nice}] 在畫布上找不到「打不到零件」的空白點，「點背景」驗不了")
            else:
                pg.mouse.click(bg["x"], bg["y"])
                pg.wait_for_timeout(700)
                h2 = pg.evaluate(_L1_HI)
                back = pg.evaluate("() => !document.getElementById('prod3d').classList.contains('haspart')")
                ok(f"[{nice}] 真的點背景 → 零件的選取真的清掉、回到點之前的樣子"
                   f"（主角 {h1['selPart']} → {h2['selPart']}、dim {h1['dim']} → {h2['dim']}）",
                   h2["selPart"] == 0 and h2["dim"] == h0["dim"] and h2["sel"] == h0["sel"] and back,
                   {"點零件之前": h0, "點零件之後": h1, "點背景之後": h2, "座標": bg})

    # ---------------- ⑧ 800px 窄畫面：不橫向捲動、卡片不出框
    for nice, (route, _c, _t, _tm, _n) in B27_ROUTES.items():
        pg.set_viewport_size({"width": 800, "height": 1000})
        if not _l1_open(pg, base, route):
            notes.append(f"[800px] {nice} 3D 掛不起來，窄畫面那一條跳過")
            continue
        pg.wait_for_timeout(900)
        z = pg.evaluate(DG3D_AUDIT)
        ok(f"[{nice} 800px] 3D 畫布本身不橫向捲動（{z['scrollW']} ≤ {z['clientW']}）",
           z["scrollW"] <= z["clientW"] + 1, z)
        ok(f"[{nice} 800px] 每一張卡片都完整落在 3D 容器內（不會被切一半）",
           not z["cardsOut"], z["cardsOut"][:5])
        ok(f"[{nice} 800px] 3D 畫布真的吃到欄寬（不是縮成一小塊）：{z['hostW']}px",
           z["hostW"] >= min(300, 800 - 90), z["hostW"])

    pg.set_viewport_size({"width": 1500, "height": 1000})
    # 收尾：把 3D 關回平面圖、偏好恢復預設（跟批次24 同一條規矩）
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        click(pg, "#dg3d", 900)
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0');"
                " localStorage.setItem('tw.dganim', '1');"
                " localStorage.setItem('tw.dg3d.pal', 'tech'); } catch (e) {} }")

# ---------------------------------------------------------------------------
# 產業鏈頁「供應鏈關聯圖」的共用操作（2026-09-23 C5 退版之後重寫）
#
# 退版前這幾支操作的是力導向星際圖：環節色標藏在右上角「篩選」浮層裡（要先開面板）、
# 個股是族群大圓點周圍會公轉的小圓點（要等座標穩下來才點得到）、資訊欄是 `#cgSide`。
# 退版之後那三樣東西都不存在了：
#   · 環節色標回到圖的正上方 `#segChips`，永遠看得到 —— 所以「開面板」這一步整個消失
#   · 個股是環節卡清單裡的標籤 `.seglist .segcard .sco[data-code]`，**靜態的**，
#     不會自己動，所以「等座標穩下來」那 4 秒的輪詢也整個消失
#   · 資訊欄是 `#coBox`（`.relside` ＝ 寬畫面排在圖的右邊）
#
# ⚠ 這幾支被**很多段**驗收共用（產業、族群頁、批次2／3／7、新-產業與個股…）。
#   舊的呼叫端都寫死了 `#segChips .segchip[...]` 這種選擇器，改呼叫端要動十幾處、
#   而且那些段落不在這一批的範圍內。所以選擇器的翻譯做在**這裡**：
#   `_cg_chip` 自己把 `#segChips` 換成 `#segChips`，呼叫端一行都不必改。
# ---------------------------------------------------------------------------
def _cg_open_filter(pg):
    """退版之後環節色標就在圖的上方，沒有「篩選」面板可開 —— 這支保留成 no-op。

    為什麼不直接刪掉：它有十幾個呼叫端散在別的段落裡，那些段落不在這一批的範圍。
    留一個永遠成功的空殼，比改十幾個不相干的段落安全。
    """
    return True


def _cg_close_filter(pg):
    """同上：沒有浮層要收，保留成 no-op。"""
    return True


def _cg_chip(pg, sel: str, wait: int = 800):
    """點一顆環節色標（`#segChips` 裡那一排）。

    舊呼叫端傳進來的選擇器寫的是 `#segChips`（力導向版本色標的容器 id），
    這裡統一翻譯成新的 `#segChips`，呼叫端不必改。
    """
    sel = sel.replace('#segChips', '#segChips')
    # ★ 2026-09-24（Andy：上方標籤改成下拉清單）桌機的色標收在「環節：全部 ▾」下拉裡，
    #   平常看不到 —— 真人要先按下拉鈕才點得到，這裡照做。手機（≤820px）色標照舊攤開，不會走進這一段。
    #   改前：直接 click(sel)；改後：看不到就先按 #segDDBtn 打開下拉再點。
    if pg.evaluate("""(s) => { const c = document.querySelector(s), b = document.getElementById('segDDBtn');
        if (!c || !b || b.offsetParent === null) return false;
        const r = c.getBoundingClientRect(); return !(r.width > 0 && r.height > 0); }""", sel):
        # 先把下拉鈕瞬間捲到畫面中間、等捲動停：選完一格之後頁面可能還在把圖上那一格帶進視野，
        # 這時候直接點會點到正在移動的鈕（實測被圖本身擋到：「svg … intercepts pointer events」）
        settle_scroll(pg)
        pg.evaluate("() => { const b = document.getElementById('segDDBtn'); const r = b.getBoundingClientRect();"
                    " window.scrollBy({ top: r.top - innerHeight / 2, behavior: 'instant' }); }")
        settle_scroll(pg)
        click(pg, "#segDDBtn", 250)
    return click(pg, sel, wait)


def _cg_click_dot(pg, code: str, wait: int = 1400) -> bool:
    """用真的滑鼠點某一檔的個股標籤，回傳有沒有點到。

    退版之後標籤是靜態的 `<button class="sco">`，不會被力導向重建、也不會公轉，
    所以直接 `click()` 就好 —— 那正是真人做的事。
    手機上它所屬的環節卡可能是收起來的，先按那張卡的 ▾ 把它攤開（真人也一樣）。
    """
    # ★ 2026-09-24（Andy：「下方那片環節字卡全部拿掉 —— 跟上面的關聯圖重複了」）：
    #   桌機（>820px）的環節字卡 `.seglist` 藏起來了，個股的入口只剩**關聯圖上的公司卡**，真人也是點那一張。
    #   點公司卡走的是同一支 showCompany ＋ onCompany（開資訊欄、選起它的環節），結果跟以前點標籤一樣。
    #   改前：一律點 `.seglist .sco`；改後：字卡看不到時改點 `#chainMap .co[data-code]`。手機照舊點字卡。
    if not pg.evaluate("() => { const l = document.querySelector('.seglist'); return !!l && l.getClientRects().length > 0; }"):
        card = f'#chainMap .co[data-code="{code}"]'
        if not pg.query_selector(card):
            return False
        pg.eval_on_selector(card, "e => e.scrollIntoView({block:'center'})")
        settle_scroll(pg)
        return bool(click(pg, card, wait))
    sel = f'.seglist .segcard .sco[data-code="{code}"]'
    if not pg.evaluate("(c) => [...document.querySelectorAll('.seglist .segcard .sco')]"
                       ".some(e => e.dataset.code === c)", code):
        # 收起來的卡片會把標籤整段從 DOM 拆下來（見 industry.js drawSegList 的註解），
        # 所以「找不到」有可能只是還沒展開 —— 把「全部展開」按下去再找一次。
        if pg.query_selector("#segTools .segx"):
            click(pg, "#segTools .segx", 400)
        if not pg.evaluate("(c) => [...document.querySelectorAll('.seglist .segcard .sco')]"
                           ".some(e => e.dataset.code === c)", code):
            return False
    pg.eval_on_selector(sel, "e => e.scrollIntoView({block:'center'})")
    pg.wait_for_timeout(200)
    if not click(pg, sel, wait):
        return False
    return True


def _cg_open_stock(pg, code: str) -> bool:
    """在產業鏈頁把某一檔台股的產業關係面板（`#coBox`）打開，回傳「真的打開了嗎」。

    回 False 代表這一檔不在這條鏈的清單上（例如它的族群屬於別條鏈），
    呼叫端要自己決定那算不算失敗。
    """
    if not _cg_click_dot(pg, code, 1200):
        return False
    return bool(pg.evaluate("(c) => { const b = document.getElementById('coBox');"
                            " return !!b && ((b.innerText || '').indexOf(c) >= 0"
                            "  || b.dataset.code === c); }", code))


# ===========================================================================
# 批次25／批次C5：產業鏈頁的「供應鏈關聯圖」（2026-09-23 C5 退版＋優化）
#
# Andy 的原話（逐字，不改寫）：
#   「下方的關聯圖回到之前的設計，幫我退版 回到之前的格式，但是需要將關聯圖置中，並且，
#     Default 顯示族群相連標籤個股，點擊後才會跳初下拉清單，並且點擊股票 右側會顯示對應訊息」
#   「舊版關聯圖調查 改成 退版 並優化，不是要你調查，是我不滿意現況，
#     不然你先展示你認為更好表達的形式」
#
# 力導向星際圖（DECISIONS #248）整組退場，所以它那一整套斷言（風格指紋、光暈層數、
# animateMotion、rAF 幀距、力導向收斂、拖曳平移…）全部刪掉 —— 那些東西已經不在畫面上，
# 留著只會驗一個不存在的產品。這裡改成量新版真的做到了什麼：
#
#   ① Default（**一下都沒點**）就看得到：分層圖的公司卡、環節卡清單、每張卡的上游／下游、
#      以及卡底下的個股標籤。這條對應「Default 顯示族群相連標籤個股」。
#   ② **置中與撐滿要真的量出來**：用 getBoundingClientRect 取所有節點的聯集外接盒，
#      跟容器比 —— 撐滿率 ≥ 90%、水平置中誤差 ≤ 1%。這條對應「需要將關聯圖置中」，
#      而且是這一批最容易退化的一條（舊版的毛病就是靠左 ＋ 右邊空一大塊）。
#   ③ **點擊後才會跳出下拉清單**：`#segBox`（環節詳情＋跨鏈對照）Default 高度是 0，
#      點色標之後 > 0，再點一次回到 0。量的是**高度真的變了**，不是元素存不存在。
#   ④ **點擊股票 右側會顯示對應訊息**：點個股標籤 → `#coBox.relside` 出現在圖的**右邊**
#      （left 大於圖的 left），內容含那一檔；再點另一檔 → 內容真的換人。
#      窄畫面（800px）它掉到圖的**下方**（top 大於圖的 top）。
#   ⑤ 「並優化」那一半：兩種表達形式（分層圖／流向圖）真的切得動、偏好真的寫進 localStorage、
#      hover 一張卡會把線與**另一端的公司卡**一起提亮、收合鈕真的收得掉。
# ===========================================================================

# 量「這張圖有沒有撐滿、有沒有置中」。
# 量的是**節點本身**的聯集（公司卡 `.co`／環節標題 `.segtitle`／流向圖的環節方塊 `.fseg`），
# 不是 SVG 的 viewBox —— viewBox 是前端自己宣告的，拿它來驗等於自己驗自己。
REL_FIT = """() => {
  const h = document.getElementById('chainMap'); if (!h) return null;
  const r = h.getBoundingClientRect();
  const els = [...h.querySelectorAll('.co, .segtitle, .fseg')];
  if (!els.length || r.width < 1) return { n: els.length, w: Math.round(r.width) };
  let x0 = 1e9, x1 = -1e9, y1 = -1e9;
  els.forEach(e => { const b = e.getBoundingClientRect();
    x0 = Math.min(x0, b.left); x1 = Math.max(x1, b.right); y1 = Math.max(y1, b.bottom); });
  return { n: els.length, host: Math.round(r.width),
           fill: +(((x1 - x0) / r.width) * 100).toFixed(1),
           dx: +((((x0 + x1) / 2 - (r.left + r.right) / 2) / r.width) * 100).toFixed(2),
           own: h.dataset.fill, colw: h.dataset.colw, padx: h.dataset.padx,
           over: Math.round(y1 - r.bottom) };
}"""

# 這一頁「Default 畫面」有什麼。全部是看得見的東西，沒有一條是「元素存在」。
REL_DEFAULT = """() => {
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 1 && r.height > 1; };
  const cards = [...document.querySelectorAll('.seglist .segcard')];
  const box = document.getElementById('segBox');
  const map = document.getElementById('chainMap');
  return {
    cards: cards.length,
    flows: cards.filter(c => !!c.querySelector('.sf')).length,
    tags: [...document.querySelectorAll('.seglist .segcard .sco')].filter(vis).length,
    coded: [...document.querySelectorAll('.seglist .segcard .sco[data-code]')]
             .filter(e => vis(e) && e.dataset.code).length,
    chips: document.querySelectorAll('#segChips .segchip').length,
    co: map ? map.querySelectorAll('.co').length : 0,
    edges: map ? map.querySelectorAll('.edge').length : 0,
    bands: map ? map.querySelectorAll('.fband').length : 0,
    mapHidden: map ? !!map.hidden : null,
    segBoxH: box ? Math.round(box.getBoundingClientRect().height) : -1,
    ghosts: ['cgGraph','cgSide','cgSegs','cgTip','cgSegBox','cgSec','cgLegend','cgZoomIn']
              .filter(id => !!document.getElementById(id)),
    docW: document.documentElement.scrollWidth, winW: window.innerWidth,
  };
}"""

# 右側資訊欄（`#coBox`）現在在哪、寫著誰
REL_SIDE = """() => {
  const b = document.getElementById('coBox'), m = document.getElementById('chainMap');
  if (!b || !m) return null;
  const r = b.getBoundingClientRect(), mr = m.getBoundingClientRect();
  return { h: Math.round(r.height), left: Math.round(r.left), top: Math.round(r.top),
           mapLeft: Math.round(mr.left), mapTop: Math.round(mr.top),
           side: b.classList.contains('relside'),
           txt: (b.innerText || '').replace(/\s+/g, ' ').slice(0, 90),
           links: b.querySelectorAll('a, button').length };
}"""


def _rel_goto(pg, base, chain="semiconductor", w=1440, view="layer", fold="1"):
    """走到某一條產業鏈頁，並把兩個偏好設成已知值（不然上一段留下的狀態會汙染這一段）。

    ⚠ 一定要 `reload`：同一個網址用 `goto` 是 same-document navigation，
      view 根本不會重畫 —— 那會讓「改了視窗寬度再進來」量到的是**上一個寬度**那一份。
      2026-09-23 寫這一段的時候就先踩過一次（390px 量到 800px 的版面）。
    """
    pg.set_viewport_size({"width": w, "height": 1100})
    pg.goto(f"{base}#industry/{chain}", wait_until="networkidle")
    pg.evaluate("(a) => { try { localStorage.setItem('tw.relView', a[0]);"
                " localStorage.setItem('tw.relOpen', a[1]);"
                " localStorage.setItem('tw.segExpand', 'all'); } catch (e) {} }", [view, fold])
    pg.reload(wait_until="networkidle")
    wait_until(pg, "() => { const m = document.getElementById('chainMap');"
                   " return !!m && (m.querySelectorAll('.co, .fseg').length > 0); }", 8000)
    pg.wait_for_timeout(500)


def _rel_fit_ok(pg, f, label):
    """判「撐滿且置中」，但**塞不下的時候換一條規則**。

    為什麼要分兩種：欄數是資料決定的（AI 伺服器鏈有 6 層、半導體 4 層），
    6 欄在 800px 的容器裡就算把欄寬收到下限（136px）也還要 906px ——
    再收下去卡片就放不下「名稱＋代號」了，那是把「字看得清楚」換成「不用左右滑」，
    換錯邊。所以塞不下時圖**在自己的框裡左右滑**（整頁仍然不准橫捲），
    這是刻意的取捨，不是沒做到置中。判準用前端自己算的撐滿率：
      · <= 100%  → 塞得下 → 必須撐滿 >= 90%、置中誤差 <= 1.2%
      · >  100%  → 塞不下 → 改驗「框自己可以左右滑」而且「整頁沒有橫向捲軸」
    """
    if not f or f.get("n", 0) < 5:
        return ok(f"{label} 圖還在", False, f)
    if float(f.get("own") or 0) <= 100:
        return (ok(f"{label} 圖撐滿容器（>=90%）：{f['fill']}%", f["fill"] >= 90, f)
                and ok(f"{label} 圖水平置中（誤差 <=1.2%）：{f['dx']}%", abs(f["dx"]) <= 1.2, f))
    sc = pg.evaluate("""() => { const h = document.getElementById('chainMap');
        return { box: h.scrollWidth > h.clientWidth + 1,
                 page: document.documentElement.scrollWidth <= window.innerWidth + 1 }; }""")
    return ok(f"{label} 欄數太多塞不下（前端算出 {f['own']}%），"
              f"改成在圖自己的框裡左右滑，整頁仍然不橫捲", sc["box"] and sc["page"], [f, sc])


def t_b25_graph(pg, base):
    """批次25：關聯圖本身 —— 置中、撐滿、兩種表達形式、hover 提亮、收合、窄畫面。"""
    # ---------- ② 置中與撐滿（這一批的核心要求，逐寬度實際量） ----------
    for w in (1440, 1280, 1100):
        _rel_goto(pg, base, "semiconductor", w)
        f = pg.evaluate(REL_FIT)
        if not ok(f"[{w}px] 分層關聯圖畫得出來（公司卡與環節標題都有）",
                  bool(f) and f.get("n", 0) >= 20, f):
            continue
        ok(f"[{w}px] 關聯圖撐滿容器（>=90%）：量到 {f['fill']}%", f["fill"] >= 90, f)
        ok(f"[{w}px] 關聯圖水平置中（誤差 <=1%）：量到 {f['dx']}%", abs(f["dx"]) <= 1.0, f)
        ok(f"[{w}px] 前端自己算的撐滿率跟畫面上量到的對得起來（差 <=3%）",
           abs(float(f["own"]) - f["fill"]) <= 3, f)
        ok(f"[{w}px] 內容沒有溢出容器底部", f["over"] <= 2, f)

    # ---------- ⑤-1 兩種表達形式真的切得動，而且偏好真的記住 ----------
    _rel_goto(pg, base, "semiconductor", 1440, view="layer")
    a = pg.evaluate(REL_DEFAULT)
    ok("預設是分層圖（有公司卡、有帶箭頭的走線、沒有流向帶）",
       a["co"] >= 20 and a["edges"] > 0 and a["bands"] == 0, a)
    click(pg, '#relView button[data-rv="flow"]', 1000)
    b = pg.evaluate(REL_DEFAULT)
    ok("切到流向圖：公司卡整批換成環節流向帶（畫面真的變了）",
       b["bands"] > 0 and b["co"] == 0, [a["co"], a["bands"], b["co"], b["bands"]])
    fb = pg.evaluate(REL_FIT)
    ok(f"流向圖一樣撐滿且置中：{fb.get('fill')}% / {fb.get('dx')}%",
       fb.get("fill", 0) >= 90 and abs(fb.get("dx", 99)) <= 1.0, fb)
    ok("切換偏好真的寫進 localStorage",
       pg.evaluate("() => localStorage.getItem('tw.relView')") == "flow")
    click(pg, '#relView button[data-rv="layer"]', 1000)
    c = pg.evaluate(REL_DEFAULT)
    ok("切回分層圖：流向帶收掉、公司卡回來", c["co"] >= 20 and c["bands"] == 0, c)

    # ---------- ⑤-2 hover 一張公司卡：線與**另一端的公司卡**一起提亮 ----------
    _rel_goto(pg, base, "semiconductor", 1440)
    h0 = pg.evaluate("() => ({ hi: document.querySelectorAll('#chainMap .edge.hi').length,"
                     " near: document.querySelectorAll('#chainMap .co.near').length })")
    cid = pg.evaluate("""() => { const ids = new Set();
        document.querySelectorAll('#chainMap .edge').forEach(e => { ids.add(e.dataset.from); ids.add(e.dataset.to); });
        const n = [...document.querySelectorAll('#chainMap .co')].find(c => ids.has(c.dataset.id));
        return n ? n.dataset.id : null; }""")
    if ok("圖上找得到一張有上下游關係的公司卡", bool(cid), cid):
        pg.hover(f'#chainMap .co[data-id="{cid}"]')
        pg.wait_for_timeout(450)
        h1 = pg.evaluate("() => ({ hi: document.querySelectorAll('#chainMap .edge.hi').length,"
                         " near: document.querySelectorAll('#chainMap .co.near').length,"
                         " dim: document.querySelectorAll('#chainMap .edge.dim').length })")
        ok("滑過一張公司卡：跟它有關的線真的亮起來、其餘壓暗",
           h1["hi"] > h0["hi"] and h1["dim"] > 0, [h0, h1])
        ok("而且**另一端的公司卡也一起提亮**（不是只有線亮，那樣看不出通到誰）",
           h1["near"] >= 2, [h0, h1])
        pg.mouse.move(5, 5); pg.wait_for_timeout(350)
        h2 = pg.evaluate("() => ({ hi: document.querySelectorAll('#chainMap .edge.hi').length,"
                         " near: document.querySelectorAll('#chainMap .co.near').length })")
        ok("滑鼠移開就全部恢復（不會留下一組洗不掉的高亮）",
           h2["hi"] == 0 and h2["near"] == 0, h2)

    # ---------- 點公司卡 ＝ 選起它那一格：其餘公司卡真的被壓暗 ----------
    d0 = pg.evaluate("() => document.querySelectorAll('#chainMap .co.dim').length")
    seg = pg.evaluate("""() => { const n = document.querySelector('#chainMap .co[data-segment]');
        return n ? n.dataset.segment : null; }""")
    if ok("圖上點得到一張公司卡", bool(seg), seg):
        click(pg, f'#chainMap .co[data-segment="{seg}"]', 1000)
        d1 = pg.evaluate("() => ({ dim: document.querySelectorAll('#chainMap .co.dim').length,"
                         " selCard: document.querySelectorAll('.seglist .segcard.sel').length,"
                         " dimCard: document.querySelectorAll('.seglist .segcard.dim').length })")
        ok("點公司卡：不屬於它那一格的卡片真的被壓暗（畫面真的變了）",
           d1["dim"] > d0, [d0, d1])
        ok("而且下面的環節卡清單同步：那一格 .sel、其餘 .dim",
           d1["selCard"] == 1 and d1["dimCard"] > 0, d1)

    # ---------- ⑤-3 收合鈕真的收得掉、展得開 ----------
    _rel_goto(pg, base, "semiconductor", 1440)
    ok("預設（桌機）關聯圖是展開的", pg.evaluate("() => !document.getElementById('chainMap').hidden"))
    click(pg, "#relFold", 600)
    ok("按「收合圖」之後圖真的不見了，但環節卡清單還在",
       pg.evaluate("""() => { const m = document.getElementById('chainMap');
           return !!m.hidden && document.querySelectorAll('.seglist .segcard').length > 0; }"""))
    click(pg, "#relFold", 900)
    fz = pg.evaluate(REL_FIT)
    ok("再按一次展開，而且展開之後照樣撐滿置中（收合時量不到寬度，要重畫）",
       bool(fz) and fz.get("fill", 0) >= 90 and abs(fz.get("dx", 99)) <= 1.0, fz)

    # ---------- 窄畫面：800px 不橫捲、390px 預設收起圖 ----------
    _rel_goto(pg, base, "semiconductor", 800)
    n8 = pg.evaluate(REL_DEFAULT)
    ok("[800px] 整頁沒有橫向捲軸", n8["docW"] <= n8["winW"] + 1, [n8["docW"], n8["winW"]])
    f8 = pg.evaluate(REL_FIT)
    ok(f"[800px] 關聯圖照樣撐滿且置中：{f8.get('fill')}% / {f8.get('dx')}%",
       f8.get("fill", 0) >= 90 and abs(f8.get("dx", 99)) <= 1.0, f8)

    pg.set_viewport_size({"width": 390, "height": 900})
    pg.goto(f"{base}#industry/semiconductor", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.removeItem('tw.relOpen');"
                " localStorage.removeItem('tw.relView');"
                " localStorage.removeItem('tw.segExpand'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2200)
    n3 = pg.evaluate(REL_DEFAULT)
    ok("[390px] 關聯圖預設收起來（手機的 Default 是環節卡清單，不是要左右滑的圖）",
       n3["mapHidden"] is True, n3)
    ok("[390px] 收起來之後環節卡清單與個股標籤照樣看得見",
       n3["cards"] > 0 and n3["tags"] > 0, n3)
    ok("[390px] 整頁沒有橫向捲軸", n3["docW"] <= n3["winW"] + 1, [n3["docW"], n3["winW"]])
    small = pg.evaluate("""() => { let m = 99, who = '';
        document.querySelectorAll('.seglist .segcard .sco .nm, .seglist .segcard .sh .nm, .seglist .segcard .sf, #segChips .segchip').forEach(e => {
          const r = e.getBoundingClientRect(); if (r.width < 1 || r.height < 1) return;
          const s = parseFloat(getComputedStyle(e).fontSize);
          if (s < m) { m = s; who = (e.textContent || '').slice(0, 12); } });
        return { min: +m.toFixed(2), who: who }; }""")
    ok(f"[390px] 清單上最小的字 {small['min']}px >= 11px", small["min"] >= 11, small)
    pg.evaluate("() => { try { localStorage.removeItem('tw.relView');"
                " localStorage.removeItem('tw.relOpen');"
                " localStorage.removeItem('tw.segExpand'); } catch (e) {} }")
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 批次C5：Andy 逐字的四條
def t_b25_tags(pg, base):
    """C5：① Default 標籤個股 ② 點了才跳下拉清單 ③ 點股票右側顯示訊息 ④ 退版後沒有力導向殘骸。"""
    for cid, cname in (("semiconductor", "半導體"), ("ai_server", "AI 伺服器")):
        for w in (1440, 800):
            _rel_goto(pg, base, cid, w)
            d = pg.evaluate(REL_DEFAULT)
            if not ok(f"[{cname} {w}px] 這一頁的關聯圖區畫得出來", bool(d) and d["cards"] > 0, d):
                continue
            # ★ 2026-09-24（Andy：「下方那片環節字卡全部拿掉 —— 跟上面的關聯圖重複了」，只動桌機）：
            #   桌機（>820px）的字卡 `.seglist` 藏起來了，「上下游」與「個股」都由關聯圖本身回答：
            #   改前：字卡 Default 看得到上游／下游、看得到 ≥10 顆帶代號的標籤；
            #   改後（桌機）：字卡看不到（0 顆標籤），圖上有走線、公司卡 ≥10 張；800px 照舊驗字卡。
            if w > 820:
                ok(f"[{cname} {w}px] 下方字卡拿掉了（看得到的標籤 {d['tags']} 顆）", d["tags"] == 0, d)
                ok(f"[{cname} {w}px] 上下游改由圖上的走線回答（{d['edges']} 條）", d["edges"] > 0, d)
                ok(f"[{cname} {w}px] 個股改由圖上的公司卡回答（{d['co']} 張）", d["co"] >= 10, d)
            else:
                ok(f"[{cname} {w}px] Default 就看得到每一格的「上游／下游」（{d['flows']}/{d['cards']} 張卡）",
                   d["flows"] >= max(1, d["cards"] // 2), d)
                ok(f"[{cname} {w}px] Default 就看得到個股標籤，而且帶得出代號（{d['coded']} 個）",
                   d["coded"] >= 10, d)
            ok(f"[{cname} {w}px] 舊的力導向星際圖一個殘骸都不剩", d["ghosts"] == [], d["ghosts"])
            ok(f"[{cname} {w}px] Default 沒有任何下拉清單展開（高度 0）", d["segBoxH"] == 0, d)
            _cg_chip(pg, "#segChips .segchip:not(.nomem)", 900)   # 選擇器會被翻譯成 #segChips
            h1 = pg.evaluate("() => { const b = document.getElementById('segBox');"
                             " return { h: Math.round(b.getBoundingClientRect().height),"
                             "   only: !!b.querySelector('#segOnly'),"
                             "   tw: b.querySelectorAll('a').length }; }")
            # ★ 2026-09-25（Andy：桌機整塊環節資訊面板拿掉，「已只看這一格」改由下拉「全部環節」取消）。
            #   改前：兩個寬度點色標後 #segBox 高 > 40、有 #segOnly 與個股連結；
            #   改後：桌機（>820）點色標後 #segBox 高 0、沒有 #segOnly、沒有連結；800px 照舊。
            if w > 820:
                ok(f"[{cname} {w}px] 點色標之後不會再長出環節面板（高度 {h1['h']}、無「只看這一格」）",
                   h1["h"] == 0 and not h1["only"] and h1["tw"] == 0, h1)
            else:
                ok(f"[{cname} {w}px] 點色標之後下拉清單真的展開（高度 0 -> {h1['h']}）",
                   h1["h"] > 40, h1)
                ok(f"[{cname} {w}px] 展開的內容是這一格的說明（有「只看這一格」與可點的個股連結）",
                   h1["only"] and h1["tw"] > 0, h1)
            _cg_chip(pg, "#segChips .segchip.sel", 700)
            h2 = pg.evaluate("() => Math.round(document.getElementById('segBox').getBoundingClientRect().height)")
            ok(f"[{cname} {w}px] 再點一次同一顆色標，清單真的收回去（{h1['h']} -> {h2}）", h2 == 0, h2)

            codes = pg.evaluate("""() => [...document.querySelectorAll('.seglist .segcard .sco[data-code]')]
                .map(e => e.dataset.code).filter(Boolean).slice(0, 6)""")
            if not ok(f"[{cname} {w}px] 清單上至少找得到兩檔帶代號的個股標籤", len(codes) >= 2, codes):
                continue
            ok(f"[{cname} {w}px] 點股票之前右側是空的",
               pg.evaluate("() => !document.getElementById('coBox')"))
            # 桌機的入口是圖上的公司卡（字卡藏起來了），800px 照舊點字卡標籤 —— 見 _cg_click_dot
            # 改前：click(pg, '.seglist .segcard .sco[data-code=…]')；改後：_cg_click_dot 依寬度挑入口
            _cg_click_dot(pg, codes[0], 1100)
            s1 = pg.evaluate(REL_SIDE)
            if ok(f"[{cname} {w}px] 點個股標籤之後資訊欄真的出現，而且寫的是這一檔（{codes[0]}）",
                  bool(s1) and s1["h"] > 60 and codes[0] in s1["txt"], s1):
                if w >= 1100:
                    ok(f"[{cname} {w}px] 資訊欄排在圖的**右邊**（Andy：「右側會顯示對應訊息」）",
                       s1["side"] and s1["left"] > s1["mapLeft"] + 100, s1)
                else:
                    ok(f"[{cname} {w}px] 窄畫面資訊欄掉到圖的**下方**（並排會把圖擠到看不清）",
                       s1["top"] > s1["mapTop"], s1)
                ok(f"[{cname} {w}px] 資訊欄裡有可以往下走的入口（看個股頁／同環節／佐證連結）",
                   s1["links"] >= 2, s1)
            _cg_click_dot(pg, codes[1], 1100)
            s2 = pg.evaluate(REL_SIDE)
            ok(f"[{cname} {w}px] 再點另一檔（{codes[1]}）資訊欄真的換人，不是疊第二張",
               bool(s2) and codes[1] in s2["txt"] and codes[0] not in s2["txt"]
               and pg.evaluate("() => document.querySelectorAll('#coBox').length") == 1,
               [s1 and s1["txt"], s2 and s2["txt"]])
            pg.evaluate("() => { const b = document.getElementById('coBox');"
                        " const x = b && b.querySelector('.close'); if (x) x.click(); }")
            pg.wait_for_timeout(900)
            fz = pg.evaluate(REL_FIT)
            _rel_fit_ok(pg, fz, f"[{cname} {w}px] 關掉資訊欄之後")

    # ★ 2026-09-24：字卡只剩窄畫面／手機有，這一條改在 800px 驗（改前：1440px）
    _rel_goto(pg, base, "semiconductor", 800)
    pg.evaluate("() => { const s = document.getElementById('side'); if (s) s.classList.remove('open'); }")
    tgt = pg.evaluate("""() => { const t = document.querySelector('.seglist .segcard .sf .sg[data-seg]');
        return t ? t.dataset.seg : null; }""")
    if ok("環節卡上找得到可以點的上下游環節名", bool(tgt), tgt):
        click(pg, f'.seglist .segcard .sf .sg[data-seg="{tgt}"]', 900)
        r = pg.evaluate("""(s) => ({ sel: document.querySelectorAll('.seglist .segcard.sel').length,
            hit: !!document.querySelector(`.seglist .segcard.sel[data-seg="${s}"]`),
            boxH: Math.round(document.getElementById('segBox').getBoundingClientRect().height) })""", tgt)
        ok("點上下游的環節名：真的切到那一格（那張卡 .sel、下拉清單跟著展開）",
           r["hit"] and r["boxH"] > 40, r)
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 批次C4：剖析圖窄欄不被切
# ★ 2026-09-23 第十批 C4（Andy：「IC 封裝剖析 這頁似乎沒做好，請確認」）：
#   他的截圖是主剖面被切掉右半邊。量出來的事實（見 site/dg/ai_adv_packaging.js §0 的紀錄）：
#   **事件抽屜開著**時 main 旁邊被吃掉 360px，視窗 980～1150 之間畫布欄只剩 410～659px，
#   圖就從右邊被切掉 —— 所以這一段的觸發條件是「抽屜要開著」，關著量不到那個裂縫。
#
# 每一條都驗畫面上量得到的東西，不驗「元素存在」：
#   ① 畫布沒有被切掉右半邊：`svg.right − .dgcanvas.right <= 0`
#   ② 縮進去之後字還讀得到：`--dg-fs-min × svg實寬 ÷ viewBox寬 >= 12`
#   ③ 390 一載入不可以先被推走：`#prodDiagram.scrollLeft == 0`
#   ④ `foundry` 切 3D 再切回 2D，①②③ 仍然成立（3D 往返最容易把量到的尺寸弄髒）
C4_ROUTES = [
    ("晶圓代工", "semiconductor/dg/foundry"),
    ("先進封裝", "semiconductor/dg/ai_adv_packaging"),
    ("軟體服務 SaaS", "software/dg/saas"),
    ("雲端 MSP", "software/dg/cloud_msp"),
    ("輕油裂解", "traditional/dg/petrochemical"),
    ("重電", "infrastructure/dg/heavy_electric"),
]

C4_FIT = """() => { const host = document.getElementById('prodDiagram');
  const svg = host && host.querySelector('svg');
  const box = svg && (svg.closest('.dgcanvas') || host);
  if (!svg || !box) return null;
  const rs = svg.getBoundingClientRect(), rb = box.getBoundingClientRect();
  const vb = svg.viewBox && svg.viewBox.baseVal ? svg.viewBox.baseVal.width : 0;
  const fsMin = parseFloat(getComputedStyle(svg).getPropertyValue('--dg-fs-min')) || 0;
  return { cut: Math.round(rs.right - rb.right),          // > 0 ＝ 被切掉了
           leftCut: Math.round(rb.left - rs.left),
           svgW: Math.round(rs.width), boxW: Math.round(rb.width), vb: vb,
           fsMin: fsMin,
           // 螢幕上真的畫出來的最小字級（縮放之後）
           effFs: vb ? +(fsMin * rs.width / vb).toFixed(2) : 0,
           hostScroll: Math.round(host.scrollLeft),
           docW: document.documentElement.scrollWidth, winW: innerWidth }; }"""


def _c4_check(pg, lab):
    z = pg.evaluate(C4_FIT)
    if not ok(f"{lab} 量得到畫布與它的外框", bool(z), z):
        return None
    ok(f"★ {lab} 畫布沒有被切掉右半邊（svg.right − 框.right ＝ {z['cut']}px，要 ≤ 0）",
       z["cut"] <= 0, z)
    ok(f"★ {lab} 縮進去之後字還讀得到（畫面上的最小字級 {z['effFs']}px ≥ 12）",
       z["effFs"] >= 12, z)
    return z


def t_c4_fit(pg, base):
    """C4：六張圖 × 視窗 980／1050／1150（事件抽屜開著）都不被切；390 不被推走；3D 往返也成立。"""
    # 事件抽屜要**開著** —— 那是這個裂縫的觸發條件，關著就量不到（這一條不准省）
    pg.goto(f"{base}#overview", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.side', '1'); localStorage.setItem('tw.dg3d', '0');"
                " localStorage.setItem('tw.dgOpen', '1'); } catch (e) {} }")
    for lab, route in C4_ROUTES:
        for w in (980, 1050, 1150):
            pg.set_viewport_size({"width": w, "height": 1000})
            pg.goto(f"{base}#industry/{route}", wait_until="networkidle")
            pg.reload(wait_until="networkidle")
            pg.wait_for_timeout(2600)
            side = pg.evaluate("""() => { if (window.twSetSide) window.twSetSide(true, false);
                const a = document.querySelector('aside');
                return !!a && getComputedStyle(a).display !== 'none'; }""")
            pg.wait_for_timeout(900)
            if not ok(f"[{lab} {w}px] 事件抽屜真的開著（這是裂縫的觸發條件，關著等於沒驗）", side):
                continue
            _c4_check(pg, f"[{lab} {w}px]")
        # 390：一載入不可以先被推走
        pg.set_viewport_size({"width": 390, "height": 900})
        pg.goto(f"{base}#industry/{route}", wait_until="networkidle")
        pg.reload(wait_until="networkidle")
        pg.wait_for_timeout(2800)
        z = pg.evaluate(C4_FIT)
        if ok(f"[{lab} 390px] 量得到畫布", bool(z), z):
            ok(f"★ [{lab} 390px] `#prodDiagram` 一載入沒有被推走（scrollLeft ＝ 0）",
               z["hostScroll"] == 0, z)
            ok(f"[{lab} 390px] 沒有整頁橫向捲軸", z["docW"] <= z["winW"] + 1, z)

    # ---- ④ 3D 往返：foundry 切 3D 再切回 2D，上面幾條仍然成立
    pg.set_viewport_size({"width": 1050, "height": 1000})
    pg.goto(f"{base}#industry/semiconductor/dg/foundry", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
    pg.evaluate("() => { if (window.twSetSide) window.twSetSide(true, false); }")
    pg.wait_for_timeout(900)
    before = _c4_check(pg, "[晶圓代工 1050px 切 3D 之前]")
    if before and pg.evaluate("() => { const b = document.getElementById('dg3d'); return !!b && !b.hidden; }"):
        _dg3d_toolbar_click(pg, "#dg3d", 4200)
        ok("切到 3D 真的掛得起來（往返驗收的前提）",
           pg.evaluate("() => !!document.querySelector('#prod3d canvas')"))
        _dg3d_toolbar_click(pg, "#dg3d", 2600)
        after = _c4_check(pg, "[晶圓代工 1050px 切回 2D 之後]")
        if after:
            ok("★ 3D 往返之後畫布寬回到原本那個值（不是每往返一次就縮一點）",
               abs(after["svgW"] - before["svgW"]) <= 2, {"前": before["svgW"], "後": after["svgW"]})
    else:
        notes.append("晶圓代工這張圖沒有 3D 鈕（或 WebGL 起不來），3D 往返那四條略過")
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); } catch (e) {} }")
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 金融鏈三張與軟體鏈四張：環節必須是 0
# ★ 這是**刻意**的棘輪，不是還沒做完：`pipeline/groups/supply_chain.yaml` 裡
#   **沒有 `financial` 也沒有 `software` 這兩條鏈**（grep -c 都是 0）。
#   沒有環節卻硬掛 `data-seg`，等於在一個 public 的網站上宣稱錯誤的公司對應 ——
#   那比「點了沒反應」嚴重得多。
#   ★ 2026-09-23：已經有一路在補這兩條鏈的環節，所以判準**不再寫死 0**，
#     改成「圖上掛的每一個環節都要真的存在於那條鏈裡」（細節見 t_noseg 的 docstring）。
NOSEG_ROUTES = [
    ("銀行", "financial/dg/bank"), ("壽險金控", "financial/dg/life_fhc"),
    ("證券金控", "financial/dg/securities_fhc"),
    ("資安", "software/dg/cyber_security"), ("雲端 MSP", "software/dg/cloud_msp"),
    ("軟體服務 SaaS", "software/dg/saas"), ("電商", "software/dg/ecommerce"),
]


def t_noseg(pg, base):
    """金融鏈三張與軟體鏈四張：掛上去的 `data-seg` 必須**真的存在於那條鏈的環節表裡**。

    ★ 2026-09-23 改寫，原因寫清楚：
      第一版寫成「`[data-seg]` 數量必須 == 0」——那是因為 `supply_chain.yaml` 當時
      **沒有 `financial` 也沒有 `software` 這兩條鏈**，掛環節等於在一個 public 的網站上
      宣稱錯誤的公司對應。但現在有一路正在補這兩條鏈的環節，交件之後那七張圖會
      **從「沒有 data-seg」變成「有 data-seg」** —— 寫死 0 的話它一交件就紅，
      而那個紅是假的（產品正確，是驗收沒跟上）。

      所以判準換成**真正不變的那一件事**：
        · 那條鏈還沒有環節 → 圖上一個 `data-seg` 都不准有（等同舊的 0 棘輪）
        · 那條鏈有環節了　 → 圖上每一個 `data-seg` 都必須是那條鏈**真的有的**那幾個
      兩種情況都擋得住「順手掛一個不存在的環節」，而且不必等誰交件才改一次。
      名單直接讀 `site/data/supply_chain.json`（前端吃的就是它），不是寫死在這裡。
    """
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#industry", wait_until="networkidle"); pg.wait_for_timeout(1500)
    # `supply_chain.json` 的形狀是 `{segments: [{id, name, layer, chain, …}, …]}`（扁平一層，
    # 每個環節自己帶 `chain`），不是「每條鏈底下掛一份環節」。依 `chain` 分組。
    chains = pg.evaluate("""async () => { const r = await fetch('data/supply_chain.json');
        const j = await r.json(); const o = {};
        (j.segments || []).forEach(s => { const c = s.chain; if (!c) return;
          (o[c] = o[c] || []).push(s.id); });
        return o; }""") or {}
    for lab, route in NOSEG_ROUTES:
        chain = route.split("/")[0]
        allowed = chains.get(chain) or []
        pg.goto(f"{base}#industry/{route}", wait_until="networkidle")
        pg.reload(wait_until="networkidle")
        pg.wait_for_timeout(2400)
        z = pg.evaluate("""() => { const h = document.getElementById('prodDiagram');
            if (!h || !h.querySelector('svg')) return null;
            return { segs: h.querySelectorAll('[data-seg]').length,
                     segList: [...new Set([...h.querySelectorAll('[data-seg]')].map(e => e.dataset.seg))],
                     parts: h.querySelectorAll('[data-part]').length,
                     title: (document.getElementById('dgTitle') || {}).textContent || '' }; }""")
        if not ok(f"[{lab}] 這張圖畫得出來", bool(z), z):
            continue
        if not allowed:
            ok(f"★ [{lab}] `{chain}` 這條鏈還沒有環節 → 圖上一個 `data-seg` 都不准掛"
               f"（硬掛就是宣稱錯誤的公司對應）",
               z["segs"] == 0, {"掛了": z["segs"], "是哪幾個": z["segList"][:6]})
        else:
            bad = [x for x in z["segList"] if x not in allowed]
            ok(f"★ [{lab}] 圖上每一個 `data-seg` 都是 `{chain}` 這條鏈真的有的環節"
               f"（鏈上有 {len(allowed)} 個環節）",
               not bad, {"不存在的": bad, "圖上掛的": z["segList"][:6]})
        ok(f"[{lab}] 零件本身是有的（不是整張圖空白）", z["parts"] > 0, z["parts"])


# ===================================================================== 批次30：兩層下拉與象限卡（W6／W7）
# Andy 2026-09-23 的兩句原話：
#   W6「圖一二 兩個標籤式都需要做成下拉清單 篩選，所以他會是 族群->題材…並非所有族群都在同一個
#       下拉清單，而是對應族群出現對應個股」
#   W7／D2「圖二 格式要改成 我點選領先，底下資訊是顯示在旁邊的，另外『最近 5 個交易日換階段的族群』拿掉」
#
# 這一段是這兩件事的真人操作驗收。**每一條都驗「畫面真的因此改變了」**：
# 面板真的從 hidden 變看得見、圖上的點數真的變、localStorage 真的寫進去、幾何位置真的量得到。
SK_ROW = '.ddrow[data-for="sankey"]'

_SK_SIG = """() => {
  /* ★ 2026-09-24：桌機預設是拓撲版（flowtopo.js）——節點清單直接從它的探針讀（key 就是結構）。*/
  const t = window.App && window.App.sankeyTopo && window.App.sankeyTopo();
  if (t) return { n: t.nodes.length, sig: t.nodes.map(x => x.key).join('|') };
  const c = echarts.getInstanceByDom(document.getElementById('sankey'));
  if (!c) return null; const root = ((c.getOption().series || [])[0] || {}).data[0] || {};
  let n = 0; const sig = [];
  (root.children || []).forEach(ch => { n++; sig.push(ch.name + ':' + (ch.children || []).length);
    (ch.children || []).forEach(g => { n++; sig.push(' ' + g.gid + ':' + (g.children || []).length);
      n += (g.children || []).length; }); });
  return { n: n, sig: sig.join('|') }; }"""

_RQ = """() => { const cl = document.getElementById('rotClock');
  const qs = [...document.querySelectorAll('#rotClock .rotquads .rq')];
  if (!cl || !qs.length) return null;
  const cr = cl.getBoundingClientRect();
  return { n: qs.length,
           ks: qs.map(q => q.dataset.k),
           names: qs.map(q => (q.firstChild && q.firstChild.textContent || '').trim()),
           nums: qs.map(q => parseInt(((q.querySelector('em') || {}).textContent || '0').replace(/\\D/g, ''), 10) || 0),
           colors: [...new Set(qs.map(q => getComputedStyle(q).color))].length,
           inside: qs.filter(q => { const r = q.getBoundingClientRect();
             return r.left >= cr.left - 2 && r.right <= cr.right + 2
                 && r.top >= cr.top - 2 && r.bottom <= cr.bottom + 2; }).length,
           minFs: Math.min(...qs.map(q => parseFloat(getComputedStyle(q).fontSize) || 0)),
           on: qs.filter(q => q.classList.contains('on')).map(q => q.dataset.k) }; }"""

_STG = """() => { const b = document.getElementById('stagePanel');
  const cw = document.getElementById('rotClockWrap'), rf = document.getElementById('rankFlowWrap');
  if (!b) return null;
  const rb = b.getBoundingClientRect();
  const rc = cw ? cw.getBoundingClientRect() : null, rr = rf ? rf.getBoundingClientRect() : null;
  const hit = (a, c) => a && c && a.left < c.right - 1 && a.right > c.left + 1
                     && a.top < c.bottom - 1 && a.bottom > c.top + 1;
  const hd = document.querySelector('#v-flow .rotrhead'), rh = hd ? hd.getBoundingClientRect() : null;
  /* ★ 2026-09-25（批次30 收尾）加的四個欄位 —— 見 W7-10 那段註解：
     inRank＝面板整塊落在 #rankFlowWrap 裡（DECISIONS #260：側欄蓋在排行圖上，是設計）；
     overlapClock＝面板有沒有蓋到輪盤（這才是新版面真正不准發生的事）；
     headClear＝「資金流向排行」小標那一列沒有被蓋到（放大／怎麼看兩顆鈕要按得到）；
     inView＝面板至少有一部分在可視範圍內（點了要看得到東西）。*/
  const inside = (a, c) => a && c && a.left >= c.left - 1 && a.right <= c.right + 1
                        && a.top >= c.top - 1 && a.bottom <= c.bottom + 1;
  return { hidden: !!b.hidden, k: b.dataset.k || '',
           items: b.querySelectorAll('li[data-gid]').length,
           x: Math.round(rb.left), y: Math.round(rb.top), w: Math.round(rb.width),
           rightOfClock: rc ? rb.left >= rc.right - 2 : null,
           belowClock: rc ? rb.top >= rc.bottom - 2 : null,
           overlapRank: hit(rb, rr),
           inRank: !!inside(rb, rr),
           overlapClock: !!hit(rb, rc),
           headClear: rh ? rb.top >= rh.bottom - 1 : null,
           inView: rb.height > 0 && rb.top < innerHeight - 40 && rb.bottom > 40,
           clockW: rc ? Math.round(rc.width) : 0,
           jmp: b.querySelectorAll('li .jmp').length }; }"""


def t_batch30(pg, base):
    """W6 兩層下拉（資金輪動 ＋ 資金去向）與 W7 象限卡的真人操作驗收。"""
    pg.set_viewport_size({"width": 1500, "height": 1000})
    reset_rot(pg, base, 2600)
    # ★ 2026-09-23：「全部」的真值一定要在**任何篩選之前**量（就是這裡）。
    #   W6-5 以前拿 W6-4 現場的 `n_all` 當「全部」，但那時 W6-3 已經選了半導體鏈 ——
    #   量到的是「這條鏈」不是「全部」。而這兩個數字天生就不一樣：
    #   `renderRotClock()` 沒篩選時是 `rows.slice(0, cap)`（cap=16，48 個族群只畫前 16 顆），
    #   一旦有篩選就走 `opts.pick` 那條路 `rows.filter(...)`，**繞過 cap**，
    #   半導體鏈剛好 17 個族群 → 17 顆。於是「清除之後回到 16」是**對的**，17 才是錯的期望。
    #   實測：未篩選 16、選半導體鏈 17、勾兩個 2、清除後 16（＝和這裡量到的真值相等）。
    #   一律跟這個量出來的真值比，不准寫死 16 或 17 —— 資料一變（族群數、cap）就又紅了。
    n_clock_unfiltered = len(_rot_scatter(pg) or [])

    # ---------------------------------------------------------------- W6-1 結構
    st = pg.evaluate("""() => ({ dd: document.querySelectorAll('#v-flow .rotfilter[data-rf="flow"] .rotdd').length,
        chip: document.querySelectorAll('#v-flow .rotfilter .gchip').length,
        seg: document.querySelectorAll('#v-flow .rotfilter .seg.rotchain').length })""")
    ok("W6-1：資金輪動那排剛好兩層下拉（產業鏈 ＋ 族群）", st["dd"] == 2, st)
    ok("W6-1：舊的族群晶片與 `.seg.rotchain` 一個都不剩（不是藏起來）",
       st["chip"] == 0 and st["seg"] == 0, st)

    # ---------------------------------------------------------------- W6-2 第一層點得開，390 不溢出
    e0 = pg.evaluate(f"""() => (document.querySelector('{ROT_DD} .rotdd[data-dd="chain"] .ddbtn')||{{}})
        .getAttribute('aria-expanded')""")
    ok("W6-2：第一層下拉一開始是收著的", e0 == "false", e0)
    ok("W6-2：按第一層 → 真的展開（aria-expanded false → true）",
       rot_dd_open(pg, "chain", ROT_DD, 500) is True, e0)
    pg.set_viewport_size({"width": 390, "height": 900})
    pg.wait_for_timeout(900)
    rot_dd_open(pg, "chain", ROT_DD, 500)
    nar = pg.evaluate(f"""() => {{ const p = document.querySelector('{ROT_DD} .rotdd[data-dd="chain"] .ddpanel');
        if (!p || p.hidden) return null; const r = p.getBoundingClientRect();
        return {{ left: Math.round(r.left), right: Math.round(r.right), w: innerWidth }}; }}""")
    if ok("W6-2 [390px] 第一層面板打得開", bool(nar), nar):
        ok("W6-2 [390px] 面板沒有被切到畫面外（left ≥ 0 而且 right ≤ 390）",
           nar["left"] >= 0 and nar["right"] <= nar["w"] + 1, nar)
    pg.keyboard.press("Escape")
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.wait_for_timeout(900)

    # ---------------------------------------------------------------- W6-3 選一條鏈 → 第二層自動開且變少
    all_n = len(rot_dd_groups(pg))
    ok("W6-3：第二層一開始列得出全部族群", all_n > 20, all_n)
    picked_chain = pg.evaluate(f"""() => {{ const dd = document.querySelector('{ROT_DD} .rotdd[data-dd="chain"]');
        const b = dd.querySelector('.ddbtn'); if (b) b.click();
        const opts = [...dd.querySelectorAll('.ddopt[data-c]')].filter(o => o.dataset.c);
        const semi = opts.find(o => /半導體/.test(o.textContent)) || opts[0];
        if (!semi) return null; const c = semi.dataset.c; semi.click(); return c; }}""")
    pg.wait_for_timeout(1400)
    if ok("W6-3：第一層挑得到一條產業鏈", bool(picked_chain), picked_chain):
        sub_n = len(rot_dd_groups(pg))
        ok("W6-3：選完鏈之後第二層**自動打開**（不必再按一次）",
           pg.evaluate(f"""() => (document.querySelector('{ROT_DD} .rotdd[data-dd="group"] .ddbtn')||{{}})
               .getAttribute('aria-expanded')""") == "true")
        ok(f"★ W6-3：第二層只剩這條鏈底下的族群（{sub_n} < {all_n}）", 0 < sub_n < all_n,
           {"這條鏈": sub_n, "全部": all_n})

    # ---------------------------------------------------------------- W6-4 連勾兩個
    subs = rot_dd_groups(pg)
    if ok("W6-4：第二層至少有兩個族群可以勾", len(subs) >= 2, len(subs)):
        n_all = len(_rot_scatter(pg) or [])
        rot_dd_toggle(pg, subs[0], wait=1100)
        rot_dd_toggle(pg, subs[1], wait=1300)
        w4 = pg.evaluate(f"""() => ({{
            open: (document.querySelector('{ROT_DD} .rotdd[data-dd="group"] .ddbtn')||{{}}).getAttribute('aria-expanded'),
            btn: (document.querySelector('{ROT_DD} .rotdd[data-dd="group"] .ddbtn')||{{}}).textContent || '',
            ls: (() => {{ try {{ return JSON.parse(localStorage.getItem('tw.rot.filter') || 'null'); }}
                 catch (e) {{ return null; }} }})() }})""")
        ok("★ W6-4①：連勾兩個，第二層**仍然開著**（複選才用得下去）", w4["open"] == "true", w4["open"])
        ok("★ W6-4②：輪動時鐘上真的只剩兩個族群（不是只有清單變了）",
           len(_rot_scatter(pg) or []) == 2 and n_all > 2, f"{n_all} → {len(_rot_scatter(pg) or [])}")
        ok("★ W6-4③：收起來的按鈕上寫著「已選 2 個」", "已選 2" in w4["btn"], w4["btn"][:50])
        ok("★ W6-4④：選擇真的寫進 localStorage（`tw.rot.filter` 的 groups 有 2 個）",
           bool(w4["ls"]) and len(w4["ls"].get("groups") or []) == 2, w4["ls"])

        # ------------------------------------------------------------ W6-5 Esc 收起來、清除還原
        pg.keyboard.press("Escape")
        pg.wait_for_timeout(600)
        ok("★ W6-5：按 Esc 第二層真的收起來（aria-expanded 回 false）",
           pg.evaluate(f"""() => (document.querySelector('{ROT_DD} .rotdd[data-dd="group"] .ddbtn')||{{}})
               .getAttribute('aria-expanded')""") == "false")
        ok("W6-5：按「清除」按得下去", rot_dd_clear(pg, wait=1400))
        # ★ 2026-09-23：比的是**沒有任何篩選時**量到的真值（函式最上面那一行），
        #   不是 W6-4 現場的 `n_all` —— 那個是「半導體鏈」的點數（17），不是「全部」（16）。
        #   「清除」會把 `ROT.chain` 也一起清掉，所以還原的目標就是未篩選的那個數字。
        ok("★ W6-5：清除之後時鐘上的族群數真的回到全部（＝未篩選時量到的那個數）",
           len(_rot_scatter(pg) or []) == n_clock_unfiltered,
           f"→ {len(_rot_scatter(pg) or [])}（未篩選時是 {n_clock_unfiltered}；"
           f"W6-4 現場那個 {n_all} 是「半導體鏈」的點數，不是「全部」）")

        # ------------------------------------------------------------ W6-6 放大視窗共用同一份狀態
        # ★ 2026-09-26 改前→改後（Andy：「放大功能取消」）：資金流向頁足跡輪盤的「⤢ 放大」（#rotZoomBtn）連同它開的放大視窗拿掉。
        #   改前：放大視窗裡也是兩層下拉、在裡面勾的族群關掉後卡片摘要跟著變。改後：沒有放大視窗 → 驗入口不在。
        ok("W6-6：沒有足跡輪盤的放大視窗入口了（2026-09-26 拿掉）", pg.evaluate("() => !document.getElementById('rotZoomBtn') && !document.getElementById('rotZoomBack')"))

    # ---------------------------------------------------------------- W7-7 舊的三塊都不在
    gone = pg.evaluate("() => ['rotBoard','rotCycle','rotMove'].filter(id => !!document.getElementById(id))")
    ok("W7-7：`#rotBoard`／`#rotCycle`／`#rotMove` 三塊都不在 DOM 了（D2 起 rotMove 也移除）",
       gone == [], gone)

    # ---------------------------------------------------------------- W7-8 四顆象限卡（1500 ＋ 700 ＋ 390）
    # ★ 2026-09-25（批次30 收尾）改前→改後：寬度 (1500, 390) → (1500, 700)，390 另外量手機那四顆（下面 W7-8m）。
    #   理由：這段是 2026-09-23 寫的，當時手機也畫桌機那張 `#rotClock`。
    #   2026-09-24 手機 v3 上線後（site/mobile3.js，Andy 拍板「足跡輪盤套新雷達」），≤640px 的資金輪動卡
    #   掛 `.m3host`，桌機那張 `#rotClock` 整個藏起來（實測 390px：clientWidth/Height = 0×0、getClientRects 為空），
    #   四個象限改由新雷達 `#mRadarFlow` 的四顆角落徽章 `.mqb` 承擔（截圖 docs/_show/pg-flow-390.png 看得到四顆）。
    #   所以 390 量 `#rotClock .rq` 永遠是 null —— **斷言驗的是舊版面，不是使用者看不到象限卡**。
    #   原本「窄畫面最容易飄出去」的擔心仍然成立，所以桌機那一型改在 700px 量（641～820px 是桌機 84% 那一型，
    #   象限卡壓在盤緣，是最容易出界的寬度）；390 改量手機實際畫出來的那四顆，而且真的點一顆。
    for w in (1500, 700):
        pg.set_viewport_size({"width": w, "height": 1000})
        pg.goto(f"{base}#flow", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        q = pg.evaluate(_RQ)
        if not ok(f"W7-8 [{w}px] 量得到四顆象限卡", bool(q), q):
            continue
        ok(f"W7-8 [{w}px] 剛好四顆，名字是改善／領先／轉弱／落後",
           q["n"] == 4 and sorted(q["names"]) == sorted(["改善", "領先", "轉弱", "落後"]), q["names"])
        ok(f"★ W7-8 [{w}px] 四顆的 computed color 互異（一眼分得出哪一格是哪一段）",
           q["colors"] == 4, q["colors"])
        ok(f"★ W7-8 [{w}px] 四顆都落在 `#rotClock` 的矩形裡（位置是用像素算的，窄畫面最容易飄出去）",
           q["inside"] == 4, q)
        ok(f"W7-8 [{w}px] 卡片上的字 ≥ 11px", q["minFs"] >= 11, q["minFs"])

    # ---------------------------------------------------------------- W7-8m 手機（390）：新雷達的四顆角落徽章
    # 同樣四件事（四顆、名字、顏色互異、在盤的矩形裡、字 ≥ 11px），外加真的點一顆：
    # 2026-09-25 以前資金流向這張手機雷達的 onQuad 是 `() => {}`，四顆徽章點了完全沒反應（總覽那張有反應），
    # 這一段就是那個修正的驗收 —— 點「改善」盤上的點要變少、焦點條要換成改善、再點一次要還原。
    pg.set_viewport_size({"width": 390, "height": 1000})
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    _MQ = """() => { const r = document.querySelector('#mRadarFlow .mradar');
      const qs = [...document.querySelectorAll('#mRadarFlow .mqb')];
      const cl = document.getElementById('rotClock');
      if (!r || !qs.length) return null;
      const rr = r.getBoundingClientRect(), f = document.querySelector('#flowRotCard .mfocus');
      return { n: qs.length, names: qs.map(q => (q.firstChild && q.firstChild.textContent || '').trim()),
               colors: [...new Set(qs.map(q => getComputedStyle(q).color))].length,
               inside: qs.filter(q => { const b = q.getBoundingClientRect();
                 return b.width > 0 && b.left >= rr.left - 2 && b.right <= rr.right + 2
                     && b.top >= rr.top - 2 && b.bottom <= rr.bottom + 2; }).length,
               minFs: Math.min(...qs.map(q => parseFloat(getComputedStyle(q).fontSize) || 0)),
               dots: document.querySelectorAll('#mRadarFlow svg g[data-g]').length,
               pressed: qs.filter(q => q.getAttribute('aria-pressed') === 'true').map(q => q.dataset.quad),
               quad: document.getElementById('mRadarFlow').dataset.quad || '',
               st: f ? ((f.querySelector('.st') || {}).textContent || '') : '',
               deskClock: cl ? cl.getClientRects().length > 0 : null }; }"""
    m0 = pg.evaluate(_MQ)
    if ok("W7-8m [390px] 量得到手機雷達的四顆角落徽章（`#mRadarFlow .mqb`）", bool(m0), m0):
        ok("W7-8m [390px] 剛好四顆，名字是改善／領先／轉弱／落後",
           m0["n"] == 4 and sorted(m0["names"]) == sorted(["改善", "領先", "轉弱", "落後"]), m0["names"])
        ok("★ W7-8m [390px] 四顆的 computed color 互異", m0["colors"] == 4, m0["colors"])
        ok("★ W7-8m [390px] 四顆都落在雷達的矩形裡（沒有被切出畫面）", m0["inside"] == 4, m0)
        ok("W7-8m [390px] 徽章上的字 ≥ 11px", m0["minFs"] >= 11, m0["minFs"])
        ok("W7-8m [390px] 桌機那張 `#rotClock` 在手機是藏起來的（兩張不會同時出現）",
           m0["deskClock"] is False, m0["deskClock"])
        pg.eval_on_selector('#mRadarFlow .mqb[data-quad="improving"]', "b => b.click()")
        pg.wait_for_timeout(500)
        m1 = pg.evaluate(_MQ)
        ok("★ W7-8m [390px] 點「改善」→ 盤上的點真的變少（只剩改善那一段）",
           bool(m1) and 0 < m1["dots"] < m0["dots"], {"前": m0["dots"], "後": m1 and m1["dots"]})
        ok("★ W7-8m [390px] 點「改善」→ 徽章亮起（aria-pressed）、焦點條換成改善的族群",
           bool(m1) and m1["pressed"] == ["improving"] and m1["quad"] == "improving" and m1["st"] == "改善", m1)
        pg.eval_on_selector('#mRadarFlow .mqb[data-quad="improving"]', "b => b.click()")
        pg.wait_for_timeout(500)
        m2 = pg.evaluate(_MQ)
        ok("★ W7-8m [390px] 再點一次「改善」→ 點數還原、沒有徽章亮著",
           bool(m2) and m2["dots"] == m0["dots"] and m2["pressed"] == [] and m2["quad"] == "", m2)
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(2600)

    # ---------------------------------------------------------------- W7-9～12 點象限卡
    q = pg.evaluate(_RQ)
    if not ok("量得到四顆象限卡（後面幾條的前提）", bool(q), q):
        return
    idx = next((i for i, n in enumerate(q["nums"]) if n > 0), None)
    if ok("找得到一顆底下有族群的象限卡", idx is not None, q["nums"]):
        k1, n1 = q["ks"][idx], q["nums"][idx]
        b0 = pg.evaluate(_STG)
        ok("W7-9：還沒點的時候展開面板是收著的", bool(b0) and b0["hidden"], b0)
        pg.eval_on_selector(f'#rotClock .rotquads .rq[data-k="{k1}"]', "b => b.click()")
        pg.wait_for_timeout(1200)
        s1 = pg.evaluate(_STG)
        ok("★ W7-9：點一顆 → 展開面板真的從 hidden 變成看得見", bool(s1) and not s1["hidden"], s1)
        ok(f"★ W7-9：面板列出的族群數 == 卡片上寫的數字（{n1}）", s1["items"] == n1,
           {"卡片": n1, "面板": s1["items"]})
        # D2 的補償：換段資訊搬到每一列的 .jmp 徽章上（`#rotMove` 拿掉的東西沒有消失）
        ok("D2：換段資訊沒有消失，搬到面板每一列的 `.jmp` 徽章上",
           s1["jmp"] >= 0, s1["jmp"])
        # W7-10 幾何
        # ★ 2026-09-25（批次30 收尾）改前→改後：
        #   改前「展開面板沒有蓋到『資金流向排行』」（not overlapRank）——那是 2026-09-23 D2 的版面：
        #   面板插在 `.rotstagerow` 第二欄、夾在時鐘和排行中間，排行一個像素都不能被吃掉。
        #   改後「面板整塊落在排行那一格裡、沒蓋到輪盤、排行小標那一列還看得到、輪盤寬度不因此改變」。
        #   理由：2026-09-24 夜 Andy 指定「點族群時資訊要跟點『領先』徽章一樣顯示在輪盤旁邊的側欄
        #   （同一個位置、同一種樣式）」＋審查 R2 #24「開象限面板時卡片 606→833px 跳動、輪盤切編號模式」，
        #   面板改成 `#rankFlowWrap` 裡的 absolute 側欄、**刻意蓋在排行圖上**（DECISIONS #260、index.html 的
        #   `#rankFlowWrap>.sidepanel` 那段），2026-09-25 再改成高度跟內容走、底下的排行露出來。
        #   所以 overlapRank=True 是新設計本身，不是 bug；新設計真正不准發生的是「蓋到輪盤」與「輪盤被擠窄」。
        #   截圖（docs/_show/quad-flow-1440.png）：輪盤 563px 寬不動，面板在「資金流向排行」小標正下方、蓋住排行圖。
        ok("★ W7-10 [1500px]：展開面板落在「資金流向排行」那一格裡（側欄蓋在排行圖上，DECISIONS #260）",
           s1["inRank"] is True, s1)
        ok("★ W7-10 [1500px]：展開面板沒有蓋到輪盤", s1["overlapClock"] is False, s1)
        ok("W7-10 [1500px]：「資金流向排行」小標那一列沒被蓋到（放大／怎麼看按得到）", s1["headClear"] is True, s1)
        ok("★ W7-10 [1500px]：打開面板之後輪盤寬度不變（R2 #24：不准把輪盤擠窄）",
           abs(s1["clockW"] - b0["clockW"]) <= 1, {"開前": b0["clockW"], "開後": s1["clockW"]})
        ok("★ W7-10 [1500px]：面板出現在時鐘**右邊**（Andy 指名的位置）",
           s1["rightOfClock"] is True, s1)
        # W7-11 換一顆、再點同一顆
        idx2 = next((i for i, n in enumerate(q["nums"]) if n > 0 and q["ks"][i] != k1), None)
        if ok("找得到第二顆有族群的象限卡", idx2 is not None, q["nums"]):
            k2 = q["ks"][idx2]
            pg.eval_on_selector(f'#rotClock .rotquads .rq[data-k="{k2}"]', "b => b.click()")
            pg.wait_for_timeout(1200)
            s2 = pg.evaluate(_STG)
            q2 = pg.evaluate(_RQ)
            ok("★ W7-11：點第二顆 → 面板換人（`data-k` 真的變）",
               not s2["hidden"] and s2["k"] == k2 and s2["k"] != s1["k"], {"前": s1["k"], "後": s2["k"]})
            ok("W7-11：同時只有一顆是選起來的", q2["on"] == [k2], q2["on"])
            pg.eval_on_selector(f'#rotClock .rotquads .rq[data-k="{k2}"]', "b => b.click()")
            pg.wait_for_timeout(1000)
            ok("★ W7-11：再點同一顆真的收合", pg.evaluate(_STG)["hidden"], pg.evaluate(_STG))
        # W7-12 點面板裡的族群列 → #rankPanel 開
        pg.eval_on_selector(f'#rotClock .rotquads .rq[data-k="{k1}"]', "b => b.click()")
        pg.wait_for_timeout(1200)
        r0 = pg.evaluate("() => { const b = document.getElementById('rankPanel'); return !b || b.hidden; }")
        pg.eval_on_selector("#stagePanel li[data-gid]", "li => li.click()")
        pg.wait_for_timeout(1400)
        ok("★ W7-12：點面板裡的族群列 → 成分股面板 `#rankPanel` 真的打開（走既有那條展開路徑）",
           r0 and pg.evaluate("""() => { const b = document.getElementById('rankPanel');
               return !!b && !b.hidden && b.querySelectorAll('.ms a[href^="#stock/"]').length > 0; }"""))
        # W7-13 拉時間軸 → 四顆卡的數字跟著變
        before = pg.evaluate(_RQ)["nums"]
        rot_seek(pg, 10, 1200)
        after = pg.evaluate(_RQ)["nums"]
        ok("★ W7-13：把「看哪一天」拉到 10 天前，四顆象限卡的數字真的重算（跟著「看哪一天」走）",
           before != after, {"最新": before, "10 天前": after})
        rot_seek(pg, 0, 900)

    # ---------------------------------------------------------------- W7-10 窄畫面退讓
    pg.set_viewport_size({"width": 1000, "height": 1000})
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    qn = pg.evaluate(_RQ)
    if qn:
        kn = next((qn["ks"][i] for i, n in enumerate(qn["nums"]) if n > 0), qn["ks"][0])
        pg.eval_on_selector(f'#rotClock .rotquads .rq[data-k="{kn}"]', "b => b.click()")
        pg.wait_for_timeout(1400)
        sn = pg.evaluate(_STG)
        if ok("W7-10 [1000px] 面板打得開", bool(sn) and not sn["hidden"], sn):
            ok("★ W7-10 [1000px] 窄畫面時面板退回時鐘**下方**（放不下就退讓，是合理的）",
               sn["belowClock"] is True, sn)
            # 改前→改後同上面 1500 那段：not overlapRank → inRank ＋ 不蓋輪盤（單欄時排行那一格就在輪盤下面）
            ok("W7-10 [1000px] 面板落在排行那一格裡、沒蓋到輪盤",
               sn["inRank"] is True and sn["overlapClock"] is False, sn)
            # ★ 2026-09-25 新增：1000×1000 時面板上緣在 y≈1070，整塊在畫面外 —— 點了只看到徽章變色。
            #   app.js 的 rotStageReveal() 只在「整塊都在畫面下緣之外」時捲到剛好看得到。
            ok("★ W7-10 [1000px] 點象限卡之後面板真的捲進畫面（不是開在看不到的地方）",
               sn["inView"] is True, sn)
    pg.set_viewport_size({"width": 1500, "height": 1000})

    # ---------------------------------------------------------------- 桑基下拉 14～20
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
    sk0 = pg.evaluate("""() => ({ dd: document.querySelectorAll('.ddrow[data-for="sankey"] .rotdd').length,
        chip: document.querySelectorAll('.linkrow.gchips[data-for="sankey"] .gchip').length })""")
    ok("W6-14：資金去向那排剛好兩層下拉", sk0["dd"] == 2, sk0)
    ok("W6-14：舊的族群晶片一個都不剩", sk0["chip"] == 0, sk0)

    # ---------------------------------------------------------------- W6-14b 兩排不准互相覆寫
    # ★ 2026-09-23 實測抓到的退化：`filterDropdown()` 把資金去向那排的 class 設成
    #   `ddrow rotfilter`，而 `wireRotFilter()` 是 `$$('.rotfilter')` 全抓 ——
    #   只要使用者在**資金輪動**那排動一下（或那張卡重畫一次），
    #   資金去向那排就被整個覆寫成資金輪動的版本：單選變成 52 個 checkbox、
    #   「全部族群（不篩選）」消失、勾下去篩的是輪動時鐘而不是桑基圖。
    #   這一條就是守這件事：**先在資金輪動那排勾一個族群，再回頭量資金去向那排還是不是原本的樣子**。
    def _sk_shape():
        return pg.evaluate("""() => { const r = document.querySelector('.ddrow[data-for="sankey"]');
            if (!r) return null;
            return { all: !!r.querySelector('[data-g=""]'),
                     chk: r.querySelectorAll('input[type=checkbox][data-g]').length,
                     one: r.querySelectorAll('.ddopt.one').length }; }""")
    shape0 = _sk_shape()
    if ok("W6-14b：量得到資金去向那排的形狀", bool(shape0), shape0):
        ok("W6-14b：它是**單選**（有「全部族群（不篩選）」、沒有 checkbox）",
           shape0["all"] and shape0["chk"] == 0 and shape0["one"] > 0, shape0)
        g14 = rot_dd_groups(pg)
        if g14:
            rot_dd_toggle(pg, g14[0], wait=1400)
            shape1 = _sk_shape()
            ok("★ W6-14b：在**資金輪動**那排勾一個族群之後，資金去向那排**沒有被覆寫**"
               "（仍然是單選、「全部族群（不篩選）」還在）",
               bool(shape1) and shape1["all"] and shape1["chk"] == 0,
               {"勾之前": shape0, "勾之後": shape1})
            rot_dd_clear(pg, wait=1400)

    ok("W6-15：按第一層 → 真的展開",
       pg.evaluate(f"""() => {{ const dd = document.querySelector('{SK_ROW} .rotdd[data-dd="chain"]');
           const b = dd && dd.querySelector('.ddbtn'); if (!b) return null;
           b.click(); return b.getAttribute('aria-expanded'); }}""") == "true")
    pg.set_viewport_size({"width": 390, "height": 900})
    pg.wait_for_timeout(1000)
    pg.evaluate(f"""() => {{ const b = document.querySelector('{SK_ROW} .rotdd[data-dd="chain"] .ddbtn');
        if (b && b.getAttribute('aria-expanded') !== 'true') b.click(); }}""")
    pg.wait_for_timeout(500)
    sn2 = pg.evaluate(f"""() => {{ const p = document.querySelector('{SK_ROW} .rotdd[data-dd="chain"] .ddpanel');
        if (!p || p.hidden) return null; const r = p.getBoundingClientRect();
        return {{ left: Math.round(r.left), right: Math.round(r.right), w: innerWidth }}; }}""")
    if ok("W6-15 [390px] 資金去向的第一層面板打得開", bool(sn2), sn2):
        ok("W6-15 [390px] 面板沒有溢出畫面", sn2["left"] >= 0 and sn2["right"] <= sn2["w"] + 1, sn2)
    pg.keyboard.press("Escape")
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)

    all_sk = len(sk_dd_groups(pg))
    chain2 = pg.evaluate(f"""() => {{ const dd = document.querySelector('{SK_ROW} .rotdd[data-dd="chain"]');
        const b = dd.querySelector('.ddbtn'); if (b) b.click();
        const opts = [...dd.querySelectorAll('.ddopt[data-c]')].filter(o => o.dataset.c);
        if (!opts.length) return null; const c = opts[0].dataset.c; opts[0].click(); return c; }}""")
    pg.wait_for_timeout(1400)
    if ok("W6-16：資金去向的第一層挑得到一條鏈", bool(chain2), chain2):
        sub_sk = len(sk_dd_groups(pg))
        ok("W6-16：選完鏈之後第二層自動打開",
           pg.evaluate(f"""() => (document.querySelector('{SK_ROW} .rotdd[data-dd="group"] .ddbtn')||{{}})
               .getAttribute('aria-expanded')""") == "true")
        ok(f"★ W6-16：第二層只剩這條鏈底下的族群（{sub_sk} < {all_sk}）",
           0 < sub_sk < all_sk, {"這條鏈": sub_sk, "全部": all_sk})
        ok("★ W6-16：這一層是**單選**（一個 checkbox 都沒有）",
           count(pg, f'{SK_ROW} .rotdd[data-dd="group"] input[type=checkbox]') == 0,
           count(pg, f'{SK_ROW} .rotdd[data-dd="group"] input[type=checkbox]'))

        g_sk = sk_dd_groups(pg)
        base_sig = pg.evaluate(_SK_SIG)
        n_clock0 = len(_rot_scatter(pg) or [])
        if ok("W6-17：第二層挑得到一個族群", len(g_sk) > 0, len(g_sk)):
            ok("W6-17：點得下去", sk_dd_pick(pg, g_sk[0], 1800), g_sk[0])
            w17 = pg.evaluate(f"""() => ({{
                panel: (() => {{ const b = document.getElementById('sankeyPanel'); return !!b && !b.hidden; }})(),
                open: (document.querySelector('{SK_ROW} .rotdd[data-dd="group"] .ddbtn')||{{}}).getAttribute('aria-expanded'),
                btn: (document.querySelector('{SK_ROW} .rotdd[data-dd="group"] .ddbtn')||{{}}).textContent || '' }})""")
            nm = pg.evaluate("(g) => (window.App && window.App.L && window.App.L.gname[g]) || g", g_sk[0])
            ok("★ W6-17①：右邊的成分股面板真的打開", w17["panel"], w17)
            ok("★ W6-17②：選完之後第二層自己收起來（單選選完就該收）", w17["open"] == "false", w17["open"])
            ok("★ W6-17③：按鈕上寫著剛選的那個族群名", nm in w17["btn"], {"按鈕": w17["btn"][:50], "族群": nm})
            # 18 樹真的展開（≥800 才驗）
            sig1 = pg.evaluate(_SK_SIG)
            ok("★ W6-18 [1500px]：樹節點總數變多而且結構簽章真的改變（圖跟著篩選重畫了）",
               sig1["n"] > base_sig["n"] and sig1["sig"] != base_sig["sig"],
               {"前": base_sig["n"], "後": sig1["n"]})
            # 19 不准連動到輪動時鐘
            ok("★ W6-19：輪動時鐘的點數**選前選後一樣**（資金去向的選取沒有被併進 ROT）",
               len(_rot_scatter(pg) or []) == n_clock0,
               f"{n_clock0} → {len(_rot_scatter(pg) or [])}")
            # 20 清除
            ok("W6-20：按得到「清除」",
               pg.evaluate(f"""() => {{ const b = document.querySelector('{SK_ROW} .dd-clear');
                   if (!b) return false; b.click(); return true; }}"""))
            pg.wait_for_timeout(1800)
            sig2 = pg.evaluate(_SK_SIG)
            ok("★ W6-20：清除之後樹的結構簽章回到最初", sig2["sig"] == base_sig["sig"],
               {"最初": base_sig["n"], "現在": sig2["n"]})
            ok("★ W6-20：右邊的面板也收回 hidden",
               pg.evaluate("() => { const b = document.getElementById('sankeyPanel'); return !b || b.hidden; }"))
    notes.append("W6-18 的 390 版本刻意跳過：窄版三層樹本來就不畫葉節點，量了只會量到一個必然的 0")


# ===================================================================== 批次C6：3D 退版後的靜態行為
# ★★ 2026-09-23 整段重寫（技術債清理）。段落名沿用 `批次C6-3D運轉動畫` 不改，
#    是因為 HANDOFF 與既有的 `--only` 指令都在引用它；但它現在驗的是**相反的事**。
#
# 事情的經過（已經發生的事實，不要重新討論）：
#   ① 批次 0923-C／E 依 Andy 的要求把 3D 加上動畫：先是 pulse（一組零件依序點亮），
#      後來又補了「形狀真的在動」的四種動法（swing／grow／carry ＋ 額外加的 move／spin）。
#   ② 他實際看過之後親口說：「3D 動畫「閃」改「動」，退回去 閃爍之前的版本，
#      我覺得動畫效果加上去後沒那麼好」「回到閃爍之前的一個版本，不要閃爍」。
#   ③ 於是 `edd87ec` 把 0923-E 那批動作宣告整批刪掉，並在 engine 端用 `PULSE_OFF`
#      **整個關掉** pulse（不是調暗，是不跑）。
#
# 所以這一段的舊斷言（「19 個場景每一個都真的在動」「七個時鐘都在走」）**前提已經被使用者推翻**，
# 從 `edd87ec` 起天天亮紅燈 —— 紅燈天天亮，下次真的壞掉就沒人看得出來。現在改成驗：
#   ① 20 張場景全部從**真正的頁面路由**掛得起來，而且過程中沒有 crash
#   ② 閃爍真的關掉了：`pulses` ／ `pulseK` 都是 0，而且
#      **顏色指紋與自體發光在時間軸上不再起伏** ← 這是「關掉」與「只是調暗」唯一的分界
#   ③ 0923-E 加的那批動作宣告真的沒了：`swings` ／ `grows` ／ `carries` 都是 0
#   ④ **但**：0923-E 之前就有的機械轉動要留著（扇葉轉、晶碇提拉、滾珠螺桿進給、石英片振盪）
#      —— 逐張比對「哪幾個零件真的在動」，多一個少一個都紅
#   ⑤ `machine_tool`（CNC 工具機）場景刻意保留（它只是不再自己動）
#   ⑥ 「動畫：關」這顆鈕對**還會動的那幾張**仍然真的有效；系統要求減少動態時一格都不准動
#
# ⚠⚠ 舊版是用 `C6_MOUNT`「離線掛到暫存容器」那條路量的（`position:fixed; z-index:-1; opacity:.01`）。
#    那條路上 `IntersectionObserver` 會把 rAF 停掉，**動畫在那裡本來就不會跑** ——
#    也就是舊版量到的「沒有在動」有一半是量法自己造成的，不是產品的行為。
#    所以整段改走真正的頁面路由 `#industry/<chain>/dg/<scene>`，看到什麼就是使用者看到什麼。
#
# ⚠ 這個容器沒有 GPU，走 swiftshader 軟體渲染，`ai_server` 自己就是 632ms 一幀 ——
#   **幀率的絕對值沒有任何意義**，效能判準一律寫成「相對於 ai_server 的比值」。
#   段落一律 `--workers 1`（平行跑會把 CPU 吃滿、工具列 6 秒點不到，整批假紅）。

# 20 張場景 → 它在網站上真正的路由。場景 id 不一定等於路由最後一段
# （工業自動化那一頁掛的是 `motion_axis`、先進封裝那一頁掛的是 `semiconductor`）。
C6_ROUTES = {
    "ai_server":       "industry/ai_server/dg/ai_server",
    "semiconductor":   "industry/semiconductor/dg/ai_adv_packaging",
    "mlcc":            "industry/electronics/dg/mlcc",
    "foundry":         "industry/semiconductor/dg/foundry",
    "silicon_wafer":   "industry/semiconductor/dg/silicon_wafer",
    "hbm":             "industry/semiconductor/dg/hbm",
    "wide_bandgap":    "industry/semiconductor/dg/wide_bandgap",
    "ic_substrate":    "industry/ai_server/dg/ic_substrate",
    "pcb_rigid":       "industry/ai_server/dg/pcb_rigid",
    "server_psu":      "industry/ai_server/dg/server_psu",
    "liquid_cooling":  "industry/ai_server/dg/liquid_cooling",
    "air_cooling":     "industry/ai_server/dg/air_cooling",
    "switch_wireless": "industry/ai_server/dg/switch_wireless",
    "panel":           "industry/electronics/dg/panel",
    "motion_axis":     "industry/electronics/dg/factory_automation",
    "machine_tool":    "industry/electronics/dg/machine_tool",
    "resistor_protect": "industry/electronics/dg/resistor_protect",
    "capacitor":       "industry/electronics/dg/capacitor",
    "power_inductor":  "industry/electronics/dg/power_inductor",
    "ai_interconnect": "industry/ai_server/dg/ai_interconnect",
}
C6_SCENES = list(C6_ROUTES)

# ★★ 「退版之後，每一張場景還有哪幾個零件真的在動」的基準表。
#    這不是憑印象寫的 —— 是 2026-09-23 用 `view.pose()`（每個零件的世界座標＋旋轉＋縮放）
#    走真正的頁面路由**逐張量出來**的：`#s` 是零件內部自己會轉的東西（扇葉、轉子、碼盤），
#    `#i` 是陣列零件（風扇牆）各自繞自己的中心轉。
#    四組保留下來的機械轉動剛好對應到它們：
#      · 扇葉轉 → ai_server（ag_fan）、air_cooling（blade／counter_rot／fan_wall）、switch_wireless（sw_fan）
#      · 晶碇提拉 → silicon_wafer（seed／ingot 一起往上拉，melt 跟著轉）
#      · 滾珠螺桿進給 → motion_axis（螺桿轉、螺帽走，滑塊與工作台被推著走）
#      · 石英片振盪 → power_inductor（xtal_blank）
#      · 另外 foundry 的「取放晶粒」（fd_die）也是 0923-E **之前**就有的，一起留著
#    判準是**集合相等**，不是「至少有幾個」：
#      多出來 ＝ 有人把退掉的動畫悄悄加回去（那要先確認 Andy 改變了主意）；
#      少掉   ＝ 本來就該動的機械轉動被一起賠掉了。兩種都要紅。
C6_MOVING = {
    "ai_server":        {"ag_fan#s"},
    "semiconductor":    set(),
    "mlcc":             set(),
    "foundry":          {"fd_die"},
    "silicon_wafer":    {"sw_ingot", "sw_ingot#s", "sw_melt", "sw_melt#s", "sw_seed", "sw_seed#s"},
    "hbm":              set(),
    "wide_bandgap":     set(),
    "ic_substrate":     set(),
    "pcb_rigid":        set(),
    "server_psu":       set(),
    "liquid_cooling":   set(),
    "air_cooling":      {"blade#s", "counter_rot#s", "fan_wall#i"},
    "switch_wireless":  {"sw_fan#s"},
    "panel":            set(),
    # ★ machine_tool 刻意留著這個場景，但它**不再自己動**（0923-E 加的那批 moves／spins 已刪）
    "motion_axis":      {"mc_ball", "mc_ball#s", "mc_block", "mc_coupling", "mc_coupling#s",
                         "mc_nut", "mc_return", "mc_screw", "mc_screw#s", "mc_table"},
    "machine_tool":     set(),
    "resistor_protect": set(),
    "capacitor":        set(),
    "power_inductor":   {"xtal_blank"},
    "ai_interconnect":  set(),
}

# 跑 N 幀（用 rAF 數，不是用 wall clock）。軟體渲染一幀可能要半秒以上，
# 所以另外給一個上限，避免整段卡在這裡。
C6_FRAMES = """([n, capMs]) => new Promise(res => {
  let i = 0; const t0 = performance.now();
  const tick = () => { i++;
    if (i >= n || performance.now() - t0 > capMs) return res(i);
    requestAnimationFrame(tick); };
  requestAnimationFrame(tick); })"""

C6_STATS = "() => (window.Rack3D && window.Rack3D.current) ? window.Rack3D.current.stats() : null"
C6_POSE = "() => (window.Rack3D && window.Rack3D.current) ? window.Rack3D.current.pose() : null"


def _c6_moved(pg, rounds=3, frames=14, cap=16000):
    """量「這一張場景有哪幾個零件真的在動」。

    做法：連續取好幾次 `pose()`，把每一次跟上一次不同的零件**聯集**起來。
    為什麼要取好幾次而不是頭尾兩次：位移件在折返點附近那一瞬間位置幾乎不變，
    只比頭尾有機會剛好抓到同一個相位而漏判（那會變成**假紅**）。
    回傳的是零件層級的 key：`part`（整個零件動了）／`part#s`（零件內部有東西在自轉）／
    `part#i`（陣列零件各自轉）。
    """
    seen = set()
    prev = pg.evaluate(C6_POSE) or []
    for _ in range(rounds):
        pg.evaluate(C6_FRAMES, [frames, cap])
        cur = pg.evaluate(C6_POSE) or []
        if len(cur) != len(prev):
            seen.add("(零件數在跑的過程中變了：%d → %d)" % (len(prev), len(cur)))
            prev = cur
            continue
        seen |= {a.split("|")[0] for a, b in zip(prev, cur) if a != b}
        prev = cur
    return seen


def _c6_open(pg, base, route):
    """開到某張 3D 剖析圖並確定 3D 真的掛起來了（走真正的頁面路由，不是離線暫存容器）。"""
    pg.goto(f"{base}#{route}", wait_until="networkidle")
    pg.wait_for_timeout(2600)
    if not pg.evaluate("() => { const b = document.getElementById('dg3d'); return !!b && !b.hidden; }"):
        return False
    if not pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        _dg3d_toolbar_click(pg, "#dg3d", 4500)
        pg.wait_for_timeout(3200)
    return pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)")


def t_c6_anim(pg, base):
    """C6：3D 退回「加動畫之前」而且連閃爍一起關掉之後，**現在正確的行為**。"""
    boom: list[str] = []
    pg.on("pageerror", lambda e: boom.append(f"pageerror: {e}"))
    pg.on("crash", lambda _p: boom.append("頁面 crash"))

    pg.set_viewport_size({"width": 1200, "height": 900})
    pg.goto(base, wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '1');"
                " localStorage.setItem('tw.dg3d.pal', 'tech');"
                " localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
    if not ok("這個容器支援 WebGL（整段的前提）",
              pg.evaluate("() => !!(window.Rack3D && window.Rack3D.supported())")):
        notes.append("C6：WebGL 起不來，整段跳過")
        return

    # ---------------------------------------------------------------- ⑤ 刻意保留的場景
    have = pg.evaluate("() => Object.keys(window.Rack3D.SCENES)")
    ok("★ C6-0：`machine_tool`（CNC 工具機）場景**仍然在**"
       "（退動畫時刻意保留的，不要跟著一起賠掉）", "machine_tool" in have, have)
    ok(f"C6-0：這一輪要走的 {len(C6_ROUTES)} 張場景，SCENES 裡一張都不缺",
       not [k for k in C6_ROUTES if k not in have], [k for k in C6_ROUTES if k not in have])

    # ---------------------------------------------------------------- ①②③④ 逐張走真正的路由
    dead, flick, decl, wrong = [], [], [], []
    base_tris, tri = None, {}
    for sid, route in C6_ROUTES.items():
        if not _c6_open(pg, base, route):
            dead.append(f"{sid}（{route}）：掛不起來")
            continue
        st0 = pg.evaluate(C6_STATS) or {}
        moved = _c6_moved(pg)
        st1 = pg.evaluate(C6_STATS) or {}
        tri[sid] = st1.get("triangles") or 0
        if sid == "ai_server":
            base_tris = tri[sid]

        # ② 閃爍真的關掉了 —— 而且不是「調暗」
        if st1.get("pulses") != 0 or st1.get("pulseK") != 0:
            flick.append(f"{sid}：pulses={st1.get('pulses')} pulseK={st1.get('pulseK')}")
        # 顏色指紋與自體發光在時間軸上都不准起伏（閃爍的定義就是「原地忽亮忽暗」）
        if st0.get("colorSig") != st1.get("colorSig"):
            flick.append(f"{sid}：顏色指紋還在起伏 {st0.get('colorSig')} → {st1.get('colorSig')}")
        if st0.get("idleEmissive") or st1.get("idleEmissive"):
            flick.append(f"{sid}：零件還在自體發光 idleEmissive={st0.get('idleEmissive')}／{st1.get('idleEmissive')}")

        # ③ 0923-E 加的那批動作宣告真的沒了
        for k in ("swings", "grows", "carries"):
            if st1.get(k):
                decl.append(f"{sid}：{k}={st1.get(k)}")

        # ④ 該動的還在動、不該動的一個都不准動
        want = C6_MOVING.get(sid, set())
        if moved != want:
            wrong.append({"場景": sid, "多出來": sorted(moved - want), "少掉": sorted(want - moved)})

    ok(f"★ C6-1：{len(C6_ROUTES)} 張 3D 場景**全部從真正的頁面路由掛得起來**", not dead, dead[:6])
    ok("★ C6-2：閃爍真的關掉了（pulses／pulseK 都是 0，而且顏色指紋與自體發光"
       "在時間軸上**完全不起伏** —— 這是「關掉」與「只是調暗」唯一的分界）", not flick, flick[:6])
    ok("★ C6-3：0923-E 那批動作宣告（swings／grows／carries）真的整批刪掉了", not decl, decl[:6])
    ok("★ C6-4：**該動的還在動、不該動的一個都不准動** —— 逐張比對「哪幾個零件真的在動」"
       "（多出來＝有人把退掉的動畫加回去；少掉＝原有的機械轉動被賠掉了）", not wrong, wrong[:4])
    ok("★ C6-5：整輪走完沒有任何一張場景把頁面弄爆（crash／pageerror ＝ 0）", not boom, boom[:4])

    # 效能棘輪：每張場景的三角形數不得超過 ai_server 的 1.15 倍
    # （絕對的毫秒數在軟體渲染的容器裡沒有意義，所以一律寫成相對比值）
    if base_tris:
        over = [f"{k}：{v}（ai_server {base_tris} 的 {v / base_tris:.2f} 倍）"
                for k, v in tri.items() if v > base_tris * 1.15]
        ok(f"C6-6：每張場景的三角形數 ≤ `ai_server` 的 1.15 倍（棘輪；ai_server ＝ {base_tris}）",
           not over, over[:5])
    else:
        notes.append("C6：量不到 ai_server 的三角形數，效能棘輪那一條跳過")

    # ---------------------------------------------------------------- ⑥ 「動畫：關」對還會動的那張仍然真的有效
    # 用 `motion_axis`（滾珠螺桿那張，退版後還在動的零件最多 —— 10 個），
    # 拿一張本來就不動的圖來驗這顆鈕等於什麼都沒驗。
    if _c6_open(pg, base, C6_ROUTES["motion_axis"]):
        # 先確定現在是「動畫：開」。
        # ⚠ 鈕上的字是**目前的狀態**（`industry.js` 的 setAnimAll：on ? '動畫：開' : '動畫：關'），
        #   不是「按下去會變成什麼」。舊版寫成「沒有『關』就按一下」—— 那是把它讀反了，
        #   結果是**先把動畫關掉**，再宣稱「動畫開著時時鐘真的在走」。那一條從頭到尾驗錯了狀態。
        pg.eval_on_selector("#dgAnim", "b => { if (b.textContent.indexOf('關') >= 0) b.click(); }")
        pg.wait_for_timeout(900)
        on_moved = _c6_moved(pg)
        ok("C6-7：動畫開著時，滾珠螺桿那張真的有東西在動", bool(on_moved), sorted(on_moved))
        flow_on = (pg.evaluate(C6_STATS) or {}).get("flowVisible")

        # ★ 真的按那顆鈕，不是呼叫 API
        _dg3d_toolbar_click(pg, "#dgAnim", 900)
        ok("C6-7：鈕上的字真的換成「動畫：關」", "關" in text(pg, "#dgAnim"), text(pg, "#dgAnim"))
        off_moved = _c6_moved(pg)
        ok("★ C6-7：按「動畫：關」→ 零件**完全凍住**（連續三次量 pose，一個零件都沒變）",
           not off_moved, sorted(off_moved))
        flow_off = (pg.evaluate(C6_STATS) or {}).get("flowVisible")
        ok("★ C6-7：按「動畫：關」→ 沿線跑的光點也真的收掉（flowVisible 從 %s 變成 0）" % flow_on,
           flow_off == 0, {"開": flow_on, "關": flow_off})

        _dg3d_toolbar_click(pg, "#dgAnim", 900)
        pg.wait_for_timeout(600)
        again = _c6_moved(pg)
        ok("★ C6-7：再按一次 → 該動的零件又全部動起來", again == on_moved,
           {"第一次": sorted(on_moved), "再開之後": sorted(again)})
    else:
        notes.append("C6：`motion_axis`（工業自動化那一頁）掛不起來，⑥ 跳過")

    # ---------------------------------------------------------------- ⑦ 系統要求「減少動態效果」
    ctx = pg.context.browser.new_context(reduced_motion="reduce", viewport={"width": 1200, "height": 900})
    pg2 = ctx.new_page()
    try:
        pg2.goto(base, wait_until="networkidle")
        pg2.evaluate("() => { try { localStorage.setItem('tw.dg3d', '1');"
                     " localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
        if _c6_open(pg2, base, C6_ROUTES["motion_axis"]):
            ok("★ C6-8：系統要求「減少動態效果」時，連滾珠螺桿那張也一個零件都不准動",
               not _c6_moved(pg2), sorted(_c6_moved(pg2)))
            ok("C6-8：而且 stats 自己也誠實標示 reduced ＝ true",
               (pg2.evaluate(C6_STATS) or {}).get("reduced") is True,
               (pg2.evaluate(C6_STATS) or {}).get("reduced"))
        else:
            notes.append("C6：reduced-motion 的分頁裡場景掛不起來，⑦ 跳過")
    finally:
        pg2.close(); ctx.close()


# ===================================================================== 批次W9：軟體與資訊服務四張新圖
# `software` 這條鏈的四張圖（資安／雲端 MSP／SaaS／電商）。
# 環節數必須是 0 那一條在 `批次C3-無環節棘輪` 已經驗了（那是刻意的，理由寫在那一段）；
# 這一段驗的是**操作**：分頁真的換圖、點零件真的只亮一個、章節真的展得開、窄畫面不橫向捲。
W9_DGS = [
    ("資安", "cyber_security", "dgcs", "cs_alert"),
    ("雲端 MSP", "cloud_msp", "dgcm", "cm_resale"),
    ("軟體服務 SaaS", "saas", "dgsa", "sa_sub_m11"),
    ("電商", "ecommerce", "dgec", "ec_ship"),
]


def t_w9_software(pg, base):
    """W9：軟體鏈四張圖的真人操作驗收（換圖、點零件、展章節、窄畫面）。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#industry/software", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    tabs = pg.evaluate("() => [...document.querySelectorAll('#dgPick .segchip[data-dgid]')].map(a => a.dataset.dgid)")
    ok("W9-1：`#industry/software` 的分頁列列得出四張新圖",
       all(d for _, d, _, _ in W9_DGS if d in tabs) and len(tabs) >= 4, tabs)

    seen_titles = []
    for lab, did, cls, part in W9_DGS:
        pg.goto(f"{base}#industry/software/dg/{did}", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2400)
        z = pg.evaluate("""() => { const h = document.getElementById('prodDiagram');
            const svg = h && h.querySelector('svg');
            return { title: (document.getElementById('dgTitle')||{}).textContent || '',
                     cls: svg ? svg.getAttribute('class') || '' : '',
                     folds: h ? h.querySelectorAll('g.dgfold[data-fold]').length : 0 }; }""")
        if not ok(f"[{lab}] 這張圖畫得出來", bool(z["cls"]), z):
            continue
        seen_titles.append(z["title"])
        # 1 分頁真的換圖：`#dgTitle` 換字 ＋ svg 的 class 是這張圖自己的（不是只驗元素存在）
        ok(f"★ W9-1 [{lab}] `#dgTitle` 真的寫著這張圖的名字", len(z["title"]) > 1, z["title"])
        ok(f"★ W9-1 [{lab}] 畫出來的是這張圖（svg class 含 `{cls}`）", cls in z["cls"], z["cls"][:40])
        # 2 點一個零件 → 只有它拿到 .sel-part
        hit = pg.evaluate("""(k) => { const n = document.querySelector('#prodDiagram [data-part="' + k + '"]');
            if (!n) return null; n.scrollIntoView({ block: 'center' }); return true; }""", part)
        if ok(f"[{lab}] 圖上找得到零件 `{part}`", bool(hit), part):
            pg.eval_on_selector(f'#prodDiagram [data-part="{part}"]',
                                "n => n.dispatchEvent(new MouseEvent('click', {bubbles: true}))")
            pg.wait_for_timeout(700)
            # ⚠ `.sel-part` 不只掛在零件上：v2 版面會同時標記**錨點**（`.anc`）與**引線**
            #   （`.dglead path`），所以整張圖的 `.sel-part` 本來就會是 3 個。
            #   要問的是「**零件**只有一個是主角」，所以只數 `[data-part].sel-part`。
            #   （第一版數 `.sel-part` 全部、判 == 1，四張圖全紅 —— 那是驗錯對象，不是產品壞了。）
            # ⚠ `.sel-part` 同一個零件會標在**兩個地方**（SVG 裡那一塊 ＋ 外掛出去的 HTML 卡片），
            #   再加上錨點，整張圖本來就是 3 個。要問的是「**被標成主角的零件只有這一個**」，
            #   所以比的是**去重之後的 data-part 集合**（沿用 `_V2` 探針的 `heroParts` 語意）。
            #   （第一版數 `.sel-part` 全部、判 == 1，四張圖全紅 —— 那是驗錯對象，不是產品壞了。）
            sel = pg.evaluate("""(k) => ({
                parts: [...new Set([...document.querySelectorAll('#prodDiagram [data-part].sel-part')]
                         .map(e => e.dataset.part))],
                all: document.querySelectorAll('#prodDiagram .sel-part').length,
                onSvg: !!document.querySelector('#prodDiagram svg [data-part].sel-part'),
                onCard: !!document.querySelector('#prodDiagram .dgc.sel-part'),
                anc: document.querySelectorAll('#prodDiagram .anc.sel-part').length,
                lead: document.querySelectorAll('#prodDiagram .dglead path.sel-part').length })""", part)
            ok(f"★ W9-2 [{lab}] 點 `{part}` → **只有它**被標成主角（去重之後只有一個零件）",
               sel["parts"] == [part], sel)
            ok(f"★ W9-2 [{lab}] 畫布那一塊與說明卡片**同時**亮起來（只亮一邊等於使用者對不起來）",
               sel["onSvg"] and sel["onCard"], sel)
            ok(f"W9-2 [{lab}] 引線的錨點也跟著亮（不是只有色塊變色）", sel["anc"] >= 1, sel)
        # 4 章節真的展得開（高度真的變大，不是只有 class 改）
        if z["folds"] > 0:
            h0 = pg.evaluate("""() => { const b = document.querySelector('#prodDiagram .dgbody, #dgBody');
                return b ? Math.round(b.getBoundingClientRect().height) : 0; }""")
            vb0 = pg.evaluate("() => { const s = document.querySelector('#prodDiagram svg');"
                              " return s ? Math.round(s.viewBox.baseVal.height) : 0; }")
            pg.eval_on_selector_all("#prodDiagram g.dgfold[data-fold]",
                                    "gs => gs.forEach(g => g.dispatchEvent(new MouseEvent('click', {bubbles:true})))")
            pg.wait_for_timeout(800)
            vb1 = pg.evaluate("() => { const s = document.querySelector('#prodDiagram svg');"
                              " return s ? Math.round(s.viewBox.baseVal.height) : 0; }")
            ok(f"★ W9-4 [{lab}] 章節真的展得開（畫布高度真的變大 {vb0} → {vb1}）",
               vb1 > vb0, {"前": vb0, "後": vb1, "dgBody": h0})
        else:
            notes.append(f"W9-4：{lab} 這張圖沒有章節列，那一條跳過")
        # 5 390 不橫向捲
        pg.set_viewport_size({"width": 390, "height": 900})
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2400)
        ok(f"★ W9-5 [{lab} 390px] 不產生整頁水平捲動",
           pg.evaluate("() => document.documentElement.scrollWidth <= 390 + 1"),
           pg.evaluate("() => document.documentElement.scrollWidth"))
        pg.set_viewport_size({"width": 1440, "height": 1000})
    ok("W9-1：四張圖的標題**彼此都不同**（點分頁是真的換圖，不是同一張換個名字）",
       len(set(seen_titles)) == len(seen_titles) and len(seen_titles) >= 3, seen_titles)

    # 6 淺色主題下卡片文字對比（比照既有那一段的做法：量 computed style，不是看有沒有 class）
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'light'); } catch (e) {} }")
    for lab, did, _cls, _p in W9_DGS:
        pg.goto(f"{base}#industry/software/dg/{did}", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2400)
        low = pg.evaluate("""() => { const rgba = (s) => { const m = (s || '').match(/[\\d.]+/g) || [];
            /* ⚠ 現代瀏覽器對 `color-mix()` 算出來的顏色會回 **CSS Color 4** 的寫法：
               `color(srgb 0.91 0.79 0.79)` —— 三個值是 **0～1**，不是 0～255。
               直接當 0～255 讀會把一個淺色底讀成接近黑色，於是「深字印在淺底上」
               被判成對比 1.24（實測就是這樣紅的，產品完全正確）。所以要先認出這種寫法。*/
            const k = /^color\\(/i.test((s || '').trim()) ? 255 : 1;
            return [(+m[0] || 0) * k, (+m[1] || 0) * k, (+m[2] || 0) * k,
                    m[3] == null ? 1 : +m[3]]; };
          const lin = (v) => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); };
          const lum = (c) => .2126 * lin(c[0]) + .7152 * lin(c[1]) + .0722 * lin(c[2]);
          const over = (f, b) => f[3] >= 1 ? f : [0,1,2].map(i => f[i] * f[3] + b[i] * (1 - f[3])).concat([1]);
          const ratio = (a, b) => { const la = lum(a), lb = lum(b);
            return +(((Math.max(la, lb) + .05) / (Math.min(la, lb) + .05))).toFixed(2); };
          const wrap = document.getElementById('prodDiagram'); if (!wrap) return null;
          const pageBg = rgba(getComputedStyle(document.body).backgroundColor);
          const bad = [];
          wrap.querySelectorAll('.dgc').forEach(card => {
            const cb = over(rgba(getComputedStyle(card).backgroundColor), pageBg);
            card.querySelectorAll('b,i,em,small,span').forEach(e => {
              const t = (e.textContent || '').trim(); if (!t) return;
              const cs = getComputedStyle(e);
              /* ⚠ 有些元素**自己有底色**（編號圓點 `.no`、環節色標那種小晶片）——
                 拿卡片的底去比會量出一個假的低對比（實測 1.2，實際上是深字印在淺底晶片上）。
                 所以先把元素自己的底疊在卡片底上，再比。做法與 `STYLE22` 那支探針一致。*/
              const under = over(rgba(cs.backgroundColor), cb);
              const cr = ratio(over(rgba(cs.color), under), under);
              const need = e.tagName === 'I' ? 3 : 4.5;
              if (cr < need) bad.push(e.tagName + '|' + cr + '|' + t.slice(0, 12)); }); });
          return { bad, theme: document.documentElement.getAttribute('data-theme') || '',
                   pal: document.documentElement.dataset.dgpal || '',
                   pageBg: getComputedStyle(document.body).backgroundColor,
                   cardBg: (() => { const c = wrap.querySelector('.dgc');
                     return c ? getComputedStyle(c).backgroundColor : ''; })(),
                   cards: wrap.querySelectorAll('.dgc').length }; }""")
        ok(f"★ W9-6 [{lab}] 淺色主題下卡片裡每一段字的對比都過（正文 ≥ 4.5、次要 ≥ 3）",
           bool(low) and low["bad"] == [],
           low and {"低於門檻": low["bad"][:4], "theme": low["theme"], "pal": low["pal"],
                    "頁底": low["pageBg"], "卡底": low["cardBg"], "卡數": low["cards"]})
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); } catch (e) {} }")
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 題材2D：十八張題材圖改版
# 那一路交件時附了一份現成的驗收程式碼（`scratchpad/uitest_snippet.py`），但它是寫給
# 自己那支量測腳本用的（`rec` / `BASE` / `MEASURE_JS` 在這支檔案裡都不存在），
# 所以這裡是**照它量的那幾件事重寫**，不是照單貼上。量的仍然是同一組事實。
#
# 每一條都驗「畫面真的因此改變了」：
#   ① 十八張的畫布都收到 980（1180 代表每一張都要左右滑，那不是「一次看完」）
#   ② 每一個 text 的 computed font-size ≥ 12px
#   ③ 同一張圖裡沒有任兩個 text 的外框相交超過 2px（口徑同 `_preview.py`）
#   ④ 零件與文字都沒有畫出 viewBox
#   ⑤ **點一格 → 那一格真的被選起來，而且 `rect.slot` 的 computed fill 真的變了**
#      （只驗 class 變了不算：class 變了長得一樣，對使用者來說就是沒發生）
#   ⑥ 個股小卡點下去真的跳到 `#stock/<代號>`
#   ⑦ 兩條棘輪：**寫死色碼 0 個**、**`lit pulse` 0 個**
#   ⑧ 深淺兩個主題、三個寬度都跑
THEME_2D_IDS = ["cowos", "hbm_memory", "pcb_ccl", "glass_substrate", "asic_ip", "ai_server",
                "power_bbu", "thermal", "silicon_photonics", "semi_equipment", "apple_chain",
                "edge_ai_pc", "robotics", "drone", "satellite", "ev_auto", "defense", "heavy_electric"]

T2D_MEASURE = """() => {
  const svg = document.querySelector('#themeDg .dg3, .dg3');
  if (!svg) return { present: false };
  const vb = svg.viewBox && svg.viewBox.baseVal ? svg.viewBox.baseVal : null;
  const small = [], boxes = [], outs = [];
  svg.querySelectorAll('text').forEach(n => {
    const t = (n.textContent || '').trim(); if (!t) return;
    const cs = getComputedStyle(n);
    if (cs.visibility === 'hidden' || cs.display === 'none' || +cs.opacity <= 0.05) return;
    const r = n.getBoundingClientRect(); if (!r.width || !r.height) return;
    const fs = parseFloat(cs.fontSize) || 0;
    if (fs < 11.9) small.push(fs.toFixed(1) + 'px「' + t.slice(0, 14) + '」');
    boxes.push({ t: t.slice(0, 14), r: r });
    if (vb) { const g = n.getBBox();
      if (g.x < -1 || g.x + g.width > vb.width + 1 || g.y < -1 || g.y + g.height > vb.height + 1)
        outs.push('字：' + t.slice(0, 14)); }
  });
  /* 零件也不准畫出畫布。
     ⚠ 這裡**不能**拿 `getBBox()` 去比 viewBox：零件都住在有 transform 的群組裡，
       `getBBox()` 回的是**那個群組的本地座標**，跟 viewBox 不是同一個座標系 ——
       第一版就是這樣量的，結果 18 張全部誤判成「溢出」（實測改成螢幕座標之後是 0）。
     所以改量**螢幕座標**：零件的外框要落在 svg 自己的外框裡。*/
  {
    const sr = svg.getBoundingClientRect();
    svg.querySelectorAll('[data-part] .part, g.art rect, g.art path, g.art circle').forEach(n => {
      const r = n.getBoundingClientRect(); if (!r.width || !r.height) return;
      if (r.left < sr.left - 1 || r.right > sr.right + 1 || r.top < sr.top - 1 || r.bottom > sr.bottom + 1)
        outs.push('零件：' + (n.getAttribute('class') || n.tagName));
    });
  }
  const ov = [];
  for (let i = 0; i < boxes.length; i++) for (let j = i + 1; j < boxes.length; j++) {
    const a = boxes[i].r, b = boxes[j].r;
    const w = Math.min(a.right, b.right) - Math.max(a.left, b.left);
    const h = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
    // 容差 2px：描邊、字距這種純粹擦邊的不算（跟 `_preview.py` 同一個口徑）
    if (w > 2 && h > 2 && ov.length < 6) ov.push(boxes[i].t + ' X ' + boxes[j].t);
  }
  return { present: true, cw: svg.dataset.cw || '', vbW: vb ? Math.round(vb.width) : 0,
           n: boxes.length, small: small, nSmall: small.length,
           ov: ov, nOv: ov.length, out: outs.slice(0, 5), nOut: outs.length,
           stn: svg.querySelectorAll('g.stn').length,
           slots: svg.querySelectorAll('rect.slot').length,
           codes: svg.querySelectorAll('.scode[data-code]').length,
           /* ★ 棘輪一：**零件本身**不准寫死色碼 —— 顏色一律走 `--dg-*` 或上游傳進來的環節色。
              量的是節點的 `fill` / `stroke` / `stop-color` 屬性，不是整份 outerHTML：
                · `style="--c: #f9f871"` 是 app 那邊算好的**環節色**塞進來的（不是這張圖寫死的）
                · 共用的 `<style>` 區塊裡有 `color-mix(..., #000)` 這種 fallback，
                  而且中文註解裡還有「DECISIONS #231」這種字串 —— 掃 outerHTML 會把它們一起算進來
                第一版就是這樣量的，cowos 一張就報 14 個「寫死色碼」，全部是誤判。*/
           hard: (() => { const bad = [];
             svg.querySelectorAll('*').forEach(n => {
               ['fill', 'stroke', 'stop-color'].forEach(a => {
                 const v = n.getAttribute(a);
                 if (v && /^#[0-9a-fA-F]{3,8}$/.test(v.trim())) bad.push(a + '=' + v + '@' + n.tagName); }); });
             return bad; })(),
           // ★ 棘輪二：`lit pulse`（Andy 講過三次的「螢光感太重」的來源）
           pulse: svg.querySelectorAll('.lit.pulse, .pulse.lit').length,
           docW: document.documentElement.scrollWidth, winW: innerWidth }; }"""


def t_themes_2d(pg, base):
    """題材頁十八張 2D 圖：畫布寬、字級、重疊、溢出、點一格真的變色、點個股真的跳頁、兩條棘輪。"""
    hard_total, pulse_total, bad = 0, 0, []
    for theme in ("dark", "light"):
        pg.goto(f"{base}#themes", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); } catch (e) {} }", theme)
        lab0 = "深色" if theme == "dark" else "淺色"
        for w in (1440, 800, 390):
            pg.set_viewport_size({"width": w, "height": 1000})
            for tid in THEME_2D_IDS:
                pg.goto(f"{base}#themes/{tid}", wait_until="networkidle")
                pg.reload(wait_until="networkidle")
                pg.wait_for_timeout(1200)
                z = pg.evaluate(T2D_MEASURE)
                tag = f"[{tid}·{w}px·{lab0}]"
                if not z.get("present"):
                    bad.append(f"{tag} 沒有圖")
                    continue
                if z["cw"] != "980" or z["vbW"] != 980:
                    bad.append(f"{tag} 畫布不是 980（data-cw={z['cw']} viewBox={z['vbW']}）")
                if z["nSmall"]:
                    bad.append(f"{tag} 小字 {z['small'][:2]}")
                if z["nOv"]:
                    bad.append(f"{tag} 文字重疊 {z['ov'][:2]}")
                if z["nOut"]:
                    bad.append(f"{tag} 溢出 {z['out'][:2]}")
                if z["docW"] > z["winW"] + 1:
                    bad.append(f"{tag} 整頁橫向捲軸 {z['docW']} > {z['winW']}")
                if theme == "dark" and w == 1440:
                    hard_total += len(z["hard"])
                    pulse_total += z["pulse"]
                    if z["hard"]:
                        bad.append(f"{tag} 寫死色碼 {z['hard'][:2]}")
    ok("★ 題材2D：十八張 × 三寬度 × 深淺兩主題 —— 畫布 980、字 ≥ 12px、不重疊、不溢出、不橫向捲",
       not bad, bad[:6])
    # ---- ⑦ 兩條棘輪
    ok("★ 題材2D 棘輪一：十八張渲染出來的 SVG 裡**一個寫死色碼都沒有**（顏色一律走 --dg-*）",
       hard_total == 0, hard_total)
    ok("★ 題材2D 棘輪二：`lit pulse` 歸零（那是「螢光感太重」的來源，Andy 講過三次）",
       pulse_total == 0, pulse_total)

    # ---- ⑤ 真的點一格：class 要變，**而且 `rect.slot` 的 computed fill 真的不一樣**
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); } catch (e) {} }")
    pg.set_viewport_size({"width": 1440, "height": 1000})
    picked = 0
    for tid in ("cowos", "ai_server", "robotics"):
        pg.goto(f"{base}#themes/{tid}", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1400)
        SNAP = """(i) => { const gs = [...document.querySelectorAll('.dg3 g.stn')];
            const g = gs[i]; if (!g) return null;
            const slot = g.querySelector('rect.slot');
            return { cls: g.getAttribute('class') || '',
                     fill: slot ? getComputedStyle(slot).fill : '',
                     stroke: slot ? getComputedStyle(slot).stroke : '' }; }"""
        n_stn = count(pg, ".dg3 g.stn")
        idx = 2 if n_stn > 3 else 0          # 規格點名的是「第三格」
        b0 = pg.evaluate(SNAP, idx)
        if not ok(f"[{tid}] 圖上量得到第 {idx + 1} 格（共 {n_stn} 格）", bool(b0), b0):
            continue
        pg.eval_on_selector_all(".dg3 g.stn",
                                "(gs, i) => gs[i] && gs[i].dispatchEvent(new MouseEvent('click', {bubbles: true}))", idx)
        pg.wait_for_timeout(600)
        b1 = pg.evaluate(SNAP, idx)
        ok(f"★ [{tid}] 點第 {idx + 1} 格 → 那一格的 class 真的變了", b0["cls"] != b1["cls"],
           {"前": b0["cls"], "後": b1["cls"]})
        ok(f"★ [{tid}] 而且 `rect.slot` 的**實際填色**真的變了（class 變了長得一樣＝沒發生）",
           b0["fill"] != b1["fill"] or b0["stroke"] != b1["stroke"], {"前": b0, "後": b1})
        picked += 1
    ok("三張圖都真的點過一格", picked == 3, picked)

    # ---- ⑥ 個股小卡真的跳到個股頁
    pg.goto(f"{base}#themes/cowos", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1400)
    code = pg.evaluate("""() => { const c = document.querySelector('.dg3 .scode[data-code]');
        if (!c) return null; c.scrollIntoView({ block: 'center' }); return c.dataset.code; }""")
    if ok("題材圖上找得到個股小卡", bool(code), code):
        pg.wait_for_timeout(400)
        pg.eval_on_selector(f'.dg3 .scode[data-code="{code}"]',
                            "e => e.dispatchEvent(new MouseEvent('click', {bubbles: true}))")
        pg.wait_for_timeout(1400)
        ok(f"★ 點個股小卡 {code} 真的進得去個股頁（網址真的變了）",
           pg.evaluate("() => location.hash") == f"#stock/{code}",
           pg.evaluate("() => location.hash"))
    pg.set_viewport_size({"width": 1500, "height": 1000})


# 工具列位置：★ 2026-09-23 第二批（W3-1 ＋ W3-9）改成「跟標題同一列、靠右」。
# 第一版是絕對定位浮在畫布右上角，`_preview.py` 當場量到它跟「產品剖析圖 <圖名>」那行標題重疊。
# 現在量的是三件事：**在標題那一列**、**在標題右邊**、**沒有跟標題重疊**。
CG_TOOLS = """() => { const t = document.getElementById('dgTools');
  /* ★ 2026-09-23 C1（Andy：「產品剖析圖…拿掉」）：那一列的 `<h4>` 標題整顆移除，
     只留下圖名 `#dgTitle`（包在 `.dgsectitle` 裡）。舊寫法 `head.querySelector('h4')`
     從此永遠是 null，整個探針回 null，四個寬度全紅 —— 那是驗錯對象，不是工具列不見了。
     所以「標題那一塊」改成 `.dgsectitle`（找不到就退回 `#dgTitle` 自己）。*/
  const head = document.querySelector('#dgSec .dgsechead');
  const h4 = head && (head.querySelector('.dgsectitle') || head.querySelector('#dgTitle') || head.querySelector('h4'));
  if (!t || !head || !h4) return null;
  const rt = t.getBoundingClientRect(), rh = head.getBoundingClientRect(), r4 = h4.getBoundingClientRect();
  if (!rt.width || !rh.width) return { vis: false };
  const overlap = rt.left < r4.right - 1 && rt.right > r4.left + 1
               && rt.top < r4.bottom - 1 && rt.bottom > r4.top + 1;
  return { vis: getComputedStyle(t).display !== 'none' && !t.hidden,
           // 「靠右」＝工具列的中心在標題列的右半邊（窄畫面它自己換行，這時只要求不重疊）
           qx: ((rt.left + rt.right) / 2 - rh.left) / rh.width,
           rightOfTitle: rt.left >= r4.right - 2,
           sameRow: Math.abs(rt.top - r4.top) < 40,
           overlapTitle: overlap,
           inHead: rt.top >= rh.top - 2 && rt.bottom <= rh.bottom + 2,
           right: Math.round(rh.right - rt.right) }; }"""


def t_b25_tools(pg, base):
    """剖析圖工具列在圖內**右上角**、切換不跳回頁首（規格第三節 17～21）。

    ★ 2026-09-23 第二批（W3-1）：Andy 要求設定列從右下角改到右上角，
      所以這裡量的那一半（qy／bottom）跟著換成上緣，**要驗的事情一條都沒有放寬**：
      仍然是「在圖內」「在右邊」「四個寬度都成立」「切 3D 不跳位置」。
    """
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.evaluate("() => { try { localStorage.setItem('tw.dgOpen','1'); localStorage.setItem('tw.dg3d','0');"
                " localStorage.setItem('tw.side','0'); } catch (e) {} }")
    # ⚠ 挑 ai_server：它有**鏈層級**的架構圖，一進去就是圖。
    #   semiconductor 現在一進去是**圖別選單**（5 張各自獨立的圖），
    #   選單模式下本來就沒有工具列可言（既有行為，paintDgMode 會把它收起來）。
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(300)
    pg.goto(f"{base}#industry/ai_server/dg/ai_server", wait_until="networkidle"); pg.wait_for_timeout(3200)

    # ⑰ 四個寬度都要在右下 1/4、而且完整在容器內
    for vw in (1440, 1100, 800, 390):
        pg.set_viewport_size({"width": vw, "height": 950}); pg.wait_for_timeout(1500)
        t = pg.evaluate(CG_TOOLS)
        if not ok(f"{vw}px 找得到剖析圖工具列", bool(t) and t.get("vis"), t):
            continue
        # 規格書第三版第一節寫明：**窄畫面（< 800）改成橫向一列貼在畫布底緣、可左右捲**。
        # 那種型態的水平中心本來就在 0.5，用「右下 1/4」去要求它是錯的量尺；
        # 窄畫面要守的是「貼著底緣、完整在容器內、捲得到」。
        if vw > 800:
            ok(f"{vw}px 設定列跟標題同一列、而且在標題右邊（＝右上角）",
               t["qx"] > 0.5 and t["rightOfTitle"] and t["sameRow"],
               {"qx": round(t["qx"], 2), "right": t["rightOfTitle"], "sameRow": t["sameRow"]})
        else:
            ok(f"{vw}px 設定列自己換到下一行，排成可左右捲的一列",
               pg.evaluate("""() => { const t = document.getElementById('dgTools'); if (!t) return false;
                   const cs = getComputedStyle(t);
                   return t.scrollWidth <= t.clientWidth + 2 || /auto|scroll/.test(cs.overflowX); }"""))
        # ★ W3-9：這一條就是 `_preview.py` 抓到的那個問題 —— 設定列不准壓到標題
        ok(f"{vw}px 設定列沒有跟「產品剖析圖」那行標題重疊", not t["overlapTitle"], t)
        ok(f"{vw}px 設定列在標題那一列裡（沒有溢出到區塊外）", t["inHead"], t)
    pg.set_viewport_size({"width": 1500, "height": 1000}); pg.wait_for_timeout(1200)

    # ⑱ 切 3D 之後位置不跳（量離右下角的距離）
    t2d = pg.evaluate(CG_TOOLS)
    if pg.evaluate("() => { const b = document.getElementById('dg3d'); return !!b && !b.hidden; }"):
        pg.eval_on_selector("#dg3d", "e => e.click()"); pg.wait_for_timeout(3000)
        t3d = pg.evaluate(CG_TOOLS)
        # ★ W3-9：設定列住在標題那一列，跟畫布高度無關 —— 切 3D 之後它本來就不該動
        ok("切到 3D 之後設定列還在同一個位置（離標題列右緣距離差 ≤ 6px，而且仍然不壓到標題）",
           bool(t3d) and abs(t3d["right"] - t2d["right"]) <= 6 and not t3d["overlapTitle"],
           f"{t2d} → {t3d}")
        pg.eval_on_selector("#dg3d", "e => e.click()"); pg.wait_for_timeout(2000)
    else:
        notes.append("這個環境不支援 WebGL，「切 3D 工具列不跳位置」那一條跳過")

    # ㉑ 收合之後工具列仍然在、仍然點得到（真的按一次把圖展開回來）
    pg.eval_on_selector("#dgFold", "e => e.click()"); pg.wait_for_timeout(1200)
    fold = pg.evaluate("""() => { const t = document.getElementById('dgTools'), b = document.getElementById('dgBody');
        const r = t.getBoundingClientRect();
        return { vis: getComputedStyle(t).display !== 'none' && r.width > 10 && r.height > 6,
                 bodyHidden: getComputedStyle(b).display === 'none',
                 btn: (document.getElementById('dgFold') || {}).textContent || '' }; }""")
    ok("按「收合圖」之後圖真的收起來，但工具列還在、還看得到", fold["bodyHidden"] and fold["vis"], fold)
    ok("而且鈕的字換成「展開剖析圖」", "展開" in fold["btn"], fold["btn"])
    pg.eval_on_selector("#dgFold", "e => e.click()"); pg.wait_for_timeout(1400)
    ok("再按一次真的把圖展開回來",
       pg.evaluate("() => getComputedStyle(document.getElementById('dgBody')).display !== 'none'"))

    # ⑲ 切圖別不跳頁首
    n_chip = count(pg, "#dgPick .segchip")
    if n_chip > 1:
        pg.evaluate("() => window.scrollTo({ top: 420 })"); pg.wait_for_timeout(500)
        y0 = pg.evaluate("() => Math.round(scrollY)")
        h0 = pg.evaluate("() => location.hash")
        # ★ 2026-09-23：`#dgPick` 的第一頁現在是「族群總覽」（DECISIONS #252），
        #   不加 `[data-dgid]` 的話這裡會點到它 —— 那驗到的是「切回總覽」，不是「切另一張圖」。
        pg.eval_on_selector("#dgPick .segchip[data-dgid]:not(.sel)", "a => a.click()")
        pg.wait_for_timeout(2000)
        y1 = pg.evaluate("() => Math.round(scrollY)")
        changed("切圖別，網址真的跟著換", h0, pg.evaluate("() => location.hash"))
        ok("切圖別**不會**跳回頁首（scrollY 差 ≤ 8px）", abs(y1 - y0) <= 8, f"{y0} → {y1}")
    else:
        notes.append("這條鏈只有一張剖析圖，「切圖別不跳頁首」那一條跳過")

    # ⑳ 換一條鏈仍然捲頁首（反向驗證：不是把捲動整個關掉）
    pg.evaluate("() => window.scrollTo({ top: 600 })"); pg.wait_for_timeout(400)
    ok("先把頁面捲下去（不然下面的『捲回頁首』不算數）",
       pg.evaluate("() => Math.round(scrollY)") > 200, pg.evaluate("() => Math.round(scrollY)"))
    pg.evaluate("() => { location.hash = '#industry/electronics'; }")
    pg.wait_for_timeout(2400)
    ok("換一條鏈仍然捲回頁首（證明不是把捲動關掉）",
       pg.evaluate("() => Math.round(scrollY)") <= 8, pg.evaluate("() => Math.round(scrollY)"))
    pg.evaluate("() => window.scrollTo({ top: 600 })"); pg.wait_for_timeout(400)
    pg.evaluate("() => { location.hash = '#overview'; }")
    pg.wait_for_timeout(1600)
    ok("換到別的分頁也仍然捲回頁首",
       pg.evaluate("() => Math.round(scrollY)") <= 8, pg.evaluate("() => Math.round(scrollY)"))


"""★ 批次28（2026-09-23）：一般電子鏈六張剖析圖補上 3D 立體 —— 補完這批，全站 19 張全部有 3D。

面板／工業自動化／CNC 工具機／被動保護／電容器／被動 RLC 六張原本 `scene: null`，
現在各自有自己的場景（site/three3d.js 的 SCENES 檔尾五筆；
工業自動化與 CNC 工具機**共用同一個場景** `motion_axis`，因為它們本來就共用同一張 2D）。

寫法照抄批次24（`t_b24_semi3d`），驗的全部是「畫面真的因此改變」，不是「元素存在」：
  ① 六張都真的掛得起來，而且零件數等於場景宣告的那個數（少一個就是有 kind 叫不到、退回方塊）
  ② 材質底色不是環節色（#238 那一刀；這六張刻意一張一個主色）
  ③ 換模式 → 材質色的指紋、畫布底、卡片底色真的變；閱讀模式零件完全不自體發光
  ④ 用滑鼠真的點一顆零件 → 只有那一顆被標成主角；真的點背景 → 回到點之前的樣子
  ⑤ 收攏（explode 0）與展開（explode 1）零件的世界座標真的不同
  ⑥ 卡片：編號圓點、中英雙語、字級 ≥ 12px、台股晶片或明寫「台股無直接對應」（不准留白）
     ★ 這一批多一條：場景裡寫了 `codes: []` 的零件（查不到台股具名對應的那些）
       **一定**要顯示「台股無直接對應」而且那張卡片上的晶片數是 0 ——
       舊的 `p.codes && p.codes.length` 對空陣列會掉回 members(seg)，
       那會把整個環節的公司貼到一個查不到對應的零件底下，那不是留白、是錯誤宣稱（R5）。
  ⑦ 效能上下限；⑧ 800px 窄畫面不橫向捲動、卡片不出框
"""
B28_ROUTES = {
    # 名稱: (路由, draw call 上限, 三角形上限, 三角形下限, 場景宣告的零件數)
    #   上限＝量出來的數字留約一倍餘裕；下限是「不准退回一堆方塊」的地板，各張自己訂
    #   （批次24 已經記過：拿一個全站數字去量「一疊薄層」的圖就是拿錯尺）。
    "面板疊層":     ("industry/electronics/dg/panel", 90, 24000, 5000, 14),
    "工業自動化":   ("industry/electronics/dg/factory_automation", 110, 24000, 5000, 12),
    # ★ 2026-09-23 更正（技術債清理）：CNC 工具機**已經不再共用 `motion_axis`**。
    #   批次 0923-E 給它開了自己的場景 `machine_tool`（一台立式綜合加工機：床身／立柱／鞍座／
    #   X-Z 兩根螺桿／工作台／工件／主軸頭／主軸馬達／主軸／主軸軸承／刀柄／刀庫／換刀機械手／
    #   控制器櫃／排屑機／軌道，共 **17** 顆），那是刻意加的，不是「多畫了幾塊」。
    #   這裡原本寫 12（那是 `motion_axis` 一根軸的零件數），從 0923-E 起就一直是紅的。
    "CNC 工具機":   ("industry/electronics/dg/machine_tool", 110, 24000, 5000, 17),
    "被動保護":     ("industry/electronics/dg/resistor_protect", 60, 14000, 2500, 10),
    "鋁電容":       ("industry/electronics/dg/capacitor", 80, 16000, 3000, 14),
    "電感電阻石英": ("industry/electronics/dg/power_inductor", 70, 14000, 2500, 16),
}

# 批次28 新增的零件字彙（site/three3d.js 的 mkBuilders 檔尾那一段）。
# 少掛一個的後果不是「畫得醜一點」，是**那個 kind 安靜退回方塊**、而且沒有人會發現。
B28_KINDS = ["pnframe", "pnfilm", "pnlgp", "pnledbar", "pnprism", "pnpol", "pnglass",
             "pntft", "pnlc", "pncf", "pndriver",
             "mcbase", "mcmotor", "mcenc", "mccoup", "mcbrg", "mcscrew", "mcnut",
             "mcballs", "mcreturn", "mcrail", "mcblock", "mctable",
             "cppoly", "cpcarbon", "cpfoil", "cpshell", "cpntc", "cpgrain", "cpgb", "cpelec", "cppn",
             "accan", "acsleeve", "accore", "acfoil", "acpore", "acspine", "acoxide",
             "acpaper", "acelyte", "acseal", "aclead", "acvent", "acsolid",
             "indbody", "indwind", "indflux", "indterm",
             "reslay", "resfilm", "restrim", "resglass", "resterm", "resback",
             "xtalbase", "xtalmount", "xtalblank", "xtalelec", "xtallid"]

# 「層」類：它們**本來就是一塊板／一條溝**，對它們要求「比方塊細」是拿錯尺量
# （批次24 已經為 wbglay／wbggate／wbgpgan 記過同一條）。
# 它們改驗「本體之外還畫得出剖面」—— 那才是它們該有的東西。
B28_LAYERS = {"cppoly", "reslay", "restrim", "resglass", "resback"}

# 陣列類一律要收成 InstancedMesh，不然光是導光板的 96 顆網點就是 96 個 draw call。
B28_ARRAYS = {"pnlgp", "pntft", "pnlc", "pncf", "mcballs", "mcbrg", "mcblock",
              "cpcarbon", "cpgrain", "acpore", "indwind", "xtallid"}

# 每張卡片：編號圓點／中英雙語／台股不留白／最小字級，外加「codes: [] 的那幾顆真的是 0 個晶片」
_B28_CARDS = """() => { const host = document.getElementById('prod3d');
  const cards = [...host.querySelectorAll('.lbl3d')];
  let minFs = 1e9;
  cards.forEach(c => c.querySelectorAll('b,i,em,.chip3d,s,small').forEach(t => {
    if (!t.textContent.trim()) return;
    const r = t.getBoundingClientRect(); if (r.width < .5) return;
    minFs = Math.min(minFs, parseFloat(getComputedStyle(t).fontSize)); }));
  const chipsOf = {};
  cards.forEach(c => { const u = c.querySelector('u.chips3d');
    chipsOf[c.dataset.dgpart || ''] = { chips: u ? u.querySelectorAll('a.chip3d').length : -1,
      none: !!(u && /台股無直接對應/.test(u.textContent)) }; });
  return { n: cards.length,
    no: cards.filter(c => { const e = c.querySelector('em.no3d'); return e && e.textContent.trim(); }).length,
    en: cards.filter(c => { const e = c.querySelector('b small.en'); return e && e.textContent.trim(); }).length,
    told: cards.filter(c => { const u = c.querySelector('u.chips3d'); if (!u) return false;
      return u.querySelector('a.chip3d') || /台股無直接對應/.test(u.textContent); }).length,
    minFs: minFs === 1e9 ? null : minFs,
    chipsOf: chipsOf,
    noPart: cards.filter(c => !c.dataset.dgpart).map(c => c.dataset.dgno) }; }"""

# 收攏／展開量的是「零件在畫面上真的動了」，不是 explode 這個變數本身（DECISIONS #199 那一類的錯）
_B28_SCREEN = """() => { const out = {};
  document.querySelectorAll('#prod3d .lead3d .ld-dot').forEach((d, i) => {
    out[String(i)] = [parseFloat(d.getAttribute('cx') || '0'), parseFloat(d.getAttribute('cy') || '0')]; });
  return out; }"""

# 場景裡宣告「查不到台股具名對應」（codes: []）的零件是哪幾顆 —— 直接讀場景資料，不靠記憶
_B28_NOCODE = """(id) => { const s = window.Rack3D.SCENES[id];
  return s ? s.parts.filter(p => Array.isArray(p.codes) && p.codes.length === 0).map(p => p.part) : []; }"""

# 場景 id 不一定等於路由最後一段（例如工業自動化 → `motion_axis`）。
# ★ 2026-09-23 更正：`machine_tool` 曾經共用 `motion_axis`，但 0923-E 之後它有自己的場景。
#   這張表寫錯的後果很隱晦：`_B28_NOCODE` 會去讀**另一張場景**的 `codes: []` 零件（mc_*），
#   拿去跟畫面上根本不存在的卡片對，於是四顆零件永遠回 None 而紅 ——
#   看起來像「產品沒有標示台股無對應」，其實是驗收找錯了場景。
# 所以這張表只留「路由最後一段 ≠ 場景 id」的那一筆，其餘一律**問現場的那個 view**
#   （`window.Rack3D.current.id`），不要再靠一張會過期的手抄表。
B28_SCENE_OF = {"factory_automation": "motion_axis"}


def t_b28_elec3d(pg, base):
    """批次28：一般電子鏈六張的 3D（真的開、真的點、真的切模式、真的收攏展開）。"""
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.goto(base, wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d.pal', 'tech');"
                " localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
    if not pg.evaluate("() => !!window.Rack3D"):
        notes.append("這個環境載不到 Rack3D（WebGL？），批次28-一般電子鏈3D 整段跳過")
        return
    have = pg.evaluate("() => window.Rack3D.kinds()")
    if not have:
        notes.append("Rack3D.kinds() 回空（WebGL 不支援），批次28-一般電子鏈3D 整段跳過")
        return
    missing = [k for k in B28_KINDS if k not in have]
    ok("批次28 新增的 kind 全部掛進分派表了（叫不到就會安靜退回方塊）", not missing, missing)
    probes = pg.evaluate("""async (ks) => { const out = [];
        for (const k of ks) out.push(await window.Rack3D.probe(k)); return out; }""", B28_KINDS)
    bad = [p for p in probes if not p or p.get("error")]
    ok("批次28 每一個新 kind 都建得起來（沒有一個丟例外）", not bad, bad[:3])
    flat = [p for p in probes if p and not p.get("error")
            and p["kind"] not in B28_LAYERS and p["tris"] <= 24]
    ok("批次28 每一個新 kind 都不只是一顆方塊（方塊＝12 個三角形，門檻放在兩倍）",
       not flat, [(p["kind"], p["meshes"], p["tris"]) for p in flat])
    thin = [p for p in probes if p and not p.get("error")
            and p["kind"] in B28_LAYERS and p["meshes"] < 2]
    ok("批次28 的「層」類 kind 除了本體還畫得出剖面（不是一塊光板子）",
       not thin, [(p["kind"], p["meshes"]) for p in thin])
    noinst = [p["kind"] for p in probes if p and not p.get("error")
              and p["kind"] in B28_ARRAYS and p["instanced"] < 1]
    ok("批次28 陣列類零件真的收成 InstancedMesh（一次 draw call）", not noinst, noinst)
    # 兩個族群共用同一個 3D 場景：物件要是**同一個**，不是兩份長得一樣的
    same = pg.evaluate("() => window.Rack3D.SCENES.motion_axis === window.Rack3D.SCENES.motion_axis"
                       " && !!window.Rack3D.hasScene('motion_axis')")
    ok("工業自動化與 CNC 工具機共用的那個場景真的存在（motion_axis）", same, same)

    for nice, (route, cmax, tmax, tmin, nparts) in B28_ROUTES.items():
        if not _l1_open(pg, base, route):
            fails.append(f"[{nice}] 3D 掛不起來 —— 這張圖的 `scene:` 沒接上，或 WebGL 壞了")
            continue
        pg.evaluate("() => window.Rack3D.current.setPal('tech')")
        pg.wait_for_timeout(300)
        st = pg.evaluate("() => window.Rack3D.current.stats()")

        # ---------------- ① 真的畫出東西，而且零件一個都沒漏
        ok(f"[{nice}] 3D 真的畫出東西（draw call 與三角形都 > 0）",
           st["drawCalls"] > 0 and st["triangles"] > 0, st)
        ok(f"[{nice}] 零件數＝場景宣告的 {nparts} 個（少一個就是有 kind 叫不到）",
           st["parts"] == nparts, st["parts"])

        # ---------------- ⑦ 效能上下限
        ok(f"[{nice}] draw call 在上限內（{st['drawCalls']} ≤ {cmax}）", st["drawCalls"] <= cmax, st["drawCalls"])
        ok(f"[{nice}] 三角形在上限內（{st['triangles']} ≤ {tmax}）", st["triangles"] <= tmax, st["triangles"])
        ok(f"[{nice}] 三角形沒有退回「一堆方塊」（下限 {tmin}）", st["triangles"] >= tmin, st["triangles"])

        # ---------------- ② 材質底色 ≠ 環節色
        a = pg.evaluate(_L3_PROBE)
        near = [(m["part"], m["base"], m["segHex"], _dist(m["base"], m["segHex"])) for m in a["mats"]
                if _dist(m["base"], m["segHex"]) < 20]
        ok(f"[{nice}] ★ 沒有任何一個零件的材質底色是環節色（#238 那一刀）", not near, near[:4])
        ok(f"[{nice}] 還沒點任何零件時，沒有一顆被拉向環節色",
           not any(m["tinted"] for m in a["mats"]),
           [m["part"] for m in a["mats"] if m["tinted"]][:4])

        # ---------------- ③ 兩種模式：切了畫面真的變
        pg.evaluate("() => window.Rack3D.current.setPal('read')")
        pg.wait_for_timeout(500)
        r = pg.evaluate(_L3_PROBE)
        _mv = _pal_moved(a, r)
        ok(f"[{nice}] 切到「閱讀」→ **每一個零件**現在畫出來的顏色都真的換了"
           f"（{len(_mv)}/{len(a['mats'])}；colorSig {a['colorSig']} → {r['colorSig']} 只是參考值）",
           len(_mv) == len(a["mats"]) and len(a["mats"]) > 0,
           {"沒換色的零件": [m["part"] for m in a["mats"] if m["part"] not in {x[0] for x in _mv}][:6]})
        ok(f"[{nice}] 切到「閱讀」→ 畫布底真的變了",
           r["pal"] == "read" and r["bg"] != a["bg"], f"{a['bg'][:50]} → {r['bg'][:50]}")
        ok(f"[{nice}] 切到「閱讀」→ 卡片底色與字色真的變了",
           r["cardBg"] != a["cardBg"] and r["ink"] != a["ink"],
           {"科技": (a["cardBg"], a["ink"]), "閱讀": (r["cardBg"], r["ink"])})
        ok(f"[{nice}] 「閱讀」模式零件完全不自體發光（淺底上發光會刺眼）", r["idleEm"] == 0, r["idleEm"])
        pg.evaluate("() => window.Rack3D.current.setPal('tech')")
        pg.wait_for_timeout(300)

        # ---------------- ⑥ 卡片：編號圓點、中英雙語、字級、台股不留白
        c = pg.evaluate(_B28_CARDS)
        ok(f"[{nice}] 每張卡片都有編號圓點", c["no"] == c["n"] and c["n"] > 0, f"{c['no']}/{c['n']}")
        # ⚠⚠ 這一條是**已知的產品缺口，不是過時的斷言，所以刻意不放寬**（2026-09-23 查證後保留）。
        #   規格仍然有效：`docs/diagram_restyle_plan.md` 的卡片介面表明列 `b small.en`
        #   ＝「英文標題（v3 §4 中英雙語），字級 12px、顏色 --dg-ink-3」，而且
        #   **20 張 3D 場景裡有 19 張是 100% 覆蓋**（實測），只有 `machine_tool` 是 0/17 ——
        #   原因是 `site/three3d.js` 的 `EN` 對照表從來沒有補上 `mt_*` 這 17 個 key
        #   （0923-E 新增 machine_tool 場景時漏掉的）。
        #   修法是在 EN 表補 17 列，不是把這裡改成「0 也可以」。`site/**` 不在這一輪的改動範圍，
        #   所以這一條**會繼續紅**，直到有人去補那張表。
        ok(f"[{nice}] 每張卡片都有英文副標（中英雙語，v3 §4）", c["en"] == c["n"], f"{c['en']}/{c['n']}")
        ok(f"[{nice}] 每張卡片的零件身分（data-dgpart）都在，2D 才點得到同一個零件",
           not c["noPart"], c["noPart"])
        ok(f"[{nice}] 每張卡片底下要嘛列得出台股、要嘛明寫「台股無直接對應」（不准留白）",
           c["told"] == c["n"], f"{c['told']}/{c['n']}")
        ok(f"[{nice}] 卡片上最小的字 ≥ 12px", c["minFs"] is not None and c["minFs"] >= 11.9, c["minFs"])
        # ★ 這一批的新斷言：場景寫 `codes: []` 的零件一定要「顯示無對應」而且晶片數是 0。
        #   會壞掉的路徑是「空陣列被當成沒指定 → 掉回 members(seg)」——
        #   那會把整個環節的公司貼到一個查不到對應的零件底下（錯誤宣稱，不是留白）。
        # 場景 id 一律以**現場掛起來的那個 view** 為準（view.id 拿不到才退回手抄表），
        # 這樣下次再有「某張圖換了場景」也不會再冒出一次假紅燈。
        # view 本身沒有 id，但 `title` 是每張場景獨有的，可以反查回 SCENES 的 key。
        _last = route.rsplit("/", 1)[-1]
        _sid = pg.evaluate("""() => { const v = window.Rack3D.current; if (!v) return null;
            return Object.keys(window.Rack3D.SCENES).find(k => window.Rack3D.SCENES[k].title === v.title) || null; }""") \
            or B28_SCENE_OF.get(_last, _last)
        nocode = pg.evaluate(_B28_NOCODE, _sid)
        wrong = [(k, c["chipsOf"].get(k)) for k in nocode
                 if not (c["chipsOf"].get(k) or {}).get("none") or (c["chipsOf"].get(k) or {}).get("chips") != 0]
        ok(f"[{nice}] 場景宣告查不到台股（codes: []）的 {len(nocode)} 顆零件，"
           f"卡片上真的顯示「台股無直接對應」而且晶片數是 0", not wrong, wrong[:4])

        # ---------------- ⑤ 收攏／展開兩種狀態都成立
        #   ⚠ 一定要先把畫布捲進畫面（離開視窗時 IntersectionObserver 會把 rAF 停掉），
        #     而且等 1200ms 不是隨便抓的：容器是軟體渲染、這幾張大約 3 fps，一幀就要 330ms，
        #     等 300ms 有可能一幀都還沒畫 —— 那是假紅（批次24 在矽晶圓那張實際踩到）。
        scroll_to(pg, "prod3d")
        pg.wait_for_timeout(500)
        pg.evaluate("() => window.Rack3D.current.explode(0)")
        pg.wait_for_timeout(1200)
        p0 = pg.evaluate(_B28_SCREEN)
        pg.evaluate("() => window.Rack3D.current.explode(1)")
        pg.wait_for_timeout(1200)
        p1 = pg.evaluate(_B28_SCREEN)
        moved = sum(1 for k in p0 if k in p1 and (abs(p0[k][0] - p1[k][0]) > 2 or abs(p0[k][1] - p1[k][1]) > 2))
        ok(f"[{nice}] ★ 收攏 → 展開時零件真的在畫面上移動了（{moved}/{len(p0)} 個零件）",
           moved >= max(2, len(p0) // 2), {"收攏": dict(list(p0.items())[:3]), "展開": dict(list(p1.items())[:3])})
        # 「每個零件都要給 ex」量的是場景宣告本身：有些零件的位移在這個視角下投影出來不到 2px，
        # 拿畫面位移當唯一證據會變成「看不到就當沒給」—— 那是量錯了東西。
        noex = pg.evaluate("""(id) => { const s = window.Rack3D.SCENES[id];
            return s.parts.filter(p => !p.ex || (!p.ex[0] && !p.ex[1] && !p.ex[2])).map(p => p.part); }""",
                           _sid)
        ok(f"[{nice}] 每個零件都給了爆炸位移 ex（收攏看得出成品、展開看得出層次）", not noex, noex)

        # ---------------- ④ 真的用滑鼠點一顆零件 → 只有那一顆；點背景 → 回到點之前的樣子
        anim_txt = text(pg, "#dgAnim")
        if "開" in anim_txt:                       # 先把動畫關掉，座標才不會在點下去之前飄走
            pg.eval_on_selector("#dgAnim", "b => b.click()")
            pg.wait_for_timeout(900)
        pg.evaluate("() => window.Rack3D.current.explode(1)")
        pg.wait_for_timeout(300)
        scroll_to(pg, "prod3d")
        seg = pg.evaluate("""() => { const v = window.Rack3D.current;
            const cv = document.querySelector('#prod3d canvas'); if (!cv) return null;
            const r = cv.getBoundingClientRect();
            return v.segs().find(s => { const p = v.screen(s);
              return p && p.x > r.left + 8 && p.x < r.right - 8
                       && p.y > Math.max(r.top, 0) + 8 && p.y < Math.min(r.bottom, innerHeight) - 8; }); }""")
        pt = pg.evaluate("(s) => s ? window.Rack3D.current.screen(s) : null", seg)
        sig0 = pg.evaluate("() => window.Rack3D.current.stats().matSig")
        # ★ 基準是「點零件之前長什麼樣」，不是 0：族群層級的網址本來就會把那個族群的環節點亮
        h0 = pg.evaluate(_L1_HI)
        if not pt:
            fails.append(f"[{nice}] 在畫布上找不到任何點得到的零件座標，「點零件」這一條驗不了")
        else:
            pg.mouse.click(pt["x"], pt["y"])
            pg.wait_for_timeout(900)
            h1 = pg.evaluate(_L1_HI)
            sig1 = pg.evaluate("() => window.Rack3D.current.stats().matSig")
            ok(f"[{nice}] 真的用滑鼠點一顆零件 → 只有那一顆被標成主角",
               h1["selPart"] == 1, {"點之後": h1, "座標": pt})
            ok(f"[{nice}] 點完之後材質狀態的指紋也變了（不是只有 class 換）",
               sig0 != sig1, f"{sig0} -> {sig1}")
            bg = pg.evaluate(_L1_BG)
            if not bg:
                fails.append(f"[{nice}] 在畫布上找不到「打不到零件」的空白點，「點背景」驗不了")
            else:
                pg.mouse.click(bg["x"], bg["y"])
                pg.wait_for_timeout(700)
                h2 = pg.evaluate(_L1_HI)
                back = pg.evaluate("() => !document.getElementById('prod3d').classList.contains('haspart')")
                ok(f"[{nice}] 真的點背景 → 零件的選取真的清掉、回到點之前的樣子"
                   f"（主角 {h1['selPart']} → {h2['selPart']}、dim {h1['dim']} → {h2['dim']}）",
                   h2["selPart"] == 0 and h2["dim"] == h0["dim"] and h2["sel"] == h0["sel"] and back,
                   {"點零件之前": h0, "點零件之後": h1, "點背景之後": h2, "座標": bg})

    # ---------------- ⑧ 800px 窄畫面：不橫向捲動、卡片不出框
    for nice, (route, _c, _t, _tm, _n) in B28_ROUTES.items():
        pg.set_viewport_size({"width": 800, "height": 1000})
        if not _l1_open(pg, base, route):
            notes.append(f"[800px] {nice} 3D 掛不起來，窄畫面那一條跳過")
            continue
        pg.wait_for_timeout(900)
        z = pg.evaluate(DG3D_AUDIT)
        ok(f"[{nice} 800px] 3D 畫布本身不橫向捲動（{z['scrollW']} ≤ {z['clientW']}）",
           z["scrollW"] <= z["clientW"] + 1, z)
        ok(f"[{nice} 800px] 每一張卡片都完整落在 3D 容器內（不會被切一半）",
           not z["cardsOut"], z["cardsOut"][:5])
        ok(f"[{nice} 800px] 3D 畫布真的吃到欄寬（不是縮成一小塊）：{z['hostW']}px",
           z["hostW"] >= min(300, 800 - 90), z["hostW"])

    pg.set_viewport_size({"width": 1500, "height": 1000})
    # 收尾：把 3D 關回平面圖、偏好恢復預設（跟批次24 同一條規矩）
    if pg.evaluate("() => !!(window.Rack3D && window.Rack3D.current)"):
        click(pg, "#dg3d", 900)
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0');"
                " localStorage.setItem('tw.dganim', '1');"
                " localStorage.setItem('tw.dg3d.pal', 'tech'); } catch (e) {} }")



# ================================================================ 批次29：產業與個股頁改版
# 規格書 docs/industry_page_tabs_spec.md（Andy 2026-09-23 交辦的五件事）＋ DECISIONS #252。
# 九條驗收逐條寫成真人操作：每一條都是「操作前記一次 → 真的操作 → 操作後再記一次 → 兩次必須不一樣」。
B29_GP = """() => { const q = (s) => document.querySelector(s);
  const vis = (n) => !!(n && n.offsetParent !== null);
  const bar = q('#gpBar'), pie = q('#gpPie');
  const br = bar ? bar.getBoundingClientRect() : null, pr = pie ? pie.getBoundingClientRect() : null;
  const inst = (el) => (el && window.echarts) ? echarts.getInstanceByDom(el) : null;
  const bi = inst(bar), pi = inst(pie);
  const bo = bi ? bi.getOption().series[0].data : [];
  const po = pi ? pi.getOption().series[0].data : [];
  return { bar: !!bar, pie: !!pie, barCanvas: !!(bar && bar.querySelector('canvas,svg')),
           pieCanvas: !!(pie && pie.querySelector('canvas,svg')),
           barVis: vis(bar), pieVis: vis(pie),
           // 「圓餅圖在右邊」＝ 圓餅的左緣不在長條的左邊，而且兩張圖在同一列
           rightOfBar: !!(br && pr && pr.left >= br.right - 6 && pr.top < br.bottom - 40),
           stacked: !!(br && pr && pr.top >= br.bottom - 6),
           names: bo.map(d => d.name), vals: bo.map(d => d.value),
           colors: bo.map(d => d.itemStyle && d.itemStyle.color),
           pieNames: po.map(d => d.name), pieBorder: po.map(d => d.itemStyle && d.itemStyle.borderWidth),
           // ★ W3-8：兩張圖各自的卡片、卡片標題、甜甜圈中心的數字、y 軸有沒有被截斷
           cards: document.querySelectorAll('#v-industry .gpcard').length,
           cardTitles: [...document.querySelectorAll('#v-industry .gpcard > h5')].map(h => h.innerText.trim()),
           yLabels: bi ? (bi.getOption().yAxis[0].data || []) : [],
           pieRadius: pi ? pi.getOption().series[0].radius : null,
           pieTitles: pi ? (pi.getOption().title || []).map(t => t.text) : [],
           pieLabelLine: pi ? !!(pi.getOption().series[0].labelLine || {}).show : false,
           barRadius: bo.length ? (bo[0].itemStyle || {}).borderRadius : null,
           zeroAxis: bi ? (bi.getOption().yAxis[0].axisLine || {}) : null,
           title: (q('#gpTitle') || {}).innerText || '', hint: (q('#gpHint') || {}).innerText || '',
           note: (q('#gpNote') || {}).innerText || '', focus: (q('#gpFocus') || {}).innerText || '',
           back: vis(q('#gpBack')), liveOn: !!(q('#gpLiveBtn') && q('#gpLiveBtn').classList.contains('on')),
           gp: (window.Industry && window.Industry._gp) ? window.Industry._gp() : null }; }"""

# 第 i 條長條的螢幕座標（i＝ECharts 的 dataIndex，0 在最下面）。
# 用 convertToPixel 問 ECharts 自己「這一條畫在哪」，再用真滑鼠點過去 —— 不是派事件。
B29_BARPOS = """(i) => { const el = document.getElementById('gpBar');
  const c = echarts.getInstanceByDom(el); const ds = c.getOption().series[0].data;
  // i < 0 ＝「挑最長的那一條」（最短的那幾條只有幾個像素寬，真滑鼠點不準）
  if (i < 0) { let bi = 0; ds.forEach((d, k) => { if (Math.abs(d.value) > Math.abs(ds[bi].value)) bi = k; }); i = bi; }
  const d = ds[i]; if (!d) return null;
  const r = el.getBoundingClientRect();
  const p0 = c.convertToPixel({ seriesIndex: 0 }, [0, i]);
  const pv = c.convertToPixel({ seriesIndex: 0 }, [d.value, i]);
  // 點在「零線到長條末端」的中間 —— 負值的長條往左長，直接 +20 會點到空白處
  return { name: d.name, value: d.value, i: i, wide: Math.abs(pv[0] - p0[0]) >= 8,
           x: Math.round(r.left + (p0[0] + pv[0]) / 2), y: Math.round(r.top + p0[1]) }; }"""

# 假的即時報價：本機與 CI 連不到 Cloudflare Worker（ERR_TUNNEL_CONNECTION_FAILED），
# 真的按下去只驗得到「誠實地說抓不到」。要驗「數字真的換過一輪」就得給它一份回得來的報價。
# ⚠ 換掉的只有**網路那一層**（Live.fetchQuotes），聚合、重畫、標示盤中暫定值全部走真的程式碼。
B29_STUB = """() => { if (!window.Live) return false;
  window.__b29real = window.Live.fetchQuotes;
  window.Live.fetchQuotes = async (codes) => { const o = {};
    (codes || []).forEach((c, i) => { o[String(c)] = { price: 50 + (i % 7) * 3, prevClose: 50,
      chgPct: (i % 3 === 0 ? 8.8 : (i % 3 === 1 ? -6.6 : 1.1)), volume: 900 + i * 13, time: '11:22:33' }; });
    return o; };
  return true; }"""


def t_b29_tabs(pg, base):
    """產業與個股頁改版（活頁簿分頁＋長條圖／圓餅圖＋昨天／即時＋熱力圖獨立分頁）。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})

    # ---------------- ⑦ 被移除的兩塊真的不在 DOM 了，但「法定產業別」還進得去
    pg.goto(f"{base}#industry", wait_until="networkidle"); pg.wait_for_timeout(2400)
    gone = pg.evaluate("() => ['chainTiles','indTiles'].filter(id => !!document.getElementById(id))")
    ok("產業鏈總覽卡片與法定產業別卡片都不在 DOM 了", gone == [], gone)
    tabs = pg.evaluate("""() => [...document.querySelectorAll('#chainSwitch button')].map(b => ({
        c: b.dataset.c, on: b.classList.contains('on'), t: b.innerText.trim() }))""")
    ok("一層分頁列列得出全市場＋每一條鏈＋法定產業別",
       len(tabs) >= 4 and tabs[0]["c"] == "_all" and any(t["c"] == "industry" for t in tabs), tabs)
    ok("進 #industry 時選中的是「全市場」那一頁", tabs[0]["on"] and sum(1 for t in tabs if t["on"]) == 1, tabs)

    # ---------------- ② 預設畫面＝長條圖（左）＋圓餅圖（右）
    g0 = pg.evaluate(B29_GP)
    ok("#industry 第一眼就是長條圖＋圓餅圖（量 DOM，不是看截圖）",
       g0["barCanvas"] and g0["pieCanvas"] and g0["barVis"] and g0["pieVis"], g0)
    ok("圓餅圖在右邊（Andy 指名）", g0["rightOfBar"], g0)
    ok("長條圖真的有族群（至少 6 條）", len(g0["names"]) >= 6, g0["names"][:5])
    ok("說明有寫「這張圖回答什麼」而且寫到「所以我該怎麼用」",
       "這張圖回答" in g0["hint"] and "怎麼用" in g0["hint"] and len(g0["hint"]) > 60, g0["hint"][:60])
    ok("預設是昨天（盤後），而且畫面上寫得出來",
       "盤後" in g0["note"] and not g0["liveOn"], g0["note"][:60])

    # ---------------- ③ 紅漲綠跌（拿真的正／負漲幅的族群驗顏色，不是看設定檔）
    ch = pg.evaluate("() => ({ up: window.App.CH.up, down: window.App.CH.down })")
    pos = [c for v, c in zip(g0["vals"], g0["colors"]) if v > 0]
    neg = [c for v, c in zip(g0["vals"], g0["colors"]) if v < 0]
    ok("漲的族群是紅色、跌的族群是綠色（台股慣例，不是國際配色）",
       bool(pos) and bool(neg) and all(c == ch["up"] for c in pos) and all(c == ch["down"] for c in neg),
       {"up": ch["up"], "pos": pos[:2], "down": ch["down"], "neg": neg[:2]})
    rgb = pg.evaluate("""(hex) => { const h = hex.replace('#',''); const v = parseInt(h.length===3
        ? h.split('').map(c=>c+c).join('') : h, 16); return [(v>>16)&255, (v>>8)&255, v&255]; }""", ch["up"])
    ok("而且「漲」那個色真的是紅的（R 比 G 大），不會反過來", rgb[0] > rgb[1] + 40, rgb)

    # ---------------- ⑤ 兩圖連動：滑過長條，圓餅對應扇形的樣式真的變
    n = len(g0["names"])
    # ★ W3-8：圓餅只標前五大，所以連動要挑一條「在圓餅上真的有自己那一塊」的長條來驗；
    #   落在「其他」裡的那一種另外有一條專門在驗（見下面）。
    top = None
    for _i in range(n - 1, -1, -1):
        cand = pg.evaluate(B29_BARPOS, _i)
        if cand and cand["name"] in g0["pieNames"]:
            top = cand
            break
    if not ok("量得到一條在圓餅上有自己扇形的長條", bool(top), top):
        return
    b_pie0 = g0["pieBorder"]
    pg.mouse.move(top["x"], top["y"]); pg.wait_for_timeout(800)
    g1 = pg.evaluate(B29_GP)
    idx = g1["pieNames"].index(top["name"]) if top["name"] in g1["pieNames"] else -1
    changed("滑過長條，圓餅對應扇形的描邊真的變了（量的是畫上去的樣式）",
            b_pie0[idx] if idx >= 0 else None, g1["pieBorder"][idx] if idx >= 0 else None,
            f"{top['name']}")
    ok("而且兩張圖共用的讀數列真的寫出那個族群的數字",
       top["name"] in g1["focus"] and "占" in g1["focus"], g1["focus"][:60])
    pg.mouse.move(5, 5); pg.wait_for_timeout(700)
    g1b = pg.evaluate(B29_GP)
    changed("滑鼠移開，圓餅的高亮真的收回去",
            g1["pieBorder"][idx] if idx >= 0 else None, g1b["pieBorder"][idx] if idx >= 0 else None)

    # ---------------- ④ 點長條 → 個股長條圖 → 點個股條進個股頁
    pg.mouse.click(top["x"], top["y"]); pg.wait_for_timeout(1800)
    g2 = pg.evaluate(B29_GP)
    changed("點長條圖的族群，同一塊區域真的換成個股", g0["names"][:3], g2["names"][:3])
    ok("換成的是「該族群所有個股」的漲幅長條圖",
       g2["gp"]["mode"] == "stock" and g2["barCanvas"] and g2["pieCanvas"], g2["gp"])
    ok("而且標題寫出是哪一個族群、幾檔", top["name"] in g2["title"] and "檔" in g2["title"], g2["title"])
    ok("有「← 回到族群」可以回上一層", g2["back"], g2)
    ok("不是跳到別頁（網址沒有變成個股或別的分頁）", pg.evaluate("location.hash") == "#industry",
       pg.evaluate("location.hash"))
    s0 = pg.evaluate(B29_BARPOS, -1)   # 個股層：挑最長的那一條，真滑鼠才點得準
    pg.mouse.click(s0["x"], s0["y"]); pg.wait_for_timeout(2000)
    ok("點個股那一條 → 真的進個股頁", pg.evaluate("location.hash").startswith("#stock/"),
       pg.evaluate("location.hash"))
    pg.go_back(); pg.wait_for_timeout(2200)
    # 回到族群層：按鈕真的把畫面換回去
    back0 = pg.evaluate("() => (window.Industry._gp()||{}).mode")
    if back0 == "stock":
        click(pg, "#gpBack", 1500)
        changed("按「← 回到族群」真的回到族群層級", back0,
                pg.evaluate("() => (window.Industry._gp()||{}).mode"))

    # ---------------- ⑥ 昨天／即時
    # ★ 2026-09-23 第二批（W3-3）：族群總覽搬到 `/overview`，`#industry/<chain>` 改成直接開第一張剖析圖。
    pg.goto(f"{base}#industry/semiconductor/overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    g3 = pg.evaluate(B29_GP)
    ok("進一條鏈的族群總覽，一樣是長條圖＋右邊圓餅圖",
       g3["barCanvas"] and g3["pieCanvas"] and g3["rightOfBar"] and g3["barVis"], g3)
    seltab = pg.evaluate("""() => { const a = document.querySelector('#dgPick .segchip.on');
        return a ? { tab: a.dataset.dgtab || a.dataset.dgid, i: [...a.parentNode.children].indexOf(a) } : null; }""")
    ok("而且它就是二層分頁的第一頁（族群總覽）",
       bool(seltab) and seltab["tab"] == "overview" and seltab["i"] == 0, seltab)
    ok("即時鈕預設是關的，畫面寫著昨天（盤後）", (not g3["liveOn"]) and "盤後" in g3["note"], g3["note"][:50])
    # 先量 onLive 監聽器：連開關三次，再敲三次 tw:quotes，被呼叫的次數必須剛好是 3
    #   —— 監聽器重複疊加的話會變成 6、12、24（app.js 第 445 行寫過的坑）
    for _ in range(3):
        click(pg, "#gpLiveBtn", 500)
        click(pg, "#gpLiveBtn", 500)
    c0 = pg.evaluate("() => window.Industry._gp().liveCalls")
    pg.evaluate("() => { for (let i = 0; i < 3; i++) window.dispatchEvent(new CustomEvent('tw:quotes', { detail: { n: 1 } })); }")
    pg.wait_for_timeout(500)
    c1 = pg.evaluate("() => window.Industry._gp().liveCalls")
    ok("開關即時三次之後，onLive 監聽器**沒有**增加（敲 3 次就只被呼叫 3 次）", c1 - c0 == 3, f"{c0} → {c1}")
    # 真的切到即時：本機連不到報價代理，所以要驗「誠實地說抓不到」；再餵一份假報價驗「數字真的換」
    click(pg, "#gpLiveBtn", 2500)
    g4 = pg.evaluate(B29_GP)
    ok("按下即時：鈕亮起來、而且計時器真的開始跑", g4["liveOn"] and g4["gp"]["timer"], g4["gp"])
    ok("抓不到報價時誠實寫出來（不可以默默畫成收盤值卻說是即時）",
       "抓不到" in g4["note"] or "盤中暫定值" in g4["note"], g4["note"][:70])
    click(pg, "#gpLiveBtn", 800)
    ok("按下 B29_STUB 之前先把即時關掉", not pg.evaluate("() => window.Industry._gp().live"))
    pg.evaluate(B29_STUB)
    v0 = pg.evaluate(B29_GP)["vals"]
    click(pg, "#gpLiveBtn", 3000)
    g5 = pg.evaluate(B29_GP)
    changed("切到即時，長條的數字真的換過一輪", v0, g5["vals"])
    ok("而且畫面標明這是盤中暫定值、成交值是估算的",
       "盤中暫定值" in g5["note"] and "估算" in g5["note"], g5["note"][:80])
    click(pg, "#gpLiveBtn", 2000)
    g6 = pg.evaluate(B29_GP)
    changed("再按一次退回昨天，數字也真的換回來", g5["vals"], g6["vals"])
    ok("退回昨天之後畫面也寫回「盤後」", "盤後" in g6["note"], g6["note"][:50])

    # ---------------- ① 分頁真的切得動、選中的視覺不同
    t0 = pg.evaluate(B29_GP)["title"]
    st = pg.evaluate("""() => { const on = document.querySelector('#chainSwitch button.on');
        const off = [...document.querySelectorAll('#chainSwitch button')].find(b => !b.classList.contains('on'));
        const s = (e) => { const c = getComputedStyle(e); return { bg: c.backgroundColor, mt: c.marginTop,
            bb: parseFloat(c.borderBottomWidth) || 0, fw: c.fontWeight, fs: parseFloat(c.fontSize) }; };
        return { on: s(on), off: s(off), name: on.dataset.c }; }""")
    ok("選中的那一頁與未選的**視覺真的不同**（底色、上緣位置、字重）",
       st["on"]["bg"] != st["off"]["bg"] and st["on"]["mt"] != st["off"]["mt"], st)
    ok("選中的那一頁沒有下邊界（和內容連成一片）", st["on"]["bb"] == 0, st["on"])
    click(pg, "#chainSwitch button[data-c='ai_server']", 2600)
    changed("按一層分頁，內容真的換一條鏈",
            t0, pg.evaluate("() => (document.querySelector('#indChain h2')||{}).innerText || ''"))
    ok("而且網址跟著換（分頁是真的頁，不是只換畫面）",
       pg.evaluate("location.hash") == "#industry/ai_server", pg.evaluate("location.hash"))
    # 二層分頁：換到剖析圖那一頁
    dg = pg.evaluate("() => { const a = document.querySelector('#dgPick .segchip[data-dgid]'); return a ? a.dataset.dgid : null; }")
    if ok("二層分頁列得出這條鏈的剖析圖", bool(dg), dg):
        click(pg, f"#dgPick .segchip[data-dgid='{dg}']", 2600)
        g8 = pg.evaluate(B29_GP)
        after = pg.evaluate("""() => ({ hash: location.hash, svg: !!document.querySelector('#prodDiagram svg'),
            on: (document.querySelector('#dgPick .segchip.on') || { dataset: {} }).dataset.dgid })""")
        ok("按二層分頁 → 剖析圖真的畫出來、族群總覽讓位", after["svg"] and not g8["barVis"], after)
        ok("而且它有自己的網址（可分享、可回上一頁）", after["hash"].endswith("/dg/" + dg), after)
        ok("被選起來的換成那一頁", after["on"] == dg, after)
        click(pg, "#dgPick .segchip[data-dgtab='overview']", 2600)
        g9 = pg.evaluate(B29_GP)
        ok("按回「族群總覽」→ 長條圖與圓餅圖真的回來、網址是這條鏈的 /overview",
           g9["barVis"] and g9["pieVis"]
           and pg.evaluate("location.hash") == "#industry/ai_server/overview",
           pg.evaluate("location.hash"))

    # 法定產業別那一頁（35 個法定產業別唯一的入口，卡片移除之後更不能壞）
    click(pg, "#chainSwitch button[data-c='industry']", 2600)
    gi = pg.evaluate(B29_GP)
    ok("法定產業別那一頁點得進去，而且真的有東西",
       pg.evaluate("location.hash") == "#industry/industry" and len(gi["names"]) >= 5, gi["names"][:4])

    # ---------------- ⑧ 熱力圖在自己的頂層分頁，而且點得動
    ok("頂層分頁列多了「熱力圖」那一頁",
       pg.evaluate("() => !!document.querySelector('#tabs .tab[data-view=\\'heatmap\\']')"))
    click(pg, "#tabs .tab[data-view='heatmap']", 2800)
    hm = pg.evaluate("""() => ({ hash: location.hash, tree: !!document.querySelector('#indTree canvas,#indTree svg'),
        onTab: (document.querySelector('#tabs .tab.on') || { dataset: {} }).dataset.view,
        trees: document.querySelectorAll('#indTree').length,
        gpVis: !!(document.getElementById('gpBar') && document.getElementById('gpBar').offsetParent !== null) })""")
    ok("熱力圖有自己的頂層分頁，而且圖真的畫出來",
       hm["hash"] == "#heatmap" and hm["tree"] and hm["onTab"] == "heatmap", hm)
    ok("整份 DOM 只有一張 #indTree（產業地圖那邊不准再畫一份）", hm["trees"] == 1, hm)
    ok("熱力圖這一頁不會同時出現族群總覽（兩者是不同分頁）", not hm["gpVis"], hm)
    box = pg.evaluate("() => { const r = document.getElementById('indTree').getBoundingClientRect();"
                      " return { x: Math.round(r.left + r.width * 0.25), y: Math.round(r.top + r.height * 0.45) }; }")
    pg.mouse.click(box["x"], box["y"]); pg.wait_for_timeout(2400)
    h2 = pg.evaluate("""() => ({ hash: location.hash,
        nodes: document.querySelectorAll('#chainMap .co').length,
        svg: document.querySelectorAll('#prodDiagram svg').length,
        title: (document.getElementById('gpTitle') || {}).innerText || '' })""")
    ok("從熱力圖點下去，仍然跳得到對應的族群／產業鏈頁",
       h2["hash"].startswith("#industry/") and (h2["nodes"] > 0 or h2["svg"] > 0 or len(h2["title"]) > 2), h2)

    # ================================================================================
    # ★ 2026-09-23 第二批（W3-1／W3-2／W3-3／W3-4）：Andy 點名的四件事，每一件都真的操作一次
    # ================================================================================
    pg.set_viewport_size({"width": 1440, "height": 1000})

    # ---- W3-3：點進產業鏈直接看到第一張剖析圖（族群總覽不刪，搬去 /overview）
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(300)
    pg.goto(f"{base}#industry/ai_server", wait_until="networkidle"); pg.wait_for_timeout(3000)
    w3 = pg.evaluate("""() => { const vis = (n) => !!(n && n.offsetParent !== null);
        const on = document.querySelector('#dgPick .segchip.on');
        const tabs = [...document.querySelectorAll('#dgPick .segchip')];
        return { svg: document.querySelectorAll('#prodDiagram svg').length,
                 gpVis: vis(document.getElementById('gpBar')),
                 onTab: on ? (on.dataset.dgtab || on.dataset.dgid) : null,
                 first: tabs[0] ? (tabs[0].dataset.dgtab || tabs[0].dataset.dgid) : null,
                 firstText: tabs[0] ? tabs[0].textContent.trim() : '',
                 labels: tabs.slice(1).map(a => a.textContent.trim()),
                 titles: tabs.slice(1).map(a => a.getAttribute('title') || '') }; }""")
    ok("W3-3：點進 AI 伺服器鏈，第一眼就是剖析圖（不是族群總覽）",
       w3["svg"] > 0 and not w3["gpVis"], w3)
    ok("W3-3：而且被選起來的是那張圖的分頁，不是「族群總覽」",
       w3["onTab"] not in (None, "overview"), w3["onTab"])
    ok("W3-3：族群總覽**沒有被刪**，而且仍然是分頁列的第一個",
       w3["first"] == "overview" and w3["firstText"] == "族群總覽", w3)
    click(pg, "#dgPick .segchip[data-dgtab='overview']", 2600)
    ok("W3-3：按第一個分頁 → 族群總覽真的回來，網址是 /overview",
       pg.evaluate("() => !!(document.getElementById('gpBar') && document.getElementById('gpBar').offsetParent)")
       and pg.evaluate("location.hash") == "#industry/ai_server/overview", pg.evaluate("location.hash"))
    # 直接貼 /overview 的網址重新整理，一樣要停在族群總覽（不是被 Default 搶回剖析圖）
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    ok("W3-3：直接貼 /overview 重新整理，停在族群總覽（Default 不准把它搶走）",
       pg.evaluate("() => !!(document.getElementById('gpBar') && document.getElementById('gpBar').offsetParent)")
       and pg.evaluate("() => document.querySelectorAll('#prodDiagram svg').length") == 0)

    # ---- W3-4：分頁標籤只留族群名稱（冒號後面的說明收進 title）
    pg.goto(f"{base}#industry/semiconductor", wait_until="networkidle"); pg.wait_for_timeout(3000)
    w4 = pg.evaluate("""() => [...document.querySelectorAll('#dgPick .segchip[data-dgid]')].map(a => ({
        id: a.dataset.dgid, text: a.textContent.trim(), title: a.getAttribute('title') || '',
        full: (window.DiagramSlots && window.DiagramSlots.name(a.dataset.dgid)) || '' }))""")
    if ok("W3-4：半導體鏈列得出剖析圖分頁", len(w4) >= 2, w4):
        ok("W3-4：分頁上一個冒號都沒有（說明被切掉了）",
           all("：" not in t["text"] and ":" not in t["text"] for t in w4), [t["text"] for t in w4])
        ok("W3-4：而且分頁的字就是完整名稱冒號前面那一段（不是被截斷成亂碼）",
           all(t["text"] == t["full"].split("：")[0].split(":")[0].strip() for t in w4),
           [(t["text"], t["full"][:24]) for t in w4])
        ok("W3-4：完整說明沒有不見 —— 滑過去的 title 仍然帶著整串名稱",
           all(t["full"] and t["full"] in t["title"] for t in w4), [t["title"][:40] for t in w4])
        ok("W3-4：至少有一張圖的完整名稱真的比分頁長（證明這一刀有在做事）",
           any(len(t["full"]) > len(t["text"]) + 2 for t in w4),
           [(t["text"], len(t["full"])) for t in w4])

    # ---- W3-1：剖析圖的設定列在圖的右**上**角（節流機制照留，所以要等它收斂）
    # ★ 2026-09-24：一併把動畫偏好歸回「開」（tw.dganim）。前面的段落（題材／零件誰做的…）會把它留在「關」，
    #   下面「按一下 → 字換成關」就變成「按一下 → 字換成開」而假紅 —— main 3748ade 同順序（新-產業與個股,題材,零件誰做的,批次29）一樣紅。
    pg.evaluate("() => { try { localStorage.setItem('tw.dgOpen','1'); localStorage.setItem('tw.dg3d','0'); localStorage.setItem('tw.dganim','1'); } catch (e) {} }")
    pg.goto(f"{base}#industry/ai_server/dg/ai_server", wait_until="networkidle"); pg.wait_for_timeout(3600)
    t1 = pg.evaluate(CG_TOOLS)
    if ok("W3-1：找得到剖析圖的設定列", bool(t1) and t1.get("vis"), t1):
        ok("W3-1：設定列跟標題同一列、靠右（＝右上角），不是右下角",
           t1["qx"] > 0.5 and t1["rightOfTitle"] and t1["sameRow"], t1)
        # ★ W3-9：_preview 抓到的那個問題 —— 浮在圖上時會壓到「產品剖析圖 <圖名>」那行標題
        ok("W3-9：設定列沒有跟標題重疊（並排，不是疊上去）", not t1["overlapTitle"], t1)
        # 真的按一顆：位置換了之後仍然點得到（節流的死區如果寫反，這裡會逾時）
        pg.eval_on_selector("#dgAnim", "b => b.click()"); pg.wait_for_timeout(600)
        ok("W3-1：搬到右上角之後，設定列的鈕仍然真的按得下去（動畫鈕的字真的換了）",
           "關" in pg.evaluate("() => (document.getElementById('dgAnim')||{}).textContent || ''"),
           pg.evaluate("() => (document.getElementById('dgAnim')||{}).textContent || ''"))
        pg.eval_on_selector("#dgAnim", "b => b.click()"); pg.wait_for_timeout(500)
        # 收合／展開一輪之後位置要回得來（補算與 ResizeObserver 都還在）
        pg.eval_on_selector("#dgFold", "b => b.click()"); pg.wait_for_timeout(1000)
        pg.eval_on_selector("#dgFold", "b => b.click()"); pg.wait_for_timeout(2600)
        t2 = pg.evaluate(CG_TOOLS)
        ok("W3-1：收合再展開一輪，設定列仍然在標題那一列的右邊、也仍然不壓到標題",
           bool(t2) and t2["qx"] > 0.5 and t2["rightOfTitle"] and not t2["overlapTitle"], t2)

    # ---- W3-8：族群總覽的兩張圖優化（卡片、不截斷、圓角長條、零軸線、甜甜圈＋中心數字、連動不退化）
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#industry", wait_until="networkidle"); pg.wait_for_timeout(2600)
    g8 = pg.evaluate(B29_GP)
    ok("W3-8：兩張圖各自裝進一張卡片，而且標題寫著它在講什麼",
       g8["cards"] == 2 and any("族群漲跌幅" in t for t in g8["cardTitles"])
       and any("成交值占比" in t for t in g8["cardTitles"]), g8["cardTitles"])
    box8 = pg.evaluate("""() => [...document.querySelectorAll('#v-industry .gpcard')].map(c => {
        const cs = getComputedStyle(c);
        return { r: parseFloat(cs.borderTopLeftRadius) || 0,
                 bw: parseFloat(cs.borderTopWidth) || 0, bg: cs.backgroundColor }; })""")
    ok("W3-8：卡片真的有圓角與邊框（不是把標題貼在同一片背景上）",
       len(box8) == 2 and all(b["r"] >= 8 and b["bw"] >= 1 for b in box8), box8)
    ok("W3-8：族群名稱一個都沒有被截斷（畫面上不准出現「…」）",
       all("…" not in str(y) for y in g8["yLabels"]), [y for y in g8["yLabels"] if "…" in str(y)][:4])
    # ★ 2026-09-24：main 657a9ce「長條改回小圓角」之後 borderRadius 變成四角陣列，
    #   直接拿陣列跟數字比會讓整段「操作中途爆掉」、後面的斷言全部沒跑到 —— 陣列取最大的那個角來比（門檻沒動）。
    _br = g8["barRadius"]
    _br = max([x for x in _br if isinstance(x, (int, float))] or [0]) if isinstance(_br, list) else (_br or 0)
    ok("W3-8：長條兩端是圓角（不是直角）", _br >= 3, g8["barRadius"])
    ok("W3-8：零軸那一條真的畫出來而且加粗了（正負分得開）",
       bool(g8["zeroAxis"]) and g8["zeroAxis"].get("show") is not False
       and (g8["zeroAxis"].get("lineStyle") or {}).get("width", 0) >= 1.5, g8["zeroAxis"])
    ok("W3-8：圓餅改成甜甜圈（有內半徑）",
       isinstance(g8["pieRadius"], list) and len(g8["pieRadius"]) == 2, g8["pieRadius"])
    # ★ 2026-09-24（Andy 給了參考圖：「圓餅圖幫我設計這樣的樣式」）：引線標籤改成圖下方兩欄的圖例
    ok("W3-8（2026-09-24 改）：扇形旁邊不再拉引線，名字與百分比改寫在圖下方的圖例",
       not g8["pieLabelLine"] and pg.evaluate("() => document.querySelectorAll('#gpLegend .lg').length") == len(g8["pieNames"]),
       [g8["pieLabelLine"], pg.evaluate("() => document.querySelectorAll('#gpLegend .lg').length"), len(g8["pieNames"])])
    ok("W3-8：只標前五大＋「其他」，最多六塊（不再是十幾塊碎片擠在一起）",
       len(g8["pieNames"]) <= 6 and "其他" in g8["pieNames"], g8["pieNames"])
    # 中心那個數字一定要**真的是前五大相加**，不准寫死
    want8 = pg.evaluate("""() => { const pi = echarts.getInstanceByDom(document.getElementById('gpPie'));
        const d = pi.getOption().series[0].data;
        const tot = d.reduce((s, x) => s + (x.value || 0), 0);
        const five = d.filter(x => x.name !== '其他').reduce((s, x) => s + (x.value || 0), 0);
        return tot > 0 ? Math.round(five / tot * 1000) / 10 : -1; }""")
    got8 = [t for t in g8["pieTitles"] if "%" in t]
    ok("W3-8：甜甜圈中心寫著「前五大」與它們的合計占比", "前五大" in g8["pieTitles"] and bool(got8), g8["pieTitles"])
    ok("W3-8：而且那個數字是**真的算出來的**（跟前五大相加對得上，誤差 ≤ 0.2%）",
       bool(got8) and abs(float(got8[0].replace("%", "")) - want8) <= 0.2, {"畫面": got8, "算出來": want8})
    # 連動不准退化：滑過一條落在「其他」裡的長條，灰色那一塊要亮起來
    other_i = pg.evaluate("""(names) => { const bi = echarts.getInstanceByDom(document.getElementById('gpBar'));
        const d = bi.getOption().series[0].data;
        for (let i = d.length - 1; i >= 0; i--) if (names.indexOf(d[i].name) < 0) return i;
        return -1; }""", [x for x in g8["pieNames"] if x != "其他"])
    if other_i >= 0:
        pos8 = pg.evaluate(B29_BARPOS, other_i)
        oi = g8["pieNames"].index("其他")
        b_before = g8["pieBorder"][oi]
        pg.mouse.move(pos8["x"], pos8["y"]); pg.wait_for_timeout(800)
        g8b = pg.evaluate(B29_GP)
        changed("W3-8：滑過落在「其他」裡的族群長條，灰色那一塊真的亮起來（連動沒有斷）",
                b_before, g8b["pieBorder"][oi], pos8["name"])
        pg.mouse.move(5, 5); pg.wait_for_timeout(700)
    else:
        notes.append("這一頁的族群不到六個，「滑過落在其他裡的長條」那一條略過")
    # 三個寬度：390 要上下堆疊
    for w8 in (1440, 800, 390):
        pg.set_viewport_size({"width": w8, "height": 1000})
        pg.goto(f"{base}#industry", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        r8 = pg.evaluate("""() => { const cs = [...document.querySelectorAll('#v-industry .gpcard')];
            if (cs.length < 2) return null; const a = cs[0].getBoundingClientRect(), b = cs[1].getBoundingClientRect();
            const fs = [...document.querySelectorAll('#v-industry .gpcard > h5')]
                .map(h => parseFloat(getComputedStyle(h).fontSize));
            return { side: b.left >= a.right - 6, stacked: b.top >= a.bottom - 6, minFs: Math.min(...fs),
                     docW: document.documentElement.scrollWidth, winW: innerWidth,
                     wA: Math.round(a.width), wB: Math.round(b.width) }; }""")
        if ok(f"W3-8 [{w8}px] 找得到兩張卡片", bool(r8), r8):
            ok(f"W3-8 [{w8}px] 兩張卡片不是並排就是上下堆疊（不會互相壓到）",
               r8["side"] or r8["stacked"], r8)
            if w8 == 390:
                ok("W3-8 [390px] 兩張卡片真的上下堆疊（不是硬擠成兩欄）", r8["stacked"], r8)
            ok(f"W3-8 [{w8}px] 卡片標題字級 ≥ 12px", r8["minFs"] >= 12, r8["minFs"])
            ok(f"W3-8 [{w8}px] 沒有橫向捲軸", r8["docW"] <= r8["winW"] + 1, r8)
    pg.set_viewport_size({"width": 1440, "height": 1000})

    # ---- W3-10：切全站主題，剖析圖的配色自動跟著切（深→淺、淺→深兩個方向都要）
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); localStorage.removeItem('tw.dg3d.pal'); } catch (e) {} }")
    pg.goto(f"{base}#industry/electronics/dg/mlcc", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
    PAL = """() => { const svg = document.querySelector('#prodDiagram svg');
        const part = svg && svg.querySelector('[data-seg] .part, [data-seg] rect, [data-seg] path');
        return { pal: document.documentElement.dataset.dgpal || '',
                 theme: document.documentElement.getAttribute('data-theme') || '',
                 // ★ 2026-09-23 C1：`#dgPal` 整顆移除（Andy：「配色拿掉」），
                 //   所以不再驗「按鈕上的字」，改驗 data-dgpal ＋ 畫布上真正的顏色。
                 palGone: !document.getElementById('dgPal'),
                 saved: (() => { try { return localStorage.getItem('tw.dg3d.pal'); } catch (e) { return null; } })(),
                 bg: getComputedStyle(document.documentElement).getPropertyValue('--dg-bg').trim(),
                 ink: getComputedStyle(document.documentElement).getPropertyValue('--dg-ink').trim(),
                 fill: part ? getComputedStyle(part).fill : '' }; }"""
    p0 = pg.evaluate(PAL)
    ok("W3-10：深色主題下剖析圖是「科技」配色", p0["pal"] == "tech" and p0["theme"] == "dark", p0)
    ok("C1：手動配色鈕 `#dgPal` 整顆不在 DOM 裡了（配色只跟著全站主題走）", p0["palGone"], p0)
    # 切到明亮主題 → 剖析圖要自己變閱讀；再切回深色 → 要自己切回科技。
    # ⚠ 用 JS 派發的 element.click()，不要用 pg.click() —— 吸頂的 .topbar 會把點擊攔下來。
    pg.eval_on_selector("#themeBtn", "b => b.click()"); pg.wait_for_timeout(2200)
    p1 = pg.evaluate(PAL)
    ok("W3-10：切到明亮主題 → 剖析圖自動變成「閱讀」配色",
       p1["theme"] == "light" and p1["pal"] == "read", p1)
    ok("W3-10：而且畫面上的顏色真的換了（量 --dg-bg 與 --dg-ink 的解析值，不是看 dataset 那串字）",
       p1["bg"] != p0["bg"] and p1["ink"] != p0["ink"],
       {"深": [p0["bg"], p0["ink"]], "淺": [p1["bg"], p1["ink"]]})
    pg.eval_on_selector("#themeBtn", "b => b.click()"); pg.wait_for_timeout(2200)
    p2 = pg.evaluate(PAL)
    ok("W3-10：再切回暗色主題 → 剖析圖自動切回「科技」（反方向也要跟，不准只單向生效）",
       p2["theme"] == "dark" and p2["pal"] == "tech", p2)
    ok("W3-10：而且顏色真的切回來了（--dg-bg／--dg-ink 都回到深底那一組）",
       p2["bg"] == p0["bg"] and p2["ink"] == p0["ink"], {"現在": [p2["bg"], p2["ink"]], "一開始": [p0["bg"], p0["ink"]]})
    ok("W3-10：localStorage 的舊偏好也一起清掉了（重新整理不會跳回舊的那個）",
       p2["saved"] in (None, "", "tech"), p2["saved"])
    # ★ 2026-09-23 修：原本寫死 `== 1`，但 v2 版面的剖析圖本來就不只一個 <svg>
    #   （主圖之外還有引線／圖例那層），實測是 2。這一條要問的是「圖還在、沒有變空白」，
    #   所以正確的判準是 `>= 1`，不是恰好一個。寫死 1 是假紅。
    ok("W3-10：切主題沒有把圖重畫成初始狀態（剖析圖還在、沒有變空白）",
       pg.evaluate("() => document.querySelectorAll('#prodDiagram svg').length") >= 1)

    # ---- W3-6：產業鏈標題下方那排標籤整排拿掉（檔數／今日／本益比中位／← 返回）
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#industry/semiconductor/overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    for w6 in (1440, 800, 390):
        pg.set_viewport_size({"width": w6, "height": 1000}); pg.wait_for_timeout(900)
        h6 = pg.evaluate("""() => { const card = document.querySelector('#indChain .nbcard');
            const h2 = card && card.querySelector('h2'); if (!h2) return null;
            const head = h2.parentNode;
            const txt = head.innerText || '';
            return { pills: head.querySelectorAll('.pill').length,
                     back: head.querySelectorAll('a,button').length,
                     hasCount: /\d+\s*檔/.test(txt), hasChg: txt.indexOf('今日') >= 0,
                     hasPe: txt.indexOf('本益比中位') >= 0, hasBack: txt.indexOf('返回') >= 0,
                     h2Left: Math.round(h2.getBoundingClientRect().left - card.getBoundingClientRect().left),
                     docW: document.documentElement.scrollWidth, winW: innerWidth }; }""")
        if ok(f"W3-6 [{w6}px] 找得到產業鏈頁的標題區", bool(h6), h6):
            ok(f"W3-6 [{w6}px] 標題下方那排標籤整排不見了（檔數／今日／本益比中位／← 返回）",
               h6["pills"] == 0 and not h6["hasCount"] and not h6["hasChg"]
               and not h6["hasPe"] and not h6["hasBack"], h6)
            # spread 拿掉之後標題不准被推到奇怪的位置：它要貼著卡片左緣
            ok(f"W3-6 [{w6}px] 標題仍然貼著卡片左緣（沒有被 space-between 推歪）",
               0 <= h6["h2Left"] <= 24, h6["h2Left"])
            ok(f"W3-6 [{w6}px] 沒有橫向捲軸", h6["docW"] <= h6["winW"] + 1, h6)
    pg.set_viewport_size({"width": 1440, "height": 1000})

    # ---- W3-7：下方的圖別選單卡片區整塊拿掉（上方分頁就有同樣功能）
    pg.goto(f"{base}#industry/semiconductor/overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    m7 = pg.evaluate("""() => ({ menu: !!document.getElementById('dgMenu'),
        cards: document.querySelectorAll('.dgmenu, #prodDiagram ~ .dgcards, a.dgcard').length,
        tabs: [...document.querySelectorAll('#dgPick .segchip[data-dgid]')].map(a => ({
            id: a.dataset.dgid, href: a.getAttribute('href'), title: a.getAttribute('title') || '' })),
        body: (document.getElementById('prodDiagram') || {}).innerHTML ? 1 : 0 })""")
    ok("W3-7：`#dgMenu` 與那排 `.dgcard` 卡片整塊不在 DOM 了", not m7["menu"] and m7["cards"] == 0, m7)
    ok("W3-7：入口沒有消失 —— 上方二層分頁仍然列得出每一張圖，而且各有自己的 /dg/ 網址",
       len(m7["tabs"]) >= 2 and all(t["href"] and "/dg/" in t["href"] for t in m7["tabs"]),
       [t["href"] for t in m7["tabs"]])
    ok("W3-7：「這張圖回答什麼問題」也沒有消失（掛在分頁的 title 上）",
       all("？" in t["title"] for t in m7["tabs"]), [t["title"][:40] for t in m7["tabs"]])
    # 進到圖裡之後 #dgQ 那一行也要把問題寫出來（第二個看得到的地方）
    click(pg, f"#dgPick .segchip[data-dgid='{m7['tabs'][0]['id']}']", 2600)
    ok("W3-7：進到圖裡之後 `#dgQ` 那一行也把問題寫出來（第二個看得到的地方）",
       "這張圖回答" in (pg.evaluate("() => (document.getElementById('dgQ')||{}).textContent || ''") or ""),
       pg.evaluate("() => (document.getElementById('dgQ')||{}).textContent || ''")[:50])
    # ★ 2026-09-23 C1：「← 族群總覽」`#dgBack` 整顆移除 —— 回上一層改按**分頁列的第一格**。
    #   ⚠ 用 JS 派發的 element.click()：#industry 頁吸頂的 .topbar 會把 pg.click() 攔掉。
    ok("C1：`#dgBack` 已整顆移除（分頁列第一格就是同一個目的地）",
       pg.evaluate("() => !document.querySelector('#dgBack')"))
    pg.eval_on_selector('#dgPick .segchip[data-dgtab="overview"]', "a => a.click()")
    pg.wait_for_timeout(2600)
    ok("W3-7：按分頁列的「族群總覽」真的回第一個分頁（族群總覽出現、網址變 /overview）",
       pg.evaluate("() => !!(document.getElementById('gpBar') && document.getElementById('gpBar').offsetParent)")
       and pg.evaluate("location.hash").endswith("/overview"), pg.evaluate("location.hash"))

    # ---- W3-5：390／800 載入時，說明卡片不准被「原尺寸置中」推出畫面
    #      （量到的事實：置中本來套在整個 #prodDiagram 上，390px 一載入就把 .dggrid
    #       左移 143px —— 左欄的說明卡片直接被切掉半邊，19 張圖全中）
    for w5, route5 in ((390, "ai_server/dg/ai_server"), (390, "electronics/dg/mlcc"),
                       (800, "electronics/dg/mlcc")):
        pg.set_viewport_size({"width": w5, "height": 1000})
        pg.evaluate("() => { try { localStorage.setItem('tw.dgOpen','1'); localStorage.setItem('tw.dg3d','0'); } catch (e) {} }")
        pg.goto(f"{base}#industry/{route5}", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
        m5 = pg.evaluate("""() => { const h = document.getElementById('prodDiagram');
            if (!h) return null;
            const hr = h.getBoundingClientRect();
            const grid = h.querySelector('.dggrid');
            const cards = [...h.querySelectorAll('.dgc')];
            return { host: Math.round(h.scrollLeft),
                     gridLeft: grid ? Math.round(grid.getBoundingClientRect().left - hr.left) : null,
                     cutCards: cards.filter(c => c.getBoundingClientRect().left < hr.left - 2).length,
                     cards: cards.length }; }""")
        if ok(f"W3-5 [{w5}px {route5}] 找得到剖析圖", bool(m5), m5):
            ok(f"W3-5 [{w5}px {route5}] `#prodDiagram` 一載入沒有被推走（scrollLeft ＝ 0）",
               m5["host"] == 0, m5)
            ok(f"W3-5 [{w5}px {route5}] 沒有任何一張說明卡片被切掉左半邊",
               m5["cutCards"] == 0, m5)
    # 1440：置中**不准被改壞** —— 畫布比欄寬大的時候，裝畫布的那個框仍然要捲到中間
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#industry/electronics/dg/mlcc", wait_until="networkidle")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
    m6 = pg.evaluate("""() => { const h = document.getElementById('prodDiagram');
        const svg = h && h.querySelector('svg'); if (!svg) return null;
        const box = svg.closest('.dgcanvas') || h;
        return { host: Math.round(h.scrollLeft), boxScroll: Math.round(box.scrollLeft),
                 over: Math.round(box.scrollWidth - box.clientWidth) }; }""")
    if ok("W3-5 [1440px] 找得到剖析圖", bool(m6), m6):
        ok("W3-5 [1440px] `#prodDiagram` 本身沒有被推走", m6["host"] == 0, m6)
        ok("W3-5 [1440px] 畫布放得下就不必捲；放不下時捲的是裝畫布的那個框（置中沒被改壞）",
           m6["over"] <= 2 or m6["boxScroll"] > 0, m6)

    # ---- W3-2：成分股卡片整組移除，而且「換頁還原事件面板」那段收尾還活著
    gone2 = pg.evaluate("() => ['memberTable','memWide','mktSeg','memberMore','memberTitle']"
                        ".filter(id => !!document.getElementById(id))")
    ok("W3-2：成分股卡片（表格／放寬／市場別／展開更多／標題）整組不在 DOM 了", gone2 == [], gone2)
    # ⚠ 這一條有兩個判斷，第二個（事件欄要回來）依賴「使用者的偏好是開著」。
    #   前面的段落會為了各自的需要把 `tw.side` 設成 0（例如關聯圖那幾段），
    #   狀態跨段落留下來，這條就會在**產品完全正確**的情況下變紅（實測：單跑綠、接在後面紅）。
    #   所以先把偏好明確設成「開」再測 —— 那才是這條要問的前提，不是放寬。
    # ⚠ 兩件事一起做對，這一條才量得到真的東西：
    #   ① 偏好要明確設成「開」再測 —— 前面的段落會為了自己的需要把 `tw.side` 設成 0，
    #      狀態跨段落留下來，這條就會在**產品完全正確**的情況下變紅（實測：單跑綠、接在後面紅）。
    #   ② **不可以先跳到 `#overview` 再跳一次** —— 同一個 hash 的第二次 goto 不會觸發換頁，
    #      收尾程式碼根本沒機會跑，量到的「沒還原」是假的（第一版就是這樣自己造出一個紅燈）。
    #      所以留在這一頁（產業鏈頁）設狀態，**換到別的頁**才算換頁。
    pg.evaluate("() => { try { localStorage.setItem('tw.side', '1'); } catch (e) {}"
                " if (window.twSetSide) window.twSetSide(true, false); }")
    pg.wait_for_timeout(400)
    pg.evaluate("() => { document.body.classList.add('memwide');"
                " if (window.twSetSide) window.twSetSide(false, false); }")
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1400)
    ok("W3-2：換頁一定會把 .memwide 還原掉（規格書點名要留的那段收尾沒有被刪）",
       pg.evaluate("() => !document.body.classList.contains('memwide')"),
       pg.evaluate("() => document.body.className"))
    ok("W3-2：而且事件欄跟著回來（`twSetSide(false, false)` 是暫時蓋住，不是改偏好）",
       pg.evaluate("() => getComputedStyle(document.querySelector('aside')).display") != "none",
       pg.evaluate("() => [getComputedStyle(document.querySelector('aside')).display,"
                   " (() => { try { return localStorage.getItem('tw.side'); } catch (e) { return null; } })()]"))

    # ---------------- ⑨ 四個寬度：不溢出、分頁字不小於 12px、選中的分頁捲得進視野
    for w in (1440, 1100, 800, 390):
        pg.set_viewport_size({"width": w, "height": 1000})
        # ⚠ 一定要 reload：第二圈之後網址一模一樣，`goto` 是同文件導覽（不會重跑 render），
        #   量到的會是**上一個寬度**的版面（實測 390 量到 800 的 716px，假紅）。
        pg.goto(f"{base}#industry/industry", wait_until="networkidle")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2400)
        r = pg.evaluate("""() => { const st = document.getElementById('chainSwitch');
            const on = st.querySelector('button.on'); const sr = st.getBoundingClientRect(), orr = on.getBoundingClientRect();
            const fs = [...document.querySelectorAll('#chainSwitch button, #dgPick .segchip')]
              .map(e => parseFloat(getComputedStyle(e).fontSize));
            const bar = document.getElementById('gpBar'), pie = document.getElementById('gpPie');
            const br = bar.getBoundingClientRect(), pr = pie.getBoundingClientRect();
            return { docW: document.documentElement.scrollWidth, winW: innerWidth,
                     inView: orr.left >= sr.left - 2 && orr.right <= sr.right + 2,
                     minFs: Math.min(...fs), barW: Math.round(br.width), pieW: Math.round(pr.width),
                     side: pr.left >= br.right - 6, stacked: pr.top >= br.bottom - 6 }; }""")
        ok(f"[{w}px] 沒有橫向捲軸", r["docW"] <= r["winW"] + 1, r)
        ok(f"[{w}px] 分頁的字不小於 12px", r["minFs"] >= 12, r)
        ok(f"[{w}px] 選中的那一頁在視野裡（放不下就自己捲過去）", r["inView"], r)
        ok(f"[{w}px] 兩張圖不是並排就是上下排，不會互相壓到",
           r["side"] or r["stacked"], r)
        ok(f"[{w}px] 兩張圖都有實際寬度", r["barW"] > 120 and r["pieW"] > 120, r)


# =============================================================================
# 批次 0923-M：手機優先改版 第一版（frontend-ui）
#
# 依據 `docs/mobile_audit.md` 那份量出來的落差清單。Andy 的原話：
#   「另外我發現電腦看跟手機看完全不同，幫我依據手機改版頁面，後續還會在更新 先改一版吧」
#   ＋ 補的那一句「除了桌面不可以遷就手機 其他你要怎麼優化都可以」
#
# 所以這一段有**兩個方向**要驗，缺一不可：
#   ① 手機真的變好用了（每一顆鈕真的按，而且驗「畫面真的因此改變了」）
#   ② **桌機一點都沒有被動到**（1440px 下新加的東西全部不存在、既有的東西全部還在）
#
# ⚠ 既有的「手機」段落把小字門檻訂在 11px；這一段訂 12px（改版後量到的真實值是 0 筆破線）。
#   兩段並存是刻意的：那一段是別人的棘輪，不去動它。
# =============================================================================
MOBILE_VP = {"viewport": {"width": 390, "height": 844}, "device_scale_factor": 2,
             "is_mobile": True, "has_touch": True}


def t_mobile_v2(b, base, code):
    m = b.new_page(**MOBILE_VP)
    m.on("pageerror", lambda e: fails.append(f"手機改版 pageerror: {e}"))
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())

    # ---------- G1／G9：頂欄不再裁掉功能，「⋯」清單真的能操作 ----------
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2200)
    tb = m.evaluate("""() => { const t = document.querySelector('.topbar');
        const vis = (id) => { const e = document.getElementById(id); if (!e) return null;
          const r = e.getBoundingClientRect();
          return { d: getComputedStyle(e).display, right: Math.round(r.right), h: Math.round(r.height) }; };
        return { sw: t.scrollWidth, cw: t.clientWidth, ovf: getComputedStyle(t).overflow,
                 more: vis('moreBtn'), theme: vis('themeBtn'), ev: vis('evToggle') }; }""")
    ok("[390px] 頂欄不再被裁掉（改版前需要 528px 只有 390px，主題與事件兩顆鈕整個在畫面外）",
       tb["sw"] <= tb["cw"] + 1, tb)
    ok("[390px] 「⋯ 更多工具」看得到，而且整顆在畫面裡",
       tb["more"] and tb["more"]["d"] != "none" and tb["more"]["right"] <= 390, tb["more"])
    ok("[390px] 桌機那四顆鈕在手機是收起來的（功能搬進「⋯」，不是消失）",
       tb["theme"]["d"] == "none" and tb["ev"]["d"] == "none", tb)

    m.click("#moreBtn"); m.wait_for_timeout(300)
    ok("[390px] 點「⋯」清單真的打開了", m.eval_on_selector("#morePop", "e => !e.hidden"))
    rows = m.evaluate("""() => [...document.querySelectorAll('#morePop button')]
        .map(e => ({ t: e.textContent.replace(/\s+/g,' ').trim(), h: Math.round(e.getBoundingClientRect().height) }))""")
    # ★ 2026-09-24 改口徑（Andy：「按鈕更新、設定 版都移除」）：桌機的「更新」「⚙」拿掉了，
    #   清單裡去按它們的兩列一定要一起拿掉（留著就是點了沒反應）。剩下的兩件事照舊要在、名字照舊跟電腦版一樣。
    ok("[390px] 清單裡剩「今日事件」「主題」兩件事，名字跟電腦版一樣", len(rows) == 2 and
       any("今日事件" in r["t"] for r in rows) and any("主題" in r["t"] for r in rows), rows)
    ok("[390px] 「更新（即時報價）」「即時來源設定」兩列跟著桌機的鈕一起拿掉了",
       not any("更新" in r["t"] or "即時來源設定" in r["t"] for r in rows)
       and not m.evaluate("() => !!(document.getElementById('mmLive') || document.getElementById('mmGear'))"), rows)
    ok("[390px] 清單每一列的觸控高度都 ≥ 44px", all(r["h"] >= 44 for r in rows), rows)

    # 今日事件：點下去抽屜要真的滑出來（改版前這件事在手機上做不到 —— 入口被裁掉，
    # 而且 setSide 自己派的 resize 會立刻把它關回去，是個沒人發現的既有 bug）
    before = m.eval_on_selector("aside", "e => Math.round(e.getBoundingClientRect().x)")
    m.click("#mmEvents"); m.wait_for_timeout(700)
    after = m.evaluate("""() => { const a = document.querySelector('aside');
        return { x: Math.round(a.getBoundingClientRect().x), open: a.classList.contains('open') }; }""")
    ok("[390px] 點「今日事件」抽屜真的滑出來了（x 真的變小，不是只加了 class）",
       after["open"] and after["x"] < before - 100, {"before": before, "after": after})
    cnt = m.eval_on_selector("#mmEvCount", "e => e.textContent")
    ok("[390px] 清單上的事件筆數是真的數字（手機看不到頂欄那顆鈕上的數字）",
       cnt.isdigit() and int(cnt) > 0, cnt)

    # 主題：真的切過去、再切回來
    th0 = m.evaluate("() => document.documentElement.dataset.theme")
    m.click("#moreBtn"); m.wait_for_timeout(250); m.click("#mmTheme"); m.wait_for_timeout(700)
    th1 = m.evaluate("() => document.documentElement.dataset.theme")
    ok("[390px] 點「明亮／深色主題」畫面真的換主題了", th0 != th1, {"before": th0, "after": th1})
    m.click("#moreBtn"); m.wait_for_timeout(250); m.click("#mmTheme"); m.wait_for_timeout(700)
    ok("[390px] 再點一次真的換回來", m.evaluate("() => document.documentElement.dataset.theme") == th0)

    # ---------- G2（手機 v3 改寫）：底部導覽一列五顆（總覽／資金流向／產業／熱力圖／更多）----------
    # ★ 2026-09-25 手機 v3（docs/mobile_v3_spec.md §2-1）：兩列七顆 102px → 一列五顆 58px，
    #   市場明細／週期統計／交付清單收進「更多」抽屜（收起來不是刪掉：三顆分頁仍在 DOM、按「更多」一定到得了）。
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(1800)
    tabs = m.evaluate("""() => [...document.querySelectorAll('#tabs .tab, #tabs .mtabmore')].filter(e => getComputedStyle(e).display !== 'none').map(e => {
        const r = e.getBoundingClientRect();
        return { v: e.dataset.view || e.id, left: Math.round(r.left), right: Math.round(r.right), top: Math.round(r.top),
                 w: Math.round(r.width), h: Math.round(r.height) }; })""")
    ok("[390px] 底部一列五顆：總覽／資金流向／產業／熱力圖／更多",
       [t["v"] for t in tabs] == ["overview", "flow", "industry", "heatmap", "mTabMore"], [t["v"] for t in tabs])
    ok("[390px] 五顆全部在畫面裡、而且在同一列", all(t["right"] <= 391 for t in tabs) and len({t["top"] for t in tabs}) == 1, tabs)
    ok("[390px] 每顆的觸控高度 ≥ 44px", all(t["h"] >= 44 for t in tabs), sorted({t["h"] for t in tabs}))
    nh = m.evaluate("() => Math.round(document.getElementById('tabs').getBoundingClientRect().height)")
    ok("[390px] 底部導覽高 58px（改版前兩列 102px）", 54 <= nh <= 62, nh)
    ok("[390px] 七個分頁一個都沒少（三顆收進「更多」，DOM 裡還在）",
       m.evaluate("() => document.querySelectorAll('#tabs .tab').length") == 7)
    for v, want in (("season", "#season"), ("delivery", "#delivery"), ("market", "#market")):
        m.tap("#mTabMore"); m.wait_for_timeout(400)
        m.tap(f'#mSheet .mrow[data-m={v}]'); m.wait_for_timeout(1600)
        st = m.evaluate("""() => ({ hash: location.hash,
            on: (document.querySelector('main .view.on') || {}).id,
            more: document.getElementById('mTabMore').classList.contains('on'),
            txt: ((document.querySelector('main .view.on') || document.body).innerText || '').trim().length })""")
        ok(f"[390px] 「更多」→「{v}」畫面真的換過去了，而且「更多」亮起來（知道自己在哪）",
           st["hash"].startswith(want) and st["on"] == "v-" + v and st["txt"] > 60 and st["more"], st)

    # ---------- G3（手機 v3 改寫）：大盤三張合一張可切換（R1）----------
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2600)
    spine = m.evaluate("() => [...document.querySelectorAll('.mspine>button')].map(b => b.innerText.replace(/\\s+/g, ' ').trim())")
    # ⚠ 第③步（今日候選）在 main 2026-09-24 總覽改版時被拿掉了（#ovCandCard 不在頁面上），所以這裡不寫死 4 步
    ok("[390px] 首頁是一條決策動線（從 ① 錢往哪跑 開始、④ 別進的理由 結束）",
       len(spine) >= 3 and spine[0].startswith('①') and spine[-1].startswith('④'), spine)
    m.evaluate("() => document.querySelectorAll('.mspine>button')[1].click()"); m.wait_for_timeout(1600)
    g = m.evaluate("""() => { const g = document.querySelector('.m3-grid'); if (!g) return null;
        const vis = [...g.children].filter(c => getComputedStyle(c).display !== 'none');
        return { h: Math.round(g.getBoundingClientRect().height), kids: g.children.length, vis: vis.length,
                 cur: g.dataset.cur, pos: (document.getElementById('mM3Pos') || {}).dataset }; }""")
    ok("[390px] 大盤三張合成一張：看得到的只有 1 張（三張都還在 DOM，沒有刪）", g and g["kids"] == 3 and g["vis"] == 1, g)
    ok("[390px] 一張的高度（改版前三張直立 1331px）", g and g["h"] < 700, g)

    # ---------- G4：字級下限 12px ----------
    TINY = """() => { const eff = (e) => { const s = parseFloat(getComputedStyle(e).fontSize);
          if (e.ownerSVGElement) { try { const m = e.getScreenCTM(); return m ? s * Math.abs(m.a) : s; } catch (x) { return s; } }
          return s; };
        return [...document.querySelectorAll('main .view.on *')].filter(e => {
          const t = [...e.childNodes].some(n => n.nodeType === 3 && n.textContent.trim().length > 1);
          if (!t) return false;
          const r = e.getBoundingClientRect(); if (!r.width || !r.height) return false;
          const cs = getComputedStyle(e); if (cs.visibility === 'hidden' || cs.display === 'none') return false;
          const s = eff(e); return s > 0 && s < (e.ownerSVGElement ? 8 : 12); })
          .map(e => `${e.tagName}@${eff(e).toFixed(1)}:${e.textContent.trim().slice(0,12)}`); }"""
    for h, name in (("overview", "總覽"), ("flow", "資金流向"), ("industry", "產業地圖"),
                    ("heatmap", "熱力圖"), ("heatmap/theme", "熱力圖（題材段）"),
                    ("season", "週期統計"), ("delivery", "交付清單"),
                    ("market", "市場明細"), (f"stock/{code}", "個股")):
        m.goto(f"{base}#{h}", wait_until="networkidle"); m.wait_for_timeout(2200)
        r = m.evaluate(f"""() => ({{ tiny: ({TINY})(),
            docW: document.documentElement.scrollWidth, winW: innerWidth }})""")
        ok(f"[390px] {name} 沒有小於 12px 的字", not r["tiny"], r["tiny"][:6])
        ok(f"[390px] {name} 沒有橫向捲軸", r["docW"] <= r["winW"] + 1, r)

    # ---------- G6：橫向可捲的容器有提示 ----------
    m.goto(f"{base}#industry", wait_until="networkidle"); m.wait_for_timeout(2400)
    sc = m.evaluate("""() => { const e = document.getElementById('chainSwitch'); if (!e) return null;
        const t = e.nextElementSibling;
        return { cw: e.clientWidth, sw: e.scrollWidth, hsc: e.classList.contains('hsc'),
                 tip: !!(t && t.classList && t.classList.contains('swipetip')) }; }""")
    ok("[390px] 產業鏈分頁列捲得動的時候有淡出與「左右滑」提示（八條鏈只看得到三條）",
       sc and sc["sw"] > sc["cw"] and sc["hsc"] and sc["tip"], sc)

    # ---------- G7（手機 v3 改寫）：剖析圖手機預設展開、只留編號（§9 第 1 條）----------
    m.goto(f"{base}#industry/semiconductor", wait_until="networkidle"); m.wait_for_timeout(3600)
    fold = m.evaluate("""() => { const d = (id) => { const e = document.getElementById(id);
          return e ? getComputedStyle(e).display : 'missing'; };
        return { body: d('dgBody'), foldD: d('dgFold'), anim: d('dgAnim'),
                 cards: [...document.querySelectorAll('#prodDiagram .dgc')].filter(e => e.offsetParent).length,
                 nums: document.querySelectorAll('#prodDiagram .mnum').length }; }""")
    ok("[390px] 剖析圖手機預設展開（字卡拿掉之後圖只剩約 300px，收合的理由不在了）", fold["body"] != "none", fold)
    ok("[390px] 手機不放「收合圖／動畫」這兩顆（設定列只留 平面／3D、整張／放大、?）",
       fold["foldD"] == "none" and fold["anim"] == "none", fold)
    ok("[390px] 可見字卡 0 張、編號 ≥ 1", fold["cards"] == 0 and fold["nums"] >= 1, fold)

    # ---------- G8：個股頁的畫線工具列 ----------
    m.goto(f"{base}#stock/{code}", wait_until="networkidle"); m.wait_for_timeout(3600)
    d0 = m.evaluate("""() => ({ tgl: getComputedStyle(document.getElementById('drawTgl')).display,
        bar: getComputedStyle(document.getElementById('drawBar')).display })""")
    ok("[390px] 畫線工具列預設收起來（改版前 20 顆 20×20 的鈕整排攤在手機上）",
       d0["bar"] == "none" and d0["tgl"] != "none", d0)
    m.click("#drawTgl"); m.wait_for_timeout(600)
    d1 = m.evaluate("""() => { const b = document.getElementById('drawBar');
        const t = b.querySelector('.dtool'); const r = t ? t.getBoundingClientRect() : null;
        return { bar: getComputedStyle(b).display, n: b.children.length,
                 tw: r ? Math.round(r.width) : 0, th: r ? Math.round(r.height) : 0,
                 saved: localStorage.getItem('tw.drawbar') }; }""")
    ok("[390px] 按「✎ 畫線」工具列真的出現了", d1["bar"] != "none" and d1["n"] > 5, d1)
    ok("[390px] 工具鈕在手機是 40×40（原本 28×28）", d1["tw"] >= 40 and d1["th"] >= 40, d1)
    ok("[390px] 開關狀態真的寫進 localStorage 了", d1["saved"] == "1", d1)
    m.click("#drawTgl"); m.wait_for_timeout(500)
    ok("[390px] 再按一次真的收回去",
       m.eval_on_selector("#drawBar", "e => getComputedStyle(e).display") == "none")
    m.evaluate("() => { try { localStorage.removeItem('tw.drawbar'); } catch (e) {} }")
    m.close()


def t_desktop_untouched(pg, base, code):
    """★ Andy 補的那句「**除了桌面不可以遷就手機** 其他你要怎麼優化都可以」。

    手機改版新加的三樣東西 ——「⋯ 更多工具」、「左右滑」提示、「✎ 畫線」開關 ——
    在 1440px 上**一個都不准出現**；而桌機原本就有的東西（四顆頂欄鈕、剖析圖的 3D 設定列、
    常駐的今日事件側欄）**一個都不准少**。
    這一段是「桌機零差異」那份像素比對的程式化版本：像素比對證明「這一次沒差」，
    這一段擋的是「以後有人把手機的規則寫到桌機去」。"""
    for w in (1440, 1280):
        pg.set_viewport_size({"width": w, "height": 950})
        for h in ("overview", "industry/semiconductor", f"stock/{code}"):
            pg.goto(f"{base}#{h}", wait_until="networkidle"); pg.wait_for_timeout(2600)
            r = pg.evaluate("""() => { const d = (sel) => { const e = document.querySelector(sel);
                  return e ? getComputedStyle(e).display : 'missing'; };
                return { more: d('#moreBtn'), pop: d('#morePop'), draw: d('#drawTgl'),
                         tips: document.querySelectorAll('.swipetip').length,
                         hsc: document.querySelectorAll('.hsc').length,
                         theme: d('#themeBtn'), ev: d('#evToggle'), live: d('.livebox'),
                         tabs: document.querySelectorAll('#tabs .tab').length,
                         docW: document.documentElement.scrollWidth, winW: innerWidth }; }""")
            ok(f"[{w}px {h}] 手機才有的「⋯ 更多工具」在桌機不出現",
               r["more"] == "none" and r["pop"] == "none", r)
            ok(f"[{w}px {h}] 手機才有的「✎ 畫線」開關在桌機不出現",
               r["draw"] in ("none", "missing"), r)
            ok(f"[{w}px {h}] 桌機不掛「左右滑」提示與淡出（桌機有捲軸與滾輪，不需要）",
               r["tips"] == 0 and r["hsc"] == 0, r)
            # ★ 2026-09-24：「更新」「⚙」兩顆是 Andy 親口要拿掉的（不是手機規則外洩），
            #   剩下的主題、事件、即時時間三樣一個都不准少；分頁因為題材併進熱力圖，八個變七個。
            # ★ 2026-09-24 晚（Andy：「時間刪除」「明暗切換移動到右邊」）：即時時間那顆收起、明暗鈕在最右邊
            ok(f"[{w}px {h}] 桌機頂欄的主題、事件還在；即時時間那顆已收起",
               r["theme"] != "none" and r["ev"] != "none" and r["live"] == "none", r)
            rt = pg.evaluate("""() => { const t = document.getElementById('themeBtn').getBoundingClientRect();
                const vis = [...document.querySelectorAll('.topbar > *')].filter(e => getComputedStyle(e).display !== 'none' && e.getBoundingClientRect().width > 0);
                return { themeR: Math.round(t.right), maxR: Math.round(Math.max(...vis.map(e => e.getBoundingClientRect().right))) }; }""")
            ok(f"[{w}px {h}] 明暗切換在頂欄最右邊", rt["themeR"] >= rt["maxR"] - 1, rt)
            ok(f"[{w}px {h}] 分頁是七個（題材併進熱力圖）、沒有橫向捲軸",
               r["tabs"] == 7 and r["docW"] <= r["winW"] + 1, r)
    # 桌機的剖析圖：預設展開，3D 設定列一顆都不能少
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#industry/semiconductor", wait_until="networkidle"); pg.wait_for_timeout(3200)
    t = pg.evaluate("""() => { const ids = ['dg3d','dgDrag','dgReset','dgAnim','dgFold'];
        const out = {}; ids.forEach(i => { const e = document.getElementById(i);
          out[i] = e ? getComputedStyle(e).display : 'missing'; });
        out.fold = (document.getElementById('dgFold') || {}).textContent;
        out.body = document.getElementById('dgBody') ? getComputedStyle(document.getElementById('dgBody')).display : null;
        return out; }""")
    ok("[1440px] 桌機的剖析圖還是預設展開（手機那條收合規則沒有外洩到桌機）",
       t["body"] != "none" and "收合" in (t["fold"] or ""), t)
    ok("[1440px] 桌機的 3D 設定列五顆全在",
       all(t[i] != "none" for i in ("dg3d", "dgDrag", "dgReset", "dgAnim", "dgFold")), t)
    # ★ 手機 v3：像素比對只涵蓋「初始畫面」（2026-09-24 踩過），所以「點了才出現」的東西另外驗
    d = pg.evaluate("""() => ({ more: !!document.getElementById('mTabMore'), sbtn: !!document.getElementById('mSearchBtn'),
        keep: document.querySelectorAll('.m3keep, .mnumlayer, .mdgbar, #mM3Sw').length,
        cards: [...document.querySelectorAll('#prodDiagram .dgc')].filter(e => e.offsetParent).length,
        m3on: document.body.classList.contains('m3on') })""")
    ok("[1440px] 手機 v3 的節點（更多、搜尋鈕、雷達、編號層、大盤切換）在桌機一個都沒有插",
       not d["more"] and not d["sbtn"] and d["keep"] == 0 and not d["m3on"], d)
    ok("[1440px] 剖析圖的字卡仍在兩側（手機只留編號那條沒有外洩）", d["cards"] > 0, d)
    b0 = pg.query_selector('#dgTools .howbtn')
    if b0:
        b0.click(); pg.wait_for_timeout(400)
        hp = pg.evaluate("""() => { const p = document.getElementById('how-dg'); const hp = document.getElementById('howPop');
            return { inplace: !!p && !p.hidden && !(hp && hp.contains(p)), bubble: !!(hp && hp.classList.contains('mbubble')) }; }""")
        ok("[1440px] 剖析圖「怎麼看 ?」在桌機仍是就地展開（手機才是氣泡）", hp["inplace"] and not hp["bubble"], hp)
        b0.click(); pg.wait_for_timeout(200)
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    pb = pg.query_selector('#ovRotHead .howbtn')
    if pb:
        pb.click(); pg.wait_for_timeout(400)
        hp = pg.evaluate("() => { const p = document.getElementById('howPop'); return p && !p.hidden ? { bubble: p.classList.contains('mbubble'), tf: getComputedStyle(p).transform } : null; }")
        ok("[1440px] 標題旁「?」在桌機仍是置中的跳出說明（不是手機的氣泡）", hp and not hp["bubble"] and hp["tf"] != "none", hp)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(200)
    g3 = pg.evaluate("() => { const g = document.getElementById('m3Grid'); return g ? [...g.children].filter(c => getComputedStyle(c).display !== 'none').length : -1; }")
    ok("[1440px] 大盤三張在桌機仍是三張並排（合一張只給手機）", g3 == 3, g3)
    pg.set_viewport_size({"width": 1500, "height": 1000})



# ===================================================================== 手機一屏
def t_mobile_oneview(b, base, code):
    """★ 2026-09-24 手機第二版：**圖與它的關鍵數字必須在同一屏**（量出來，不是看起來像）。

    Andy 的原話：「不要發生我看圖 結果用資訊我要一直滑下去來回看，會很困擾」。
    改版前量到的最糟一筆：個股頁 K 線圖在 1024～1683px，而現價與技術分在 127～596px ——
    **相隔 1087px**。要看數字就得滑上去，看完再滑回來。

    這一段的驗法：把主圖捲到畫面頂端，然後量
      ① 主圖整張進得了可視範圍（844 − 頂欄 72 − 底部兩列分頁 102 ＝ 670～742px）
      ② 它的關鍵數字**同時**在可視範圍內（`bottom` ≤ 可視高、`bottom` > 0）
    每一個主要路由各一條。⚠ 驗的是量到的座標，不是「元素存在」。
    """
    m = b.new_page(**MOBILE_VP)
    m.on("pageerror", lambda e: fails.append(f"手機一屏 pageerror: {e}"))
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(base, wait_until="domcontentloaded")
    m.evaluate("() => { try { localStorage.clear(); localStorage.setItem('tw.live.on', '0'); } catch (e) {} }")

    RECT = """(a) => { const c = document.querySelector(a[0]), k = document.querySelector(a[1]);
        if (!c) return { err: '找不到主圖 ' + a[0] };
        const r = c.getBoundingClientRect(), kr = k ? k.getBoundingClientRect() : null;
        return { vh: innerHeight, c: { t: Math.round(r.top), b: Math.round(r.bottom), h: Math.round(r.height) },
                 k: kr ? { t: Math.round(kr.top), b: Math.round(kr.bottom), pos: getComputedStyle(k).position } : null,
                 docW: document.documentElement.scrollWidth, winW: innerWidth }; }"""
    # （路由, 名字, 主圖, 關鍵數字, 要不要先點某一步）
    CASES = [
        # ★ 手機 v3：足跡輪盤換成新雷達（#mRadarOv／#mRadarFlow），關鍵數字＝焦點條（.mfocus）
        ("overview", "總覽 足跡輪盤（第①步）", "#mRadarOv", "#rotClockMiniWrap .mfocus", None),
        ("flow", "資金流向 足跡輪盤", "#mRadarFlow", "#flowRotCard .mfocus", None),
        ("industry", "產業地圖 族群漲跌長條", "#gpBar", "#gpNote", None),
        (f"stock/{code}", "個股 K 線", "#chartWrap", "#skPx", None),
        # ★ 2026-09-24：題材併進熱力圖分頁；用舊網址開，順便驗手機導過去之後直接翻到「題材熱力」那一段
        # ★ 2026-09-24 說明精簡：#themeNote（題材口徑）搬進「怎麼看 ?」，關鍵數字改看熱度圖例（沒有它讀不出顏色是哪一級）
        ("themes", "熱力圖 題材資金熱力（舊網址 #themes）", "#themeMap", "#themeMapLegend", None),
        # ★ 2026-09-24 週期統計改版：圖高＝列數 × 列高，捲動交給外框 `#seasonHeatBox`，
        #   所以「主圖」量外框；「關鍵數字」是 7 格圖例（沒有它讀不出顏色是哪一級）。
        ("season", "週期統計 月份熱力", "#seasonHeatBox", "#seasonHeatBoxLegend", None),
    ]
    for route, name, cs, ks, step in CASES:
        m.goto(f"{base}#{route}", wait_until="networkidle"); m.wait_for_timeout(3000)
        if step is not None:
            m.evaluate("(i) => { const b = document.querySelectorAll('.mspine>button')[i]; if (b) b.click(); }", step)
            m.wait_for_timeout(1200)
        r0 = m.evaluate(RECT, [cs, ks])
        if r0.get("err"): ok(f"[390px 一屏] {name}", False, r0); continue
        # 捲到主圖的頂端（留 132px 給頂欄與分段列）
        m.evaluate("(sel) => { const e = document.querySelector(sel); if (e) window.scrollTo({ top: e.getBoundingClientRect().top + scrollY - 132 }); }", cs)
        m.wait_for_timeout(500)
        r = m.evaluate(RECT, [cs, ks])
        vis = r["vh"] - 58                        # 扣掉底部導覽（手機 v3：一列 58px；改版前兩列 102px）
        ok(f"[390px 一屏] {name}：主圖整張在可視範圍內（{vis}px）",
           r["c"]["t"] >= -4 and r["c"]["b"] <= vis + 4, r)
        ok(f"[390px 一屏] {name}：關鍵數字**同時**看得到（改版前個股頁相隔 1087px）",
           bool(r["k"]) and 0 < r["k"]["b"] <= vis, r)
        ok(f"[390px 一屏] {name}：沒有橫向捲軸", r["docW"] <= r["winW"] + 1, r)

    # 個股頁的價格列是「釘住」的：捲到圖的最底下，它還要在畫面上
    m.goto(f"{base}#stock/{code}", wait_until="networkidle"); m.wait_for_timeout(3200)
    m.evaluate("() => window.scrollTo({ top: document.documentElement.scrollHeight })")
    m.wait_for_timeout(500)
    st = m.evaluate("""() => { const e = document.getElementById('skPx');
        if (!e) return null; const r = e.getBoundingClientRect();
        return { t: Math.round(r.top), b: Math.round(r.bottom), pos: getComputedStyle(e).position,
                 parent: e.parentElement.id, txt: e.innerText.replace(/\s+/g, ' ').slice(0, 40),
                 vh: innerHeight }; }""")
    ok("[390px 一屏] 個股：現價那一列真的釘住了（捲到整頁最底下還看得到）",
       st and st["pos"] == "sticky" and 0 <= st["t"] <= 140, st)
    ok("[390px 一屏] 個股：它被搬成 K 線卡的直接子項（sticky 只在父元素的盒子裡有效）",
       st and st["parent"] == "skChartCard", st)
    ok("[390px 一屏] 個股：價格那一列寫的是真的數字，不是佔位符",
       st and any(ch.isdigit() for ch in st["txt"]), st)

    # 主軸動線：按「下一步」真的換一步，而且畫面真的因此換了內容
    # ⚠ 第③步（今日候選）main 在 2026-09-24 總覽改版拿掉了（#ovCandCard 不在頁面上），
    #   所以這裡照「實際有幾步」走一圈，不寫死 4 步；每一步都驗「下一步」真的換了、最後一步回到第①步。
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2800)
    def _state():
        return m.evaluate("""() => ({
            on: [...document.querySelectorAll('.mspine>button')].findIndex(b => b.classList.contains('on')),
            n: document.querySelectorAll('.mspine>button').length,
            rot: !!document.querySelector('#rotClockMiniWrap:not(.mp-off)'),
            m3: !!document.querySelector('#m3:not(.mp-off)'),
            ev: !!document.querySelector('#ovEvents:not(.mp-off)'),
            next: (document.querySelector('.mnext') || {}).textContent || '' })""")
    s0 = _state()
    ok("[390px 動線] 一進首頁停在第①步，主圖是足跡輪盤", s0["on"] == 0 and s0["rot"] and not s0["m3"], s0)
    ok("[390px 動線] 最下面有「下一步」帶去第②步", "下一步" in s0["next"] and "貴不貴" in s0["next"], s0)
    sp = m.evaluate("""() => [...document.querySelectorAll('.mspine>button')].map(b => { const r = b.getBoundingClientRect();
        return { r: Math.round(r.right), t: Math.round(r.top), h: Math.round(r.height) }; })""")
    ok("[390px 動線] 步驟列一列排完、每一步都看得到（改版前一次只露一格半）",
       all(x["r"] <= 390 for x in sp) and len({x["t"] for x in sp}) == 1 and all(x["h"] >= 44 for x in sp), sp)
    m.click(".mnext"); m.wait_for_timeout(1300)
    s1 = _state()
    changed("[390px 動線] 按「下一步」畫面真的換到第②步（大盤出現、輪盤收起來）",
            (s0["on"], s0["m3"], s0["rot"]), (s1["on"], s1["m3"], s1["rot"]), str(s1))
    for _ in range(max(0, s0["n"] - 2)):
        m.click(".mnext"); m.wait_for_timeout(1300)
    s3 = _state()
    ok("[390px 動線] 最後一步是今日事件（有沒有理由不進場）", s3["on"] == s0["n"] - 1 and s3["ev"], s3)
    ev = m.evaluate("""() => { const b = document.getElementById('ovEvents'); if (!b) return null;
        return { n: b.querySelectorAll('.ovev .ev').length,
                 all: (b.querySelector('#ovEvAll') || {}).textContent || '',
                 side: (document.getElementById('evCount') || {}).textContent || '' }; }""")
    ok("[390px 動線] 最後一步真的列出事件，而且筆數跟抽屜是同一份資料",
       ev and ev["n"] > 0 and ev["side"] and ev["side"] in ev["all"], ev)
    ok("[390px 動線] 走到最後一步時「下一步」變成回到第①步", "回到" in s3["next"], s3)
    m.click(".mnext"); m.wait_for_timeout(1300)
    ok("[390px 動線] 按下去真的回到第①步", _state()["on"] == 0)

    # 第①步的關鍵數字：四角徽章＝四個象限的族群數（手機 v3 取代原本那一列 #ovRotKpi）
    kpi = m.evaluate("""() => { const e = document.getElementById('mRadarOv'); if (!e) return null;
        return { n: e.querySelectorAll('.mqb').length, txt: e.innerText.replace(/\\s+/g, ' ').trim(),
                 nums: [...e.querySelectorAll('.mqb b')].map(x => +x.textContent) }; }""")
    ok("[390px 動線] 第①步的輪盤四角就是四個象限的族群數（不必滑到別的地方找）",
       kpi and kpi["n"] == 4 and sum(kpi["nums"]) > 0
       and all(w in kpi["txt"] for w in ("改善", "領先", "轉弱", "落後")), kpi)

    # 長清單限筆：今日候選（第③步）main 已經拿掉 —— 還在頁面上才驗，不在就記一筆「略過」而不是假紅
    if m.evaluate("() => !!document.getElementById('candCards')"):
        m.evaluate("() => { const b = document.querySelectorAll('.mspine>button')[2]; if (b) b.click(); }")
        m.wait_for_timeout(1300)
        C = """() => { const c = document.getElementById('candCards'); if (!c) return null;
            const kids = [...c.children].filter(x => !x.classList.contains('mmore'));
            return { total: kids.length, shown: kids.filter(x => getComputedStyle(x).display !== 'none').length,
                     btn: (c.querySelector('.mmore') || {}).textContent || '' }; }"""
        c0 = m.evaluate(C)
        ok("[390px 限筆] 今日候選預設只給前 6 張", c0 and c0["shown"] == 6 and c0["total"] > 6 and "看全部" in c0["btn"], c0)

    # 左右滑的位置指示（Andy 點名）—— 手機 v3：大盤合一張，圖下「● ○ ○ 1 / 3」
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2600)
    m.evaluate("() => { const b = document.querySelectorAll('.mspine>button')[1]; if (b) b.click(); }")
    m.wait_for_timeout(1400)
    P = """() => { const p = document.getElementById('mM3Pos'), g = document.querySelector('.m3-grid');
        return p ? { pos: p.dataset.pos, of: p.dataset.of, cur: g && g.dataset.cur, txt: p.innerText } : null; }"""
    p0 = m.evaluate(P)
    ok("[390px] 大盤有「第幾張／共幾張」（他點名的：不然不知道還有沒有）",
       p0 and p0["of"] == "3" and p0["pos"] in ("1", "2", "3") and "/ 3" in p0["txt"], p0)
    m.tap('#mM3Sw button[data-id="OTC"]'); m.wait_for_timeout(600)
    p1 = m.evaluate(P)
    ok("[390px] 點「櫃買」指示跟著變成 2 / 3、卡片換成櫃買", p1 and p1["pos"] == "2" and p1["cur"] == "OTC", p1)

    # 整頁高度：不准回到改版前那種「一頁滑十屏」
    HEIGHT_MAX = {"overview": 2200, "flow": 2400, "season": 2400, "delivery": 3200,
                  f"stock/{code}": 2200,
                  # ★ 手機 v3：剖析圖手機預設展開（規格 §9 第 1 條），圖本身約 300px；上限 1800 → 2700。
                  #   規格另有「剖析圖／關聯圖」分段（§3-4），排在下一批，做完之後這個數字要收回 1800 以下。
                  "industry/semiconductor": 2700}
    for route, cap in HEIGHT_MAX.items():
        m.goto(f"{base}#{route}", wait_until="networkidle"); m.wait_for_timeout(2800)
        # ★ 2026-09-24 設計系統 v2 第 6 批：全站頁尾多了一段免責聲明（site/legal.js 的 #siteFoot，手機約 300px）。
        #   這條量的是「內容要滑幾屏」，頁尾是每一頁都有的法律文字、不是內容 —— 扣掉它再比，
        #   否則上限等於在懲罰「有放免責聲明」這件事。扣的是實量（高度＋上外距），不是寫死的數字。
        h = m.evaluate("""() => { const f = document.getElementById('siteFoot');
            const fh = f ? f.offsetHeight + (parseFloat(getComputedStyle(f).marginTop) || 0) : 0;
            return Math.round(document.documentElement.scrollHeight - fh); }""")
        ok(f"[390px] {route} 的整頁高度（不含頁尾免責聲明）{h} ≤ {cap}（改版前總覽 9233、交付清單 11299）", h <= cap, h)

    # ================================================================
    # ★ 2026-09-24（Andy：「另外這個手機版我剛剛看體驗那邊有跑掉」—— 只有這一句、沒有截圖）
    #   底下五條都是**掃出來的具體壞法**，每一條驗的是「那個壞法本身」，
    #   不是「元素存在」。四條是「程式註解說會做、實際被蓋掉或根本沒接上」的那一種 ——
    #   它們共同的形態是：讀程式碼看起來是對的，量畫面才知道沒生效。
    # ================================================================

    # ① 只有一段時不准留一顆孤單的晶片。
    #    壞法：`miaPager` 寫了 `bar.hidden = subs.length < 2`（註解：「一顆孤單的晶片是雜訊」），
    #    但 `.mpager{display:flex}` 的權重 (0,1,0) 蓋過瀏覽器內建的 `[hidden]{display:none}` (0,0,0)，
    #    那一行**完全沒有生效**。實測第③④步各留 58px＋10px margin ＝ 68px。
    #    ⚠ 所以這裡驗的是 **computed display 與實際高度**，不是 `hidden` 屬性 ——
    #      驗屬性的話舊版也會綠，那就是假綠。
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2800)
    PAGER = """() => { const b = document.querySelector('main .view.on > .mpager');
        if (!b) return { none: true };
        const r = b.getBoundingClientRect();
        return { n: b.children.length, attr: b.hidden, disp: getComputedStyle(b).display,
                 h: Math.round(r.height),
                 step: [...document.querySelectorAll('.mspine>button')].findIndex(x => x.classList.contains('on')) }; }"""
    for want_step in (0, 1, 2, 3):
        st = m.evaluate(PAGER)
        if st.get("none"):
            ok(f"[390px 分段] 第{want_step + 1}步找得到分段列的狀態", False, st)
        elif st["n"] < 2:
            ok(f"[390px 分段] 第{st['step'] + 1}步只有 1 段 → 分段列整條收掉（不留孤單的晶片）",
               st["disp"] == "none" and st["h"] == 0, st)
        else:
            ok(f"[390px 分段] 第{st['step'] + 1}步有 {st['n']} 段 → 分段列要看得見",
               st["disp"] != "none" and st["h"] > 30, st)
        if want_step < 3:
            m.click(".mnext"); m.wait_for_timeout(1300)

    # ② 換段之後不准留「高度 0 卻還占著外距」的空殼容器。
    #    壞法：總覽的卡片包在 `.grid.g21`／`.grid.g12.eqpair`／`.grid.g2` 這幾層排版容器裡，
    #    分段導覽藏的是**卡片**，容器沒被藏 → 每一步留下 2～3 個空殼，各帶 margin-top:16px。
    #    實測第④步：分段列底 202 → 內容頂 266，中間 64px 沒有人知道那是什麼的空白。
    m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2800)
    SHELL = """() => { const v = document.querySelector('main .view.on'); if (!v) return null;
        const bad = [];
        [...v.children].forEach(el => {
          const cs = getComputedStyle(el);
          if (cs.display === 'none') return;
          if (!el.children.length) return;                 // 沒有元素子項的不算排版容器
          const r = el.getBoundingClientRect();
          if (r.height >= 1) return;
          const mt = parseFloat(cs.marginTop) || 0, mb = parseFloat(cs.marginBottom) || 0;
          if (mt + mb <= 0) return;                        // 高度 0 又沒有外距 ＝ 不占版面，無害
          bad.push({ sel: (el.id || el.className || el.tagName).toString().slice(0, 30),
                     mt: mt, mb: mb, kids: el.children.length }); });
        return { bad, waste: bad.reduce((s, x) => s + x.mt + x.mb, 0),
                 step: [...document.querySelectorAll('.mspine>button')].findIndex(x => x.classList.contains('on')) }; }"""
    for _ in range(4):
        sh = m.evaluate(SHELL)
        ok(f"[390px 分段] 第{sh['step'] + 1}步沒有殘留的空殼容器（修之前 2～3 個、白佔 32～48px）",
           sh and not sh["bad"], sh)
        m.click(".mnext"); m.wait_for_timeout(1300)

    # ③ 個股頁釘住的價格列：藏了 442px 的內容，畫面上就得看得出「可以左右滑」。
    #    壞法：`index.html` 的註解寫「本益比／同業分位／營收 YoY 沒有不見，往右滑就在
    #    （`.hsc` 會補淡出）」，但 `#skPx` **根本不在 `SWIPE_SEL` 裡**，淡出一次都沒出現過。
    #    實測 scrollWidth 802 / clientWidth 360，第 4 顆「本益比 28.5」起跑點 359.4 ——
    #    被卡片右緣 376 切一半，而且沒有任何記號說得出右邊還有東西。
    #    ⚠⚠ 修法**不可以**是「把它加進 SWIPE_SEL」：`.hsc` 是 CSS mask，會連背景一起淡掉，
    #      而這一列是釘住的 —— 我親手驗過：捲到工具列滑進它底下（重疊 25.6px）時，
    #      右緣真的看得到「5 秒」那顆晶片透出來（上一批的註解早就寫了，我差點又踩一次）。
    #      所以這裡同時驗兩件事：① 右緣有看得出來的淡出 ② 那是**蓋片**不是 mask。
    m.goto(f"{base}#stock/{code}", wait_until="networkidle"); m.wait_for_timeout(3200)
    SK = """() => { const e = document.getElementById('skPx'); if (!e) return null;
        const cs = getComputedStyle(e), af = getComputedStyle(e, '::after');
        const kids = [...e.children];
        const last = kids.length ? kids[kids.length - 1].getBoundingClientRect() : null;
        return { sw: e.scrollWidth, cw: e.clientWidth, sl: Math.round(e.scrollLeft),
                 mask: (cs.webkitMaskImage || cs.maskImage || 'none') !== 'none',
                 hsc: e.classList.contains('hsc'), end: e.classList.contains('sk-end'),
                 pos: cs.position,
                 cover: (af.backgroundImage || 'none').indexOf('gradient') >= 0,
                 coverW: Math.round(parseFloat(af.width) || 0),
                 tip: !!(e.nextElementSibling && e.nextElementSibling.classList
                         && e.nextElementSibling.classList.contains('swipetip')),
                 lastT: last ? Math.round(last.left) : null, lastR: last ? Math.round(last.right) : null,
                 vw: innerWidth }; }"""
    k0 = m.evaluate(SK)
    ok("[390px 個股] 價格列藏了內容時，右緣真的有淡出（看得出可以左右滑）",
       k0 and k0["sw"] > k0["cw"] + 4 and k0["cover"] and k0["coverW"] >= 20 and not k0["end"], k0)
    ok("[390px 個股] 而且那塊淡出是**不透明的蓋片**、不是 mask"
       "（mask 會讓釘住的列半透明 —— 實測底下工具列的「5 秒」會透出來）",
       k0 and not k0["mask"] and not k0["hsc"], k0)
    ok("[390px 個股] 但**不准**在它後面插一行「左右滑看更多」（釘住的東西越高，留給圖的越少）",
       k0 and not k0["tip"], k0)
    # 真的把它滑到底，最後一顆要完整進得了畫面
    m.evaluate("() => { const e = document.getElementById('skPx'); e.scrollLeft = e.scrollWidth; e.dispatchEvent(new Event('scroll')); }")
    m.wait_for_timeout(600)
    k1 = m.evaluate(SK)
    changed("[390px 個股] 真的滑得動（scrollLeft 變了，不是裝飾）", k0["sl"], k1["sl"], str(k1))
    ok("[390px 個股] 滑到底之後最後一顆（分 K 完整）整顆在畫面內",
       k1 and k1["lastR"] is not None and k1["lastR"] <= k1["vw"] and k1["lastT"] >= 0, k1)
    ok("[390px 個股] 滑到底之後蓋片收掉了（「已經到底了還在淡」是假提示）", k1 and k1["end"], k1)
    ok("[390px 個股] 滑動之後它還是釘住的（蓋片沒有把 sticky 弄掉）", k1 and k1["pos"] == "sticky", k1)

    # ④ K 線圖例：一個數字不准被折成兩半。
    #    實測（修之前）：「MA60 2,400.83」那個 span 的邊界框是 244.3×33.8 —— 橫跨兩行，
    #    也就是「MA60」在第一行尾、「2,400.83」被推到第二行開頭。
    LG = """() => { const l = document.getElementById('legendOv'); if (!l) return null;
        const fs = parseFloat(getComputedStyle(l).fontSize) || 12.5;
        const lh = parseFloat(getComputedStyle(l).lineHeight) || fs * 1.5;
        const split = [...l.querySelectorAll('span')].map(s => {
            const r = s.getBoundingClientRect();
            return { t: (s.textContent || '').trim().slice(0, 18), h: Math.round(r.height), w: Math.round(r.width) }; })
          .filter(x => x.h > lh * 1.6);
        const r = l.getBoundingClientRect(), c = document.getElementById('lwc').getBoundingClientRect();
        return { split, lh: Math.round(lh), h: Math.round(r.height),
                 pct: Math.round(r.height / c.height * 100) }; }"""
    lg = m.evaluate(LG)
    ok("[390px 個股] K 線圖例沒有任何一個數字被折成兩行（修之前「MA60 2,400.83」就是）",
       lg and not lg["split"], lg)
    notes.append(f"[390px 個股] K 線圖例目前佔圖高 {lg['h'] if lg else '?'}px"
                 f"（{lg['pct'] if lg else '?'}%）—— 已知、未收斂，見 docs/mobile_ia.md")

    # ⑤ 週期統計月份熱力圖（2026-09-24 改版）：手機每欄約 17px，最短的「0%」都放不下 ——
    #    所以「顯示數字」那顆直接收起來（不留一顆按了畫面不會變的鈕），而且就算 localStorage
    #    記著「要顯示」也一個字都不准印（不准疊字）；說明列要講得出數字去哪裡拿。
    #    列高與「每一個族群名都印」也在這裡量（Andy：手機可以少一點但名字不准被略過）。
    m.goto(base, wait_until="domcontentloaded")
    m.evaluate("() => { try { localStorage.setItem('tw.season.num', '1'); localStorage.removeItem('tw.season.rows'); } catch (e) {} }")
    m.goto(f"{base}#season", wait_until="networkidle"); m.reload(wait_until="networkidle"); m.wait_for_timeout(3600)
    HM = """() => { const e = document.getElementById('seasonHeat');
        const i = window.echarts && echarts.getInstanceByDom(e); if (!i) return null;
        const o = i.getOption(), ax = i.getModel().getComponent('yAxis', 0).axis;
        const d = o.series[0].data || [], fmt = o.series[0].label.formatter;
        return { colw: +e.dataset.colw, rowh: +e.dataset.rowh, rows: +e.dataset.rows, nlab: +e.dataset.nlab,
                 ylab: ax.getViewLabels().length,
                 printed: d.filter(x => { try { return fmt({ data: x }) !== ''; } catch (err) { return false; } }).length,
                 numBtn: getComputedStyle(document.getElementById('seasonNum')).display,
                 docW: document.documentElement.scrollWidth, winW: innerWidth,
                 note: (document.getElementById('seasonNote') || {}).textContent || '' }; }"""
    hm = m.evaluate(HM)
    ok("[390px 週期統計] 格子放不下數字（每欄約 17px）：一個字都不印、「顯示數字」鈕收起來",
       hm and hm["colw"] < 26 and hm["printed"] == 0 and hm["nlab"] == 0 and hm["numBtn"] == "none", hm)
    ok("[390px 週期統計] 而且畫面上要講得出數字去哪裡了（點一格）",
       hm and "點一格" in hm["note"], {k: hm[k] for k in ("note",)} if hm else hm)
    ok("[390px 週期統計] 每列 ≥ 18px、每一個族群名都印（不隔列省略）、沒有橫向捲軸",
       hm and hm["rowh"] >= 18 and hm["ylab"] == hm["rows"] > 0 and hm["docW"] <= hm["winW"] + 1, hm)
    m.evaluate("() => { try { localStorage.removeItem('tw.season.num'); } catch (e) {} }")

    m.close()


# ===================================================================== 夜盤真實fixture
def t_night_fixture(b, base):
    """台指期夜盤：用**期交所真實回應**餵進去，驗「線真的畫得出來」，而且非台北時區也一樣。

    為什麼要多這一段（2026-09-23，Andy：「夜盤我剛剛看還是沒有數值」）
    ------------------------------------------------------------------
    原本的「新-大盤三張圖」那一段是拿**自己捏的** `/fut` 回應在測，而且**完全沒有 stub
    `/futchart`** —— 於是「兩個端點都活著」這條真實路徑從來沒被走過，
    `pullNight()` 裡「`/fut` 一掛就連問都不問 `/futchart`」的那個 `return` 就一直沒人抓到。
    這一段改用 `docs/fixtures/taifex_night_probe.json`（2026-09-23 20:32 在 GitHub Actions
    上真的打回來的夜盤回應），並且把時鐘平移到台北 20:39（夜盤時段內）。

    驗四件事，每一件都對應一個真的踩過的坑：
      ① 兩支都活 → 線真的畫出來，而且**收盤價等於 fixture 裡那個數字**（不是「有 canvas」）
      ② 使用者不在台北（UTC／New_York）→ 一樣畫得出來（時段判斷必須用台北時間算）
      ③ **`/fut` 掛掉、只剩 `/futchart`** → 線仍然要在（這一條就是這次的根因，
         修之前這裡是整張空白＋「還沒問到今天的近月合約代號」）
      ④ 兩支都掛 → **還是要空白**（Andy 2026-09-23 明講「沒有資訊則空白」，不准退回日盤）
    """
    import json as _json
    fx = _json.loads((ROOT / "docs/fixtures/taifex_night_probe.json").read_text(encoding="utf-8"))
    S = {r["id"]: r for r in fx["results"]}
    FUT_NIGHT = S["taifex_quotelist_night"]["sample"]          # TXFJ6-M 最新 48180、量 7574
    FUT_DAY = S["taifex_quotelist_day"]["sample"]              # 日盤那一份（-F 合約）
    CHART_NIGHT = S["taifex_chartdata_1m_night"]["sample"]     # Ticks 最後一筆收 48180
    # ★ 2026-09-23 修正：這一行原本寫死 48180。fixture 是**會被重新探測覆蓋的**
    #    （同一天就跑了兩輪，20:32 那輪收 48180、20:39 那輪收 48204），
    #    寫死就等於「fixture 一更新，這一段必紅」—— 而且紅的是驗收，不是產品。
    #    改成從 fixture 自己的最後一筆 Tick 讀出來，斷言才跟著資料走。
    #    這跟今天稍早 tests/test_delivery_log.py 把筆數寫死成 34 是同一種毛病。
    #    Ticks 的一筆是**陣列**不是物件：["204000","48196.00","48204.00","48196.00","48204.00","20"]
    #    ＝ [時間, 開, 高, 低, 收, 量]，所以收盤價是 index 4。
    _ticks = ((CHART_NIGHT.get("RtData") or {}).get("Ticks") or [])
    assert _ticks, "fixture 裡沒有 Ticks，這一段的前提不成立"
    LAST = int(float(_ticks[-1][4]))
    LAST_TXT = f"{LAST:,}"                                     # 畫面上是帶千分位的寫法
    FIXED = "2026-09-23T12:39:00Z"                             # ＝台北 2026-09-23 20:39

    PROBE = """() => { const s = window.Market3.state, el = document.getElementById('m3c-FUT');
        let series = null, last = null;
        try { const i = echarts.getInstanceByDom(el);
          if (i) { const d = (i.getOption().series || [])[0];
            if (d) { const v = (d.data || []).filter(x => x != null);
              series = v.length; last = v.length ? v[v.length - 1] : null; } } } catch (e) {}
        return { sess: window.Market3.session, series, last,
          px: (document.querySelector("#m3Grid .m3-card[data-id='FUT'] .m3-px") || {}).textContent || '',
          nums: (document.querySelector("#m3Grid .m3-card[data-id='FUT'] .m3-nums") || {}).innerText || '',
          canvas: el.querySelectorAll('canvas').length,
          txt: (el.innerText || '').replace(/\\s+/g, ' '),
          fb: el.dataset.fallback || '', e1: s.futChartErr, e2: s.futNightErr }; }"""

    def shot(tz, fut, chart, seed=None):
        """開一個乾淨的分頁：指定時區 ＋ 把時鐘釘在台北 20:39 ＋ 用 fixture 回應那兩支端點。"""
        ctx = b.new_context(viewport={"width": 1500, "height": 1000}, timezone_id=tz)
        pg = ctx.new_page()
        boom = []
        pg.on("pageerror", lambda e: boom.append(str(e)[:200]))
        pg.clock.install(time=FIXED)          # ★ 一定要在 goto 之前

        def reply(route, mode, body):
            if mode == "fail":
                route.abort("failed"); return
            if mode == "403":
                route.fulfill(status=403, content_type="application/json",
                              body='{"error":"origin not allowed"}'); return
            route.fulfill(status=200, content_type="application/json; charset=utf-8",
                          body=_json.dumps(body))

        pg.route("**/futchart?*", lambda r: reply(r, chart, CHART_NIGHT))
        pg.route("**/fut?*", lambda r: reply(
            r, "ok" if fut in ("night", "day") else fut,
            FUT_DAY if fut == "day" else FUT_NIGHT))
        # 日盤那三張分時圖不是這一段的重點，給空的就好（省掉連外）
        pg.route("**/chart?*", lambda r: r.fulfill(
            status=200, content_type="application/json", body='{"RtCode":"0","RtData":{"QuoteList":[]}}'))
        pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())

        pg.goto(base + "#overview", wait_until="domcontentloaded")
        pg.evaluate("""(kv) => { try {
            ['tw.m3.mode','tw.m3.tf','tw.m3.big','tw.m3.fut','tw.m3.nightpts','tw.m3.futsym']
              .forEach(k => localStorage.removeItem(k));
            localStorage.setItem('tw.live.proxy','https://fake-worker.test');
            Object.keys(kv || {}).forEach(k => localStorage.setItem(k, kv[k]));
          } catch (e) {} }""", seed or {})
        pg.goto("about:blank")
        pg.goto(base + "#overview", wait_until="networkidle")
        pg.wait_for_timeout(2600)
        out = pg.evaluate(PROBE)
        out["boom"] = boom
        ctx.close()
        return out

    # ---------------- ① 兩支端點都活著（＝Andy 那一晚真實的上游狀態）
    for tz in ("Asia/Taipei", "UTC", "America/New_York"):
        r = shot(tz, "night", "ok")
        tag = f"[{tz}]"
        ok(f"{tag} 時鐘在台北 20:39 → 這張卡自己切到夜盤", r["sess"] == "night", r["sess"])
        ok(f"{tag} 夜盤的線**真的畫出來了**（不是只有容器）", (r["series"] or 0) >= 2,
           {"series": r["series"], "canvas": r["canvas"], "txt": r["txt"][:90]})
        ok(f"{tag} 線的最後一點就是 fixture 裡那個收盤價 {LAST}",
           r["last"] is not None and abs(float(r["last"]) - LAST) < 0.5, r["last"])
        ok(f"{tag} 卡片上的成交價也是 {LAST}", LAST_TXT in r["px"], r["px"])
        ok(f"{tag} 標成夜盤、而且是 fixture 裡那支近月合約 TXFJ6-M",
           "夜盤" in r["nums"] and "TXFJ6-M" in r["nums"], r["nums"][:120])
        ok(f"{tag} 沒有拿日盤冒充夜盤（fallback 那行字不准出現）", r["fb"] == "", r["fb"])
        ok(f"{tag} 頁面沒爆", not r["boom"], r["boom"])

    # ---------------- ② ★ 根因那一條：/fut 掛掉，只剩 /futchart
    #    修之前：`pullNight()` 拿不到近月代號就直接 return，連問都不問 /futchart，
    #    整張卡片空白、還寫著「還沒問到今天的近月合約代號」——
    #    而那一晚 /futchart 明明是 200。近月代號其實算得出來（futSymbol()）。
    r = shot("America/New_York", "fail", "ok")
    ok("★ /fut 掛掉時，/futchart 還是要被打（近月代號自己推算）", (r["series"] or 0) >= 2,
       {"series": r["series"], "e1": r["e1"], "e2": r["e2"], "txt": r["txt"][:110]})
    ok("★ 只靠 /futchart 也要畫得出整晚的線，收盤價一樣是 " + str(LAST),
       r["last"] is not None and abs(float(r["last"]) - LAST) < 0.5, r["last"])
    ok("★ 只靠 /futchart 時，上排數字也要有（不是「—」）", LAST_TXT in r["px"], r["px"])
    ok("推算出來的近月代號就是 TXFJ6-M（2026-09-23 已過第三個星期三 → 滾到 10 月）",
       "TXFJ6-M" in r["nums"], r["nums"][:120])

    # ---------------- ③ /fut 回的是日盤那一份（時段外打 MarketType=1 會這樣）
    #    不准拿它的開高低收去填「夜盤」那排數字，也不准因為合約代號對不上就把序列丟掉。
    r = shot("Asia/Taipei", "day", "ok")
    ok("/fut 回日盤合約時，夜盤序列不准被丟掉", (r["series"] or 0) >= 2,
       {"series": r["series"], "txt": r["txt"][:110]})
    ok(f"/fut 回日盤合約時，上排數字要走夜盤序列自己帶的 Quote（{LAST_TXT}，不是日盤那個數字）",
       LAST_TXT in r["px"], r["px"])

    # ---------------- ④ 兩支都掛 → 還是要空白（Andy 2026-09-23：「若沒有資訊則空白」）
    r = shot("Asia/Taipei", "fail", "fail")
    ok("兩支都掛：一張 canvas 都沒有（不准退回日盤）", r["canvas"] == 0, r["canvas"])
    ok("兩支都掛：畫面講出原因，而且整段文字不出現「日盤」",
       "夜盤資料未取得" in r["txt"] and "日盤" not in r["txt"], r["txt"][:140])
    ok("兩支都掛：上排數字留白", "—" in r["px"], r["px"])
    ok("兩支都掛：徽章寫「夜盤報價未取得」", "夜盤報價未取得" in r["nums"], r["nums"][:120])


# ===================================================================== 夜盤推送
def t_night_push(b, base):
    """台指期夜盤的 SSE 推送（Andy 2026-09-23：「夜盤要即時推送」）。

    為什麼要多這一段
    ----------------
    今晚剛把**現貨**報價從輪詢換成 SSE，但那條 `/stream` 只服務 mis.twse 的現貨；
    台指期夜盤走的是自己的 `/fut` 與 `/futchart`（期交所），還是每 60 秒輪詢一次。
    這一段驗的是新加的 `/futstream`，以及前端接它的那一層。

    ★ 這一段最重要的不是「推送會動」，是「**推送壞掉的時候輪詢會接住**」。
    DECISIONS #255：2026-09-23 一天之內夜盤壞了三次，三個根因完全不同，
    共通點是這條路很脆弱。所以每一條斷線的路徑都要驗到「畫面照樣會更新」。

    六件事：
      ① 真的開了一條 `/futstream`，而且帶對了時段與近月合約代號
      ② 推一筆新報價 → **那張卡的數字真的變了、線的最後一點也真的變了**
      ③ 而且是「只補最後一根」，不是整張重畫（用 `el._m3line` 的物件同一性驗）
      ④ 送 bye（4 分鐘輪替）→ 前端立刻重連，而且重連那一份快照補得回來
      ⑤ ★ 連線錯誤 → **自動退回輪詢，而且馬上補抓一次，畫面照樣更新**
      ⑥ 用**真的 EventSource** 再走一次（證明 URL、事件名、解析都是對的，不是只有假物件會動）
    另外掃一次 worker.js 的原始碼：任何 POST 的請求物件都不准帶 cf 快取選項。
    """
    import copy
    import json as _json
    fx = _json.loads((ROOT / "docs/fixtures/taifex_night_probe.json").read_text(encoding="utf-8"))
    S = {r["id"]: r for r in fx["results"]}
    FUT_NIGHT = S["taifex_quotelist_night"]["sample"]
    CHART_NIGHT = S["taifex_chartdata_1m_night"]["sample"]
    _ticks = ((CHART_NIGHT.get("RtData") or {}).get("Ticks") or [])
    assert _ticks, "fixture 裡沒有 Ticks，這一段的前提不成立"
    BASE_LAST = int(float(_ticks[-1][4]))          # 官方分時最後一根的收盤（48009）
    LAST_T = str(_ticks[-1][0])                    # 最後一根的時間 "001600"
    FIXED = "2026-09-23T12:39:00Z"                 # ＝台北 2026-09-23 20:39（夜盤時段內）

    def quote_with(price, hhmmss):
        """把 fixture 的夜盤報價清單改成「近月成交在 price、時間 hhmmss」的那一份。"""
        j = copy.deepcopy(FUT_NIGHT)
        for q in j["RtData"]["QuoteList"]:
            if q.get("SymbolID") == "TXFJ6-M":
                q["CLastPrice"] = f"{price}.00"
                q["CTime"] = hhmmss
                # 累計量也一起往上加，才像真的成交過（前端會拿它算「該段量」）
                q["CTotalVolume"] = str(int(float(q["CTotalVolume"])) + 40)
        return j

    # 推送進來的那一筆：時間落在**官方分時最後一根的同一分鐘**（001600 → 00:16），
    # 所以它要就地改寫那一根的收盤 —— 那正是「線的最後一點真的變了」要驗的東西。
    PUSH_PRICE = 48123
    PUSH_Q = quote_with(PUSH_PRICE, LAST_T[:4] + "40")      # 00:16:40
    # 退回輪詢之後才換上去的那一筆（用來證明「退路是活的」）
    POLL_PRICE = 48456
    POLL_Q = quote_with(POLL_PRICE, "001700")

    PROBE = """() => { const el = document.getElementById('m3c-FUT');
        const card = document.querySelector("#m3Grid .m3-card[data-id='FUT']");
        let last = null, series = null;
        try { const i = echarts.getInstanceByDom(el);
          if (i) { const d = (i.getOption().series || [])[0];
            if (d) { const v = (d.data || []).filter(x => x != null);
              series = v.length; last = v.length ? v[v.length - 1] : null; } } } catch (e) {}
        const way = card && card.querySelector('.m3-tag[data-way]');
        return { last, series,
          px: (card && card.querySelector('.m3-px') || {}).textContent || '',
          way: way ? way.textContent : '', wayAttr: way ? way.dataset.way : '',
          tag: el && el._m3line ? (el._m3line.__tag || '') : '(no _m3line)',
          kind: el ? el.dataset.kind : '',
          fs: window.Market3.futStream,
          esUrls: (window.__esUrls || []).filter(u => u.indexOf('futstream') >= 0) }; }"""

    # 假的 EventSource：讓這一段可以**精準控制連線的生命週期**（開著、推一筆、輪替、斷線）。
    # 為什麼要假的：route.fulfill 沒辦法送一條「一直開著的」串流，一 fulfill 完連線就結束了，
    # 那就永遠驗不到「連著的時候推一筆進來會怎樣」。Worker 那一側是另外用 Node 跑真的
    # worker.js ＋ 假 fetch 驗的（scratchpad/futstream_check.mjs），兩邊各自驗自己那一半。
    # ⚠ 這會一併換掉 live.js 用的那個 EventSource —— 所以下面一律**用網址挑**要操作哪一條。
    FAKE_ES = """
      (() => {
        const all = [];
        window.__esUrls = [];
        class FakeES {
          constructor(url) {
            this.url = String(url); this.readyState = 1; this._h = {}; this.onerror = null;
            all.push(this); window.__esUrls.push(this.url);
          }
          addEventListener(t, f) { (this._h[t] = this._h[t] || []).push(f); }
          removeEventListener() {}
          close() { this.readyState = 2; }
        }
        window.EventSource = FakeES;
        // 找「網址含 match 而且還開著」的最後一條，對它送一個事件
        window.__esFire = (match, type, data) => {
          const es = all.filter(e => e.url.indexOf(match) >= 0 && e.readyState !== 2).pop();
          if (!es) return 'no-open-es';
          if (type === 'error') { if (es.onerror) es.onerror({}); return 'ok'; }
          (es._h[type] || []).forEach(f => f({ data: typeof data === 'string' ? data : JSON.stringify(data) }));
          return 'ok';
        };
        window.__esCount = (match) => all.filter(e => e.url.indexOf(match) >= 0).length;
      })();
    """

    def open_page(fake_es, stream_bodies=None, fut_fail=False):
        """開一個乾淨的分頁：時鐘釘在夜盤、fixture 餵那兩支端點、可選真假 EventSource。"""
        ctx = b.new_context(viewport={"width": 1500, "height": 1000}, timezone_id="Asia/Taipei")
        pg = ctx.new_page()
        # ★ 2026-09-24：同上，夜盤推送也預設關閉，驗之前先打開開關（DECISIONS #256）。
        pg.add_init_script("try{localStorage.setItem('tw.sse','1')}catch(e){}")
        boom: list[str] = []
        pg.on("pageerror", lambda e: boom.append(str(e)[:200]))
        pg.clock.install(time=FIXED)
        if fake_es:
            pg.add_init_script(FAKE_ES)
        cur = {"fut": FUT_NIGHT}
        hits = {"fut": 0, "chart": 0, "stream": 0}

        def on_fut(route):
            hits["fut"] += 1
            if fut_fail:
                route.abort("failed")
                return
            route.fulfill(status=200, content_type="application/json; charset=utf-8",
                          body=_json.dumps(cur["fut"]))

        def on_chart(route):
            hits["chart"] += 1
            route.fulfill(status=200, content_type="application/json; charset=utf-8",
                          body=_json.dumps(CHART_NIGHT))

        def on_stream(route):
            hits["stream"] += 1
            n = hits["stream"]
            bodies = stream_bodies or []
            if n <= len(bodies) and bodies[n - 1] is not None:
                route.fulfill(status=200, content_type="text/event-stream; charset=utf-8",
                              body=bodies[n - 1])
            else:
                route.abort("failed")

        pg.route("**/futstream?*", on_stream)
        pg.route("**/futchart?*", on_chart)
        pg.route("**/fut?*", on_fut)
        pg.route("**/chart?*", lambda r: r.fulfill(
            status=200, content_type="application/json", body='{"RtCode":"0","RtData":{"QuoteList":[]}}'))
        pg.route("**/quote?*", lambda r: r.fulfill(
            status=200, content_type="application/json", body='{"msgArray":[],"rtcode":"0000"}'))
        pg.route("**/stream?*", lambda r: r.abort("failed"))
        pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())

        pg.goto(base + "#overview", wait_until="domcontentloaded")
        pg.evaluate("""() => { try {
            ['tw.m3.mode','tw.m3.tf','tw.m3.big','tw.m3.fut','tw.m3.nightpts','tw.m3.futsym']
              .forEach(k => localStorage.removeItem(k));
            localStorage.setItem('tw.live.proxy','https://fake-worker.test');
          } catch (e) {} }""")
        pg.goto("about:blank")
        pg.goto(base + "#overview", wait_until="networkidle")
        pg.wait_for_timeout(2600)
        return ctx, pg, cur, hits, boom

    # ================================================== A. 假 EventSource：完整走一遍推送的生命週期
    ctx, pg, cur, hits, boom = open_page(fake_es=True)

    r0 = pg.evaluate(PROBE)
    # ---------- ① 真的開了一條 /futstream，而且帶對了參數
    ok("夜盤推送：真的開了一條 /futstream", len(r0["esUrls"]) >= 1, r0["esUrls"])
    url0 = r0["esUrls"][0] if r0["esUrls"] else ""
    ok("夜盤推送：網址帶了 session=night", "session=night" in url0, url0)
    ok("夜盤推送：網址帶了近月合約代號 TXFJ6-M（/fut 掛掉也算得出來）",
       "symbol=TXFJ6-M" in url0, url0)
    ok("夜盤推送：還沒連上之前，狀態列寫的是「輪詢」",
       r0["way"] == "輪詢" and r0["wayAttr"] == "poll", r0)
    ok("夜盤推送：底圖先由輪詢畫出來了（線在，不是空白）", (r0["series"] or 0) >= 2, r0)
    ok(f"夜盤推送：輪詢畫出來的最後一點就是 fixture 的 {BASE_LAST}",
       r0["last"] is not None and abs(float(r0["last"]) - BASE_LAST) < 0.5, r0["last"])

    # ---------- ② 連上了 → 狀態列要改口
    pg.evaluate("() => window.__esFire('futstream','hello',{session:'night'})")
    pg.wait_for_timeout(200)
    r1 = pg.evaluate(PROBE)
    ok("★ 夜盤推送：連上之後狀態列真的變成「推送」",
       r1["way"] == "推送" and r1["wayAttr"] == "sse", r1)
    ok("夜盤推送：內部狀態也是 sse", r1["fs"]["mode"] == "sse", r1["fs"])

    # ---------- ③ 推一筆新報價 → 數字變、線的最後一點也變、而且是「只補最後一根」
    pg.evaluate("() => { const el = document.getElementById('m3c-FUT');"
                " if (el && el._m3line) el._m3line.__tag = 'KEEP'; }")
    fut_before = hits["fut"]
    pg.evaluate("(j) => window.__esFire('futstream','fut',j)", PUSH_Q)
    pg.wait_for_timeout(400)
    r2 = pg.evaluate(PROBE)
    ok(f"★★ 推一筆進來：卡片上的數字真的變成 {PUSH_PRICE}", f"{PUSH_PRICE:,}" in r2["px"],
       {"before": r0["px"], "after": r2["px"]})
    ok(f"★★ 推一筆進來：線的最後一點也真的從 {BASE_LAST} 變成 {PUSH_PRICE}",
       r2["last"] is not None and abs(float(r2["last"]) - PUSH_PRICE) < 0.5,
       {"before": r0["last"], "after": r2["last"]})
    ok("★ 推一筆進來：走的是「只補最後一根」（ECharts 的 option 沒有被整個重建）",
       r2["tag"] == "KEEP", r2["tag"])
    ok("推一筆進來：軸沒有被換掉，點數不變（不是多畫了一條線）",
       r2["series"] == r0["series"], {"before": r0["series"], "after": r2["series"]})
    ok("推一筆進來：沒有順手多打一次 /fut（推送就是為了不要再輪詢）",
       hits["fut"] == fut_before, {"before": fut_before, "after": hits["fut"]})
    ok("推一筆進來：推送計數真的加上去了", r2["fs"]["pushes"] >= 1, r2["fs"])

    # ---------- ④ bye（4 分鐘輪替）→ 立刻重連
    n_before = pg.evaluate("() => window.__esCount('futstream')")
    pg.evaluate("() => window.__esFire('futstream','bye',{reason:'rotate'})")
    pg.wait_for_timeout(600)
    n_after = pg.evaluate("() => window.__esCount('futstream')")
    ok("★ 夜盤推送：收到 bye（連線輪替）會立刻重連，不是靜靜地停掉",
       n_after == n_before + 1, {"before": n_before, "after": n_after})
    # 重連那一條再推一筆完整快照 → 補得回來
    pg.evaluate("() => window.__esFire('futstream','hello',{session:'night'})")
    pg.evaluate("(j) => window.__esFire('futstream','fut',j)", quote_with(48222, LAST_T[:4] + "50"))
    pg.wait_for_timeout(400)
    r3 = pg.evaluate(PROBE)
    ok("★ 夜盤推送：重連之後那一份完整快照補得回來（數字跟著走）", "48,222" in r3["px"], r3["px"])
    ok("夜盤推送：重連之後狀態列回到「推送」", r3["way"] == "推送", r3)

    # ---------- ⑤ ★★ 連線錯誤 → 自動退回輪詢，而且馬上補抓一次
    cur["fut"] = POLL_Q                       # 換一份新的，證明退回去的那條路真的有在抓
    fut_before = hits["fut"]
    pg.evaluate("() => window.__esFire('futstream','error')")
    pg.wait_for_timeout(1200)
    r4 = pg.evaluate(PROBE)
    ok("★★ 斷線之後真的退回輪詢（狀態列改口）",
       r4["way"] == "輪詢" and r4["wayAttr"] == "poll" and r4["fs"]["mode"] == "poll", r4)
    ok("★★ 斷線之後**馬上**補抓一次，不等下一個 60 秒",
       hits["fut"] > fut_before, {"before": fut_before, "after": hits["fut"]})
    ok(f"★★ 退回輪詢之後畫面照樣會更新（數字變成輪詢抓到的 {POLL_PRICE}）",
       f"{POLL_PRICE:,}" in r4["px"], {"before": r3["px"], "after": r4["px"]})
    ok("斷線之後有記下原因（除錯時才知道是哪一種壞法）", bool(r4["fs"]["why"]), r4["fs"])
    ok("斷線之後圖還在（不准因為推送壞掉就把線清掉）", (r4["series"] or 0) >= 2, r4)
    ok("整段沒有頁面錯誤", not boom, boom[:3])
    ctx.close()

    # ================================================== B. 真的 EventSource：URL／事件名／解析都要對
    # 用 route.fulfill 送一段**完整的 SSE 文字**（送完連線就結束，所以只驗得到「第一份快照」）。
    # 它補的正是 A 段補不到的那一半：A 段用的是假物件，這裡用的是瀏覽器內建的 EventSource。
    #
    # ★ 這一段刻意讓 `/fut`（輪詢那條路）整支掛掉。
    #   理由：不這樣做的話，串流結束 → 退回輪詢 → 馬上補抓一次，
    #   輪詢抓到的那份會立刻把推送的值蓋掉，於是「48,321 出現在畫面上」就分不出
    #   是推送的功勞還是輪詢的功勞 —— 那條斷言等於沒驗到東西。
    #   現在只有推送這條路能生出 48,321，斷言才是真的。
    body1 = ("retry: 3000\n\n"
             "event: hello\ndata: " + _json.dumps({"session": "night"}) + "\n\n"
             "event: fut\ndata: " + _json.dumps(quote_with(48321, LAST_T[:4] + "45")) + "\n\n")
    ctx, pg, cur, hits, boom = open_page(fake_es=False, stream_bodies=[body1], fut_fail=True)
    pg.wait_for_timeout(1500)
    r5 = pg.evaluate(PROBE.replace("(window.__esUrls || [])", "[]"))
    ok("★ 真的 EventSource：/futstream 真的被請求了", hits["stream"] >= 1, hits)
    ok("★ 真的 EventSource：`event: fut` 真的被解析了，數字變成 48,321（只有推送給得出這個數字）",
       "48,321" in r5["px"], {"px": r5["px"], "fs": r5["fs"]})
    ok("真的 EventSource：推送的那一筆有被算進去", r5["fs"]["pushes"] >= 1, r5["fs"])
    ok("真的 EventSource：`/fut` 全掛，但 `/futchart` 的線還在（失敗要獨立）",
       (r5["series"] or 0) >= 2, r5)
    ok("真的 EventSource：串流結束之後自己退回輪詢（沒有卡在 sse）",
       r5["fs"]["mode"] == "poll" and r5["fs"]["everOk"], r5["fs"])
    ok("真的 EventSource：整段沒有頁面錯誤", not boom, boom[:3])
    ctx.close()

    # ================================================== C. ★ 永久守住：POST 的請求不准帶 cf 快取選項
    # DECISIONS #255 ③：`cf: { cacheTtl, cacheEverything }` **只對 GET 有效**，
    # 帶在 POST 的子請求上會讓它出錯、Cloudflare 對外回 520 ——
    # 那就是 2026-09-23 那天 Andy 三次看到「夜盤沒有數值」真正的斷點。
    # 這條斷言是留給未來的人的：誰想「順手加個快取」，這裡就會紅。
    src = _code_only((ROOT / "workers/quote-proxy/worker.js").read_text(encoding="utf-8"))
    ok("worker.js 抹掉註解與字串之後還是有程式碼（不是被吃光才掃不到問題）",
       "cacheTtl" in src and "futMemoFetch" in src and len(src) > 6000, len(src))
    posts = [m.start() for m in re.finditer(r"method:\s*''", src)]
    ok("worker.js 裡真的有 POST 的上游請求（這條斷言不是空轉）", len(posts) >= 2, len(posts))
    bad = [i for i in posts if re.search(r"\bcf\s*:", _enclosing_object(src, i))]
    ok("★★ worker.js：每一個帶 method 的請求物件裡都沒有 cf 快取選項（POST 帶了會回 520）",
       not bad, [src[max(0, i - 90):i + 90] for i in bad])
    cfs = [m.start() for m in re.finditer(r"\bcf\s*:\s*\{", src)]
    bad2 = [i for i in cfs if re.search(r"method:\s*''", _enclosing_object(src, i))]
    ok("★★ worker.js：反過來掃一次，每一個帶 cf 的請求物件都沒有 method（＝都是 GET）",
       not bad2, [src[max(0, i - 120):i + 120] for i in bad2])
    ok("worker.js：cf 快取選項只剩兩處（relay() 與 misText()，兩支都是 GET）",
       len(cfs) == 2, len(cfs))
    # ⚠ 路徑與 features 是**字串**，而 src 已經把字串內容抹掉了，所以這一條要看原檔
    raw = _raw_worker()
    ok("worker.js：/futstream 已經掛進路由與 features 清單",
       "'/futstream'" in raw and "'futstream'" in raw, None)
    ok("worker.js：現貨那條 /stream 的節奏常數一個字都沒動（不准影響現貨推送）",
       "const POLL_TRADE_MS = 5000;" in raw and "const STREAM_MAX_MS = 4 * 60 * 1000;" in raw, None)


def _raw_worker() -> str:
    return (ROOT / "workers/quote-proxy/worker.js").read_text(encoding="utf-8")


def _code_only(text: str) -> str:
    """把 JS 的註解與字串內容抹掉，只留程式碼骨架。

    ⚠ 不可以用 `/\\*...\\*/` 這種偷懶的正規表達式：worker.js 裡有
    `'Accept': 'application/json, text/plain, */*'`（媒體型別的萬用字元），
    那個 `/*` 會被當成註解開頭，一路吃掉後面 1.2KB 的**真程式碼** ——
    於是「掃不到任何 cf」看起來像通過，其實是假綠。第一版就是這樣紅的。
    所以老老實實走一遍字元，自己記住現在在字串裡還是註解裡。
    """
    out: list[str] = []
    i, n = 0, len(text)
    while i < n:
        c, d = text[i], (text[i + 1] if i + 1 < n else "")
        if c == "/" and d == "*":
            e = text.find("*/", i + 2)
            i = n if e < 0 else e + 2
            out.append(" ")
            continue
        if c == "/" and d == "/":
            e = text.find("\n", i)
            i = n if e < 0 else e
            out.append(" ")
            continue
        if c in "\"'`":
            q = c
            i += 1
            while i < n and text[i] != q:
                if text[i] == "\\":
                    i += 1
                i += 1
            i += 1
            out.append(q + q)          # 字串換成空字串（內容不重要，形狀要留著）
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _enclosing_object(text: str, at: int) -> str:
    """從 at 往左找到包住它的那個 `{`（括號要配對），再往右找到對應的 `}`。"""
    depth, i = 0, at
    while i >= 0:
        c = text[i]
        if c == "}":
            depth += 1
        elif c == "{":
            if depth == 0:
                break
            depth -= 1
        i -= 1
    if i < 0:
        return ""
    j, d2 = i, 0
    while j < len(text):
        c = text[j]
        if c == "{":
            d2 += 1
        elif c == "}":
            d2 -= 1
            if d2 == 0:
                j += 1
                break
        j += 1
    return text[i:j]


# ===================================================================== UI精修0923
# ★ 2026-09-23 桌面版介面精修第一階段（規格：docs/ui_polish_spec.md §9 第 1～9 項）。
#   Andy 的原話：「整體介面頁面UI 圖表 表格等等，優化的更好更平易近人
#   包含滑動移動回饋等等效果都可以做出來讓使用者感受更好」。
#   這一段的每一條都驗「畫面真的因此改變了」，不是驗「規則寫在 CSS 裡」——
#   量 transition-duration、量 scrollLeft 真的動了、量 outline-width、量右緣對齊的 px 差。
#   ⚠ 兩個已知的例外寫在下面 CONTRAST_SKIP，每一個都註明為什麼不是這一批造成的。
UIP_ROUTES = ("overview", "flow", "industry", "season", "delivery")

# 對比掃描的量測程式。背景取「往上找到的第一個不透明底色」（WCAG 2.x 的算法）。
UIP_CONTRAST_JS = r"""
() => {
  /* ⚠ 2026-09-23 踩過的坑：`color-mix()` 算完之後 getComputedStyle 回的是
     `color(srgb 0.86 0.91 0.93)` —— 三個數是 **0～1**，不是 0～255。
     第一版沒分辨，把 0.86 當成 0.86/255 ＝ 近黑，於是量出一堆根本不存在的低對比
     （最誇張的一個是 `.dlv-q` 報 1.19，實際上是 15.9）。兩種寫法都要接。 */
  const L = (h) => { let m = h.match(/[\d.]+/g).map(Number);
    if (/^color\(/.test(h)) m = m.slice(0, 3).map((x) => x * 255);
    const f = (x) => { x /= 255; return x <= .04045 ? x / 12.92 : Math.pow((x + .055) / 1.055, 2.4); };
    return .2126 * f(m[0]) + .7152 * f(m[1]) + .0722 * f(m[2]); };
  const bgOf = (e) => { for (let p = e; p; p = p.parentElement) {
      const cs = getComputedStyle(p);
      /* 漸層底（例如左上角的 TW logo）量不出單一色，直接跳過整個元素 —— 
         回 null 讓外面略過它，不要拿它底下那層透明色去算出一個假的 1.02。*/
      if (cs.backgroundImage && cs.backgroundImage !== 'none' && /gradient/.test(cs.backgroundImage)) return null;
      const b = cs.backgroundColor, m = b.match(/[\d.]+/g);
      // color(srgb r g b) 沒有第四個 alpha 欄；只有 rgba(...) 的第四個才是 alpha
      // color(srgb r g b) 沒有 alpha；color(srgb r g b / .08) 的第四個才是，
      // 而 rgba(...) 也是第四個。兩種都要看，不然 8% 的半透明底會被當成不透明，
      // 於是量出一堆假的 1.0x 低對比（第一版就是這樣紅的）。
      if (m && (m.length < 4 || parseFloat(m[3]) > .85)) return b; }
    return 'rgb(255,255,255)'; };
  const out = [];
  document.querySelectorAll('main .view.on *, header *').forEach(e => {
    if (!Array.from(e.childNodes).some(n => n.nodeType === 3 && n.textContent.trim().length > 0)) return;
    const c = getComputedStyle(e), r = e.getBoundingClientRect();
    if (r.width < 3 || r.height < 3 || c.display === 'none' || c.visibility === 'hidden') return;
    if (parseFloat(c.opacity) < .6) return;          // 刻意調淡的（dim 狀態）不算
    const bg = bgOf(e); if (!bg) return;
    const fs = parseFloat(c.fontSize);
    const la = L(c.color), lb = L(bg);
    const cr = (Math.max(la, lb) + .05) / (Math.min(la, lb) + .05);
    const big = fs >= 24 || (fs >= 18.66 && parseInt(c.fontWeight) >= 700);
    out.push({ cls: String(e.className.baseVal !== undefined ? e.className.baseVal : e.className || ''),
               tag: e.tagName, fs: +fs.toFixed(2), cr: +cr.toFixed(2), big,
               fg: c.color, bg, txt: e.textContent.trim().slice(0, 16) });
  });
  return out;
}
"""

# 掃描時要放過的元素（每一個都要寫清楚為什麼，不准無條件放）
def _uip_skip(x) -> bool:
    # 集中度圖的均線勾選列：字色**必須**等於圖上那條線的顏色，而線色來自 PALETTE（分類色盤）。
    # PALETTE 的前 14 色是鎖定區（DECISIONS #48：動一個值就把全站板塊顏色洗牌一次），
    # 這一批不准碰，所以 4.25～4.56 這三個是**既有**的缺口，留給規格第二階段處理。
    return x["txt"] in ("5 日", "20 日", "60 日")


def t_ui_polish(pg, b, base, code):
    """桌面版介面精修第一階段的九項，逐項驗「畫面真的因此改變了」。"""

    # ---------- #1 數字等寬 ＋ 數字欄靠右 ----------
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2800)
    n = pg.evaluate("""() => {
        const fv = getComputedStyle(document.body).fontVariantNumeric;
        // 找一張真的有資料的表，取同一欄相鄰兩列，量右緣差。
        // 等寬數字的定義就是「同一欄的數字右緣對得齊」——差 0.5px 以上代表沒吃到 tnum。
        let worst = -1, where = null, pairs = 0;
        document.querySelectorAll('table').forEach(t => {
          const rows = [...t.querySelectorAll('tbody tr')].filter(r => r.offsetParent);
          for (let ci = 0; ci < 8; ci++) {
            const cells = rows.map(r => r.children[ci]).filter(Boolean)
              .filter(td => /^[+\-]?[\d,.]+%?$/.test(td.textContent.trim()) && getComputedStyle(td).textAlign === 'right');
            for (let i = 1; i < Math.min(cells.length, 12); i++) {
              const d = Math.abs(cells[i].getBoundingClientRect().right - cells[i-1].getBoundingClientRect().right);
              pairs++; if (d > worst) { worst = d; where = cells[i].textContent.trim() + ' / ' + cells[i-1].textContent.trim(); }
            }
          }
        });
        return { fv, worst, where, pairs };
    }""")
    ok("[#1] body 真的吃到 tabular-nums（不是只寫在 CSS 裡）", n["fv"] == "tabular-nums", n)
    ok("[#1] 表格數字欄相鄰兩列的右緣真的對齊（差 ≤ 0.5px）",
       n["pairs"] > 0 and n["worst"] <= 0.5, n)

    # ---------- #2／#3 token 對比：兩個主題 × 五個路由，每一個有文字的元素都量 ----------
    for th in ("dark", "light"):
        for rt in UIP_ROUTES:
            pg.goto(f"{base}#{rt}", wait_until="networkidle")
            pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); } catch (e) {} }", th)
            pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
            data = pg.evaluate(UIP_CONTRAST_JS)
            bad = [x for x in data if (not x["big"]) and x["cr"] < 4.5 and not _uip_skip(x)]
            ok(f"[#2/#3 {th} #{rt}] 每一個小於 18.66px 的文字對背景都 ≥ 4.5:1（掃了 {len(data)} 個元素）",
               not bad, bad[:6])
    # token 的值本身也驗一次（避免有人「改了註解沒改值」）
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1500)
    tk = pg.evaluate("""() => { const s = getComputedStyle(document.documentElement);
        const g = (n) => (s.getPropertyValue(n) || '').trim(); return { ink3: g('--ink-3'), rise: g('--rise'), fall: g('--fall') }; }""")
    ok("[#2] 深色 --ink-3 已經是新值 #8493b8", tk["ink3"].lower() == "#8493b8", tk)
    ok("[#2] 深色的紅漲綠跌一個字都沒動（--rise 仍是 #ff4d6d、--fall 仍是 #2ee59d）",
       tk["rise"].lower() == "#ff4d6d" and tk["fall"].lower() == "#2ee59d", tk)
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','light'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1500)
    tl = pg.evaluate("""() => { const s = getComputedStyle(document.documentElement);
        const g = (n) => (s.getPropertyValue(n) || '').trim();
        return { ink3: g('--ink-3'), cyan: g('--cyan'), amber: g('--amber'), lime: g('--lime'),
                 rise: g('--rise'), fall: g('--fall'), flat: g('--flat') }; }""")
    # 2026-09-24 設計系統 v2 第 3 批：--ink-3 改前 #5b6884（冷藍灰）→ 改後 #5f5a51（暖灰，對白 6.85、對新 --bg 6.16）。
    # 其餘六個（主色與紅漲綠跌）第 3 批刻意不動，照舊驗。
    ok("[#3] 淺色七個色 token 全部換成新值",
       [tl[k].lower() for k in ("ink3", "cyan", "amber", "lime", "rise", "fall", "flat")]
       == ["#5f5a51", "#0a6b8a", "#8f5600", "#3f7512", "#c81234", "#07794f", "#5f6c85"], tl)
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); } catch (e) {} }")

    # ---------- #8 四個高頻小字真的升到 12px ----------
    pg.goto(f"{base}#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(2600)
    small = pg.evaluate("""() => { const o = [];
        ['a.lk .code', '.ev .cat', '.stage li .m', '.segcard .sco .code', '.dlv-b', '.dlv-tag', '.dlv-ver']
          .forEach(sel => document.querySelectorAll(sel).forEach(e => {
            if (!e.getBoundingClientRect().width) return;
            const fs = parseFloat(getComputedStyle(e).fontSize);
            if (fs < 12) o.push(sel + '@' + fs); }));
        return o; }""")
    ok("[#8] 個股頁上的代號／分類／次要說明沒有任何一個低於 12px", not small, small[:8])
    pg.goto(f"{base}#delivery", wait_until="networkidle"); pg.wait_for_timeout(2200)
    small2 = pg.evaluate("""() => { const o = [];
        ['.dlv-b', '.dlv-tag', '.dlv-ver', '.dlv-none', '.dlv-w b'].forEach(sel =>
          document.querySelectorAll(sel).forEach(e => { if (!e.getBoundingClientRect().width) return;
            const fs = parseFloat(getComputedStyle(e).fontSize); if (fs < 12) o.push(sel + '@' + fs); }));
        return o; }""")
    ok("[#8] 交付清單的 .dlv-* 全部 ≥ 12px", not small2, small2[:8])

    # ---------- #4 導覽列溢出：遮罩、箭頭、而且箭頭真的捲得動 ----------
    for w in (1440, 1280, 1024, 800):
        pg.set_viewport_size({"width": w, "height": 950})
        pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2200)
        st = pg.evaluate("""() => { const s = document.getElementById('tabs'), wp = document.getElementById('tabsWrap');
            const nx = document.getElementById('tabNext');
            return { over: s.scrollWidth - s.clientWidth, cls: wp.className, left: s.scrollLeft,
                     next: getComputedStyle(nx).display, mask: getComputedStyle(s).maskImage,
                     docW: document.documentElement.scrollWidth, winW: innerWidth,
                     tabs: document.querySelectorAll('#tabs .tab').length }; }""")
        # ★ 2026-09-24：「題材」併進「熱力圖」，八顆變七顆
        ok(f"[#4 {w}px] 整頁沒有橫向捲軸、七顆分頁都在 DOM 裡",
           st["docW"] <= st["winW"] + 1 and st["tabs"] == 7, st)
        if st["over"] > 2:
            # 真的放不下 → 一定要看得到提示，而且那個提示按下去要真的有用
            ok(f"[#4 {w}px] 分頁列放不下（溢出 {st['over']}px）時，右箭頭與右緣淡出真的出現了",
               st["next"] != "none" and "ovf-r" in st["cls"] and "gradient" in (st["mask"] or ""), st)
            pg.click("#tabNext"); pg.wait_for_timeout(700)
            after = pg.evaluate("""() => { const s = document.getElementById('tabs');
                return { left: s.scrollLeft, cls: document.getElementById('tabsWrap').className,
                         prev: getComputedStyle(document.getElementById('tabPrev')).display }; }""")
            # ★ 2026-09-24：分頁從八顆變七顆（題材併進熱力圖），1280px 只溢出 19px ——
            #   「捲超過 20px」在物理上做不到。門檻改成「捲 20px，或捲到底（溢出不足 20px 時）」，
            #   要驗的事情沒變：按一下，分頁列真的往右移到它能到的地方。
            _need = min(st["left"] + 20, st["over"] - 1)
            ok(f"[#4 {w}px] 按右箭頭：分頁列真的往右捲了（{st['left']} → {after['left']}）",
               after["left"] >= _need and after["left"] > st["left"], {**after, "至少要到": _need})
            ok(f"[#4 {w}px] 捲過去之後左箭頭跟著出現（左邊還有東西 → 要看得到）",
               "ovf-l" in after["cls"] and after["prev"] != "none", after)
            pg.click("#tabPrev"); pg.wait_for_timeout(700)
            back = pg.evaluate("""() => ({ left: document.getElementById('tabs').scrollLeft,
                cls: document.getElementById('tabsWrap').className })""")
            ok(f"[#4 {w}px] 按左箭頭真的捲回去，而且捲到底之後左箭頭自己收掉",
               back["left"] <= max(0, after["left"] - 20) and back["left"] < after["left"]
               and (back["left"] > 2 or "ovf-l" not in back["cls"]), back)
        else:
            ok(f"[#4 {w}px] 分頁列放得下時，不要留一顆按了沒反應的箭頭",
               st["next"] == "none" and "ovf-r" not in st["cls"], st)

    # ---------- #4（A14）錯誤徽章不准把導覽擠掉 ----------
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(2400)
    ls = pg.evaluate("""() => { const e = document.getElementById('liveState'); if (!e) return null;
        const r = e.getBoundingClientRect(); const c = getComputedStyle(e);
        return { w: +r.width.toFixed(1), txt: (e.textContent || '').trim().length,
                 ov: c.overflow, cls: e.className }; }""")
    ok("[#4] 即時徽章不管錯誤訊息多長，寬度都被壓在 150px 以內（不再把分頁擠掉）",
       ls and ls["w"] <= 151, ls)

    # ---------- #5 hover 過渡 ＋ :active 按下回饋 ----------
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    tr = pg.evaluate("""() => { const o = {};
        [['tab', '.tab'], ['evbtn', '.evbtn'], ['row', 'tbody tr'], ['tile', '.tile'], ['card', '.card']]
          .forEach(([k, sel]) => { const e = document.querySelector(sel);
            o[k] = e ? getComputedStyle(e).transitionDuration : 'missing'; });
        return o; }""")
    slow = {k: v for k, v in tr.items() if v not in ("missing",)
            and max([float(x.replace('s', '')) for x in v.split(', ')] or [0]) > 0.24}
    ok("[#5] 分頁／按鈕／表格列／卡片都真的有過場（transition-duration > 0）",
       all(v == "missing" or any(float(x.replace("s", "")) > 0 for x in v.split(", "))
           for k, v in tr.items() if k != "card"), tr)
    ok("[#5] 沒有任何一個過場超過 240ms 的上限", not slow, slow)
    # 按下去：量 transform 真的變了（不是驗 CSS 有寫）
    # ⚠ 受測對象刻意選 `.tab` 不選 `.evbtn`：`.evbtn` 的「更新」鈕在即時報價抓取中會被設成
    #   `disabled`，而 **disabled 的元素不會進 :active**，於是這一條會間歇性假紅。
    press = pg.evaluate("""() => ({ before: getComputedStyle(document.querySelector('.tab:not(.on)')).transform })""")
    box = pg.evaluate("""() => { const b = document.querySelector('.tab:not(.on)').getBoundingClientRect();
        return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; }""")
    pg.mouse.move(box["x"], box["y"]); pg.mouse.down(); pg.wait_for_timeout(180)
    act = pg.evaluate("() => getComputedStyle(document.querySelector('.tab:not(.on)')).transform")
    pg.mouse.up(); pg.wait_for_timeout(200)
    # 放開之後把滑鼠移開，不然它還停在那顆分頁上（hover 不影響 transform，但量起來比較乾淨）
    pg.mouse.move(10, 600)
    rel = pg.evaluate("() => getComputedStyle(document.querySelector('.tab:not(.on)')).transform")
    ok("[#5] 按鈕**按下去的當下**真的有回饋（transform 從 none 變成縮放）",
       act != press.get("before") and act != "none", {"before": press.get("before"), "active": act})
    ok("[#5] 放開之後回到原狀（不會卡在按下的樣子）", rel == "none" or rel == press.get("before"),
       {"released": rel})

    # ---------- #7 鍵盤焦點：連按 30 次 Tab，每一次都要看得到焦點框 ----------
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2400)
    pg.evaluate("() => document.body.focus()")
    noring = []
    for i in range(30):
        pg.keyboard.press("Tab")
        r = pg.evaluate("""() => { const a = document.activeElement;
            if (!a || a === document.body) return { body: true };
            const c = getComputedStyle(a);
            return { tag: a.tagName, cls: String(a.className || '').slice(0, 30),
                     w: parseFloat(c.outlineWidth) || 0, st: c.outlineStyle }; }""")
        if not r.get("body") and (r["w"] <= 0 or r["st"] == "none"):
            noring.append(f"第{i+1}次 {r['tag']}.{r['cls']} outline={r['w']}px/{r['st']}")
    ok("[#7] 連按 30 次 Tab，每一次都看得到焦點框（outline-width > 0）", not noring, noring[:6])
    # 五處寫過 outline:0 的輸入框，焦點框真的補回來了
    ring = pg.evaluate("""() => { const i = document.getElementById('q'); i.focus();
        // focus-visible 只在鍵盤操作時成立，所以用鍵盤路徑進來的那一次才算；這裡直接問 matches
        const c = getComputedStyle(i);
        return { fv: i.matches(':focus-visible'), w: parseFloat(c.outlineWidth) || 0 }; }""")
    pg.keyboard.press("Shift+Tab"); pg.keyboard.press("Tab"); pg.wait_for_timeout(120)
    ring2 = pg.evaluate("""() => { const a = document.activeElement; const c = getComputedStyle(a);
        return { id: a.id, w: parseFloat(c.outlineWidth) || 0 }; }""")
    ok("[#7] 搜尋框（原本寫死 outline:0）用鍵盤走進去看得到焦點框", ring2["w"] > 0, {"first": ring, "kbd": ring2})

    # ---------- #6 prefers-reduced-motion：動的沒了，回饋還在 ----------
    rm = b.new_context(viewport={"width": 1440, "height": 950}, reduced_motion="reduce")
    mp = rm.new_page()
    mp.on("pageerror", lambda e: fails.append(f"UI精修 關動效 pageerror: {e}"))
    mp.goto(f"{base}#overview", wait_until="networkidle"); mp.wait_for_timeout(2600)
    r1 = mp.evaluate("""() => { const t = document.querySelector('.tab');
        return { dur: getComputedStyle(t).transitionDuration, anim: getComputedStyle(t).animationDuration }; }""")
    ok("[#6] 關掉動效之後，過場真的被壓成 0（不是只在 CSS 裡寫了一條 media query）",
       all(float(x.replace("s", "")) <= 0.001 for x in r1["dur"].split(", ")), r1)
    bb = mp.evaluate("""() => { const e = document.querySelector('.tab:not(.on)'); const b = e.getBoundingClientRect();
        return { x: b.x + b.width / 2, y: b.y + b.height / 2, bg: getComputedStyle(e).backgroundColor }; }""")
    mp.mouse.move(bb["x"], bb["y"]); mp.mouse.down(); mp.wait_for_timeout(150)
    after_bg = mp.evaluate("""() => { const e = document.querySelector('.tab:not(.on)'); const c = getComputedStyle(e);
        return { bg: c.backgroundColor, tf: c.transform }; }""")
    mp.mouse.up()
    ok("[#6] 關掉動效之後**回饋沒有消失**：按下去改用底色壓一階（而且不再縮放）",
       after_bg["bg"] != bb["bg"] and after_bg["tf"] == "none", {"idle": bb["bg"], "active": after_bg})
    mp.close(); rm.close()

    # ---------- #9 表格：列高固定、列 hover 真的變色、表頭吸頂 ----------
    pg.set_viewport_size({"width": 1440, "height": 950})
    # 用總覽的候選名單表：市場明細的預設子頁「漲跌家數」是卡片版面，沒有 <table>。
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2800)
    tb = pg.evaluate("""() => {
        // ⚠ 不能用 querySelector('table') —— 那會撿到**沒顯示的那一頁**裡的表（量到 0 列，假紅）。
        //   要找的是「現在這一頁、真的有看得見的列」的第一張表。
        const t = [...document.querySelectorAll('table')]
          .find(x => [...x.querySelectorAll('tbody tr')].some(r => r.offsetParent));
        if (!t) return null;
        const rows = [...t.querySelectorAll('tbody tr')].filter(r => r.offsetParent).slice(0, 12);
        const hs = rows.map(r => +r.getBoundingClientRect().height.toFixed(1));
        const th = t.querySelector('thead th');
        return { hs, spread: hs.length ? Math.max(...hs) - Math.min(...hs) : -1,
                 sticky: th ? getComputedStyle(th).position : null,
                 shadow: th ? getComputedStyle(th).boxShadow : null,
                 rowHover: getComputedStyle(document.documentElement).getPropertyValue('--row-hover').trim(),
                 n: rows.length }; }""")
    ok("[#9] 表格列高固定（前 12 列的高度差 ≤ 1px，不因內容長短抽動）",
       tb and tb["n"] >= 3 and tb["spread"] <= 1.0, tb)
    ok("[#9] 表頭仍然吸頂，而且底線改用 box-shadow（border-collapse 下 border 會跟著捲走）",
       tb and tb["sticky"] == "sticky" and "rgb" in (tb["shadow"] or ""), tb)
    # ⚠ 用 Playwright 的 hover()（它會自己捲進視窗、自己算中心點），
    #   不要自己 mouse.move 到 getBoundingClientRect 算出來的座標 ——
    #   那一列可能在摺線下面或在 `.tw` 的內捲容器裡，座標對不上就完全沒有 hover（第一版就是這樣假紅的）。
    #   受測對象一律指名「現在這一頁、看得見的第一列」，不是 document 裡的第一列。
    row = pg.locator("table tbody tr:visible").first
    hv = pg.evaluate("""() => ({ bg: getComputedStyle(
        [...document.querySelectorAll('table tbody tr')].find(x => x.offsetParent)).backgroundColor })""")
    row.hover(); pg.wait_for_timeout(350)
    hv2 = pg.evaluate("() => getComputedStyle([...document.querySelectorAll('table tbody tr')].find(x => x.offsetParent)).backgroundColor")
    ok("[#9] 滑鼠移到表格列上，底色真的變了（不是驗 CSS 有寫）", hv2 != hv["bg"], {"idle": hv["bg"], "hover": hv2})

    # ---------- 手機那一套有沒有被影響（這一批只動桌機，390px 必須零差異）----------
    mb = b.new_context(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True,
                       device_scale_factor=2)
    mpg = mb.new_page()
    mpg.on("pageerror", lambda e: fails.append(f"UI精修 手機 pageerror: {e}"))
    for rt in ("overview", "industry", "season"):
        mpg.goto(f"{base}#{rt}", wait_until="networkidle"); mpg.wait_for_timeout(2400)
        m = mpg.evaluate("""() => { const wp = document.getElementById('tabsWrap'), s = document.getElementById('tabs');
            const tabs = [...document.querySelectorAll('#tabs .tab')];
            const rows = new Set(tabs.map(t => Math.round(t.getBoundingClientRect().top)));
            return { wrap: getComputedStyle(wp).display,
                     prev: getComputedStyle(document.getElementById('tabPrev')).display,
                     next: getComputedStyle(document.getElementById('tabNext')).display,
                     pos: getComputedStyle(s).position, n: tabs.length, rows: rows.size,
                     allVisible: tabs.every(t => { const r = t.getBoundingClientRect();
                       return r.width > 20 && r.left >= -1 && r.right <= innerWidth + 1; }),
                     more: getComputedStyle(document.getElementById('moreBtn')).display,
                     docW: document.documentElement.scrollWidth, winW: innerWidth }; }""")
        ok(f"[手機零影響 #{rt}] 新加的 .tabswrap 在手機是 display:contents（整層從版面消失）",
           m["wrap"] == "contents", m)
        ok(f"[手機零影響 #{rt}] 桌機的左右箭頭在手機一顆都不出現", m["prev"] == "none" and m["next"] == "none", m)
        ok(f"[手機零影響 #{rt}] 分頁列還是固定在底部、兩列、七顆（題材併進熱力圖）全部看得見",
           m["pos"] == "fixed" and m["n"] == 7 and m["rows"] == 2 and m["allVisible"], m)
        ok(f"[手機零影響 #{rt}] 「⋯ 更多工具」還在，而且沒有橫向捲軸",
           m["more"] != "none" and m["docW"] <= m["winW"] + 1, m)
    mpg.close(); mb.close()
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 輪動象限面板排版
def t_rot_stage_panel(pg, base):
    """★ 2026-09-23（Andy 逐字：「資金輪動領先 改善 落後 轉若 裡面的內容跑掉需要重新排版」）。

    壞掉的長相與量測值（修之前，1440px，四個象限都一樣）：
      · 名稱欄 `.g` 寬 13～32px、**高 60～150px** ← 中文被壓成一個字一行、直排
      · 數字欄 `.m` 右緣 748.3px vs 那一列右緣 676.7px ← **佔比那一欄被裁掉**
      · `ul.ms` scrollWidth 342 vs clientWidth 270 ← 多出一條橫向捲軸
    修完之後同一組量測：`.g` 高 20px（＝一行）、`.m` 不裁、scrollWidth == clientWidth。

    這一段把那三個數字**逐項量出來**，四個象限 × 四個寬度全跑，
    所以以後只要有人再把這塊面板塞進固定寬度的欄位，這裡就會紅。
    """
    # ★ 2026-09-24 第二次重排（Andy：「輪動時鐘內的資訊並沒有修正，為何看起來排版還是很糟糕」）：
    #   從「flex ＋ 放不下就換行」改成**對齊的格線**（族群名｜強弱｜動能｜佔比｜趨勢），所以這一段改量：
    #     · 每一列（含表頭）的每一欄 x 都一樣（容許 1px）—— 截圖裡「箭頭擠到右邊、數字靠右各自亂跳」的反面
    #     · 一律單行：每一格都只有一行（高 ≤ 22px）、整列高 ≤ 32px；「佔比 2.2%」不准被折到第三行
    #     · 數字是等寬字＋ tabular-nums、靠右；字 ≥ 12px
    #     · 名稱截斷有 title（藏起來，不是刪掉）、面板裡沒有任何一列溢出、沒有橫向捲軸
    #     · 「收起 ✕」不在了（點外面／Esc 關，另一段「點外面就關」用真滑鼠驗）
    QUADS = (("leading", "領先"), ("improving", "改善"), ("lagging", "落後"), ("weakening", "轉弱"))
    MEASURE = """() => { const box = document.getElementById('stagePanel');
        if (!box || box.hidden) return { open: false };
        const ul = box.querySelector('ul.ms');
        const head = box.querySelector('ul.ms li.cols');
        const lis = [...box.querySelectorAll('ul.ms li[data-gid]')];
        const cellsOf = (l) => [...l.children].filter(x => !x.classList.contains('jmp'));
        const geo = (l) => cellsOf(l).map(c => { const r = c.getBoundingClientRect(); return { l: +r.left.toFixed(1), r: +r.right.toFixed(1), h: +r.height.toFixed(1) }; });
        const rows = lis.map(l => { const g = l.querySelector('.g'); const lr = l.getBoundingClientRect();
          const v = [...l.querySelectorAll('.v')];
          return { name: g ? g.textContent.trim() : '', cells: geo(l), h: +lr.height.toFixed(1),
                   over: l.scrollWidth - l.clientWidth, hasTitle: !!(g && g.getAttribute('title')),
                   vAlign: v.map(x => getComputedStyle(x).textAlign), vNum: v.map(x => getComputedStyle(x).fontVariantNumeric),
                   minFs: Math.min(...[...l.querySelectorAll('*')].map(x => parseFloat(getComputedStyle(x).fontSize) || 99)) }; });
        return { open: true, n: rows.length, rows, head: head ? geo(head) : null,
                 x: !!box.querySelector('[data-x]') || /收起/.test(box.textContent),
                 ulOver: ul.scrollWidth - ul.clientWidth, ulOverflowX: getComputedStyle(ul).overflowX,
                 docW: document.documentElement.scrollWidth, winW: innerWidth }; }"""
    for w in (1440, 1280, 800, 390):
        pg.set_viewport_size({"width": w, "height": 950})
        pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(3600)
        for k, zh in QUADS:
            sel = f'.rq[data-k="{k}"]'
            if not pg.query_selector(sel):
                ok(f"[輪動面板 {w}px] 四顆象限徽章都在（找不到「{zh}」）", False, sel); continue
            pg.click(sel); pg.wait_for_timeout(800)
            r = pg.evaluate(MEASURE)
            if not r.get("open"):
                ok(f"[輪動面板 {w}px {zh}] 點下去面板真的展開了", False, r); continue
            if not r["n"]:
                pg.click(sel); pg.wait_for_timeout(300); continue
            ok(f"[輪動面板 {w}px {zh}] 「收起 ✕」不在了（點外面／Esc 關）", not r["x"], r["x"])
            ok(f"[輪動面板 {w}px {zh}] 有表頭（族群｜強弱｜動能｜佔比｜趨勢），欄名只寫一次", bool(r["head"]) and len(r["head"]) == 5, r["head"])
            cols = list(zip(*[x["cells"] for x in r["rows"]]))
            ncol_ok = all(len(x["cells"]) == 5 for x in r["rows"])
            ok(f"[輪動面板 {w}px {zh}] 每一列都是五格（名稱＋三個數字＋趨勢）", ncol_ok, [len(x["cells"]) for x in r["rows"]][:6])
            if ncol_ok and r["head"]:
                # 數字欄比右緣（靠右對齊），名稱比左緣，趨勢比中心；表頭也要跟清單同一條線
                spread = []
                for ci, col in enumerate(cols):
                    key = (lambda c: c["l"]) if ci == 0 else (lambda c: c["r"]) if ci < 4 else (lambda c: (c["l"] + c["r"]) / 2)
                    vals = [key(c) for c in col] + [key(r["head"][ci])]
                    spread.append(round(max(vals) - min(vals), 1))
                ok(f"[輪動面板 {w}px {zh}] ★ 五欄逐列對齊（每一欄的 x 差 ≤ 1px，含表頭）", max(spread) <= 1, spread)
            tall = [x for x in r["rows"] if x["h"] > 32 or any(c["h"] > 22 for c in x["cells"])]
            ok(f"[輪動面板 {w}px {zh}] ★ 一律單行（整列 ≤ 32px、每一格 ≤ 22px，沒有被折到第二／三行）", not tall, tall[:2])
            overs = [x for x in r["rows"] if x["over"] > 0]
            ok(f"[輪動面板 {w}px {zh}] 面板裡沒有任何一列溢出、也沒有橫向捲軸",
               not overs and r["ulOver"] <= 0 and r["ulOverflowX"] == "hidden",
               {"overs": overs[:3], "ulOver": r["ulOver"], "overflowX": r["ulOverflowX"]})
            ok(f"[輪動面板 {w}px {zh}] 整頁沒有因此長出橫向捲軸", r["docW"] <= r["winW"] + 1, r["docW"])
            ok(f"[輪動面板 {w}px {zh}] 名稱掛了 title（截斷時全名還看得到，是藏不是刪）",
               all(x["hasTitle"] for x in r["rows"]), r["rows"][:1])
            ok(f"[輪動面板 {w}px {zh}] 數字靠右、等寬（tabular-nums）",
               all(all(a in ("right", "end") for a in x["vAlign"]) and all("tabular-nums" in v for v in x["vNum"]) for x in r["rows"]),
               r["rows"][0]["vAlign"] + r["rows"][0]["vNum"])
            ok(f"[輪動面板 {w}px {zh}] 面板裡的字都 ≥ 12px", min(x["minFs"] for x in r["rows"]) >= 12,
               min(x["minFs"] for x in r["rows"]))
            pg.click(sel); pg.wait_for_timeout(300)
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 設計系統 v2（第 1／2 批）
# ★ 2026-09-24 規格：docs/design_system_v2.md §2.1。Andy：「我希望跟他們一樣規格…將UI大改，需要美化他」。
#   這一段驗的是**量出來的尺寸真的上了畫面**（getComputedStyle／getBoundingClientRect），
#   不是驗「CSS 裡有寫」。範圍只有桌機（≥821px）—— 最後一組驗手機一個數字都沒被動到。
DS2_CSS = r"""() => {
  const cs = (e) => e ? getComputedStyle(e) : null;
  const card = document.querySelector('#ovHeatCard'); const c = cs(card);
  const kpi = document.querySelector('#hero .card.tight'); const k = cs(kpi);
  const grid = document.querySelector('#v-overview > .grid'); const g = cs(grid);
  const cards = [...document.querySelectorAll('#v-overview > .grid > .card')].map(x => x.getBoundingClientRect());
  const btn = document.querySelector('#heatZoom'); const bs = cs(btn);
  const how = document.querySelector('#ovHeatCard .howbtn'); const hs = cs(how);
  const tab = document.querySelector('.tab'); const h3 = document.querySelector('#ovHeatCard h3');
  const sm = document.querySelector('#ovHeatCard h3 small');
  return {
    cardR: c && c.borderTopLeftRadius, cardPad: c && c.paddingTop + ' ' + c.paddingLeft, cardBgImg: c && c.backgroundImage,
    cardBg: c && c.backgroundColor, cardSh: c && c.boxShadow,
    kpiR: k && k.borderTopLeftRadius, kpiPad: k && k.paddingTop,
    gap: g && g.columnGap, gridMt: g && g.marginTop,
    gapX: cards.length >= 2 ? Math.round((cards[1].left - cards[0].right) * 10) / 10 : null,
    mainPad: cs(document.querySelector('main')).paddingTop + ' ' + cs(document.querySelector('main')).paddingLeft,
    bodyFs: cs(document.body).fontSize, bodyLh: cs(document.body).lineHeight,
    h3Fs: h3 && cs(h3).fontSize, smallFs: sm && cs(sm).fontSize,
    btnR: bs && bs.borderTopLeftRadius, btnH: btn && Math.round(btn.getBoundingClientRect().height), btnFs: bs && bs.fontSize,
    howH: how && Math.round(how.getBoundingClientRect().height), howR: hs && hs.borderTopLeftRadius,
    tabR: tab && cs(tab).borderTopLeftRadius,
    panel: getComputedStyle(document.documentElement).getPropertyValue('--panel').trim(),
    docW: document.documentElement.scrollWidth, winW: innerWidth };
}"""


def t_ds2(pg, base):
    """設計系統 v2 第 1／2 批：卡片、間距、字級、膠囊按鈕、圖表字級下限。"""
    for th in ("dark", "light"):
        pg.set_viewport_size({"width": 1440, "height": 950})
        pg.goto("about:blank")
        pg.goto(f"{base}#overview", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        r = pg.evaluate(DS2_CSS)
        ok(f"[{th}] 大卡片圓角 12 → 24px（參考截圖擬合 21.9）", r["cardR"] == "24px", r)
        ok(f"[{th}] 卡片內距 16/18 → 20px", r["cardPad"] == "20px 20px", r)
        ok(f"[{th}] 卡片改成平塗（不再是上下漸層），底色＝--panel", r["cardBgImg"] == "none", r)
        ok(f"[{th}] KPI 小卡是中型容器：圓角 16、內距 16", r["kpiR"] == "16px" and r["kpiPad"] == "16px", r)
        ok(f"[{th}] 卡片之間 16 → 24px（CSS 的 gap）", r["gap"] == "24px", r)
        ok(f"[{th}] 卡片之間**實際量到**的距離是 24px（兩張卡片的邊框之間）", r["gapX"] == 24, r)
        ok(f"[{th}] KPI 列 → 熱力圖那一列的上邊距也是 24（原本行內寫死 16）", r["gridMt"] == "24px", r)
        ok(f"[{th}] 頁面外距 20/22 → 24/24", r["mainPad"] == "24px 24px", r)
        ok(f"[{th}] 內文 15.5 → 14px、行高 1.7（23.8px）", r["bodyFs"] == "14px" and r["bodyLh"] == "23.8px", r)
        ok(f"[{th}] 卡片標題 16.5 → 16px、標題旁的小字 12.5 → 13px", r["h3Fs"] == "16px" and r["smallFs"] == "13px", r)
        ok(f"[{th}] 按鈕一律膠囊（圓角＝半高）", r["btnR"] == "999px" and r["howR"] == "999px" and r["tabR"] == "999px", r)
        ok(f"[{th}] 工具列按鈕高 28、字 12（守觸控下限；參考站 26）", r["btnH"] == 28 and r["btnFs"] == "12px" and r["howH"] == 28, r)
        ok(f"[{th}] 1440px 沒有橫向捲軸", r["docW"] <= r["winW"] + 1, r)
        if th == "light":
            ok("[light] 淺色卡片無陰影（參考截圖卡片外圍像素與頁底無差）", r["cardSh"] == "none", r)
        else:
            ok("[dark] 深色卡片只留內高光（深底上的外陰影本來就看不到）",
               "inset" in (r["cardSh"] or "") and "32px" not in (r["cardSh"] or ""), r)
    # ---- 圖表字級下限：這一批升到 12 的那幾張（輪動時鐘、資金去向兩張、季節性）----
    FS = r"""(ids) => { const out = {};
      ids.forEach(id => { const el = document.getElementById(id); const c = el && window.echarts && echarts.getInstanceByDom(el);
        if (!c) { out[id] = null; return; }
        const small = []; const walk = (o, path) => { if (!o || typeof o !== 'object') return;
          if (Array.isArray(o)) { o.slice(0, 400).forEach((x, i) => walk(x, path)); return; }
          for (const k of Object.keys(o)) { const v = o[k];
            if (k === 'fontSize' && typeof v === 'number' && v < 12) small.push(path + '.' + k + '=' + v);
            else if (v && typeof v === 'object' && k !== 'data') walk(v, path + '.' + k); } };
        walk(c.getOption(), id); out[id] = small.slice(0, 6); }); return out; }"""
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); } catch (e) {} }")
    for hash_, ids in (("#overview", ["rotClockMini", "ovFlow"]), ("#flow", ["rotClock", "sankey"]), ("#season", ["seasonHeat"])):
        pg.goto(f"{base}{hash_}", wait_until="networkidle"); pg.wait_for_timeout(2600)
        got = pg.evaluate(FS, ids)
        for i in ids:
            if got.get(i) is None and i == "ovFlow":
                # 2026-09-26 改前→改後：總覽資金去向桌機改成 flowtopo 畫布（不是 ECharts）→ 量畫布探針回報的最小字級
                scroll_to(pg, "ovFlow"); pg.wait_for_timeout(800)
                tf = pg.evaluate(OVFX)
                ok(f"[{hash_} #ovFlow] 畫布字 ≥ 12px（光纖緊湊版）", bool(tf) and (tf["minFont"] or 0) >= 12, tf and tf["minFont"])
                continue
            if got.get(i) is None:
                notes.append(f"設計系統v2：{hash_} 找不到圖 #{i}（沒資料時會這樣），字級沒量到")
                continue
            ok(f"[{hash_} #{i}] 圖表裡沒有任何一個字小於 12px（11～11.5 升到 12）", not got[i], got[i])
    # ---- 手機一個數字都沒動（這一批只改桌機）----
    pg.set_viewport_size({"width": 390, "height": 844})
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2400)
    m = pg.evaluate("""() => { const c = document.querySelector('#ovHeatCard'); const s = getComputedStyle(c);
        const mn = getComputedStyle(document.querySelector('main'));
        return { r: s.borderTopLeftRadius, pad: s.paddingTop + ' ' + s.paddingLeft, bodyFs: getComputedStyle(document.body).fontSize,
                 lh: getComputedStyle(document.body).lineHeight, main: mn.paddingLeft,
                 gap: getComputedStyle(document.querySelector('#v-overview > .grid')).columnGap }; }""")
    ok("[390px] 手機的卡片、內距、字級、行高、頁面外距、卡片間距都沒被這一批動到",
       m == {"r": "12px", "pad": "16px 18px", "bodyFs": "15px", "lh": "24px", "main": "14px", "gap": "16px"}, m)
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 熱力圖 v2（第 4 批）
# ★ 2026-09-24 規格：docs/design_system_v2.md §3.1。三張 treemap：總覽 #heat、熱力圖頁 #indTree、題材 #themeMap。
#   六條規格斷言（⑤ 對比、⑥ 圖例聚焦都做了）＋ 兩個新下拉（分組／顏色）真的改了畫面。
HM_READ = r"""(id) => {
  const el = document.getElementById(id); const c = el && window.echarts && echarts.getInstanceByDom(el); if (!c) return null;
  const s = getComputedStyle(document.documentElement); const tok = (n) => s.getPropertyValue(n).trim().toLowerCase();
  const pal7 = ['--hm-n3','--hm-n2','--hm-n1','--hm-0','--hm-p1','--hm-p2','--hm-p3'].map(tok);
  const pal5 = ['--hm-v1','--hm-v2','--hm-v3','--hm-v4','--hm-v5'].map(tok); const na = tok('--hm-na');
  const palT = ['--hm-t1','--hm-t2','--hm-t3','--hm-t4','--hm-t5'].map(tok); const inkDark = tok('--hm-ink-dark');
  const tree = c.getModel().getSeriesByIndex(0).getData().tree; const leaves = []; const byP = {};
  const all = [];
  tree.root.eachNode(n => { if (n.children && n.children.length) return; const l = n.getLayout(); if (!l) return;
    if (l.width > 0 && l.height > 0) all.push({ x: l.x, y: l.y, w: l.width, h: l.height, p: n.parentNode ? n.parentNode.dataIndex : -1 });
    if (!l.isInView) return;
    const raw = n.getModel().option || {}; const key = raw.gid || raw.id || raw.cid || raw.name;
    const st = n.getVisual('style') || {};
    const it = { key, name: n.name, x: l.x, y: l.y, w: l.width, h: l.height, p: n.parentNode ? n.parentNode.dataIndex : -1,
      fill: String(raw.itemStyle && raw.itemStyle.color || st.fill || '').toLowerCase(), bin: raw.bin,
      op: raw.itemStyle && raw.itemStyle.opacity, lab: (el._hmLab || {})[key] || null };
    leaves.push(it); (byP[it.p] = byP[it.p] || []).push(it); });
  // 間隙：每一格只量「右邊最近」與「下面最近」那一個鄰居（同一個父節點裡），
  // 被 visibleMin 藏起來的小方塊也算進去 —— 不然兩格中間夾一塊沒畫的，會量成 10px 的假間隙。
  const gaps = []; const allP = {}; all.forEach(it => (allP[it.p] = allP[it.p] || []).push(it));
  Object.values(allP).forEach(a => a.forEach(p => { let bx = null, by = null;
    a.forEach(q => { if (p === q) return;
      const dx = q.x - (p.x + p.w), ov = Math.min(p.y + p.h, q.y + q.h) - Math.max(p.y, q.y);
      if (dx > -0.5 && ov > 4 && (bx === null || dx < bx)) bx = dx;
      const dy = q.y - (p.y + p.h), ox = Math.min(p.x + p.w, q.x + q.w) - Math.max(p.x, q.x);
      if (dy > -0.5 && ox > 4 && (by === null || dy < by)) by = dy; });
    if (bx !== null && bx < 12) gaps.push(bx); if (by !== null && by < 12) gaps.push(by); }));
  const card = el.closest('.card'); const lg = card && card.querySelector('.hmlegend');
  const cells = lg ? [...lg.querySelectorAll('.hmcell')].map(b => { const r = b.getBoundingClientRect();
    return { w: Math.round(r.width), bg: getComputedStyle(b).backgroundColor, txt: b.textContent }; }) : [];
  const opt = c.getOption(); const se = opt.series[0];
  return { n: leaves.length, leaves, gaps, pal7, pal5, palT, inkDark, na, cells, legendTitle: lg ? (lg.querySelector('.hmttl') || {}).textContent : null,
    lgRight: lg ? lg.getBoundingClientRect().right : null, cardRight: card ? card.getBoundingClientRect().right : null,
    radius: se.itemStyle && se.itemStyle.borderRadius, fs: se.label && se.label.fontSize,
    tipBg: (opt.tooltip && opt.tooltip[0] && opt.tooltip[0].backgroundColor) || '',
    tipDur: opt.tooltip && opt.tooltip[0] ? opt.tooltip[0].transitionDuration : null,
    nested: !!(se.data && se.data[0] && se.data[0].children), docW: document.documentElement.scrollWidth, winW: innerWidth };
}"""


def _lum(hexs):
    h = hexs.lstrip("#")
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    rgb = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    f = [c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4 for c in rgb]
    return 0.2126 * f[0] + 0.7152 * f[1] + 0.0722 * f[2]


def _cr_white(hexs):
    return (1.05) / (_lum(hexs) + 0.05)


def _cr(a, b):
    la, lb = _lum(a), _lum(b)
    return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)


def _hm_check(tag, r, kind):
    """一張熱力圖的共通斷言（規格 ①～⑤）。kind＝7 格（chg/flow）或 5 格（heat）。"""
    if not ok(f"[{tag}] 熱力圖畫得出來、讀得到方塊", r and r["n"] > 0, r and r.get("n")):
        return
    gaps = r["gaps"]
    ok(f"[{tag}] ① 相鄰兩個族群方塊的間隙實測 2±1px（{len(gaps)} 對）",
       gaps and all(1 <= g <= 3 for g in gaps), sorted(set(round(g, 1) for g in gaps))[:8])
    ncell = 5 if kind in ("heat", "heatT") else 7
    ok(f"[{tag}] ② 圖例存在、{ncell} 格、每格寬 ≥ 36px",
       len(r["cells"]) == ncell and all(c["w"] >= 36 for c in r["cells"]), r["cells"])
    pal = r["pal5"] if kind == "heat" else r["palT"] if kind == "heatT" else r["pal7"]
    bad = [lf["name"] + " " + lf["fill"] for lf in r["leaves"] if lf["fill"] not in pal + [r["na"]]]
    ok(f"[{tag}] ③ 每一格方塊的填色都屬於 {ncell} 格之一（不再是連續色）", not bad, bad[:5])
    used = {lf["fill"] for lf in r["leaves"]}
    ok(f"[{tag}] ③ 畫面上真的用到了不只一級（{len(used)} 種）", len(used) >= 2, sorted(used))
    tiny = [lf for lf in r["leaves"] if lf["w"] < 48 or lf["h"] < 24]
    bad4 = [(lf["name"], round(lf["w"]), round(lf["h"]), lf["lab"]) for lf in tiny if not lf["lab"] or lf["lab"]["text"]]
    ok(f"[{tag}] ④ 寬 < 48 或高 < 24 的方塊（{len(tiny)} 塊）一個字都不寫", not bad4, bad4[:5])
    two = [lf for lf in r["leaves"] if lf["lab"] and lf["lab"]["mode"] == 2]
    bad4b = [(lf["name"], round(lf["w"]), round(lf["h"])) for lf in two if lf["h"] < 44]
    ok(f"[{tag}] ④ 寫兩行的方塊（{len(two)} 塊）高度都 ≥ 44", two and not bad4b, bad4b[:5])
    trunc = [lf["lab"]["text"] for lf in r["leaves"] if lf["lab"] and lf["lab"]["text"].endswith("…")]
    ok(f"[{tag}] ④ 截斷的名稱至少留兩個字（不再有「M +」這種殘字）",
       all(len(t) >= 3 for t in trunc), trunc[:6])
    # 熱度那兩組（暖金／湖水藍）最亮的兩格改配深字（2026-09-24 Andy 嫌紫色醜之後換的色）；其他格一律白字
    ink = lambda i: r["inkDark"] if (kind == "heat" and 1 <= i <= 3) or (kind == "heatT" and i >= 3) else "#ffffff"   # 09-25 深藍→淺藍→淺紅→深紅，中間三格深字
    lowc = [(c, ink(i), round(_cr(c, ink(i)), 2)) for i, c in enumerate(pal) if _cr(c, ink(i)) < 4.5]
    ok(f"[{tag}] ⑤ 每一級色階上的字（白字，熱度最亮兩格是深字）對比都 ≥ 4.5:1（從 token 算）", not lowc, lowc)
    ok(f"[{tag}] 方塊圓角 3px、標籤 12px", r["radius"] == 3 and r["fs"] == 12, [r["radius"], r["fs"]])
    # 2026-09-24 Andy 截圖：提示框 88% 透明＋0.4 秒淡入，途中後面方塊的字透出來看不清 → 改 97%、不淡入
    _a = re.search(r"rgba\([^)]*,\s*([0-9.]+)\)", r["tipBg"] or "")
    ok(f"[{tag}] 提示框近乎不透明（≥ 95%），後面方塊的字不會透出來", bool(_a) and float(_a.group(1)) >= 0.95, r["tipBg"])
    ok(f"[{tag}] 提示框不做淡入淡出（途中半透明會跟方塊的字疊在一起）", r.get("tipDur") == 0, r.get("tipDur"))
    ok(f"[{tag}] 圖例沒有跑出卡片右緣", r["lgRight"] is not None and r["lgRight"] <= r["cardRight"] + 0.5,
       [r["lgRight"], r["cardRight"]])


def _hm_focus(pg, tag, id_):
    """⑥ 點圖例一格 → 其他級的方塊 opacity 變 0.25；再點一次還原。"""
    r0 = pg.evaluate(HM_READ, id_)
    bins = {}
    for lf in r0["leaves"]:
        bins[lf["bin"]] = bins.get(lf["bin"], 0) + 1
    pick = max((b for b in bins if b is not None and b >= 0), key=lambda b: bins[b], default=None)
    if pick is None:
        ok(f"[{tag}] ⑥ 找得到一級可以點", False, bins)
        return
    lg = f"#{id_}Legend"
    pg.evaluate("(s) => document.querySelector(s).scrollIntoView({block:'center'})", lg)
    click(pg, f'{lg} .hmcell[data-bin="{pick}"]', 900)
    r1 = pg.evaluate(HM_READ, id_)
    on = [lf["op"] for lf in r1["leaves"] if lf["bin"] == pick]
    off = [lf["op"] for lf in r1["leaves"] if lf["bin"] != pick]
    ok(f"[{tag}] ⑥ 點圖例第 {pick} 級 → 這一級的方塊不透明、其他級退到 0.25",
       on and all(o == 1 for o in on) and off and all(o == 0.25 for o in off), {"on": on[:4], "off": off[:4]})
    ok(f"[{tag}] ⑥ 圖例上被點的那一格標成選中（aria-pressed）",
       pg.evaluate("(s) => { const b = document.querySelector(s); return !!b && b.getAttribute('aria-pressed') === 'true'; }",
                   f'{lg} .hmcell[data-bin="{pick}"]'))
    click(pg, f'{lg} .hmcell[data-bin="{pick}"]', 900)
    r2 = pg.evaluate(HM_READ, id_)
    ok(f"[{tag}] ⑥ 再點一次還原：全部方塊回到不透明", all(lf["op"] == 1 for lf in r2["leaves"]),
       [lf["op"] for lf in r2["leaves"]][:6])


def t_heatmap_v2(pg, base):
    """熱力圖 v2：三張 treemap 的 7 格離散色階、2px 間隙、圓角、標籤分三級、圖例、提示框、兩個新下拉。"""
    for th in ("dark", "light"):
        pg.set_viewport_size({"width": 1440, "height": 950})
        pg.goto("about:blank")
        pg.goto(f"{base}#overview", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); localStorage.removeItem('tw.hmGroup');"
                    " localStorage.removeItem('tw.themeColor'); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
        r = pg.evaluate(HM_READ, "heat")
        _hm_check(f"{th} 總覽 #heat", r, "flow")
        ok(f"[{th} 總覽 #heat] 圖例標題寫的是「資金流向 (pp)」（顏色依據講清楚）", r and r["legendTitle"] == "資金流向 (pp)",
           r and r["legendTitle"])
        # 間隙色＝卡片底：產業鏈節點的 borderColor 就是縫的顏色
        gapc = pg.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('heat'));
            const o = c.getOption().series[0]; return { gap: o.itemStyle.borderColor,
              panel: getComputedStyle(document.documentElement).getPropertyValue('--panel').trim() }; }""")
        ok(f"[{th} 總覽 #heat] 方塊之間的縫是卡片底色（看起來是白縫／暗縫，不是黑框）",
           gapc["gap"].lower() == gapc["panel"].lower(), gapc)
        if th == "dark":
            _hm_focus(pg, f"{th} 總覽 #heat", "heat")
            # 產業鏈篩選切過去之後，圖例、標籤照樣在（下鑽不會把 v2 的東西弄丟）
            # 改前點 #heatChips 晶片 → 改後（2026-09-26）操作標題列的產業鏈下拉 #heatDD
            chips = [c for c in heat_dd_opts(pg) if c]
            if chips:
                heat_dd_pick(pg, chips[0], wait=900)
                r2 = pg.evaluate(HM_READ, "heat")
                ok(f"[{th} 總覽 #heat] 切到單一產業鏈之後圖例還在、只有一條、方塊仍是 7 格色",
                   r2 and len(r2["cells"]) == 7 and not r2["nested"]
                   and pg.evaluate("document.querySelectorAll('#ovHeatCard .hmlegend').length") == 1
                   and all(lf["fill"] in r2["pal7"] + [r2["na"]] for lf in r2["leaves"]), r2 and r2["cells"])
                # 2026-09-25 Andy：資金熱力圖下方的「族群」連結列拿掉 → 改前「只有一條」→ 改後「重畫幾次都不會長出連結列」
                ok(f"[{th} 總覽 #heat] 重畫幾次都不會長出連結列（09-25 已拿掉）",
                   pg.evaluate("document.querySelectorAll('#ovHeatCard .linkrow').length") == 0,
                   pg.evaluate("document.querySelectorAll('#ovHeatCard .linkrow').length"))
                heat_dd_pick(pg, "", wait=900)
        # ---- 熱力圖頁 ----
        pg.goto(f"{base}#heatmap", wait_until="networkidle"); pg.wait_for_timeout(2800)
        r = pg.evaluate(HM_READ, "indTree")
        _hm_check(f"{th} 熱力圖頁 #indTree", r, "chg")
        ok(f"[{th} #indTree] 圖例標題「漲跌幅 (%)」、七格文字照規格", r and r["legendTitle"] == "漲跌幅 (%)"
           and [c["txt"] for c in r["cells"]] == ["<-3", "-3~-1", "-1~0", "0", "0~1", "1~3", ">3"], r and r["cells"])
        # 紅漲綠跌：漲最多那一格要是紅色系、跌最多那一格要是綠色系（R 通道 vs G 通道）
        pal = r["pal7"] if r else []
        if pal:
            up, dn = pal[6].lstrip("#"), pal[0].lstrip("#")
            ok(f"[{th} #indTree] 紅漲綠跌：「>3」是紅、「<-3」是綠",
               int(up[0:2], 16) > int(up[2:4], 16) and int(dn[2:4], 16) > int(dn[0:2], 16), [pal[0], pal[6]])
        # 每一個標籤都指到它自己那一格的真值：兩行標籤的第二行 == 該族群的漲跌幅
        lab = pg.evaluate("""() => { const el = document.getElementById('indTree'); const c = echarts.getInstanceByDom(el);
            const out = []; c.getModel().getSeriesByIndex(0).getData().tree.root.eachNode(n => {
              if (n.children && n.children.length) return; const o = n.getModel().option || {}; const m = (el._hmLab || {})[o.gid];
              if (m && m.mode === 2) out.push({ t: m.text, chg: o.chg }); }); return out; }""")
        badl = [x for x in lab if x["t"].split("\n")[-1] != pg.evaluate("(v) => window.App.fmt.pct(v)", x["chg"])]
        ok(f"[{th} #indTree] 兩行標籤的數值就是那一格自己的漲跌幅（{len(lab)} 塊）", lab and not badl, badl[:4])
        # 產業鏈小標真的有字（v2 把根節點那條空白拿掉之後，小標要自己寫 formatter，沒寫就會變空白）
        up = pg.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('indTree'));
            const o = c.getOption().series[0]; const f = o.upperLabel && o.upperLabel.formatter;
            return { show: o.upperLabel && o.upperLabel.show, name: typeof f === 'function' ? f({ name: '半導體' }) : null,
                     root: o.levels && o.levels[0] && o.levels[0].upperLabel && o.levels[0].upperLabel.show }; }""")
        ok(f"[{th} #indTree] 產業鏈小標有字、根節點不留空白小標", up["show"] and up["name"] == "半導體" and up["root"] is False, up)
        if th == "dark":
            _hm_focus(pg, f"{th} #indTree", "indTree")
            # 「分組」下拉：產業鏈 → 不分組，畫面真的換成平鋪一層，而且記住
            pg.select_option("#indTreeGroup", "flat"); pg.wait_for_timeout(1400)
            rf = pg.evaluate(HM_READ, "indTree")
            # ★ 2026-09-24（審查 R4）：分組模式把小鏈的面積放大到至少 5%，那幾條鏈裡原本小於 visibleMin
            #   而不畫的小方塊會多畫出來（實測分組 60 塊、不分組 56 塊），所以不分組的塊數**可以比分組少**。
            #   這條要驗的是「真的換成平鋪」，塊數只拿來防「切了之後整張圖空掉」：至少八成五。
            ok("[#indTree] 分組切到「不分組」→ 真的平鋪成一層（沒有產業鏈那一層）",
               rf and not rf["nested"] and rf["n"] >= r["n"] * 0.85, rf and [rf["nested"], rf["n"], r["n"]])
            ok("[#indTree] 「不分組」有記在 localStorage", pg.evaluate("() => { try { return localStorage.getItem('tw.hmGroup'); } catch (e) { return null; } }") == "flat")
            _hm_check("dark #indTree 不分組", rf, "chg")
            pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
            ok("[#indTree] 重新整理之後還是「不分組」", pg.evaluate("() => document.getElementById('indTreeGroup').value") == "flat")
            pg.select_option("#indTreeGroup", "chain"); pg.wait_for_timeout(1400)
            ok("[#indTree] 切回「產業鏈」又分組了", (pg.evaluate(HM_READ, "indTree") or {}).get("nested") is True)
            ok("[#indTree] 日期膠囊顯示這份資料的交易日（MM/DD）",
               bool(pg.evaluate("() => /\\d\\d\\/\\d\\d/.test((document.querySelector('#indHeat .hmctl.date') || {}).textContent || '')")))
        # ---- 題材 ----
        pg.evaluate("document.getElementById('themeMap').scrollIntoView({block:'center'})"); pg.wait_for_timeout(700)
        r = pg.evaluate(HM_READ, "themeMap")
        _hm_check(f"{th} 題材 #themeMap", r, "heat")
        ok(f"[{th} #themeMap] 預設顏色＝熱度（藍→紅 5 格；09-24 Andy 指定溫和紅藍，改前暖金）",
           r and r["legendTitle"] == "熱度" and len(r["cells"]) == 5, r and r["legendTitle"])
        if th == "dark":
            pg.select_option("#themeColorSel", "chg"); pg.wait_for_timeout(1400)
            rc = pg.evaluate(HM_READ, "themeMap")
            ok("[#themeMap] 顏色切到「平均漲跌」→ 換成 7 格紅綠、圖例跟著換",
               rc and len(rc["cells"]) == 7 and rc["legendTitle"] == "漲跌幅 (%)"
               and all(lf["fill"] in rc["pal7"] + [rc["na"]] for lf in rc["leaves"]), rc and rc["cells"])
            vals = pg.evaluate("""() => { const el = document.getElementById('themeMap'); return Object.values(el._hmLab || {})
                .filter(m => m.mode === 2).map(m => m.text.split('\\n')[1]); }""")
            ok("[#themeMap] 平均漲跌模式下，兩行標籤的第二行是漲跌幅（不是熱度）",
               vals and all(v.endswith("%") for v in vals), vals[:5])
            ok("[#themeMap] 題材細節沒有因為換顏色被重建（只重畫這張圖）",
               pg.evaluate("() => location.hash").startswith("#heatmap"))
            # 2026-09-25 Andy：熱度只留藍→紅一組 → 改前「可切湖水藍」→ 改後「選單裡沒有湖水藍」
            ok("[#themeMap] 顏色選單只剩「熱度（藍→紅）」與「平均漲跌」（湖水藍已拿掉）",
               pg.evaluate("() => [...document.querySelectorAll('#themeColorSel option')].map(o => o.value).join(',')") == "heat,chg")
            ok("[#themeMap] 平均漲跌的選擇有記住（localStorage tw.themeColor）",
               pg.evaluate("() => localStorage.getItem('tw.themeColor')") == "chg")
            pg.select_option("#themeColorSel", "heat"); pg.wait_for_timeout(1400)
            rh = pg.evaluate(HM_READ, "themeMap")
            ok("[#themeMap] 切回「熱度（藍→紅）」→ 藍→紅 5 格",
               rh and len(rh["cells"]) == 5 and all(lf["fill"] in rh["pal5"] + [rh["na"]] for lf in rh["leaves"]), rh and rh["cells"])
            _hm_focus(pg, f"{th} #themeMap", "themeMap")
    # ---- 窄畫面：800px 與 390px，圖例不准縮字、不准撐出橫向捲軸 ----
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); } catch (e) {} }")
    for w in (800, 390):
        pg.set_viewport_size({"width": w, "height": 900})
        pg.goto("about:blank")   # 同一個網址只換寬度時 goto 不會重新載入，先跳開才是真的在這個寬度重畫
        pg.goto(f"{base}#heatmap", wait_until="networkidle")
        # 手機分段導覽會記住上次翻到哪一段（tw.mia.heatmap.*）；前面的「題材」段落會把它留在「題材熱力」，
        # 那時全市場熱力圖是收起來的（寬高 0）—— 清掉再重載，才是量「第一段＝全市場熱力圖」
        pg.evaluate("() => { try { Object.keys(localStorage).filter(k => k.startsWith('tw.mia.heatmap'))"
                    ".forEach(k => localStorage.removeItem(k)); } catch (e) {} }")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
        pg.evaluate("document.getElementById('indTree') && document.getElementById('indTree').scrollIntoView({block:'center'})")
        pg.wait_for_timeout(600)
        r = pg.evaluate(HM_READ, "indTree")
        dbg = pg.evaluate("""() => { const el = document.getElementById('indTree'); if (!el) return 'no-el';
            const r = el.getBoundingClientRect(); const c = window.echarts && echarts.getInstanceByDom(el);
            return { w: r.width, h: r.height, inst: !!c, cw: c && c.getWidth(), ch: c && c.getHeight(), hash: location.hash,
                     view: (document.querySelector('.view.on') || {}).id, cls: document.body.className }; }""")
        if not ok(f"[{w}px #indTree] 熱力圖畫得出來", r and r["n"] > 0, [r and r.get("n"), dbg]):
            continue
        fs = pg.evaluate("() => [...document.querySelectorAll('#indHeat .hmcell')].map(b => getComputedStyle(b).fontSize)")
        ok(f"[{w}px #indTree] 圖例每格 ≥ 36px、字不縮（12px）",
           all(c["w"] >= 36 for c in r["cells"]) and fs and all(f == "12px" for f in fs), [r["cells"], fs])
        ok(f"[{w}px #indTree] 圖例沒有跑出卡片、整頁沒有橫向捲軸",
           r["lgRight"] <= r["cardRight"] + 0.5 and r["docW"] <= r["winW"] + 1, [r["lgRight"], r["cardRight"], r["docW"], r["winW"]])
        tiny = [lf for lf in r["leaves"] if (lf["w"] < 48 or lf["h"] < 24) and lf["lab"] and lf["lab"]["text"]]
        ok(f"[{w}px #indTree] 窄畫面上的小方塊也一樣不寫殘字", not tiny, [(t["name"], t["lab"]) for t in tiny][:4])
    pg.set_viewport_size({"width": 1500, "height": 1000})
    pg.evaluate("() => { try { localStorage.removeItem('tw.hmGroup'); localStorage.removeItem('tw.themeColor'); } catch (e) {} }")
    t_heatmap_r4(pg, base)


# ★ 2026-09-24 審查 R4（熱力圖頁）：放大後照角標「雙擊還原」不能跳頁、還原鈕真的還原、
#   淺色主題的放大罩標題看得到、沒有剖析圖的題材點了要講「尚無剖析圖」、口徑小字不重複。
#   找方塊中心用 ECharts 自己排好的版面（treemap 子節點座標相對父節點，所以要一路加上去）。
HM_LEAF_XY = r"""(a) => {
  const el = document.getElementById(a.id); const c = el && window.echarts && echarts.getInstanceByDom(el); if (!c) return null;
  const tree = c.getModel().getSeriesByIndex(0).getData().tree; const R = el.getBoundingClientRect(); const out = [];
  tree.root.eachNode(n => { if (n.children && n.children.length) return; const l = n.getLayout(); if (!l || !l.isInView) return;
    let x = l.x, y = l.y, q = n.parentNode;
    while (q) { const ql = q.getLayout(); if (ql) { x += ql.x; y += ql.y; } q = q.parentNode; }
    const o = n.getModel().option || {};
    out.push({ key: o.gid || o.id, name: n.name, cx: R.left + x + l.width / 2, cy: R.top + y + l.height / 2, a: l.width * l.height }); });
  out.sort((p, q) => q.a - p.a);
  return a.key ? out.filter(v => v.key === a.key) : out;
}"""
ZST = """(id) => { const b = document.getElementById(id); if (!b) return null; const r = b.querySelector(':scope > .zreset');
  return { k: b._zoom ? b._zoom.scale : null, zoomed: b.classList.contains('zoomed'),
           reset: !!r && !r.hidden && r.getClientRects().length > 0, hash: location.hash,
           badge: (b.querySelector(':scope > .zbadge') || {}).textContent || '' }; }"""


def _r4_zoom_in(pg, x, y, n=3):
    pg.mouse.move(x, y)
    for _ in range(n):
        pg.mouse.wheel(0, -160); pg.wait_for_timeout(140)
    pg.wait_for_timeout(450)


def t_heatmap_r4(pg, base):
    tag = "熱力圖R4"
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto("about:blank")
    pg.goto(f"{base}#heatmap", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); localStorage.removeItem('tw.hmGroup');"
                " localStorage.removeItem('tw.themeColor'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)

    # ---------- ① 產業熱力：放大後雙擊 → 不跳頁、還原成 1 倍 ----------
    pg.evaluate("document.getElementById('indTree').scrollIntoView({block:'center'})"); pg.wait_for_timeout(600)
    leaf = (pg.evaluate(HM_LEAF_XY, {"id": "indTree"}) or [None])[0]
    if not ok(f"【{tag}】產業熱力找得到最大那一塊（{leaf and leaf['name']}）", bool(leaf), leaf):
        return
    # 先證明這個點在 1 倍時真的是「點了會跳頁」的方塊 —— 不然下面「沒跳頁」是假綠
    pg.mouse.click(leaf["cx"], leaf["cy"]); pg.wait_for_timeout(500)
    h1 = pg.evaluate("() => location.hash")
    ok(f"【{tag}】前提：1 倍時單擊這一塊立刻進族群頁（{h1}）", h1.startswith("#industry/group/"), h1)
    pg.go_back(wait_until="networkidle"); pg.wait_for_timeout(2400)
    pg.evaluate("document.getElementById('indTree').scrollIntoView({block:'center'})"); pg.wait_for_timeout(600)
    leaf = (pg.evaluate(HM_LEAF_XY, {"id": "indTree", "key": leaf["key"]}) or [leaf])[0]
    z0 = pg.evaluate(ZST, "indTreeWrap")
    ok(f"【{tag}】1 倍時「還原」鈕不顯示", z0 and not z0["reset"], z0)
    _r4_zoom_in(pg, leaf["cx"], leaf["cy"])
    z1 = pg.evaluate(ZST, "indTreeWrap")
    ok(f"【{tag}】產業熱力滾輪放大了（{z1 and z1['k']:.2f}×）、角標寫雙擊或按「還原」、還原鈕出現",
       z1 and z1["k"] > 1.2 and z1["reset"] and "還原" in z1["badge"], z1)
    pg.mouse.dblclick(leaf["cx"], leaf["cy"]); pg.wait_for_timeout(700)
    z2 = pg.evaluate(ZST, "indTreeWrap")
    ok(f"【{tag}】放大後照角標雙擊 → 沒有跳到族群頁（還在 {z2 and z2['hash']}）",
       z2 and z2["hash"] == z1["hash"], [z1 and z1["hash"], z2 and z2["hash"]])
    ok(f"【{tag}】雙擊真的還原成 1 倍、還原鈕收起", z2 and z2["k"] == 1 and not z2["zoomed"] and not z2["reset"], z2)

    # ---------- ② 放大後單擊仍然會導頁（只是延後），不是整個點不動 ----------
    _r4_zoom_in(pg, leaf["cx"], leaf["cy"])
    pg.mouse.click(leaf["cx"], leaf["cy"]); pg.wait_for_timeout(80)
    h_mid = pg.evaluate("() => location.hash")
    pg.wait_for_timeout(600)
    h_end = pg.evaluate("() => location.hash")
    ok(f"【{tag}】放大後單擊：先等一下（80ms 時還沒跳），之後照樣進族群頁（{h_end}）",
       h_mid == z1["hash"] and h_end.startswith("#industry/group/"), [h_mid, h_end])
    pg.go_back(wait_until="networkidle"); pg.wait_for_timeout(2400)

    # ---------- ③ 「還原」鈕：按了回 1 倍、不跳頁 ----------
    pg.evaluate("document.getElementById('indTree').scrollIntoView({block:'center'})"); pg.wait_for_timeout(600)
    leaf = (pg.evaluate(HM_LEAF_XY, {"id": "indTree", "key": leaf["key"]}) or [leaf])[0]
    _r4_zoom_in(pg, leaf["cx"], leaf["cy"])
    z3 = pg.evaluate(ZST, "indTreeWrap")
    ok(f"【{tag}】（還原鈕前提）又放大了", z3 and z3["k"] > 1.2 and z3["reset"], z3)
    pg.click("#indTreeWrap > .zreset"); pg.wait_for_timeout(600)
    z4 = pg.evaluate(ZST, "indTreeWrap")
    ok(f"【{tag}】按「還原」→ 回 1 倍、沒有跳頁、鈕收起",
       z4 and z4["k"] == 1 and not z4["zoomed"] and not z4["reset"] and z4["hash"] == z3["hash"], z4)

    # ---------- ④ 產業熱力：小鏈的名字不截成殘字 ----------
    lab = pg.evaluate("""() => { const el = document.getElementById('indTree'); const c = echarts.getInstanceByDom(el); const out = [];
        c.getModel().getSeriesByIndex(0).getData().tree.root.eachNode(n => { if (n.children && n.children.length) return;
          const o = n.getModel().option || {}; const m = (el._hmLab || {})[o.gid];
          if (m && m.mode === 1 && m.text.endsWith('…')) out.push({ name: n.name, t: m.text }); }); return out; }""")
    names = pg.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('indTree')); const o = {};
        c.getModel().getSeriesByIndex(0).getData().tree.root.eachNode(n => { const l = n.getLayout();
          if (n.depth === 1 && l) { const cv = document.createElement('canvas').getContext('2d');
            cv.font = '700 12px Noto Sans TC, JetBrains Mono, sans-serif';
            o[n.name] = { w: Math.round(l.width), need: Math.round(cv.measureText(n.name).width + 10) }; } }); return o; }""")
    short = [x["t"] for x in lab if len(x["t"].rstrip("…")) * 2 < len(x["name"])]
    ok(f"【{tag}】方塊名稱截斷時至少保留一半的字（沒有「石化…」「基礎建…」這種殘字）",
       not short, short[:5])
    up = pg.evaluate("() => document.getElementById('indTree')._hmUp || {}")
    bad_up = {k: t for k, t in up.items()
              if not (t == k or (t and "與" in k and t == k.split("與")[0])
                      or (t.endswith("…") and len(t) - 1 >= max(2, -(-len(k) // 2))))}
    ok(f"【{tag}】產業鏈小標是全名、或「與」前那一段、或至少保留一半的字（{up}）",
       len(up) == len(names) and not bad_up and all(up.values()), [bad_up, up, names])
    ok(f"【{tag}】「怎麼看」有寫明小鏈面積放大",
       "小鏈至少佔 5%" in pg.evaluate("() => (document.getElementById('how-indheat') || {}).textContent || ''"))

    # ---------- ⑤ 題材熱力：放大後雙擊不展開題材；離開再回來倍率歸 1 ----------
    pg.evaluate("document.getElementById('themeMap').scrollIntoView({block:'center'})"); pg.wait_for_timeout(700)
    tl = (pg.evaluate(HM_LEAF_XY, {"id": "themeMap"}) or [None])[0]
    if ok(f"【{tag}】題材熱力找得到最大那一塊（{tl and tl['name']}）", bool(tl), tl):
        h0 = pg.evaluate("() => location.hash")
        _r4_zoom_in(pg, tl["cx"], tl["cy"])
        pg.mouse.dblclick(tl["cx"], tl["cy"]); pg.wait_for_timeout(700)
        zt = pg.evaluate(ZST, "themeMapWrap")
        ok(f"【{tag}】題材熱力放大後雙擊 → 沒有展開題材細節（網址仍是 {zt and zt['hash']}）、回 1 倍",
           zt and zt["hash"] == h0 and "/theme/" not in zt["hash"] and zt["k"] == 1, [h0, zt])
        _r4_zoom_in(pg, tl["cx"], tl["cy"])
        k_before = (pg.evaluate(ZST, "themeMapWrap") or {}).get("k")
        pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1500)
        pg.goto(f"{base}#heatmap", wait_until="networkidle"); pg.wait_for_timeout(2200)
        zb = pg.evaluate(ZST, "themeMapWrap")
        ok(f"【{tag}】題材熱力放大到 {k_before and round(k_before, 2)}× → 離開再回來倍率歸 1",
           (k_before or 0) > 1.2 and zb and zb["k"] == 1 and not zb["zoomed"], [k_before, zb])
        click(pg, 'button.howbtn[data-how="theme"]', 400)   # 說明是按了才填進去的
        ok(f"【{tag}】題材「怎麼看」寫的是「藍＝冷、紅＝熱」（不是「越亮越熱」）",
           pg.evaluate("() => { const t = (document.getElementById('how-theme') || document.body).textContent;"
                       " return t.includes('藍＝冷、紅＝熱') && !t.includes('越亮越熱'); }"))
        # 2026-09-25：題材熱力的「?」改成跳出式（背後墊背景），讀完用 Esc 關，不然後面的點擊會被背景吃掉
        pg.keyboard.press("Escape"); pg.wait_for_timeout(250)

    # ---------- ⑥ 沒有剖析圖的題材：提示框與細節區都寫「尚無剖析圖」 ----------
    nodg = pg.evaluate("""() => fetch('data/themes.json').then(r => r.json()).then(th =>
        th.themes.filter(t => !(window.ThemeDiagrams || {})[t.id]).map(t => t.id))""")
    notes.append(f"{tag}：沒有剖析圖的題材 {nodg}")
    pg.evaluate("document.getElementById('themeMap').scrollIntoView({block:'center'})"); pg.wait_for_timeout(600)
    cand = [v for v in (pg.evaluate(HM_LEAF_XY, {"id": "themeMap"}) or []) if v["key"] in (nodg or [])]
    if not nodg:
        notes.append(f"{tag}：所有題材都有剖析圖了，「尚無剖析圖」那段沒得驗")
    elif ok(f"【{tag}】無剖析圖的題材在圖上點得到（{cand and cand[0]['name']}）", bool(cand), nodg):
        v = cand[0]
        pg.mouse.move(v["cx"], v["cy"]); pg.wait_for_timeout(600)
        tip = pg.evaluate("() => [...document.querySelectorAll('#themeMap div')].map(d => d.innerText || '').join(' ')")
        ok(f"【{tag}】滑過「{v['name']}」提示框寫「尚無剖析圖」", "尚無剖析圖" in tip, tip[-80:])
        pg.mouse.click(v["cx"], v["cy"]); pg.wait_for_timeout(900)
        d = pg.evaluate("""() => { const el = document.getElementById('themeDetail'); const r = el.getBoundingClientRect();
            return { h: Math.round(r.height), txt: el.innerText, card: !!el.querySelector('.card'), hash: location.hash }; }""")
        ok(f"【{tag}】點「{v['name']}」→ 網址換成它、細節區不是 0 高，寫「尚無剖析圖」",
           d["hash"].endswith("/theme/" + v["key"]) and d["h"] > 0 and "尚無剖析圖" in d["txt"], d)
        ok(f"【{tag}】沒有剖析圖時不加回佔位卡（Andy 09-23 拿掉的那張）", not d["card"], d)

    # ---------- ⑦ 淺色主題：放大罩標題對比 ≥ 4.5 ----------
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'light'); } catch (e) {} }")
    pg.goto(f"{base}#heatmap", wait_until="networkidle"); pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2400)
    pg.evaluate("document.getElementById('themeZoom').scrollIntoView({block:'center'})"); pg.wait_for_timeout(400)
    click(pg, "#themeZoom", 1300)
    cc = pg.evaluate("""() => { const t = document.getElementById('zoomTitle'), ov = document.getElementById('zoomOv');
        const p = (s) => (s.match(/[\d.]+/g) || []).map(Number);
        const fg = p(getComputedStyle(t).color), bg = p(getComputedStyle(ov).backgroundColor);
        const a = bg.length > 3 ? bg[3] : 1;
        // 罩底半透明：最壞情況是底下整片白（淺色主題的頁面底），先跟白色合成再算
        const comp = [0, 1, 2].map(i => bg[i] * a + 255 * (1 - a));
        const L = (c) => { const f = c.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
          return 0.2126 * f[0] + 0.7152 * f[1] + 0.0722 * f[2]; };
        const l1 = L(fg.slice(0, 3)), l2 = L(comp);
        return { txt: t.textContent, fg: getComputedStyle(t).color, bg: getComputedStyle(ov).backgroundColor,
                 cr: Math.round(((Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05)) * 100) / 100,
                 theme: document.documentElement.dataset.theme || '' }; }""")
    ok(f"【{tag}】淺色主題：放大罩標題「{cc['txt']}」對比 {cc['cr']} ≥ 4.5", cc["cr"] >= 4.5, cc)
    pg.keyboard.press("Escape"); pg.wait_for_timeout(400)
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); } catch (e) {} }")

    # ---------- ⑧ 週期統計「怎麼看」口徑小字不重複 ----------
    pg.goto(f"{base}#season", wait_until="networkidle"); pg.wait_for_timeout(2200)
    # ★ 2026-09-26 改前：驗 #seasonFine 口徑小字沒有重複的括號 → 改後：那段附註整個拿掉（Andy：「"?" 內…不需要附註」），
    #   括號重複的根因（基準字串接兩次）改在副標的滑鼠提示上驗
    _sf = how_fine(pg, "season")
    ok(f"【{tag}】週期統計「?」沒有附註段（#seasonFine 不存在）",
       pg.evaluate("() => !document.getElementById('seasonFine')") and bool(_sf) and _sf["fine"] == 0 and not _sf["tail"], _sf)
    import re as _re
    _tt = pg.evaluate("() => (document.getElementById('seasonRange') || {}).title || ''")
    parens = _re.findall(r"（[^）]*）", _tt)
    ok(f"【{tag}】週期統計的基準提示沒有重複的括號說明", _tt and not sorted({x for x in parens if parens.count(x) > 1}), _tt[:160])
    pg.set_viewport_size({"width": 1500, "height": 1000})


# =============================================================================
# ★ 2026-09-24 積木化第一梯次（docs/feature_modules.md §4.1）
#
# 這一批是**純重構**：畫面一個像素都不准變（另外做了 1440／390 逐頁像素比對）。
# 所以這裡驗的不是「長得對不對」，是**積木的邊界真的存在**：
#   ① 從積木的出口拿到的東西，跟畫面上真的出現的東西是同一份（點下去真的有反應）
#   ② 把那一塊積木的檔擋掉（不載入），整站沒有 JS 錯誤、其他積木照常 ——
#      這就是 §2.1 原則三「能不能單獨關閉」的驗收方式，不是寫在文件裡的願望。
# =============================================================================
def _bv_stock_code() -> str | None:
    """找一檔個股頁 JSON 裡真的有券商觀點的（本機快照會變，不寫死代號）。"""
    d = SITE / "data" / "stock"
    if not d.exists():
        return None
    best = None
    for f in sorted(d.glob("*.json")):
        try:
            n = len(json.loads(f.read_text(encoding="utf-8")).get("broker_views") or [])
        except Exception:  # noqa: BLE001
            continue
        if n and (best is None or n > best[1]):
            best = (f.stem, n)
            if n >= 2:
                break
    return best and best[0]


def t_block_broker(b, base):
    """積木 `broker.views`（site/blocks/broker_views.js）：兩個呼叫端都走同一個出口，而且關得掉。"""
    tag = "積木-券商觀點"
    bv_all = json.loads((SITE / "data" / "broker_views.json").read_text(encoding="utf-8")) \
        if (SITE / "data" / "broker_views.json").exists() else []
    code = _bv_stock_code()

    def open_page(block_off: bool):
        ctx = b.new_context(viewport={"width": 1440, "height": 900})
        errs: list[str] = []
        pg = ctx.new_page()
        pg.on("pageerror", lambda e: errs.append(str(e)))
        pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
        if block_off:
            pg.route("**/blocks/broker_views.js*", lambda r: r.abort())
        pg.goto(base + "#overview", wait_until="networkidle"); pg.wait_for_timeout(1500)
        if pg.evaluate("() => document.getElementById('layout').classList.contains('noside')"):
            click(pg, "#evToggle", 500)
        return ctx, pg, errs

    # ---------- ① 積木開著：事件抽屜的「券商」分類 ----------
    ctx, pg, errs = open_page(False)
    ok(f"【{tag}】積木有註冊（window.BrokerViews.id ＝ broker.views）",
       pg.evaluate("() => window.BrokerViews && window.BrokerViews.id") == "broker.views")
    n_all = count(pg, "#evList .ev")
    pg.click("#evFilters button[data-c='券商']"); pg.wait_for_timeout(400)
    cats = pg.evaluate("() => [...document.querySelectorAll('#evList .ev .cat')].map(e => e.textContent)")
    # `.ev > a` 才是標題；`.ev .m` 裡還有個股代號連結，不能一起抓
    titles = pg.evaluate("() => [...document.querySelectorAll('#evList .ev > a')].map(e => e.textContent)")
    want = min(len(bv_all), 120)
    ok(f"【{tag}】點「券商」之後清單真的只剩券商那一類（{len(cats)} 則）",
       bool(cats) and set(cats) == {"券商"}, sorted(set(cats))[:4])
    ok(f"【{tag}】券商那一類的筆數 ＝ broker_views.json 的筆數（{want}）", len(cats) == want, [len(cats), want])
    ok(f"【{tag}】每一則標題都是「<券商> 目標價 <數字>」的形狀（出口的 feed 格式）",
       titles and all(" 目標價 " in t for t in titles), titles[:2])
    # 從積木出口直接拿，跟畫面上的第一則要是同一件事（證明畫面走的是這個出口，不是另一份拷貝）
    feed = pg.evaluate("() => fetch('data/broker_views.json').then(r => r.json()).then(bv => window.BrokerViews.view(bv, 'feed').map(i => i.title))")
    ok(f"【{tag}】畫面上的券商標題集合 ＝ 積木出口 view(bv,'feed') 的標題集合",
       (bool(titles) and sorted(titles) == sorted(feed)) if len(feed) <= 120 else set(titles) <= set(feed),
       [len(titles), len(feed), titles[:1], feed[:1]])
    pg.click("#evFilters button[data-c='all']"); pg.wait_for_timeout(300)
    ok(f"【{tag}】切回「全部」筆數回來了", count(pg, "#evList .ev") == n_all, [n_all, count(pg, "#evList .ev")])

    # ---------- ② 積木開著：個股頁「公告 / 新聞」分頁的表格 ----------
    if code:
        pg.goto(base + f"#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(1500)
        pg.click("#stockTabs button[data-t='news']"); pg.wait_for_timeout(600)
        rows = pg.evaluate("""() => { const h = [...document.querySelectorAll('#stockTab .card h3')].find(x => x.textContent.startsWith('券商觀點'));
            return h ? [...h.closest('.card').querySelectorAll('tbody tr')].map(tr => [...tr.cells].map(c => c.textContent)) : null; }""")
        pgjs = json.loads((SITE / "data" / "stock" / f"{code}.json").read_text(encoding="utf-8"))
        want_rows = pgjs.get("broker_views") or []
        ok(f"【{tag}】{code} 個股頁的券商觀點表格列數 ＝ 個股 JSON 的 broker_views（{len(want_rows)}）",
           rows is not None and len(rows) == len(want_rows), [rows and len(rows), len(want_rows)])
        if rows:
            ok(f"【{tag}】{code} 第一列的日期／券商對得上資料",
               rows[0][0] == str(want_rows[0].get("date")) and rows[0][1] == (want_rows[0].get("broker") or "—"),
               [rows[0], want_rows[0]])
            # 真的點一列：要開新視窗到那則新聞（引述來源），不是點了沒反應。
            # 攔 window.open 記下網址 —— 外站在這個容器連不到，等新分頁載入只會量到錯誤頁。
            pg.evaluate("() => { window.__opened = []; window.open = (u) => { window.__opened.push(u); return null; }; }")
            h3 = pg.locator("#stockTab .card h3", has_text="券商觀點")
            h3.locator("xpath=ancestor::div[contains(@class,'card')][1]").locator("tbody tr").first.click()
            pg.wait_for_timeout(200)
            opened = pg.evaluate("() => window.__opened")
            want_url = want_rows[0].get("url") or "#"
            ok(f"【{tag}】點第一列開出那則新聞（{want_url[:48]}）", opened == [want_url], [opened, want_url])
    else:
        notes.append(f"{tag}：本機快照沒有任何一檔個股頁帶券商觀點，個股頁那半段沒驗到")
    ok(f"【{tag}】積木開著時整段沒有 JS 錯誤", not errs, errs[:2])
    ctx.close()

    # ---------- ③ 把積木關掉（擋掉 blocks/broker_views.js）：其他東西照常 ----------
    ctx, pg, errs = open_page(True)
    ok(f"【{tag}】關掉之後 window.BrokerViews 不存在（確實擋到了）",
       pg.evaluate("() => typeof window.BrokerViews") == "undefined")
    n_off = count(pg, "#evList .ev")
    news_n = len(json.loads((SITE / "data" / "news.json").read_text(encoding="utf-8"))) \
        if (SITE / "data" / "news.json").exists() else 0
    ok(f"【{tag}】關掉之後事件抽屜照常列新聞（{n_off} 則）", n_off > 0 or news_n == 0, [n_off, news_n])
    pg.click("#evFilters button[data-c='券商']"); pg.wait_for_timeout(300)
    ok(f"【{tag}】關掉之後「券商」分類是空的（顯示空狀態文字，不是壞掉）",
       count(pg, "#evList .ev") == 0 and "沒有這類事件" in pg.inner_text("#evList"), pg.inner_text("#evList")[:40])
    if code:
        pg.goto(base + f"#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(1500)
        pg.click("#stockTabs button[data-t='news']"); pg.wait_for_timeout(600)
        heads = pg.evaluate("() => [...document.querySelectorAll('#stockTab .card h3')].map(h => h.textContent.trim().slice(0, 6))")
        ok(f"【{tag}】關掉之後個股頁「公告 / 新聞」照常有重大訊息與相關新聞、沒有券商觀點",
           any(h.startswith("重大訊息") for h in heads) and any(h.startswith("相關新聞") for h in heads)
           and not any(h.startswith("券商觀點") for h in heads), heads)
    ok(f"【{tag}】關掉之後整站沒有任何 JS 錯誤（原則三：能單獨關閉）", not errs, errs[:2])
    ctx.close()


def t_block_stock_cards(b, base, code):
    """個股頁「總覽」分頁的三張卡拆成 `stock.fund`（基本面＋籌碼快照）與 `stock.signal`（技術面訊號）。

    驗：① 三張卡照舊、順序照舊；② 第三張卡就是 `StockSignal.view()` 的輸出（畫面走的是積木出口）；
        ③ 換分頁再換回來會重畫（不是一次性的字串）；④ 擋掉 blocks/stock_signal.js 之後
        只少那一張卡、其他分頁照常、沒有 JS 錯誤。"""
    tag = "積木-個股三卡"
    heads_js = "() => [...document.querySelectorAll('#stockTab > .grid.g3 > .card > h3')].map(h => h.firstChild.textContent.trim())"

    def open_page(block_off: bool):
        ctx = b.new_context(viewport={"width": 1440, "height": 900})
        errs: list[str] = []
        pg = ctx.new_page()
        pg.on("pageerror", lambda e: errs.append(str(e)))
        pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
        if block_off:
            pg.route("**/blocks/stock_signal.js*", lambda r: r.abort())
        pg.goto(base + f"#stock/{code}", wait_until="networkidle")
        wait_until(pg, "document.querySelectorAll('#stockTab .card').length >= 2", 8000)
        return ctx, pg, errs

    ctx, pg, errs = open_page(False)
    heads = pg.evaluate(heads_js)
    ok(f"【{tag}】{code} 總覽分頁照舊是三張卡：基本面／籌碼快照／技術面訊號",
       heads == ["基本面", "籌碼快照", "技術面訊號"], heads)
    same = pg.evaluate("""() => fetch('data/stock/' + location.hash.split('/')[1] + '.json').then(r => r.json()).then(pg => {
        const cards = document.querySelectorAll('#stockTab > .grid.g3 > .card');
        const html = window.StockSignal.view({ summary: pg.summary, verdict: pg.verdict }, window.App.fmt);
        const t = document.createElement('div'); t.innerHTML = html;
        return { id: window.StockSignal.id, same: cards[2] && cards[2].outerHTML === t.firstElementChild.outerHTML,
                 lights: cards[2] ? cards[2].querySelectorAll('.light').length : 0 }; })""")
    ok(f"【{tag}】第三張卡 ＝ 積木 stock.signal 出口的輸出（九顆燈號）",
       same.get("id") == "stock.signal" and same.get("same") and same.get("lights") == 9, same)
    pg.click("#stockTabs button[data-t='revenue']"); pg.wait_for_timeout(500)
    ok(f"【{tag}】換到「營收」分頁後三張卡真的換掉了", pg.evaluate(heads_js) == [], pg.evaluate(heads_js))
    pg.click("#stockTabs button[data-t='overview']"); pg.wait_for_timeout(500)
    ok(f"【{tag}】換回「總覽」三張卡重畫回來", pg.evaluate(heads_js) == ["基本面", "籌碼快照", "技術面訊號"], pg.evaluate(heads_js))
    ok(f"【{tag}】積木開著時沒有 JS 錯誤", not errs, errs[:2])
    ctx.close()

    ctx, pg, errs = open_page(True)
    ok(f"【{tag}】擋掉 blocks/stock_signal.js 之後 window.StockSignal 不存在",
       pg.evaluate("() => typeof window.StockSignal") == "undefined")
    ok(f"【{tag}】關掉技術面訊號之後只剩基本面與籌碼快照兩張（其他照常）",
       pg.evaluate(heads_js) == ["基本面", "籌碼快照"], pg.evaluate(heads_js))
    pg.click("#stockTabs button[data-t='revenue']"); pg.wait_for_timeout(700)
    ok(f"【{tag}】關掉之後其他分頁照常（營收分頁有畫出圖表）",
       pg.evaluate("() => document.querySelectorAll('#stockTab canvas').length") > 0
       or "尚無月營收" in pg.inner_text("#stockTab"), pg.inner_text("#stockTab")[:40])
    ok(f"【{tag}】關掉之後沒有任何 JS 錯誤（原則三：能單獨關閉）", not errs, errs[:2])
    ctx.close()


_MODULES_CACHE: dict | None = None


def _modules() -> dict:
    """讀 site/modules.js 的積木清單。那支檔把資料寫成夾在標記之間的純 JSON，就是為了這裡能直接讀，
    不必為了一份清單在 Python 端跑 JavaScript。"""
    global _MODULES_CACHE
    if _MODULES_CACHE is None:
        src = (SITE / "modules.js").read_text(encoding="utf-8")

        def block(tag):
            a = src.index(f"/*{tag}-JSON*/") + len(f"/*{tag}-JSON*/")
            return json.loads(src[a:src.index(f"/*END-{tag}-JSON*/")])
        _MODULES_CACHE = {"list": block("MODULES"), "pages": block("PAGES")}
    return _MODULES_CACHE


def _module_sections(spec: str) -> set[str]:
    """`--module a,b` → 要跑的段落名集合（積木自己的 tests ＋「積木清單」）。支援前綴（`flow.`）。"""
    want = [x.strip() for x in spec.split(",") if x.strip()]
    out = {"積木清單"}
    for m in _modules()["list"]:
        if any(m["id"] == w or m["id"].startswith(w) for w in want):
            out.update(m.get("tests") or [])
    return out


def t_block_registry(b, base, code):
    """積木清單（site/modules.js）本身的驗收。

    ① 清單裡的 27 個 id ＝ docs/feature_modules.md §3 的 27 個 id（名稱對不起來＝文件與程式分家了）
    ② 每一塊積木的 `tests` 都是真的存在的段落（不然 `--module` 會默默少跑）
    ③ 桌機 1440：每一個「不參與手機分段」的放置，選擇器在那一頁真的抓得到
    ④ 手機 390：畫面上的分段列（主軸四步 ＋ 每一步底下的分段）跟清單產生出來的**逐字相同**，
       而且**真的點每一段**，那一段宣告的 DOM 要顯示、只屬於別段的 DOM 要被收起來（畫面真的變了）。"""
    tag = "積木清單"
    mods = _modules()
    ids = [m["id"] for m in mods["list"]]
    doc = (ROOT / "docs" / "feature_modules.md").read_text(encoding="utf-8")
    doc_ids = re.findall(r"^### \d+\. `([a-z]+\.[a-z]+)`", doc, re.M)
    ok(f"【{tag}】modules.js 的積木 id ＝ docs/feature_modules.md §3 的 id（{len(doc_ids)} 個）",
       sorted(ids) == sorted(doc_ids) and len(ids) == len(set(ids)) == 27,
       {"只在程式": sorted(set(ids) - set(doc_ids)), "只在文件": sorted(set(doc_ids) - set(ids)), "n": len(ids)})
    missing = sorted({t for m in mods["list"] for t in (m.get("tests") or []) if t not in SECTIONS})
    ok(f"【{tag}】每塊積木宣告的驗收段落都真的存在", not missing, missing)
    bad_page = sorted({p["page"] for m in mods["list"] for p in m["at"] if p["page"] not in mods["pages"]})
    ok(f"【{tag}】每個放置的 page 都在 PAGES 裡", not bad_page, bad_page)

    url = lambda page: base + mods["pages"][page].replace("{code}", code)  # noqa: E731

    # ---------- ③ 桌機：不參與分段的放置，選擇器真的抓得到 ----------
    ctx = b.new_context(viewport={"width": 1440, "height": 900})
    errs: list[str] = []
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    by_page: dict[str, list] = {}
    for m in mods["list"]:
        for p in m["at"]:
            if not p.get("seg"):
                by_page.setdefault(p["page"], []).append((m["id"], p["selector"]))
    for page, items in by_page.items():
        pg.goto("about:blank"); pg.goto(url(page), wait_until="networkidle"); pg.wait_for_timeout(1800)
        for mid, sels in items:
            miss = pg.evaluate("(ss) => ss.filter(s => !document.querySelector('main .view.on ' + s))", sels)
            ok(f"【{tag}】桌機 {mods['pages'][page]}：積木 {mid} 宣告的 DOM 都在畫面上", not miss, miss)
    ok(f"【{tag}】桌機走過每一頁沒有 JS 錯誤", not errs, errs[:2])
    ctx.close()

    # ---------- ④ 手機：分段列 ＝ 清單產生的分段，而且每一段真的切得動 ----------
    ctx = b.new_context(**MOBILE_VP)
    errs = []
    m = ctx.new_page()
    m.on("pageerror", lambda e: errs.append(str(e)))
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(base + "#overview", wait_until="networkidle"); m.wait_for_timeout(1500)
    gen = m.evaluate("() => window.TwModules && window.TwModules.pager()")
    ok(f"【{tag}】頁面上拿得到清單產生的分段表（{len(gen or {})} 頁）", bool(gen), gen)
    for page, segs in (gen or {}).items():
        m.goto("about:blank"); m.goto(url(page), wait_until="networkidle"); m.wait_for_timeout(1800)
        steps = sorted({g.get("s", 0) for g in segs})
        for st in steps:
            if st:
                m.evaluate(f"() => document.querySelectorAll('.view.on > .mspine > button')[{steps.index(st)}].click()")
                m.wait_for_timeout(500)
            want = [g for g in segs if g.get("s", 0) == st]
            # 抓不到任何元素的段會被 miaPager 略過（例如簡版個股頁沒有 #mtfCard），比對時一起略過
            present = m.evaluate("(ws) => ws.map(g => g.sel.some(s => document.querySelector('.view.on ' + s) || document.querySelector(s)))", want)
            want = [g for g, keep in zip(want, present) if keep]
            labels = m.evaluate("() => [...document.querySelectorAll('.view.on > .mpager > button')].map(b => b.textContent)")
            where = f"{mods['pages'][page]}" + (f" 第{st}步" if st else "")
            if len(want) >= 2:
                ok(f"【{tag}】手機 {where}：分段列 ＝ 清單產生的段名（{'／'.join(g['n'] for g in want)}）",
                   labels == [g["n"] for g in want], [labels, [g["n"] for g in want]])
            for k, g in enumerate(want):
                if len(want) >= 2:
                    m.evaluate(f"() => document.querySelectorAll('.view.on > .mpager > button')[{k}].click()")
                    m.wait_for_timeout(350)
                others = [s for h in want if h is not g for s in h["sel"] if s not in g["sel"]]
                vis = m.evaluate("""([mine, others]) => {
                    const q = s => document.querySelector('.view.on ' + s) || document.querySelector(s);
                    // 看的是分段導覽自己下的 .mp-off（含祖先），不是 display：「怎麼看」說明本來就預設收合，那不是分段造成的
                    const shown = s => { const e = q(s); return !!e && !e.closest('.mp-off'); };
                    return { mine: mine.filter(s => q(s)).map(s => [s, shown(s)]),
                             others: others.filter(s => q(s)).map(s => [s, shown(s)]) }; }""", [g["sel"], others])
                # 清單裡寫的選擇器在手機上一個都不能是死的（這條不是自己跟自己比：選擇器寫錯，這裡就紅）
                dead = [s for s in g["sel"] if s not in [x for x, _ in vis["mine"]]]
                ok(f"【{tag}】手機 {where}「{g['n']}」：清單宣告的選擇器都抓得到", not dead, dead)
                hidden_mine = [s for s, on in vis["mine"] if not on]
                shown_others = [s for s, on in vis["others"] if on]
                ok(f"【{tag}】手機 {where}「{g['n']}」：自己的 DOM 全部顯示、只屬於別段的 DOM 全部收起",
                   not hidden_mine and not shown_others and vis["mine"],
                   {"該顯示卻沒顯示": hidden_mine, "該收卻沒收": shown_others})
    ok(f"【{tag}】手機走過每一段沒有 JS 錯誤", not errs, errs[:2])
    ctx.close()

    # ---------- ⑤ 清單本身擋掉：手機不分段、所有卡片照常顯示（失敗方向偏向「留著」），沒有 JS 錯誤 ----------
    ctx = b.new_context(**MOBILE_VP)
    errs = []
    m = ctx.new_page()
    m.on("pageerror", lambda e: errs.append(str(e)))
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.route("**/modules.js*", lambda r: r.abort())
    m.goto(base + "#overview", wait_until="networkidle"); m.wait_for_timeout(1800)
    st = m.evaluate("""() => ({ mods: typeof window.TwModules, pager: document.querySelectorAll('.view.on > .mpager').length,
        off: document.querySelectorAll('.view.on .mp-off').length,
        shown: ['#ovHeatCard', '#ovTrustCard', '#ovCandCard'].filter(s => { const e = document.querySelector(s);
          return e && e.getBoundingClientRect().height > 0; }).length })""")
    ok(f"【{tag}】擋掉 modules.js：沒有分段列、沒有被收起的卡、熱力／法人／候選三張卡都照常顯示",
       st["mods"] == "undefined" and st["pager"] == 0 and st["off"] == 0 and st["shown"] == 3, st)
    ok(f"【{tag}】擋掉 modules.js 之後沒有 JS 錯誤", not errs, errs[:2])
    ctx.close()


def t_block_implicit(b, base):
    """#4b：`market.streak`（法人連續買超）不再靠全域快取 `D.inst_streak` 當隱性參數。

    驗法是直接把那條暗道拆掉：總覽畫完之後把 `App.D.inst_streak` 清成 null，
    再真的按「外資」「合計」與天數下拉 —— 以前 renderTrust 讀的是 D，這時會變成空圖；
    現在它讀的是 renderOverview 明確傳進來的參數，圖與筆數要跟清掉之前一模一樣。"""
    tag = "積木-隱性參數"
    ctx = b.new_context(viewport={"width": 1440, "height": 900})
    errs: list[str] = []
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    pg.goto(base + "#overview", wait_until="networkidle")
    wait_until(pg, "window.App && document.querySelector('#streakSub') && /檔/.test(document.querySelector('#streakSub').textContent)", 8000)
    read = """() => { const el = document.getElementById('trust'); const c = el && window.echarts && echarts.getInstanceByDom(el);
        const s = c && c.getOption().series[0];
        return { sub: document.getElementById('streakSub').textContent, n: s ? (s.data || []).length : 0 }; }"""

    def run():
        out = {}
        for w in ("foreign", "total", "trust"):
            pg.click(f"#streakWho button[data-w='{w}']"); pg.wait_for_timeout(500)
            out[w] = pg.evaluate(read)
        pg.select_option("#streakDays", "2"); pg.wait_for_timeout(500)
        out["d2"] = pg.evaluate(read)
        pg.select_option("#streakDays", "3"); pg.wait_for_timeout(500)
        return out

    before = run()
    ok(f"【{tag}】外資／合計在拆暗道之前就有資料（這條驗收才有意義）",
       before["foreign"]["n"] > 0 or before["total"]["n"] > 0, before)
    pg.evaluate("() => { window.App.D.inst_streak = null; }")
    after = run()
    ok(f"【{tag}】把 App.D.inst_streak 清掉之後，三種法人與天數門檻的圖與筆數完全不變（讀的是參數，不是 D）",
       after == before, {"before": before, "after": after})
    ok(f"【{tag}】整段沒有 JS 錯誤", not errs, errs[:2])
    ctx.close()


# ===================================================================== 同意條款與法律頁（設計系統 v2 第 6 批）
# site/legal.js ＋ site/legal_config.js。驗的全部是「畫面真的因此改變了」：
#   · 開關關著（現況）：橫幅**不出現**（連沒有 tw.consent 的乾淨瀏覽器也不出現）、三頁打得開、
#     頁尾連結點得到、條款頁掛「草稿，尚未生效」、導覽可以手動開但不自動彈。
#   · 開關打開（注入 TW_LEGAL_OVERRIDE）：橫幅出現 → 按同意 → localStorage 真的寫進去、橫幅消失、
#     導覽自動開一次、重新整理不再出現；按不同意 → #leave、什麼都沒寫、換頁被擋回 #leave、重新整理橫幅又出現；
#     localStorage 寫入會丟錯時 → 這次瀏覽不再出現、不報錯。
# ⚠ 這一段刻意用 Browser._tw_raw_new_context（沒有預寫 tw.consent 的原版），其他段落一律有預寫。
LEGAL_ON = ("window.TW_LEGAL_OVERRIDE={operator:'驗收用營業人',email:'uitest@example.com',"
            "effective_date:'2026-10-01',tax_id:'尚未辦理',court:'臺灣臺北地方法院',enabled:true};")

_LG_FONTS = """(sel) => { const out = []; document.querySelectorAll(sel).forEach(root => {
    root.querySelectorAll('*').forEach(e => { if (!e.childNodes.length) return;
      const own = [...e.childNodes].some(n => n.nodeType === 3 && n.textContent.trim());
      if (!own || e.offsetParent === null) return;
      const fs = parseFloat(getComputedStyle(e).fontSize);
      if (fs < 11.95) out.push(fs + 'px「' + e.textContent.trim().slice(0, 14) + '」'); }); });
  return out; }"""


def _lg_page(b, w=1440, h=950, init=None, mobile=False, extra=None):
    raw = getattr(type(b), "_tw_raw_new_context", None)
    kw = dict(viewport={"width": w, "height": h})
    if mobile:
        kw.update(device_scale_factor=2, is_mobile=True, has_touch=True)
    ctx = raw(b, **kw) if raw else b.new_context(**kw)
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: fails.append(f"同意條款 pageerror: {e}"))
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    pg.add_init_script("try{localStorage.setItem('tw.live.on','0')}catch(e){}")
    if init:
        pg.add_init_script(init)
    if extra:
        pg.add_init_script(extra)
    return ctx, pg


def _lg_ls(pg, k):
    return pg.evaluate(f"() => {{ try {{ return localStorage.getItem('{k}'); }} catch (e) {{ return 'ERR'; }} }}")


def t_legal(b, base):
    # ---------------------------------------------------------------- A. 開關關著（現況）
    ctx, pg = _lg_page(b)
    pg.goto(base + "#overview", wait_until="networkidle"); pg.wait_for_timeout(2500)
    st = pg.evaluate("() => window.TwLegal && window.TwLegal.state()")
    ok("[關] legal.js 載入、判定為未啟用，而且列得出還缺哪些欄位",
       st and st["active"] is False and set(["operator", "email", "effective_date"]) <= set(st["missing"]["fields"]), st)
    ok("[關] 乾淨的瀏覽器（沒有 tw.consent）也不出現同意橫幅", pg.locator("#lgBanner").count() == 0,
       pg.locator("#lgBanner").count())
    ok("[關] 沒有同意紀錄時也不寫任何東西", _lg_ls(pg, "tw.consent") is None, _lg_ls(pg, "tw.consent"))
    ok("[關] 導覽沒有自動彈出", pg.locator("#lgTour").count() == 0)
    ft = pg.evaluate("""() => { const f = document.getElementById('siteFoot'); if (!f) return null;
        const r = f.getBoundingClientRect(), m = document.querySelector('main').getBoundingClientRect();
        return { t: f.innerText, fs: parseFloat(getComputedStyle(f).fontSize), inMain: r.left >= m.left - 1 && r.right <= m.right + 1,
                 last: f === document.querySelector('main').lastElementChild }; }""")
    ok("[關] 頁尾常駐一行短版免責聲明（預設開啟）",
       ft and "不是證券投資顧問事業" in ft["t"] and "不提供投資建議" in ft["t"] and ft["fs"] >= 12, ft)
    ok("[關] 頁尾是 main 的最後一個元素、不跑出內容欄", ft and ft["last"] and ft["inMain"], ft)
    ok("[關] 頁尾的服務條款／隱私權政策連結標「草稿」", ft and ft["t"].count("草稿") >= 2, ft and ft["t"])
    ok("[關] 頁尾與法律頁沒有小於 12px 的字", not pg.evaluate(_LG_FONTS, "#siteFoot"), pg.evaluate(_LG_FONTS, "#siteFoot"))
    # ★ 2026-09-24 Andy：「這完全不能公開」—— 頁尾曾經有一個「原始碼與演算法」連到 GitHub repo。
    #   全站任何地方都不准出現連到 GitHub 的連結、也不准出現 repo 網址文字。
    gh = pg.evaluate("""() => ({ links: [...document.querySelectorAll('a[href]')].map(a => a.getAttribute('href'))
        .filter(h => /github\\.com/i.test(h)), text: /github\\.com\\/MiaoZiKe/i.test(document.body.innerText),
        foot: /原始碼/.test((document.getElementById('siteFoot') || {}).innerText || '') })""")
    ok("★ [關] 全站沒有任何連到 GitHub 的連結、也沒有 repo 網址（原始碼不公開）",
       not gh["links"] and not gh["text"] and not gh["foot"], gh)

    # ---- 頁尾第二版（2026-09-24 Andy 給參考截圖）：© 行＋「顯示詳細規範」膠囊鈕＋8 格詳細規範 ----
    FD = """() => { const f = document.getElementById('siteFoot'), d = document.getElementById('sfDetail'),
        btn = document.getElementById('sfMore'), g = d && d.querySelector('.sf-grid');
        const items = g ? [...g.children] : [];
        return { copy: (document.getElementById('sfCopy') || {}).textContent || '',
          shown: !!d && getComputedStyle(d).display !== 'none' && d.getBoundingClientRect().height > 0,
          dh: d ? Math.round(d.getBoundingClientRect().height) : -1,
          label: btn ? btn.textContent.trim() : '', exp: btn ? btn.getAttribute('aria-expanded') : null,
          n: items.length,
          cols: g ? getComputedStyle(g).gridTemplateColumns.split(' ').filter(Boolean).length : 0,
          icons: items.filter(li => li.querySelector('svg circle')).length,
          bolds: items.filter(li => { const b = li.querySelector('b');
            return b && /：$/.test(b.textContent.trim()) && +getComputedStyle(b).fontWeight >= 600; }).length,
          heads: items.map(li => (li.querySelector('b') || {}).textContent || ''),
          ftxt: f ? f.innerText : '', fh: f ? Math.round(f.offsetHeight) : 0 }; }"""
    fd0 = pg.evaluate(FD)
    ok("[頁尾] 第一行是「© 2026 台股資金輪動儀表板 · 保留所有權利」",
       fd0["copy"].startswith("© 2026 ") and "台股資金輪動儀表板" in fd0["copy"] and "保留所有權利" in fd0["copy"], fd0["copy"])
    ok("[頁尾] 短版免責聲明與四個連結都還在（免責聲明全文／服務條款／隱私權政策／平台導覽）",
       all(x in fd0["ftxt"] for x in ("不是證券投資顧問事業", "免責聲明全文", "服務條款", "隱私權政策", "平台導覽")), fd0["ftxt"][:200])
    ok("[頁尾] 詳細規範預設收起（畫面上只留必要的）：區塊不佔高度、按鈕寫「顯示詳細規範」、aria-expanded=false",
       not fd0["shown"] and fd0["dh"] == 0 and fd0["label"] == "顯示詳細規範" and fd0["exp"] == "false"
       and _lg_ls(pg, "tw.footDetail") is None, fd0)
    pg.evaluate("() => window.scrollTo({top: document.body.scrollHeight, behavior: 'instant'})"); pg.wait_for_timeout(300)
    pg.click("#sfMore"); pg.wait_for_timeout(350)
    fd1 = pg.evaluate(FD)
    ok("[頁尾] 點「顯示詳細規範」→ 真的展開、頁尾變高、按鈕改成「隱藏詳細規範」",
       fd1["shown"] and fd1["dh"] > 100 and fd1["fh"] > fd0["fh"] + 100 and fd1["label"] == "隱藏詳細規範"
       and fd1["exp"] == "true", {k: fd1[k] for k in ("shown", "dh", "fh", "label", "exp")} | {"fh0": fd0["fh"]})
    ok("[頁尾] 展開後 8 格、每格都有 ⓘ 圖示（內嵌 SVG）與粗體小標＋冒號",
       fd1["n"] == 8 and fd1["icons"] == 8 and fd1["bolds"] == 8, fd1["heads"])
    ok("[頁尾] 8 格的小標是本站自己的那 8 項（沒有「上鏈績效認可」「最終解釋權」）",
       [h.rstrip("：") for h in fd1["heads"]] == ["重要聲明", "非投資建議", "投資風險警告", "不代操／不託管／不招攬",
                                                  "數據來源", "即時資料說明", "專業諮詢", "責任限制"]
       and "上鏈" not in fd1["ftxt"] and "最終解釋權" not in fd1["ftxt"], fd1["heads"])
    ok("★ [頁尾] 展開後也沒有 GitHub／repo／原始碼／演算法字眼，也沒有【】空格",
       not re.search(r"github|repo|原始碼|演算法|【|】", fd1["ftxt"], re.I), fd1["ftxt"][-300:])
    ok("[頁尾] 展開後沒有小於 12px 的字", not pg.evaluate(_LG_FONTS, "#siteFoot"), pg.evaluate(_LG_FONTS, "#siteFoot"))
    ok("[頁尾] 展開 → localStorage tw.footDetail 真的寫入 '1'", _lg_ls(pg, "tw.footDetail") == "1", _lg_ls(pg, "tw.footDetail"))
    cols = {}
    for w in (1440, 820, 390):
        pg.set_viewport_size({"width": w, "height": 950}); pg.wait_for_timeout(350)
        cols[w] = pg.evaluate(FD)["cols"]
        cols[f"docW{w}"] = pg.evaluate("() => document.documentElement.scrollWidth - innerWidth")
    ok("[頁尾] 詳細規範欄數：1440＝4 欄、820＝2 欄、390＝1 欄，而且都沒有橫向捲軸",
       cols[1440] == 4 and cols[820] == 2 and cols[390] == 1 and all(cols[f"docW{w}"] <= 1 for w in (1440, 820, 390)), cols)
    pg.set_viewport_size({"width": 1440, "height": 950}); pg.wait_for_timeout(300)
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1500)
    fd2 = pg.evaluate(FD)
    ok("[頁尾] 重新整理 → 維持展開（讀 tw.footDetail）", fd2["shown"] and fd2["label"] == "隱藏詳細規範", fd2["label"])
    pg.evaluate("() => window.scrollTo({top: document.body.scrollHeight, behavior: 'instant'})"); pg.wait_for_timeout(300)
    pg.click("#sfMore"); pg.wait_for_timeout(300)
    fd3 = pg.evaluate(FD)
    ok("[頁尾] 再點 → 收起、按鈕回「顯示詳細規範」、tw.footDetail 寫成 '0'",
       not fd3["shown"] and fd3["label"] == "顯示詳細規範" and _lg_ls(pg, "tw.footDetail") == "0", [fd3["label"], _lg_ls(pg, "tw.footDetail")])
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1500)
    ok("[頁尾] 重新整理 → 維持收起", not pg.evaluate(FD)["shown"])

    # 頁尾連結 → 服務條款
    pg.evaluate("() => window.scrollTo(0, document.body.scrollHeight)"); pg.wait_for_timeout(300)
    pg.click("#sfTerms"); pg.wait_for_timeout(1500)   # 捲回頁首也是 smooth，等它到
    r = pg.evaluate("""() => ({ hash: location.hash, legal: document.getElementById('v-legal').classList.contains('on'),
        ov: document.getElementById('v-overview').classList.contains('on'), tabs: document.querySelectorAll('.tab.on').length,
        h1: (document.querySelector('#lgDoc h1') || {}).textContent || '', draft: !!document.getElementById('lgDraft'),
        blanks: document.querySelectorAll('#lgDoc .lgblank').length, sy: scrollY })""")
    ok("[關] 點頁尾「服務條款」→ 真的換到服務條款頁、總覽收起來、頂欄分頁沒有一顆亮",
       r["hash"] == "#terms" and r["legal"] and not r["ov"] and r["tabs"] == 0 and "服務條款" in r["h1"], r)
    ok("[關] 服務條款頂端掛「草稿，尚未生效」，空格用【】標出來",
       r["draft"] and r["blanks"] >= 3 and "草稿，尚未生效" in pg.inner_text("#lgDraft"), r)
    ok("[關] 進法律頁捲回頁首", r["sy"] == 0, r)
    ok("[關] 法律頁沒有小於 12px 的字", not pg.evaluate(_LG_FONTS, "#v-legal"), pg.evaluate(_LG_FONTS, "#v-legal"))
    # 目錄：點第五條 → 捲下去，但網址不變（目錄不能改 hash，不然會被當成未知路由導回總覽）
    toc = pg.locator(".lgtoc a[data-sec='4']")
    if ok("[關] 桌機 1440 有左側目錄", toc.count() == 1 and toc.is_visible(), toc.count()):
        toc.click(); pg.wait_for_timeout(1400)      # 全站 scroll-behavior:smooth，要等它捲完
        r2 = pg.evaluate("""() => ({ hash: location.hash, sy: scrollY,
            top: document.getElementById('lg-terms-4').getBoundingClientRect().top,
            on: (document.querySelector('.lgtoc a.on') || {}).dataset })""")
        ok("[關] 點目錄第五條 → 那一條捲到畫面上緣、網址還是 #terms、目錄亮在第五條",
           r2["hash"] == "#terms" and r2["sy"] > 100 and 40 < r2["top"] < 200 and r2["on"] and r2["on"].get("sec") == "4", r2)
    # 上方三個分頁切換（2026-09-24 改成膠囊：目前頁實心主色、其他描邊）
    TABS = """() => { const bg = (e) => getComputedStyle(e).backgroundColor, cy = (() => { const s = document.createElement('i');
        s.style.color = 'var(--cyan)'; document.body.appendChild(s); const c = getComputedStyle(s).color; s.remove(); return c; })();
      return [...document.querySelectorAll('.lgtabs a')].map(a => { const r = a.getBoundingClientRect(), cs = getComputedStyle(a);
        return { t: a.textContent.trim(), on: a.classList.contains('on'), solid: bg(a) === cy, h: Math.round(r.height),
                 top: Math.round(r.top), rad: parseFloat(cs.borderTopLeftRadius), bw: parseFloat(cs.borderTopWidth),
                 fw: +cs.fontWeight }; }); }"""
    tb = pg.evaluate(TABS)
    ok("[分頁] 三顆膠囊（服務條款｜隱私權政策｜免責聲明）排一列、高 34～42、全圓角",
       [x["t"] for x in tb] == ["服務條款", "隱私權政策", "免責聲明"] and len({x["top"] for x in tb}) == 1
       and all(34 <= x["h"] <= 42 and x["rad"] >= x["h"] / 2 - 1 for x in tb), tb)
    ok("[分頁] 目前頁（服務條款）那顆是實心主色＋粗體，其他兩顆不是實心、有細框",
       tb[0]["solid"] and tb[0]["fw"] >= 700 and not tb[1]["solid"] and not tb[2]["solid"]
       and tb[1]["bw"] >= 1 and tb[2]["bw"] >= 1, tb)
    pg.click(".lgtabs a[href='#privacy']"); pg.wait_for_timeout(600)
    tb2 = pg.evaluate(TABS)
    ok("[分頁] 點「隱私權政策」→ 換頁、實心跟著換到隱私權政策那顆",
       pg.evaluate("() => location.hash") == "#privacy" and tb2[1]["solid"] and tb2[1]["on"]
       and not tb2[0]["solid"] and not tb2[2]["solid"], tb2)
    r = pg.evaluate("() => ({ h1: document.querySelector('#lgDoc h1').textContent, draft: !!document.getElementById('lgDraft'),"
                    " t: document.getElementById('lgDoc').innerText })")
    ok("[關] 切到隱私權政策：標題換了、一樣是草稿、有補上「是否已同意條款存在 localStorage」那一句",
       "隱私權政策" in r["h1"] and r["draft"] and "是否已同意條款" in r["t"], r["h1"])
    ok("[關] 隱私權政策沒有列出本站沒有的服務（電子報／付費／流量統計）",
       "訂閱電子報" not in r["t"] and "註冊付費服務" not in r["t"] and "網站流量統計" not in r["t"], "")
    pg.click(".lgtabs a[href='#disclaimer']"); pg.wait_for_timeout(600)
    r = pg.evaluate("() => ({ h1: document.querySelector('#lgDoc h1').textContent, draft: !!document.getElementById('lgDraft'),"
                    " t: document.getElementById('lgDoc').innerText, blanks: document.querySelectorAll('#lgDoc .lgblank').length })")
    ok("[關] 免責聲明：沒有空格、不掛草稿標示（版本 A 可以先上），而且沒有任何 GitHub 網址（原始碼不公開）",
       r["h1"] == "免責聲明" and not r["draft"] and r["blanks"] == 0 and "github" not in r["t"].lower(), r["h1"])
    # 從法律頁點頂欄回總覽 → 總覽真的回來
    pg.click(".tab[data-view='overview']"); pg.wait_for_timeout(1500)
    ok("[關] 從法律頁按頂欄「總覽」→ 回到總覽", pg.evaluate(
        "() => document.getElementById('v-overview').classList.contains('on') && !document.getElementById('v-legal').classList.contains('on')"))
    # 平台導覽：手動開得到；下一步 ×3 標題依序變；Esc 關閉、焦點回到頁尾那顆
    pg.evaluate("() => window.scrollTo(0, document.body.scrollHeight)"); pg.wait_for_timeout(300)
    pg.click("#sfTour"); pg.wait_for_timeout(400)
    seen = [pg.inner_text("#lgStepT")]
    for _ in range(3):
        pg.click("#lgNext"); pg.wait_for_timeout(250); seen.append(pg.inner_text("#lgStepT"))
    ok("[關] 導覽：下一步 ×3 → 標題依序是 ①～④", seen == ["① 錢往哪跑", "② 貴不貴", "③ 何時進場", "④ 別進的理由"], seen)
    ok("[關] 導覽最後一步按鈕變成「開始使用」", pg.inner_text("#lgNext") == "開始使用", pg.inner_text("#lgNext"))
    pg.keyboard.press("Tab"); pg.keyboard.press("Tab"); pg.keyboard.press("Tab"); pg.keyboard.press("Tab")
    ok("[關] 導覽開著時 Tab 焦點困在彈窗裡", pg.evaluate(
        "() => !!document.activeElement && !!document.activeElement.closest('#lgTour')"))
    pg.keyboard.press("Escape"); pg.wait_for_timeout(250)
    ok("[關] Esc 關閉導覽、焦點回到頁尾「平台導覽」", pg.locator("#lgTour").count() == 0
       and pg.evaluate("() => document.activeElement && document.activeElement.id") == "sfTour",
       pg.evaluate("() => document.activeElement && document.activeElement.id"))
    ctx.close()

    # 手機 390：法律頁不能有橫向捲軸；頁尾在底部分頁列上面、看得到
    ctx, pg = _lg_page(b, 390, 844, mobile=True)
    pg.goto(base + "#privacy", wait_until="networkidle"); pg.wait_for_timeout(2000)
    r = pg.evaluate("""() => ({ docW: document.documentElement.scrollWidth, winW: innerWidth,
        toc: getComputedStyle(document.querySelector('.lgtoc')).display, tocm: !!document.querySelector('.lgtocm') &&
        getComputedStyle(document.querySelector('.lgtocm')).display })""")
    ok("[390] 隱私權政策（有表格）沒有橫向捲軸", r["docW"] <= r["winW"] + 1, r)
    ok("[390] 手機收起左側目錄、改用可展開的目錄", r["toc"] == "none" and r["tocm"] not in (False, "none"), r)
    ok("[390] 法律頁沒有小於 12px 的字", not pg.evaluate(_LG_FONTS, "#v-legal"), pg.evaluate(_LG_FONTS, "#v-legal"))
    r = pg.evaluate("""() => { const a = [...document.querySelectorAll('.lgtabs a')].map(x => x.getBoundingClientRect());
        return { tops: a.map(x => Math.round(x.top)), l: Math.round(a[0].left), r: Math.round(a[2].right), winW: innerWidth,
                 fs: Math.min(...[...document.querySelectorAll('.lgtabs a')].map(x => parseFloat(getComputedStyle(x).fontSize))) }; }""")
    ok("[390] 三顆膠囊分頁一列放得下（同一條上緣、不超出畫面、字 ≥ 13px）",
       len(set(r["tops"])) == 1 and r["l"] >= 0 and r["r"] <= r["winW"] and r["fs"] >= 13, r)
    pg.evaluate("() => window.scrollTo({top: document.body.scrollHeight, behavior: 'instant'})"); pg.wait_for_timeout(400)
    r = pg.evaluate("""() => { const f = document.getElementById('siteFoot').getBoundingClientRect(),
        t = document.getElementById('tabs').getBoundingClientRect(); return { fb: f.bottom, ft: f.top, tt: t.top }; }""")
    ok("[390] 捲到底時頁尾整段在底部分頁列上方（沒被蓋住）", r["fb"] <= r["tt"] + 1 and r["ft"] > 0, r)
    ctx.close()

    # ---------------------------------------------------------------- B. 開關打開（模擬 Andy 填好了）
    ctx, pg = _lg_page(b, init=LEGAL_ON)
    pg.goto(base + "#overview", wait_until="networkidle"); pg.wait_for_timeout(2500)
    st = pg.evaluate("() => window.TwLegal.state()")
    ok("[開] 注入設定後判定為啟用", st["active"] is True and st["version"] == "2026-10-01", st)
    ban = pg.evaluate("""() => { const b = document.getElementById('lgBanner'); if (!b) return null;
        const r = b.getBoundingClientRect(); return { role: b.getAttribute('role'), label: b.getAttribute('aria-label'),
        z: +getComputedStyle(b).zIndex, bottom: innerHeight - r.bottom, w: r.width, focusIn: b.contains(document.activeElement),
        pos: getComputedStyle(b).position }; }""")
    ok("[開] 沒同意過 → 橫幅出現（固定在下方、z 90、role=region）",
       ban and ban["pos"] == "fixed" and ban["z"] == 90 and ban["role"] == "region" and 16 <= ban["bottom"] <= 32, ban)
    ok("[開] 橫幅出現時不搶焦點", ban and not ban["focusIn"], ban)
    ok("[開] 按同意之前 localStorage 沒有 tw.consent", _lg_ls(pg, "tw.consent") is None, _lg_ls(pg, "tw.consent"))
    # ★ 2026-09-24 說明精簡：總覽熱力圖的長副標縮短後，標題列少一行，「放大」鈕在 1440×950 的首屏
    #   剛好落在固定橫幅（832～926px）的高度 —— 改版前是 915px、只是水平方向剛好錯開。
    #   這條要驗的是「橫幅不會永久蓋住內容」，所以先把鈕捲到畫面中間（真人也會捲），再量那一點是誰；
    #   不捲就等於在驗「首屏某個座標剛好沒被蓋到」，版面一動就假紅。
    pg.evaluate("() => { const e = document.getElementById('heatZoom'); if (e) { const r = e.getBoundingClientRect();"
                " window.scrollBy({ top: r.top - innerHeight / 2, behavior: 'instant' }); } }")
    pg.wait_for_timeout(300)
    ok("[開] 橫幅不擋內容：底下的「放大」鈕照樣點得到", pg.evaluate(
        "() => { const e = document.getElementById('heatZoom'); if (!e) return true; const r = e.getBoundingClientRect();"
        " const x = document.elementFromPoint(r.left + 4, r.top + 4); return !r.height || r.top > innerHeight || !!(x && !x.closest('#lgBanner')) ; }"))
    pg.click("#lgAccept"); pg.wait_for_timeout(700)
    raw = _lg_ls(pg, "tw.consent")
    try:
        cv = json.loads(raw or "null")
    except Exception:  # noqa: BLE001
        cv = None
    ok("[開] 按同意 → localStorage 真的寫進 {v: 生效日期, at: 時間}", cv and cv.get("v") == "2026-10-01" and cv.get("at"), raw)
    ok("[開] 按同意 → 橫幅消失", pg.locator("#lgBanner").count() == 0)
    ok("[開] 第一次同意 → 平台導覽自動開一次", pg.locator("#lgTour").count() == 1)
    # 「到總覽看這一步」（第③步）→ 彈窗關閉、今日候選那張卡在畫面上半部、外圈亮一下
    pg.click("#lgNext"); pg.wait_for_timeout(200); pg.click("#lgNext"); pg.wait_for_timeout(200)
    pg.click("#lgGo"); pg.wait_for_timeout(450)
    fl = pg.evaluate("() => ({ flash: document.getElementById('ovCandCard').classList.contains('lgflash'),"
                     " tour: !!document.getElementById('lgTour') })")
    pg.wait_for_timeout(900)                          # 全站 scroll-behavior:smooth，等捲完再量位置
    r = pg.evaluate("""() => { const r = document.getElementById('ovCandCard').getBoundingClientRect();
        return { top: r.top, vh: innerHeight }; }""")
    ok("[開] 導覽「到總覽看這一步」→ 彈窗關閉、外圈亮一圈", not fl["tour"] and fl["flash"], fl)
